-- ============================================================================

-- ---- פרק: intro
insert into public.course_chapters (slug, title, summary, position, published)
values ('intro', 'איך עוברים את מבחן המתווכים', 'מבנה הבחינה, ציון העובר, חומר העזר שמותר להכניס, ואיך הקורס הזה בנוי.', 1, true)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary,
  position = excluded.position, published = true;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'exam-format', 'הבחינה: מה יש בה, ואיך ניגשים אליה', 1, 'ברוכים הבאים. לפני שצוללים לחוק, בואו נבין מול מה אנחנו עומדים. מי שמכיר את מבנה הבחינה כבר מתחיל עם יתרון.', '<h3>מבנה הבחינה</h3><p>בחינת רשם המתווכים היא בחינה אמריקאית אחת, בת <strong>25 שאלות</strong>. לכל שאלה ארבע חלופות (א-ד) ותשובה נכונה אחת. כל שאלה שווה <strong>4 נקודות</strong>, ו<strong>ציון העובר הוא 60</strong>, כלומר 15 תשובות נכונות. משך הבחינה <strong>שעתיים</strong>.</p><p>אין ניקוד שלילי. שאלה שלא ענית עליה שווה בדיוק כמו שאלה שטעית בה, ולכן <strong>תמיד מסמנים תשובה</strong>, גם כשלא בטוחים.</p><h3>בחינה עם חומר פתוח</h3><p>זה הפרט החשוב ביותר, ורוב הנבחנים מתעלמים ממנו: הרשם מחלק באולם את <strong>ספר דיני מתווכים במקרקעין, חוקים ותקנות</strong>, ואת <strong>תקנות המתווכים (אתיקה וחובות מקצועיות), התשפ"ד-2024</strong>. מותר גם מילון מאושר. אסור לכתוב על החוברות, ומחזירים אותן בסוף.</p><p>המשמעות: הבחינה לא בודקת אם שיננת סעיפים. היא בודקת אם אתם <strong>מבינים את הכללים ויודעים למצוא אותם מהר</strong>. כל שאלה היא סיפור קצר ("רפאל הוא מתווך מוסמך...") שבסופו שואלים: האם זה כדין, ומה הדין. מי שיודע באיזה חוק הסעיף יושב, פותח בדיוק שם ומאמת תוך דקה.</p><h3>מה נכנס לבחינה</h3><p>הבחינה רחבה יותר מחוק המתווכים עצמו. במבחן יולי 2026, למשל, רק כשליש מהשאלות עסקו ישירות בחוק המתווכים ובתקנות האתיקה. השאר הגיעו מדיני המקרקעין (עסקאות נוגדות, בתים משותפים, הערות אזהרה, שיתוף), מדיני החוזים (כריתה, תרופות, זקיפת תשלומים), מחוק המכר (דירות) והבטחת השקעות, מחוק הגנת הדייר, מחוק השכירות והשאילה, מחוק הגנת הצרכן, ממיסוי מקרקעין, ומתכנון ובנייה.</p><h3>איך הקורס בנוי</h3><ul><li><strong>פרק לכל חוק.</strong> כל שיעור מסביר כלל אחד או קבוצת כללים בשפה פשוטה, עם הסעיף המקורי לצידו.</li><li><strong>חידון בסוף כל שיעור.</strong> שאלות בסגנון הבחינה. תשובה שגויה מקבלת הסבר מיד, עם הפניה לסעיף. שיעור נחשב "הושלם" כשעברתם את החידון בציון 60 ומעלה, ואפשר לחזור עליו כמה שרוצים.</li><li><strong>סימולציה.</strong> 25 שאלות, קודם כל מהמבחנים האמיתיים של הרשם, בסדר אקראי, עם ציון ופירוט מלא בסוף. מומלץ לעשות סימולציה עם החוברת ליד, בדיוק כמו בבחינה.</li><li><strong>חזרה על טעויות.</strong> כל שאלה שטעיתם בה חוזרת אליכם בתרגול ייעודי, עד שהיא יושבת.</li></ul><h3>שיטת העבודה המומלצת</h3><ul><li>בכל שאלה בבחינה: מזהים קודם <strong>איזה חוק</strong> (מתווכים? מקרקעין? חוזים? מכר דירות?), ואז <strong>איזה כלל</strong>, ורק אז קוראים את החלופות.</li><li>שמים לב למילים "אך ורק", "בכל מקרה", "לעולם". חלופה מוחלטת היא לרוב מלכודת, כי לרוב הכללים יש חריג.</li><li>בחלופות שמתחילות ב"פעל כדין" או "לא פעל כדין": קודם מכריעים כן או לא, וזה מצמצם לשתי חלופות. אחר כך בוחרים את <strong>הנימוק</strong> הנכון, כי שתי החלופות שנשארו נבדלות רק בו.</li></ul>', '["25 שאלות, 4 נקודות כל אחת, שעתיים, ציון עובר 60 (15 נכונות).", "אין ניקוד שלילי: תמיד מסמנים תשובה.", "חומר פתוח: חוברת החוקים ותקנות האתיקה מחולקות באולם. הבחינה בודקת הבנה והתמצאות, לא שינון.", "כשליש מהשאלות על חוק המתווכים והתקנות, והשאר מדיני מקרקעין, חוזים, מכר דירות, הגנת הדייר, מיסוי ותכנון.", "בכל שאלה: איזה חוק, איזה כלל, ורק אז החלופות. חלופה מוחלטת היא לרוב מלכודת."]'::jsonb, '[{"type": "concept", "title": "25 שאלות, שעתיים, ציון עובר 60", "text": "כל שאלה שווה 4 נקודות. 15 תשובות נכונות מספיקות כדי לעבור. אין ניקוד שלילי, אז תמיד מסמנים תשובה.", "icon": "🎯"}, {"type": "concept", "title": "הבחינה היא עם חומר פתוח", "text": "באולם מחלקים את ספר החוקים ואת תקנות האתיקה. לא בודקים אם שיננתם סעיפים, אלא אם אתם יודעים איזה כלל חל ואיפה למצוא אותו.", "icon": "📖"}, {"type": "check", "question": "intro-q1"}, {"type": "concept", "title": "רק שליש מהשאלות על חוק המתווכים", "text": "במבחן יולי 2026: 7 שאלות על חוק המתווכים והתקנות, 8 על חוק המקרקעין, והשאר חוזים, מכר דירות, הגנת הדייר, מיסוי ותכנון.", "icon": "📊"}, {"type": "example", "title": "איך נראית שאלה", "text": "\"רפאל הוא מתווך מוסמך. הוא פונה לבעל דירה שפרסם ''למכירה'' בלי לספר שהוא מתווך, ומציע את הנכס ללקוחותיו. האם פעל כדין?\"", "law": "זה הדפוס של כמעט כל שאלה: סיפור קצר, ואז \"כדין או לא כדין, ולמה\". קודם מכריעים כן או לא, ורק אז בוחרים נימוק. עכשיו נסו אחת כזו בעצמכם."}, {"type": "check", "question": "intro-fee-conditions"}, {"type": "concept", "title": "חלופה מוחלטת היא לרוב מלכודת", "text": "\"אך ורק\", \"בכל מקרה\", \"לעולם\". לרוב הכללים בחוק יש חריג, וחלופה שלא משאירה לו מקום היא חשודה. חשודה, לא פסולה: בודקים אותה מול הסעיף.", "icon": "⚠️"}, {"type": "concept", "title": "איך הקורס עובד", "text": "כל שיעור הוא צעדים קצרים עם בדיקה אחרי כל רעיון. שיעור נחשב הושלם בציון 60 ומעלה. הסימולציה מגרילה 25 שאלות מהמבחנים האמיתיים.", "icon": "🧭"}]'::jsonb, 'הוראות לנבחן/ת, רשם המתווכים במקרקעין', null, true, true
  from public.course_chapters c where c.slug = 'intro'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'intro-q1', l.chapter_id, l.id, 'practice', null, 'כמה תשובות נכונות צריך כדי לעבור את בחינת רשם המתווכים?', '["20 מתוך 25", "15 מתוך 25", "13 מתוך 25", "תלוי במועד"]'::jsonb, 1, null, 'ציון העובר הוא 60, וכל שאלה שווה 4 נקודות: 15 תשובות נכונות מתוך 25.', 'הוראות הנבחן/ת', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'intro' and l.slug = 'exam-format'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'intro-fee-conditions', l.chapter_id, l.id, 'practice', null, 'אורן, מתווך בעל רישיון בתוקף, החתים את גלית על הזמנה בכתב למכירת דירתה, בלי בלעדיות. הוא הביא קונה, והצדדים חתמו על חוזה מכר. גלית מסרבת לשלם דמי תיווך בטענה שלא חתמה על הסכם בלעדיות. מה הדין?', '["אורן אינו זכאי. בלי הסכם בלעדיות אין זכאות לדמי תיווך, גם אם הביא את הקונה.", "אורן זכאי. רישיון בתוקף, הזמנה בכתב והיותו הגורם היעיל הם התנאים, ובלעדיות אינה תנאי.", "אורן זכאי רק אם יוכיח שביצע את כל פעולות השיווק המנויות בתקנות פעולות השיווק.", "אורן זכאי למחצית מדמי התיווך בלבד, כי בלי בלעדיות אין חזקת גורם יעיל."]'::jsonb, 1, null, 'סעיף 14(א) לחוק המתווכים מונה שלושה תנאים מצטברים: רישיון בתוקף, הזמנה בכתב לפי סעיף 9, והמתווך היה הגורם היעיל להתקשרות. בלעדיות אינה תנאי; היא רק מקימה חזקה שהמתווך היה הגורם היעיל (סעיף 14(ב)). השאלה הזו חוזרת כמעט בכל מועד, למשל אוגוסט 2024.', 'סעיף 14(א) לחוק המתווכים', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'intro' and l.slug = 'exam-format'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

-- ---- פרק: brokers-law
insert into public.course_chapters (slug, title, summary, position, published)
values ('brokers-law', 'חוק המתווכים במקרקעין, התשנ"ו-1996, ושלוש התקנות', 'שישה סעיפים שחוזרים כמעט בכל מועד: הגדרת התיווך והרישיון, סעיף 8, הזמנה בכתב, בלעדיות ופעולות שיווק, דמי תיווך והגורם היעיל, עניין אישי וסודיות, והמשמעת. עם פסקי הדין שהבחינה מצטטת.', 2, true)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary,
  position = excluded.position, published = true;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'law-scope', 'מה זה תיווך, ומי מותר לו לעסוק בו', 1, 'החוק פותח בהגדרה אחת שמכריעה המון שאלות: תיווך הוא הפגשה בתמורה. מי שעושה את זה בלי רישיון עובר עבירה, ומי שמעסיק אותו גם.', '<h3>סעיף 1: ההגדרות</h3><p><strong>תיווך במקרקעין</strong> הוא הפגשה בתמורה בין שני צדדים או יותר, לשם התקשרותם בעסקה בזכות במקרקעין. שלוש מילים חשובות: <strong>הפגשה</strong> (לא שיווק של נכס משלך), <strong>בתמורה</strong> (טובה לחבר בלי תשלום אינה תיווך), ו<strong>זכות במקרקעין</strong>, רשומה או לא, מכוח חוזה או מכוח חוק הגנת הדייר, וגם זכות באיגוד מקרקעין.</p><p><strong>לקוח</strong> הוא צד להסכם עם מתווך לקבלת שירותיו, <strong>בין אם הוא משלם דמי תיווך ובין אם לאו</strong>. כלומר כל חובות המתווך חלות גם על מי שמקבל שירות בחינם.</p><h3>סעיף 2: אין עיסוק בלי רישיון</h3><p>לא יעסוק אדם בתיווך אלא אם הוא בעל רישיון בתוקף, ולא יציג את עצמו כמתווך, לא יפרסם שהוא מתווך ולא ישתמש בתואר שיוצר רושם כזה. <strong>החריג (סעיף 2(ג))</strong>: מי שמפרסם מידע על מעוניינים בעסקאות (בעיתון, באתר, בכל דרך) אינו עובר על החוק, ובלבד שאינו מציג את עצמו כמתווך. כך עובד של חברה יזמית שמשווק את דירות החברה אינו "מתווך": הוא פועל בשם צד לעסקה ולא מפגיש בין זרים.</p><h3>סעיף 13: העסקה</h3><p>אסור להעסיק אדם בתיווך אלא אם הוא בעל רישיון בתוקף. החריג: תפקיד מינהלי (מזכירות, הנהלת חשבונות). בפסק דין דה כהן נ'' עמרם נקבע שתאגיד רשאי לתת שירותי תיווך, כל עוד פעולות התיווך עצמן נעשות בידי מתווכים מורשים: הרישיון הוא אישי.</p><h3>סעיף 15: העונש</h3><p>מי שמפר את סעיף 2 (עיסוק בלי רישיון) או את סעיף 13 (העסקת מי שאין לו רישיון): מאסר שנה וקנס. אלה שתי העבירות שחוק המתווכים עצמו מעניש עליהן. שאר החובות (8, 10, 11) הן אזרחיות ומשמעתיות. סעיף 12 (מסמכים משפטיים) שולל דמי תיווך, ועריכת מסמך כזה עלולה להיות עבירה לפי חוק לשכת עורכי הדין, כפי שנפסק במדינת ישראל נ'' אופז.</p>', '["תיווך במקרקעין: הפגשה בתמורה בין צדדים לעסקה בזכות במקרקעין (סעיף 1).", "לקוח הוא מי שהתקשר עם מתווך לקבלת שירות, גם אם אינו משלם דמי תיווך.", "סעיף 2: אין עיסוק בתיווך ואין הצגה עצמית כמתווך בלי רישיון בתוקף. חריג: מפרסם מידע שאינו מציג עצמו כמתווך.", "סעיף 13: מעסיקים בתיווך רק בעלי רישיון, חוץ מתפקיד מינהלי. תאגיד יכול לתווך דרך מתווכים מורשים.", "סעיף 15: הפרת סעיף 2 או 13 היא עבירה פלילית לפי חוק המתווכים, מאסר שנה וקנס. סעיף 12 שולל דמי תיווך, והפלילי שם מגיע מחוק לשכת עורכי הדין."]'::jsonb, '[{"type": "concept", "title": "תיווך = הפגשה בתמורה", "text": "סעיף 1: הפגשה בתמורה בין שני צדדים או יותר לשם עסקה בזכות במקרקעין. בלי \"הפגשה\" אין תיווך, ובלי \"תמורה\" אין תיווך.", "icon": "🤝"}, {"type": "concept", "title": "לקוח גם בלי תשלום", "text": "לקוח הוא צד להסכם עם המתווך לקבלת שירותיו, בין אם משלם דמי תיווך ובין אם לאו. חובות המתווך חלות גם על מי שמקבל שירות בחינם.", "icon": "🙋"}, {"type": "check", "question": "law-scope-1"}, {"type": "concept", "title": "סעיף 2: רישיון או כלום", "text": "אסור לעסוק בתיווך, להתפרסם כמתווך או להשתמש בתואר שנשמע כמו מתווך בלי רישיון בתוקף. חריג: מי שמפרסם מידע על מעוניינים ואינו מציג עצמו כמתווך.", "icon": "🪪"}, {"type": "example", "title": "שאלה 11, מאי 2024", "text": "נדב, בלי רישיון, הציע לחבר שמחפש דירה לקשר אותו עם חבר אחר שמוכר, תמורת 1% מהעסקה.", "law": "זה תיווך: הפגשה בתמורה. בלי רישיון זו עבירה פלילית לפי סעיפים 2 ו-15 (מדינת ישראל נ'' דוידסון), לא רק אובדן דמי התיווך."}, {"type": "check", "question": "law-scope-2"}, {"type": "concept", "title": "סעיף 13: מעסיקים רק בעלי רישיון", "text": "אסור להעסיק אדם בתיווך אלא אם יש לו רישיון בתוקף. חריג: תפקיד מינהלי. תאגיד רשאי לתווך, כל עוד מי שמתווך בפועל מורשה (דה כהן נ'' עמרם).", "icon": "🏢"}, {"type": "concept", "title": "סעיף 15: מאסר שנה", "text": "חוק המתווכים מעניש על שתיים: עיסוק בלי רישיון (2) והעסקת מי שאין לו רישיון (13). מאסר שנה וקנס. סעיפים 8, 10 ו-11 הם אזרחיים ומשמעתיים; סעיף 12 שולל דמי תיווך, והפלילי שם מגיע מחוק לשכת עורכי הדין.", "icon": "⚖️"}, {"type": "check", "question": "law-scope-3"}, {"type": "check", "question": "law-scope-4"}]'::jsonb, 'סעיפים 1, 2, 13 ו-15 לחוק', null, false, true
  from public.course_chapters c where c.slug = 'brokers-law'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'law-scope-1', l.chapter_id, l.id, 'practice', null, 'מתווך בעל רישיון עזר לזוג עולים חדשים למצוא דירה בהתנדבות, בלי דמי תיווך, ולא גילה להם על חריגת בנייה שידע עליה. הזוג טוען שהמתווך הפר את חובותיו. המתווך משיב שהם לא היו לקוחות, כי לא שילמו. מה הדין?', '["המתווך צודק. לקוח לפי החוק הוא רק מי שמשלם דמי תיווך, ולכן החובות אינן חלות.", "המתווך צודק, אלא אם הזוג חתם על הזמנה בכתב, ואז הוא נחשב לקוח גם בלי תשלום.", "הזוג צודק. לקוח הוא מי שהתקשר עם המתווך לקבלת שירותיו, גם אם אינו משלם, וחובת הגילוי חלה.", "הזוג צודק רק אם יוכיח שהמתווך קיבל תמורה מהמוכר, כי בלי תמורה אין תיווך."]'::jsonb, 2, null, 'סעיף 1 מגדיר "לקוח" כצד להסכם עם מתווך לקבלת שירותיו, בין אם הוא משלם דמי תיווך ובין אם לאו. חובת הנאמנות, ההגינות ומסירת המידע המהותי שבסעיף 8 חלה על כל לקוח, ותיווך בהתנדבות אינו אסור. חריגת בנייה היא מידע מהותי מובהק. השאלה הזו נשאלה ביולי 2023.', 'סעיף 1 (הגדרת "לקוח"), סעיף 8 לחוק', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'law-scope'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'law-scope-2', l.chapter_id, l.id, 'practice', null, 'עובד שכיר של חברה קבלנית, שאין לו רישיון תיווך, מציג לרוכשים את הדירות שהחברה בונה, מפרסם אותן ומוסר פרטים על הזכויות. האם הוא עובר על חוק המתווכים?', '["כן. כל מי שמציג נכסים ומוסר פרטים על זכויות במקרקעין חייב רישיון תיווך.", "כן, אלא אם מתווך בעל רישיון מפקח עליו וחתום על הזמנה בכתב מול כל רוכש.", "לא, ובלבד שאינו מציג את עצמו כמתווך במקרקעין. הוא משווק בשם צד לעסקה ולא מפגיש בין זרים.", "לא, ובלבד שאינו מוסר לרוכשים מידע מהותי על הנכס, שאותו רק מתווך רשאי למסור."]'::jsonb, 2, null, 'סעיף 2(ג): החוק אינו חל על מי שמפרסם מידע ופרטים על מעוניינים בעסקאות במקרקעין, ובלבד שאינו מציג עצמו כמתווך. ומעבר לכך, עובד החברה אינו "מפגיש בין צדדים" לפי סעיף 1 אלא פועל בשם המוכרת עצמה. אין בחוק דרישה לפיקוח של מתווך ואין איסור למסור מידע. זו שאלה 19 במבחן פברואר 2025.', 'סעיפים 1 ו-2(ג) לחוק', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'law-scope'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'law-scope-3', l.chapter_id, l.id, 'practice', null, 'בעל משרד תיווך העסיק סוכן שרישיונו פקע לפני שנה, והסוכן המשיך להראות דירות ולהחתים לקוחות. מה חשוף לו בעל המשרד?', '["רק להליך משמעתי, כי העסקה בלי רישיון אינה עבירה פלילית אלא הפרת כללי אתיקה.", "לעבירה פלילית לפי סעיפים 13 ו-15: מאסר שנה וקנס, בלי קשר לדמי התיווך.", "לשלילת דמי התיווך בעסקאות שהסוכן ביצע בלבד, כי החוק אינו מעניש מעסיקים.", "לכלום, כי האחריות על הרישיון היא של הסוכן עצמו ולא של מי שמעסיק אותו."]'::jsonb, 1, null, 'סעיף 13 אוסר להעסיק אדם בתיווך אלא אם הוא בעל רישיון בתוקף (חריג: תפקיד מינהלי), וסעיף 15 קובע שהמפר את סעיף 2 או 13 דינו מאסר שנה וקנס. אלה שתי העבירות שחוק המתווכים עצמו מעניש עליהן, ושאלה 15 במבחן ינואר 2023 בדקה בדיוק את ההבחנה הזו מול החובות האזרחיות (8, 10, 11).', 'סעיפים 13 ו-15 לחוק', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'law-scope'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'law-scope-4', l.chapter_id, l.id, 'practice', null, 'חברת תיווך בע"מ מפרסמת את עצמה ומחתימה לקוחות על הזמנות בכתב על שם החברה. בעל החברה הוא מתווך מורשה, וגם כל הסוכנים שעובדים מולו. האם המבנה הזה חוקי?', '["לא. רישיון תיווך הוא אישי, ולכן רק אדם פרטי רשאי לתת שירותי תיווך ולהחתים לקוחות.", "לא, כי בהזמנה בכתב חייבים להופיע שם ומספר זהות של מתווך, ולחברה אין מספר זהות.", "כן, כל עוד בעל החברה מורשה, גם אם מי שמתווך בפועל אינו בעל רישיון.", "כן. תאגיד רשאי לתת שירותי תיווך, ובלבד שפעולות התיווך עצמן נעשות בידי בעלי רישיון."]'::jsonb, 3, null, 'בפסק דין דה כהן נ'' עמרם (ע"א 3455/06) נקבע שהחוק אינו אוסר על תאגיד לעסוק בתיווך, אבל הרישיון הוא אישי: סעיף 13 דורש שמי שמבצע את פעולות התיווך יהיה בעל רישיון. רישיון של הבעלים לבדו אינו מספיק אם הסוכנים אינם מורשים. זו שאלה 13 במבחן אוגוסט 2024.', 'סעיף 13 לחוק; ע"א 3455/06 דה כהן נ'' עמרם', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'law-scope'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'license', 'הרישיון: תנאים, בחינה, אגרה והתליה מרצון', 2, 'שישה תנאים לרישיון, ואחד מהם הוא הבחינה שאתם לומדים אליה עכשיו. הפרטים הקטנים כאן, כמו שישה חודשים אחרי מאסר או חמש שנות תוקף לתוצאה, הם בדיוק מה שנשאל.', '<h3>סעיף 5: מי רשאי לקבל רישיון</h3><ul><li>אזרח או תושב ישראל, או תושב חוץ עם היתר עבודה כדין.</li><li>מלאו לו 18 שנים.</li><li>אינו פושט רגל.</li><li>לא הורשע בעבירה שמפאת מהותה, חומרתה ונסיבותיה אינו ראוי לשמש מתווך.</li><li>אם נידון למאסר בפועל, סיים לרצות אותו <strong>שישה חודשים לפחות</strong> לפני הגשת הבקשה.</li><li>עמד בהצלחה בבחינה.</li></ul><p>הרשם רשאי לבטל רישיון של מי שחדל להיות תושב או הפך לפושט רגל, ורשאי לסרב לתת רישיון למי שאינו ראוי לפי עובדות אחרות, בשני המקרים אחרי התייעצות בוועדה המייעצת ומתן הזדמנות לטעון.</p><h3>סעיף 6 ותקנות 1997: הבחינה</h3><p>הבחינה בכתב, רב-ברירה, שעתיים, לפחות פעמיים בשנה. <strong>60 נקודות עוברות.</strong> הרשם מודיע על התוצאות תוך 30 ימים בדואר רשום, התוצאה <strong>תקפה חמש שנים</strong> (מי שלא קיבל רישיון בתקופה הזו נבחן שוב), ומי שנכשל רשאי לערור בכתב תוך 30 ימים. מותר להשתמש במילון ובחומר שהרשם אישר; מי שנתפס עם חומר אסור או מפריע, בחינתו מופסקת ולא נקבע לו ציון.</p><h3>סעיף 18 ותקנות 12-13: אגרות</h3><p>שלוש אגרות: בחינה, אגרת רישיון חד-פעמית, ואגרה שנתית שמשולמת עד 31 במרס. מי שקיבל רישיון לראשונה פטור מהאגרה השנתית באותה שנה. <strong>מי שלא שילם את האגרה במועד אינו רשאי לשמש מתווך</strong> עד שישלם אותה בתוספת ריבית והצמדה, וזה נוגע ישירות לזכאות לדמי תיווך (סעיף 14(א)(1)).</p><h3>סעיף 17א: התליה מרצון</h3><p>מתווך שאינו רוצה לעסוק בתיווך רשאי להתלות את רישיונו בהודעה מראש ובכתב לרשם. מהינואר שאחרי ההודעה אינו משלם אגרה שנתית; מי ששילם כבר אינו מקבל החזר; וכשהוא מבטל את ההודעה הוא משלם אגרה יחסית לחודשים שנותרו. ההתליה מרצון אינה מנתקת אותו מהשיפוט המשמעתי על מה שעשה לפניה (סעיף 14ל).</p>', '["שישה תנאים לרישיון: תושבות, גיל 18, לא פושט רגל, לא הורשע בעבירה שמונעת, מאסר בפועל נגמר לפני שישה חודשים לפחות, ובחינה.", "הבחינה: רב-ברירה, שעתיים, 60 נקודות עוברות, תוצאה בתוך 30 ימים ותקפה חמש שנים, ערר תוך 30 ימים.", "אגרה שנתית עד 31 במרס; מי שלא שילם אינו רשאי לשמש מתווך עד התשלום. שנה ראשונה פטורה.", "מעבר הבחינה אינו רישיון: הרישיון ניתן אחרי בקשה ואגרה, ורק מאז מותר לעסוק.", "התליה מרצון (17א): הודעה בכתב, בלי אגרה מהינואר הבא, בלי החזר, ושיפוט משמעתי נמשך."]'::jsonb, '[{"type": "concept", "title": "שישה תנאים לרישיון", "text": "תושבות או היתר עבודה, גיל 18, לא פושט רגל, לא הורשע בעבירה שמונעת, ומי שנידון למאסר בפועל סיים אותו לפחות שישה חודשים לפני הבקשה. והבחינה.", "icon": "📋"}, {"type": "check", "question": "license-1"}, {"type": "concept", "title": "הבחינה במספרים", "text": "רב-ברירה, שעתיים, 60 נקודות עוברות. תוצאה תוך 30 ימים, תקפה חמש שנים, ערר תוך 30 ימים. לפחות שני מועדים בשנה.", "icon": "📝"}, {"type": "check", "question": "license-2"}, {"type": "concept", "title": "בחינה אינה רישיון", "text": "מי שעבר את הבחינה עדיין לא מתווך. הרישיון ניתן אחרי בקשה ותשלום אגרה, ורק מאז מותר לעסוק ולגבות דמי תיווך.", "icon": "🪪"}, {"type": "example", "title": "שאלה 3, מאי 2025", "text": "יחזקאל עבר את הבחינה לפני ארבע שנים ולא שילם את אגרת הרישיון. הוא החתים לקוח על הזמנה תקינה, מצא לו דירה, והלקוח חתם על חוזה. יומיים אחרי זה שילם יחזקאל את האגרה.", "law": "אין דמי תיווך: סעיף 14(א)(1) דורש רישיון בתוקף בעת העיסוק, ותשלום בדיעבד אינו מרפא. ולפי סעיף 2 העיסוק עצמו היה אסור."}, {"type": "concept", "title": "אגרה שנתית עד 31 במרס", "text": "מי שלא שילם אינו רשאי לשמש מתווך עד שישלם, עם ריבית והצמדה. בשנת הרישיון הראשונה אין אגרה שנתית.", "icon": "💳"}, {"type": "check", "question": "license-3"}, {"type": "concept", "title": "התליה מרצון", "text": "הודעה מראש ובכתב לרשם. מהינואר הבא אין אגרה; מי ששילם כבר לא מקבל החזר; חזרה לעבודה מחייבת אגרה יחסית. השיפוט המשמעתי נמשך על מה שקדם.", "icon": "⏸️"}, {"type": "check", "question": "license-4"}]'::jsonb, 'סעיפים 5, 6, 17א ו-18 לחוק; תקנות המתווכים, התשנ"ז-1997', null, false, true
  from public.course_chapters c where c.slug = 'brokers-law'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'license-1', l.chapter_id, l.id, 'practice', null, 'ארבעה אנשים הגישו בקשה לרישיון תיווך אחרי שעברו את הבחינה. מי מהם אינו עומד בתנאי סעיף 5 לחוק?', '["בן 19 שעובד כשכיר במשרד תיווך כעוזר מינהלי מאז שהיה בן 17.", "מי שנפתחו נגדו שלושה תיקי הוצאה לפועל בגלל חובות לבנק.", "מי שסיים לרצות מאסר בפועל ארבעה חודשים לפני הגשת הבקשה.", "מי שנכשל בבחינה שלוש פעמים לפני שעבר אותה במועד הרביעי."]'::jsonb, 2, null, 'סעיף 5(א)(5): מי שנידון למאסר בפועל חייב לסיים לרצות אותו שישה חודשים לפחות לפני הגשת הבקשה. ארבעה חודשים אינם מספיקים. גיל המינימום הוא 18 (לא 21), תיקי הוצאה לפועל אינם פשיטת רגל, ולפי סעיף 6(ב) מי שנכשל רשאי לשוב ולהיבחן בלי הגבלה. השאלה הזו נשאלה במאי 2023.', 'סעיף 5(א) לחוק', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'license'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'license-2', l.chapter_id, l.id, 'practice', null, 'דנה עברה את הבחינה בציון 64 ביולי 2020. היא דחתה את הבקשה לרישיון, ובאוגוסט 2026 הגישה אותה לראשונה. מה הדין?', '["הרשם ייתן לה רישיון. הבחינה עברה והציון מעל 60, ואין מגבלת זמן על הגשת הבקשה.", "הרשם ייתן לה רישיון רק אם תשלם את האגרות השנתיות לכל השנים שחלפו מאז הבחינה.", "היא תצטרך להיבחן שוב. תוקף תוצאת הבחינה הוא חמש שנים, וחלפו יותר משש.", "היא תצטרך להיבחן שוב, כי ציון 64 נחשב עובר רק אם הבקשה הוגשה באותה שנה."]'::jsonb, 2, null, 'תקנה 8(ב) לתקנות המתווכים, התשנ"ז-1997: תוקפן של תוצאות הבחינה יפה לחמש שנים בלבד, ומי שלא קיבל רישיון בתקופה הזו נבחן שוב. 60 נקודות הן ציון עובר בכל מקרה (תקנה 7(ב)), ואגרה שנתית משולמת רק על רישיון קיים.', 'תקנות 7 ו-8 לתקנות המתווכים, התשנ"ז-1997', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'license'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'license-3', l.chapter_id, l.id, 'practice', null, 'מתווך ותיק שכח לשלם את האגרה השנתית עד 31 במרס, והמשיך לתווך. באפריל הביא קונה לדירה, וביוני, אחרי ששילם את האגרה עם ריבית, דרש דמי תיווך. מה מעמדו באפריל?', '["רישיונו נשאר בתוקף, כי אגרה היא חוב כספי שאינו משפיע על הרישיון עד שהרשם מבטל אותו.", "הוא לא היה רשאי לשמש מתווך כל עוד לא שילם, ולכן חסר לו התנאי של רישיון בתוקף בעת העיסוק.", "רישיונו פקע סופית, ועליו להיבחן שוב לפני שיוכל לבקש רישיון חדש.", "הוא היה רשאי לתווך, ובלבד שגילה ללקוח בכתב שהאגרה טרם שולמה."]'::jsonb, 1, null, 'סעיף 18(ב): בעל רישיון שלא שילם את האגרה במועדה אינו רשאי לשמש מתווך כל עוד לא שילם אותה בתוספת ריבית והצמדה. התשלום המאוחר מחזיר אותו לעבודה, אבל אינו מרפא את התקופה שבה עסק בלי זכות, וסעיף 14(א)(1) דורש רישיון בתוקף בעת העיסוק. הרישיון אינו פוקע סופית ואין צורך בבחינה חדשה.', 'סעיף 18(ב) לחוק; תקנה 13 לתקנות המתווכים, התשנ"ז-1997', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'license'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'license-4', l.chapter_id, l.id, 'practice', null, 'מתווכת החליטה לצאת לשנת חופש והודיעה לרשם בכתב בחודש מאי על התליית רישיונה מרצון, אחרי ששילמה את האגרה לאותה שנה. מה נכון?', '["היא תקבל החזר יחסי על שבעת החודשים שנותרו בשנה, ולא תשלם אגרה בשנה הבאה כל עוד ההתליה נמשכת.", "היא לא תקבל החזר על מה ששילמה, ומהינואר הבא לא תחויב באגרה שנתית כל עוד לא ביטלה את ההודעה.", "ההתליה מרצון פוטרת אותה מאגרה רק אם תימשך שנתיים לפחות, אחרת האגרה נגבית כרגיל.", "ההתליה מרצון מנתקת אותה מסמכות ועדת המשמעת גם על מעשים שקדמו לה."]'::jsonb, 1, null, 'סעיף 17א: מי ששילם אגרה שנתית ואז התלה מרצון אינו זכאי להחזר (ס"ק (ג)), ומהחודש ינואר הראשון שאחרי ההודעה אינו מחויב באגרה כל עוד לא ביטל אותה (ס"ק (ב)). אין תקופת מינימום. וסעיף 14ל קובע שהשיפוט המשמעתי נמשך על מה שאירע לפני ההתליה, כפי שנשאל ביולי 2026.', 'סעיפים 17א ו-14ל לחוק', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'license'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'duty-of-care', 'סעיף 8: נאמנות, הגינות, ומידע מהותי שצריך גם לברר', 3, 'סעיף 8 הוא הסעיף שהכי הרבה פסקי דין נבנו עליו. שני תת-סעיפים: למסור כל מידע מהותי שיש בידכם, ולנקוט אמצעים כדי להשיג אותו. "לא ידעתי" אינו הגנה כשהיה צריך לבדוק.', '<h3>סעיף 8(א): נאמנות, הגינות ודרך מקובלת</h3><p>מתווך יפעל בנאמנות, בהגינות ובדרך מקובלת, וימסור ללקוחו <strong>כל מידע שיש בידו בעניין מהותי</strong> הנוגע לנכס. החובה חלה כלפי כל לקוח, גם כלפי הצד שאינו משלם.</p><h3>סעיף 8(ב): מיומנות, סבירות ובירור</h3><p>במילוי תפקידו יפעל המתווך במיומנות ובסבירות <strong>וינקוט אמצעים הראויים בנסיבות העניין לקבלת מידע מהותי</strong>. זו חובת בירור אקטיבית: נסח רישום, היתר בנייה, זהות הבעלים. מתווך שלא בדק אינו יכול להסתתר מאחורי "לא ידעתי".</p><h3>מה נקבע בפסיקה</h3><ul><li><strong>מאיר נ'' שושן (בר"ע 209/01)</strong>: קונים ביקשו דירה "בלי הפתעות", והתברר שחלקה נבנה בלי היתר. המתווכת לא ידעה, אבל הייתה חייבת לברר. הפרת סעיף 8 שוללת את דמי התיווך.</li><li><strong>נדב נ'' ינובסקי (ע"א 3597/09)</strong>: מתווך שהסתיר מהמוכר שהקונה שילם יותר ושלשל את ההפרש לכיסו חייב להשיב אותו למוכר. הכסף ששולם עבור הנכס שייך למוכר.</li><li><strong>סויסה נ'' זאגה (ע"א 2469/06)</strong>: מתווך שקנה קרקע מקשישים והסתיר תוכנית לשינוי ייעוד. העובדה שהמידע היה גלוי לכל אינה פוטרת אותו, והחוזה ניתן לביטול בשל הטעיה.</li><li><strong>ב.פ. הנשיא נ'' בקרמן</strong>: מתווכת שסירבה להעביר הצעה נמוכה הפרה את חובתה, ולא הייתה הגורם היעיל.</li></ul><p>תקנות האתיקה מ-2024 פירטו את החובה הזו: תקנה 4 (איסור הטעיה גם במחדל), תקנה 7 והתוספת הראשונה (רשימת המידע המהותי ונסח הרישום), תקנה 14 (העברת כל הצעה).</p>', '["סעיף 8(א): נאמנות, הגינות ודרך מקובלת, ומסירת כל מידע מהותי שבידי המתווך.", "סעיף 8(ב): מיומנות וסבירות, ואמצעים ראויים לקבלת מידע מהותי. \"לא ידעתי\" אינו הגנה כשהיה צריך לבדוק.", "מאיר נ'' שושן: מתווך שלא בירר חריגות בנייה הפר את חובתו ואינו זכאי לדמי תיווך.", "נדב נ'' ינובסקי: הפרש מחיר שהמתווך שלשל לכיסו שייך למוכר ומוחזר לו.", "סויסה נ'' זאגה: מידע מהותי שגלוי לכל עדיין חייבים לגלות; הסתרה היא הטעיה."]'::jsonb, '[{"type": "concept", "title": "8(א): למסור כל מידע מהותי", "text": "נאמנות, הגינות ודרך מקובלת, וכל מידע שיש בידי המתווך בעניין מהותי הנוגע לנכס. החובה חלה כלפי כל לקוח, גם כלפי מי שאינו משלם.", "icon": "🔍"}, {"type": "concept", "title": "8(ב): לברר, לא רק למסור", "text": "מיומנות וסבירות, ואמצעים ראויים לקבלת מידע מהותי. נסח, היתר, זהות הבעלים. מתווך שלא בדק אינו יכול לומר \"לא ידעתי\".", "icon": "🧭"}, {"type": "example", "title": "שאלה 14, מאי 2025", "text": "בני זוג ביקשו ממתווך דירה \"ללא חריגות וללא הפתעות\". נמצאה דירה, נחתם חוזה, ואז התגלה שחלק מהדירה נבנה בלי היתר. הזוג ביטל את החוזה.", "law": "מאיר נ'' שושן: המתווך היה חייב לברר פרטים מהותיים כאלה, במיוחד כשהלקוח ביקש זאת במפורש. מי שהפר את סעיף 8 אינו זכאי לדמי תיווך."}, {"type": "check", "question": "duty-of-care-1"}, {"type": "concept", "title": "מה שגלוי לכולם עדיין מגלים", "text": "סויסה נ'' זאגה: מתווך שהסתיר מידע תכנוני מהותי אינו נפטר בטענה שהמידע היה זמין לציבור. הסתרה היא הטעיה, והחוזה ניתן לביטול.", "icon": "📰"}, {"type": "check", "question": "duty-of-care-2"}, {"type": "concept", "title": "הכסף של העסקה שייך ללקוח", "text": "נדב נ'' ינובסקי: מתווך שהסתיר מהמוכר את המחיר שהקונה שילם בפועל ולקח את ההפרש חייב להשיב אותו. דמי תיווך נגבים רק לפי ההזמנה, לא דרך המחיר.", "icon": "💸"}, {"type": "check", "question": "duty-of-care-3"}, {"type": "check", "question": "duty-of-care-4"}]'::jsonb, 'סעיף 8 לחוק', null, false, true
  from public.course_chapters c where c.slug = 'brokers-law'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'duty-of-care-1', l.chapter_id, l.id, 'practice', null, 'מתווך הציג לקונה דירה בקומה אחרונה, והקונה התנה את הרכישה בכך שאפשר להוסיף שני חדרים על הגג. המתווך אישר שיש היתר, אבל ידע ולא אמר שההיתר פג בעוד חודשיים. החוזה נחתם, ההיתר פג, והקונה תובע. מה הדין?', '["הקונה היה צריך לבדוק בעצמו בעירייה. חובת הבדיקה של הקונה פוטרת את המתווך.", "מתווך אינו מוסמך לייעץ בתכנון ובנייה, ולכן מה שאמר על ההיתר אינו מחייב אותו.", "המתווך הפר את סעיף 8: תוקף ההיתר היה מידע מהותי שבידו, והוא היה חייב לגלותו.", "המתווך הפר את חובתו רק אם ייצג גם את המוכר, כי אז היה לו עניין בהשלמת העסקה."]'::jsonb, 2, null, 'סעיף 8(א) מחייב למסור ללקוח כל מידע מהותי שבידי המתווך, וכאן הקונה התנה את העסקה כולה באפשרות הבנייה. המתווך ידע ושתק. חובת הבדיקה של הלקוח אינה מבטלת את חובת הגילוי של המתווך, והאיסור לייעץ משפטית אינו רישיון להסתיר עובדה. השאלה הזו נשאלה בנובמבר 2024.', 'סעיף 8(א) לחוק; תקנות 4 ו-7(ג) לתקנות האתיקה', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'duty-of-care'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'duty-of-care-2', l.chapter_id, l.id, 'practice', null, 'מתווכת הראתה לקונה דירה, ואמרה שהיא "מושכרת" במחיר מציאה. במעמד החתימה אצל עורך הדין התברר שהדייר הוא דייר מוגן לפי חוק הגנת הדייר. הקונה סירב לחתום. המתווכת דורשת דמי תיווך כי הקונה חתם על הזמנה בכתב. מה הדין?', '["המתווכת זכאית. היא גילתה שיש שוכר, והפרטים המשפטיים של השכירות הם עניין לעורך הדין ולא לה.", "המתווכת זכאית, כי ההזמנה בכתב נחתמה והיא הגורם היעיל שהפגיש בין הצדדים.", "המתווכת אינה זכאית. דייר מוגן הוא מידע מהותי, כי זכויותיו שונות משל שוכר רגיל, ו\"יש שוכר\" לא גילה זאת.", "המתווכת אינה זכאית, כי בישראל כל שוכר נחשב דייר מוגן ולכן היה עליה לומר זאת בפירוש."]'::jsonb, 2, null, 'דייר מוגן אינו ניתן לפינוי בתום השכירות ומשלם דמי שכירות מופחתים, ולכן "יש שוכר" אינו מגלה את העיקר. סעיף 8(א) מחייב למסור כל מידע מהותי, והתוספת הראשונה לתקנות האתיקה מונה במפורש מחזיק שאינו הבעלים ומועד פינויו. בלי הסכם מכר אין בכלל זכאות לדמי תיווך לפי סעיף 14. רוב השכירויות כיום אינן מוגנות. זו שאלה 23 במבחן יולי 2025.', 'סעיף 8(א) לחוק; תקנה 7 והתוספת הראשונה לתקנות האתיקה', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'duty-of-care'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'duty-of-care-3', l.chapter_id, l.id, 'practice', null, 'מתווך ראה מודעה "פרטי, לא למתווכים" של דירה במיליון ש"ח. הוא הציע אותה לקונה כדירה של 1,050,000 ש"ח, החתים אותה על הזמנה עם 2% דמי תיווך, ותכנן להשאיר את ההפרש אצלו. הקונה גילתה את המחיר האמיתי אצל עורך הדין. האם המתווך פעל כדין?', '["כן. דמי תיווך מוגדלים מותרים כל עוד הם מדווחים כדין לרשויות המס.", "כן, כי הוא היה הגורם היעיל והזמנה בכתב נחתמה עם שיעור דמי תיווך ברור.", "לא. הוא הפר את חובת הנאמנות וההגינות כלפי הקונה כשמסר לה מחיר כוזב.", "לא, כי לא החתים גם את המוכר על הזמנה בכתב, ובלי שני לקוחות אין תיווך."]'::jsonb, 2, null, 'סעיף 8(א) מחייב נאמנות והגינות ומסירת כל מידע מהותי, והמחיר המבוקש הוא מידע מהותי מובהק. ניפוח המחיר כדי לגבות הפרש בסתר הוא הטעיה (תקנה 4 לתקנות האתיקה), ודמי תיווך נגבים רק לפי ההזמנה בכתב ולא דרך המחיר (ברוח נדב נ'' ינובסקי). מתווך רשאי לייצג רק את הקונה. זו שאלה 1 במבחן מאי 2025.', 'סעיף 8(א) לחוק; תקנה 4 לתקנות האתיקה', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'duty-of-care'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'duty-of-care-4', l.chapter_id, l.id, 'practice', null, 'מתווכת הציגה לקונה דירה וידעה שבחדר השינה רטיבות שאי אפשר לתקן בגלל שיפוע הגג, ושהיא מורידה את שווי הדירה. היא לא אמרה דבר, והקונה רכש. איזו טענה של המתווכת נכונה?', '["חובת הגילוי בחוק הגנת הצרכן חלה רק על מוצרים שנמכרים, ושירות תיווך אינו מוצר אלא שירות.", "המתווכת אינה \"עוסק\" לפי חוק הגנת הצרכן, ולכן רק חוק המתווכים חל עליה.", "אף טענה. גם חוק המתווכים וגם סעיף 4 לחוק הגנת הצרכן מחייבים לגלות פגם שמפחית משמעותית מערך הנכס.", "הקונה היה צריך לבדוק את הדירה עם איש מקצוע לפני הרכישה, ואי-בדיקה כזו פוטרת את המתווכת."]'::jsonb, 2, null, 'שתי מערכות חובה חלות יחד: סעיף 8 לחוק המתווכים (מידע מהותי שבידי המתווך) וסעיף 4 לחוק הגנת הצרכן, שמחייב עוסק, כולל נותן שירות, לגלות כל פגם שמפחית באופן משמעותי מערך הנכס. רטיבות שאינה ניתנת לתיקון היא בדיוק פגם כזה. זו שאלה 1 במבחן אוגוסט 2024.', 'סעיף 8 לחוק; סעיפים 1 ו-4 לחוק הגנת הצרכן', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'duty-of-care'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
