insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'written-order', 'סעיף 9(א): בלי הזמנה בכתב אין דמי תיווך', 4, 'חמישה פרטים חייבים להופיע בטופס, ובתי המשפט מבדילים בין פרט שחסר באמת לבין פגם טכני. כאן נמצאות שלוש מהשאלות הכי חוזרות בבחינה.', '<h3>סעיף 9(א)</h3><p>מתווך לא יהא זכאי לדמי תיווך אלא אם <strong>חתם הלקוח על הזמנה בכתב</strong> לביצוע פעולת תיווך, שנכללו בה כל הפרטים שקבע השר.</p><h3>תקנות פרטי הזמנה בכתב: חמשת הפרטים</h3><ol><li>שמות, כתובות ומספרי זיהוי של המתווך ושל הלקוח.</li><li>סוג העסקה: מכירה, שכירות.</li><li>תיאור הנכס.</li><li>מחיר העסקה המבוקשת, בקירוב.</li><li>דמי התיווך, בסכום או בשיעור מהמחיר, <strong>והאם הם כוללים מע"מ</strong>.</li></ol><h3>מהותי או טכני: מה נפסק</h3><ul><li><strong>כהן נ'' גולן (ת"ק 41268-09-12)</strong>: הזמנה שתיארה "מספר דירות בבניין" בלי לזהות נכס ובלי מחיר, והלקוח לא קיבל עותק. הלקוח שכר דירה אחרת בבניין ישירות מהבעלים. אין דמי תיווך: הפרטים חסרו, והמתווך לא היה הגורם היעיל.</li><li><strong>גופר נ'' קאופמן (ע"א 4582/08)</strong>: חסרו מספרי תעודות הזהות, אבל לא היה ספק מי המתווך ומי הלקוח. הדרישה מהותית ולא טכנית, ולכן הזכאות נשמרה.</li><li><strong>הודעת וואטסאפ</strong> שמציינת רק את גובה התשלום אינה הזמנה בכתב: חסרים ארבעה מחמשת הפרטים. השאלה שנשאלה על כך ביולי 2025 בוטלה במפתח הרשמי בגלל ניסוח, אבל הדין ברור. לעומת זאת, הזמנה מלאה שנשלחה במייל והלקוח אישר אותה במייל משלו נחשבת לפי מפתח התשובות של הרשם (מאי 2024) להסכם מחייב; הסעיף עצמו מדבר על "חתם הלקוח", ולכן הנקודה הזו מסומנת אצלנו לבדיקה משפטית.</li><li><strong>עוז נ'' עזרא (ת"א 35922/07)</strong>: דרישת הכתב חלה על היחסים מתווך-לקוח ונועדה להגן על הלקוח. הסכם בין שני מתווכים לחלוקת דמי תיווך הוא חוזה רגיל, ויכול להיכרת גם בעל פה.</li></ul>', '["סעיף 9(א): אין דמי תיווך בלי הזמנה בכתב שהלקוח חתם עליה, עם הפרטים שבתקנות.", "חמשת הפרטים: זיהוי הצדדים, סוג העסקה, תיאור הנכס, מחיר בקירוב, ודמי התיווך כולל התייחסות למע\"מ.", "כהן נ'' גולן: \"כמה דירות בבניין\" בלי זיהוי ובלי מחיר, ובלי עותק ללקוח, אינה הזמנה מספקת.", "גופר נ'' קאופמן: מספר זהות שחסר אינו שולל דמי תיווך כשאין ספק בזהות הצדדים.", "עוז נ'' עזרא: הסכם שיתוף פעולה בין מתווכים אינו טעון כתב."]'::jsonb, '[{"type": "concept", "title": "בלי כתב אין שכר", "text": "סעיף 9(א): מתווך לא יהיה זכאי לדמי תיווך אלא אם הלקוח חתם על הזמנה בכתב ובה כל הפרטים שקבע השר. זה התנאי השני בסעיף 14(א).", "icon": "✍️"}, {"type": "concept", "title": "חמישה פרטים", "text": "זיהוי שני הצדדים (שם, כתובת, מספר זהות), סוג העסקה, תיאור הנכס, מחיר בקירוב, ודמי התיווך בסכום או בשיעור, כולל אם הם כוללים מע\"מ.", "icon": "🧾"}, {"type": "check", "question": "written-order-1"}, {"type": "example", "title": "שאלה 6, מאי 2023", "text": "מתווך הראה ללקוח דירה להשכרה בבניין, לא ציין את מספר הדירה בטופס, ולא מסר ללקוח עותק. הלקוח שכר דירה אחרת באותו בניין.", "law": "כהן נ'' גולן: אין דמי תיווך. הנכס לא זוהה, הלקוח לא קיבל עותק, והמתווך לא היה הגורם היעיל לדירה שנשכרה."}, {"type": "check", "question": "written-order-2"}, {"type": "concept", "title": "מהותי מול טכני", "text": "גופר נ'' קאופמן: חסרו מספרי זהות, אבל זהות הצדדים לא הייתה במחלוקת. תכלית התקנה היא ודאות, לא טקס, ולכן הזכאות נשמרה.", "icon": "⚖️"}, {"type": "check", "question": "written-order-3"}, {"type": "concept", "title": "הכתב מגן על הלקוח, לא על מתווכים", "text": "עוז נ'' עזרא: הסכם בין שני מתווכים לחלוקת דמי התיווך הוא חוזה רגיל שיכול להיכרת בעל פה. דרישת הכתב בסעיף 9 היא רק מול הלקוח.", "icon": "🤝"}, {"type": "check", "question": "written-order-4"}]'::jsonb, 'סעיף 9(א) לחוק; תקנות המתווכים (פרטי הזמנה בכתב), התשנ"ז-1997', null, false, true
  from public.course_chapters c where c.slug = 'brokers-law'
