  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'written-order-1', l.chapter_id, l.id, 'practice', null, 'בהזמנה בכתב נכתב "דמי התיווך: 2% ממחיר העסקה". הלקוח אמר שהוא מבין שזה כולל מע"מ, והמתווך שתק. אחרי העסקה המתווך דורש 2% בתוספת מע"מ. האם הייתה חובה להתייחס למע"מ בהזמנה?', '["לא. המע\"מ נגבה לפי השיעור שבדין ביום התשלום, ואין צורך לכתוב אותו.", "לא, אלא אם הלקוח הוא עוסק מורשה שיכול לקזז את המע\"מ.", "כן. התקנות דורשות לציין אם דמי התיווך כוללים מע\"מ, והחובה חלה על המתווך בכל הזמנה.", "כן, אבל רק כשדמי התיווך נקובים בסכום ולא בשיעור מהמחיר."]'::jsonb, 2, null, 'תקנה 1(5) לתקנות פרטי הזמנה בכתב: ההזמנה תכלול את הסכום או השיעור של דמי התיווך, והאם המחיר כולל מס ערך מוסף. החובה חלה על כל הזמנה, בלי קשר למעמד הלקוח ולצורת הנקיבה. מתווך ששתק כשהלקוח אמר שהמחיר כולל מע"מ יתקשה לדרוש תוספת. זו שאלה 3 במבחן פברואר 2025.', 'תקנה 1(5) לתקנות המתווכים (פרטי הזמנה בכתב); סעיף 9(א) לחוק', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'written-order'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
