  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'written-order-2', l.chapter_id, l.id, 'practice', null, 'אחרי שיחת טלפון שלח מתווך ללקוח הודעת וואטסאפ: "בהמשך לשיחתנו, דמי התיווך למציאת חנות יהיו חודש שכירות אחד". הלקוח ענה "סבבה". המתווך מצא חנות והלקוח שכר אותה. האם ההודעה היא הזמנה בכתב?', '["כן. הודעה כתובה שהלקוח אישר היא \"הזמנה בכתב\", והמתווך היה הגורם היעיל.", "כן, ובלבד שהמתווך ישלח אחריה חשבונית עם פרטי הנכס תוך זמן סביר.", "לא. ההודעה כוללת רק את דמי התיווך, בלי זיהוי הצדדים, תיאור הנכס, סוג העסקה ומחיר בקירוב.", "לא, כי הזמנה בכתב חייבת להיחתם בחתימת יד על נייר, ומסרון אינו יכול להחליף אותה."]'::jsonb, 2, null, 'השאלה אינה הצורה אלא התוכן: התקנות דורשות חמישה פרטים, וההודעה מכילה אחד. בלי תיאור הנכס, סוג העסקה, מחיר בקירוב וזיהוי הצדדים אין הזמנה לפי סעיף 9(א), ולכן אין זכאות לפי סעיף 14(א). הנייר אינו העניין: הזמנה מלאה שהלקוח אישר במייל משלו נחשבת לפי מפתח הרשם (מאי 2024) להסכם מחייב, נקודה שמסומנת אצלנו לבדיקה משפטית.', 'סעיף 9(א) לחוק; תקנות המתווכים (פרטי הזמנה בכתב)', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'written-order'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'written-order-3', l.chapter_id, l.id, 'practice', null, 'מוכר חתם על הזמנה בכתב ועל הסכם בלעדיות, המתווך פרסם ומצא קונה, ונחתם הסכם מכר. כעת המוכר מסרב לשלם, כי בטפסים לא נכתבו מספרי תעודות הזהות שלו ושל המתווך. מה הדין לפי גופר נ'' קאופמן?', '["המתווך אינו זכאי. התקנות מונות את מספרי הזיהוי כפרט חובה, ופרט חובה שחסר שולל את ההזמנה.", "המתווך זכאי. הדרישה נועדה לוודאות בזהות הצדדים, וכשאין ספק בזהותם החסר אינו שולל את הזכאות.", "המתווך זכאי רק למחצית מדמי התיווך, כפיצוי על אי-מילוי מדויק של התקנות.", "המתווך אינו זכאי, אלא אם המוכר יחתום עכשיו על טופס מתוקן שבו מספרי הזהות."]'::jsonb, 1, null, 'בגופר נ'' קאופמן (ע"א 4582/08) אימץ בית המשפט פרשנות תכליתית: מספרי הזיהוי נועדו לוודאות בזהות המתווך והלקוח, וכשאין על כך מחלוקת, חסרונם אינו שולל דמי תיווך. אין בדין מנגנון של "חצי עמלה", ואין צורך בטופס מתוקן. זו שאלה 10 במבחן נובמבר 2024.', 'סעיף 9(א) לחוק; ע"א 4582/08 גופר נ'' קאופמן', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'written-order'
