  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'written-order-4', l.chapter_id, l.id, 'practice', null, 'מתווכת החתימה מוכרת על הזמנה בכתב, סיכמה בעל פה עם מתווכת אחרת לחלוק בדמי התיווך, והעבירה אליה את הקונים. המתווכת השנייה סגרה את העסקה, קיבלה את כל דמי התיווך, וטוענת שאין ביניהן הסכם כי הוא לא נערך בכתב. מה הדין?', '["המתווכת השנייה צודקת. חוק המתווכים דורש שכל הסכם תיווך ייערך בכתב, וגם הסכם בין מתווכים.", "המתווכת השנייה צודקת, כי רק מי שהיה הגורם היעיל מול הקונה זכאי לדמי תיווך.", "המתווכת הראשונה צודקת. דרישת הכתב חלה רק מול הלקוח, והסכם בין מתווכים הוא חוזה רגיל שנכרת גם בעל פה.", "המתווכת הראשונה צודקת רק אם החזיקה בהסכם בלעדיות בתוקף על הנכס."]'::jsonb, 2, null, 'עוז נ'' עזרא (ת"א 35922/07): דרישת הכתב שבסעיף 9 נועדה להגן על הלקוח, ואינה חלה על הסכמות בין מתווכים. הסכם שיתוף פעולה כזה כפוף לחוק החוזים ויכול להיכרת בעל פה ובהתנהגות, ומי שהפרה אותו חייבת בחלקה של השותפה. מבחן הגורם היעיל עניינו היחס ללקוח, לא החלוקה בין המתווכות. זו שאלה 19 במבחן אוגוסט 2024.', 'סעיף 9 לחוק; ת"א 35922/07 עוז נ'' עזרא', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
