  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'exclusivity', 'סעיף 9(ב)-(ד): בלעדיות, תקופות ופעולות שיווק', 5, 'בלעדיות היא הנושא הנשאל ביותר בחוק. הכל כאן מספרים: מסמך נפרד, שישה חודשים או שנה, 30 ימים או תשעה חודשים, שליש, ושתי פעולות שיווק.', '<h3>סעיף 9(ב): שני תנאים לבלעדיות</h3><p>מתווך רשאי להסכים עם לקוח על בלעדיות, ובלבד ש: (1) מתן הבלעדיות ותקופתה <strong>יאושרו בחתימת הלקוח על מסמך נפרד</strong>; (2) במהלך התקופה יבצע המתווך <strong>פעולות שיווק</strong>. בפסק דין בראון נ'' סידרון נקבע שהמסמך הנפרד הוא דרישה מהותית, ובלעדיות שנכתבה בתוך טופס ההזמנה, גם בכתב יד, אינה תקפה.</p><h3>סעיף 9(ב1)-(ג): התקופות, כשהמוכר אינו סוחר</h3><table><tr><th>הנכס</th><th>תקרה</th><th>לא נקבעה תקופה</th></tr><tr><td>דירה (למגורים, גם עתידית)</td><td>שישה חודשים</td><td>30 ימים</td></tr><tr><td>נכס אחר (חנות, מגרש)</td><td>שנה</td><td>תשעה חודשים</td></tr></table><p>הסכמה על תקופה ארוכה יותר אינה בטלה, אלא מקוצרת לתקרה.</p><h3>סעיף 9(ב2): כלל השליש</h3><p>אם עד תום <strong>שליש</strong> מתקופת הבלעדיות המתווך לא ביצע את פעולות השיווק שנקבעו, הבלעדיות מסתיימת באותו מועד. בבלעדיות של שישה חודשים: אחרי חודשיים.</p><h3>תקנות פעולות שיווק</h3><p>מתווך בבלעדיות יבצע <strong>שתי פעולות לפחות</strong> מתוך: (1) שילוט על הנכס, על לוח מודעות או במרכז קהילתי; (2) פרסום במאגר לקוחות, בדיוור או באתר אינטרנט לשיווק נכסים; (3) פרסום בעיתון יומי נפוץ; (4) פרסום בעיתון מקומי או מגזרי לפי בחירת הלקוח; (5) הזמנת רוכשים או מתווכים לבקר בנכס; (6) הזמנת חמישה מתווכים לפחות מהיישוב לשתף פעולה. אפשר להסכים על פעולה אחרת (7), יחד עם אחת מהשש או בלעדיה. <strong>המתווך מפרט בטופס נפרד מההזמנה</strong> את כל שש הפעולות, מציין שהלקוח רשאי לבחור, ואם סוכמה פעולה אחרת, גם אותה.</p><h3>למה זה חשוב: סעיף 14(ב)</h3><p>מתווך בבלעדיות שביצע את פעולות השיווק נהנה מחזקה שהוא הגורם היעיל לכל עסקה שנכרתה בתקופת הבלעדיות, גם אם המוכר מכר בעצמו.</p>', '["בלעדיות רק במסמך נפרד שהלקוח חתם עליו, ובתנאי שהמתווך מבצע פעולות שיווק (סעיף 9(ב)).", "דירה: עד שישה חודשים; בלי תקופה, 30 ימים. נכס אחר: עד שנה; בלי תקופה, תשעה חודשים.", "כלל השליש: לא בוצעו פעולות שיווק עד תום שליש מהתקופה, הבלעדיות נגמרת.", "תקנות פעולות שיווק: שתי פעולות לפחות משש, בטופס נפרד שמפרט את כולן, אלא אם סוכמה פעולה אחרת.", "בראון נ'' סידרון: בלעדיות בתוך טופס ההזמנה אינה תקפה, גם בהסכמת הלקוח."]'::jsonb, '[{"type": "concept", "title": "מסמך נפרד, או אין בלעדיות", "text": "סעיף 9(ב)(1): מתן הבלעדיות ותקופתה מאושרים בחתימת הלקוח על מסמך נפרד. בראון נ'' סידרון: זו דרישה מהותית, ואי אפשר להתנות עליה.", "icon": "📄"}, {"type": "example", "title": "שאלה 24, יולי 2025", "text": "מתווך שכח את טופס הבלעדיות, והוסיף בכתב יד בתוך טופס ההזמנה שתהיה לו בלעדיות לשישה חודשים. הדירה נמכרה דרך מתווך אחר בתוך התקופה.", "law": "אין בלעדיות ואין חזקת גורם יעיל: הדרישה למסמך נפרד נועדה שהלקוח יבין שהוא מוותר על מתווכים אחרים, והצדדים אינם יכולים להסכים אחרת."}, {"type": "check", "question": "exclusivity-1"}, {"type": "concept", "title": "התקופות: דירה מול נכס אחר", "text": "דירה: עד שישה חודשים, ובלי תקופה 30 ימים. נכס שאינו דירה (חנות, מגרש): עד שנה, ובלי תקופה תשעה חודשים. תקופה ארוכה מהתקרה מתקצרת אליה.", "icon": "📅"}, {"type": "check", "question": "exclusivity-2"}, {"type": "check", "question": "exclusivity-3"}, {"type": "concept", "title": "כלל השליש", "text": "סעיף 9(ב2): לא בוצעו פעולות השיווק עד תום שליש מהתקופה, הבלעדיות מסתיימת באותו רגע. שישה חודשים הופכים לחודשיים.", "icon": "⏱️"}, {"type": "check", "question": "exclusivity-4"}, {"type": "concept", "title": "שתי פעולות משש, בטופס נפרד", "text": "שילוט, מאגר או אינטרנט, עיתון יומי, עיתון מקומי, הזמנת מבקרים, חמישה מתווכים. לפחות שתיים, אלא אם סוכמה פעולה אחרת. הטופס מפרט את כל השש ומציין שהלקוח בוחר.", "icon": "📣"}, {"type": "check", "question": "exclusivity-5"}]'::jsonb, 'סעיף 9(ב)-(ד) לחוק; תקנות המתווכים (פעולות שיווק), התשס"ה-2004', null, false, true
  from public.course_chapters c where c.slug = 'brokers-law'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exclusivity-1', l.chapter_id, l.id, 'practice', null, 'בעל דירה חתם למתווך על הסכם בלעדיות במסמך נפרד לשישה חודשים, ובהמשך הסכימו בכתב להאריך אותו לשנה. בחודש העשירי נמכרה הדירה לקונה שהמתווך לא הכיר. האם עומדת למתווך חזקת הגורם היעיל?', '["כן. הצדדים הסכימו בכתב על שנה, והעסקה נעשתה בתוך התקופה המוסכמת.", "כן, אם המתווך ביצע שתי פעולות שיווק לפחות בחודשיים הראשונים.", "לא. בלעדיות על דירה אינה יכולה לעלות על שישה חודשים, ולכן ההארכה אינה תקפה והעסקה מחוץ לבלעדיות.", "לא, כי הארכת בלעדיות מחייבת אישור של רשם המתווכים ולא רק הסכמה בין הצדדים."]'::jsonb, 2, null, 'סעיף 9(ב1)(2): תקופת הבלעדיות לעניין דירה לא תעלה על שישה חודשים מיום ההזמנה. הסכמה על יותר מכך מתקצרת לתקרה, ולכן בחודש העשירי אין בלעדיות ואין חזקה לפי סעיף 14(ב). המתווך עדיין יכול לזכות בדמי תיווך אם יוכיח שהיה בפועל הגורם היעיל (סעיף 14(א)), אבל לא מכוח הבלעדיות. השאלה הזו נשאלה באוגוסט 2024.', 'סעיף 9(ב1) לחוק', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'exclusivity'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exclusivity-2', l.chapter_id, l.id, 'practice', null, 'ספרן שירש חנות מסבו חתם למתווך על הזמנה בכתב ועל הסכם בלעדיות במסמך נפרד, אבל השניים לא קבעו את משך הבלעדיות. מתי היא מסתיימת?', '["בתום 30 ימים מיום ההזמנה, כמו בכל בלעדיות שלא נקבעה לה תקופה.", "בתום שישה חודשים מיום ההזמנה, התקרה הקבועה בחוק.", "בתום תשעה חודשים מיום ההזמנה, כי החנות אינה דירה והמוכר אינו סוחר.", "מיד. בלי קביעת תקופה אין בלעדיות בכלל, והמסמך הנפרד חסר תוקף."]'::jsonb, 2, null, 'סעיף 9(ב1)(1): בנכס שאינו דירה, שמוכר אותו מי שאינו עוסק בכך, הבלעדיות לא תעלה על שנה, ואם לא נקבעה תקופה היא מסתיימת בתום תשעה חודשים. 30 ימים הם ההשלמה לדירה בלי תקופה (סעיף 9(ג)), ושישה חודשים הם תקרת הדירה. היעדר קביעה אינו מבטל את הבלעדיות; החוק משלים אותה. זו שאלה 8 במבחן נובמבר 2024.', 'סעיף 9(ב1) ו-9(ג) לחוק', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'exclusivity'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exclusivity-3', l.chapter_id, l.id, 'practice', null, 'בני זוג חתמו למתווך על בלעדיות במסמך נפרד למכירת דירתם, בלי לציין תקופה. אחרי חודשיים מכרו את הדירה בעצמם. המתווך ביצע שתי פעולות שיווק בשבוע הראשון, ודורש דמי תיווך מכוח חזקת הגורם היעיל. מה הדין?', '["המתווך זכאי. בלי תקופה מוסכמת הבלעדיות נמשכת שישה חודשים, והמכירה נעשתה בתוכם.", "המתווך זכאי, כי ביצע את פעולות השיווק ולכן החזקה עומדת לו עד תום תשעה חודשים.", "המתווך אינו זכאי מכוח החזקה. בדירה שלא נקבעה בה תקופה הבלעדיות הסתיימה אחרי 30 ימים.", "המתווך אינו זכאי בשום מקרה, כי מכירה עצמית של הבעלים תמיד סותרת את החזקה."]'::jsonb, 2, null, 'סעיף 9(ג): בלעדיות על דירה שלא נקבעה לה תקופה מסתיימת בתום 30 ימים מיום ההזמנה. המכירה אחרי חודשיים היא מחוץ לתקופה, ולכן אין חזקה לפי סעיף 14(ב). פעולות השיווק שומרות על הבלעדיות בתוך התקופה (כלל השליש) אבל אינן מאריכות אותה. מכירה עצמית בתוך בלעדיות תקפה דווקא מחייבת בדמי תיווך (שמואלי נ'' סמוכה).', 'סעיף 9(ג) ו-14(ב) לחוק', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'exclusivity'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exclusivity-4', l.chapter_id, l.id, 'practice', null, 'מתווך החתים בני זוג על הזמנה ועל בלעדיות נפרדת לשישה חודשים למכירת ביתם, אבל לא ביצע שום פעולת שיווק. אחרי ארבעה חודשים הם מכרו את הבית בעצמם. מה נכון?', '["המתווך זכאי לדמי תיווך: הבית נמכר בתוך ששת החודשים, ובתקופת בלעדיות אין צורך להוכיח גורם יעיל.", "הבלעדיות הסתיימה אחרי חודשיים, בתום שליש מהתקופה, כי לא בוצעו פעולות שיווק. אין חזקה, ובני הזוג אינם צריכים להוכיח דבר.", "הבלעדיות בתוקף, אבל בני הזוג יכולים לסתור את החזקה אם יוכיחו שהמתווך לא היה הגורם היעיל.", "הבלעדיות על דירה מוגבלת לשלושה חודשים, ולכן המכירה בחודש הרביעי מחוץ לתקופה בכל מקרה."]'::jsonb, 1, null, 'סעיף 9(ב2): אם המתווך לא ביצע את פעולות השיווק עד תום שליש מתקופת הבלעדיות, היא מסתיימת באותו מועד, כלומר כאן אחרי חודשיים. חזקת הגורם היעיל (סעיף 14(ב)) דורשת בלעדיות בתוקף ופעולות שיווק, ושניהם חסרים, ולכן הנטל אינו על המוכרים. תקרת הדירה היא שישה חודשים, לא שלושה. זו שאלה 15 במבחן נובמבר 2024.', 'סעיף 9(ב2) ו-14(ב) לחוק', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'exclusivity'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exclusivity-5', l.chapter_id, l.id, 'practice', null, 'מתווכת רוצה לקבל בלעדיות על חנות, והלקוח שואל אילו פעולות שיווק היא מתחייבת לבצע. איפה ואיך הדין דורש לפרט אותן?', '["בטופס ההזמנה בכתב עצמו, רשימה של כל שש הפעולות שבתקנות ושל פעולה נוספת אם סוכמה.", "בטופס נפרד מההזמנה, רשימה של כל שש הפעולות שבתקנות, ציון שהלקוח רשאי לבחור, ופעולה נוספת שסוכמה בנפרד.", "בטופס נפרד מההזמנה, רק הפעולות שהמתווכת והלקוח סיכמו ביניהם בפועל.", "אין חובה לפרט בכתב. די שהמתווכת תבצע בפועל שתי פעולות שיווק בתקופת הבלעדיות."]'::jsonb, 1, null, 'תקנה 1(ב) לתקנות פעולות שיווק: המתווך מפרט בטופס נפרד מההזמנה את כל הפעולות שבפסקאות (1) עד (6), מציין שהמזמין רשאי להסכים עמו על הפעולות שיבצע, ואם סוכמה פעולה אחרת (7) מציין גם אותה בנפרד. הביצוע בפועל (שתיים לפחות) הוא תנאי אחר, לחזקת הגורם היעיל. זו שאלה 24 במבחן פברואר 2025.', 'סעיף 9(ב) ו-9(ד) לחוק; תקנה 1 לתקנות המתווכים (פעולות שיווק)', 5, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
