insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'brokerage-fee', 'סעיף 14: שלושה תנאים לדמי תיווך, והגורם היעיל', 6, 'כל שאלת "האם המתווך זכאי לדמי תיווך" עוברת דרך שלושה תנאים מצטברים. השלישי, הגורם היעיל, הוא זה שבתי המשפט מפרשים, ומכאן רוב פסקי הדין שבבחינה.', '<h3>סעיף 14(א): שלושה תנאים מצטברים</h3><ol><li>המתווך היה <strong>בעל רישיון בתוקף</strong> בעת שעסק בתיווך.</li><li>הוא מילא אחר סעיף 9: <strong>הזמנה בכתב</strong> עם הפרטים.</li><li>הוא היה <strong>הגורם היעיל</strong> שהביא להתקשרות הצדדים <strong>בהסכם מחייב</strong>.</li></ol><p>בלעדיות אינה תנאי. היא קיצור דרך: סעיף 14(ב) קובע שמתווך בבלעדיות שביצע את פעולות השיווק, חזקה שהיה הגורם היעיל לעסקה שנכרתה בתקופת הבלעדיות.</p><h3>הגורם היעיל בפסיקה</h3><ul><li><strong>מוסקוביץ נ'' ביר (ע"א 2144/91)</strong> ו<strong>יצחקוב נ'' מרדכי אביב (ע"א 7274/97)</strong>: המבחנים הם מי הפגיש את הצדדים, הדמיון בין העסקה שנדונה לזו שנחתמה, הזמן שחלף, ומידת הפעילות של גורמים אחרים. גורם מתערב או פרק זמן שחלף אינם מנתקים מאליהם את הקשר, ויותר ממתווך אחד יכול להיות זכאי.</li><li><strong>שושני נ'' אברון</strong>: הזכאות מתגבשת עם ההסכם המחייב. הפרה וביטול מאוחרים אינם מבטלים אותה. בחוזה עם תנאי מתלה, ההסכם מחייב כשהתנאי מתקיים.</li><li><strong>שמואלי נ'' סמוכה (בר"ע 2285/05)</strong> ו<strong>סיטי נ'' פרי (ת"א 945-12-11)</strong>: בבלעדיות עם פעולות שיווק, גם מוכר שמצא קונה בעצמו חייב בדמי תיווך, במיוחד כשהקונה הגיע בעקבות השלט ושוחח עם המתווך.</li><li><strong>ב.פ. הנשיא נ'' בקרמן</strong>: מי שרק הראה את הדירה, סירב לנהל משא ומתן ונעלם, אינו הגורם היעיל. "מי שהראה ראשון" אינה חזקה.</li></ul><h3>סעיף 12: מסמכים משפטיים שוללים דמי תיווך</h3><p>מתווך לא יערוך ולא יסייע לערוך מסמכים בעלי אופי משפטי הנוגעים לעסקה, ולא ייצג לקוח במשא ומתן משפטי לקראת מסמך כזה. מי שמפר זאת <strong>אינו זכאי לדמי תיווך</strong>. הסעיף אינו ברשימת סעיף 15, אבל הוא מפנה לחוק לשכת עורכי הדין, ובמדינת ישראל נ'' אופז הורשע מתווך שערך זיכרון דברים. תקנה 23 לתקנות האתיקה חוזרת על האיסור.</p>', '["סעיף 14(א): רישיון בתוקף בעת העיסוק, הזמנה בכתב לפי סעיף 9, והגורם היעיל להסכם מחייב. שלושתם יחד.", "סעיף 14(ב): בלעדיות עם פעולות שיווק מקימה חזקה שהמתווך הוא הגורם היעיל לעסקה בתקופה.", "מוסקוביץ נ'' ביר ויצחקוב: מבחני הגורם היעיל; גורם מתערב וזמן שחלף אינם מנתקים; שני מתווכים יכולים להיות זכאים.", "שושני נ'' אברון: הזכאות קמה עם ההסכם המחייב; הפרה וביטול אחר כך אינם מבטלים אותה.", "סעיף 12: מתווך שערך מסמך משפטי, כולל זיכרון דברים, מאבד את דמי התיווך."]'::jsonb, '[{"type": "concept", "title": "שלושה תנאים, שלושתם", "text": "רישיון בתוקף בעת העיסוק, הזמנה בכתב לפי סעיף 9, והגורם היעיל להסכם מחייב. די שאחד חסר כדי לשלול את דמי התיווך. בלעדיות אינה ברשימה.", "icon": "3️⃣"}, {"type": "check", "question": "brokerage-fee-1"}, {"type": "concept", "title": "גורם יעיל: ארבעה מבחנים", "text": "מי הפגיש, כמה העסקה שנחתמה דומה לזו שנדונה, כמה זמן חלף, ומה עשו אחרים. גורם מתערב או הפסקה אינם מנתקים מאליהם את הקשר הסיבתי.", "icon": "🔗"}, {"type": "example", "title": "שאלה 19, יולי 2023", "text": "מתווך ניהל משא ומתן שלא צלח בין בעל מלון לחברה. אחרי שנה נציג הבעלים סגר עם אותה חברה במחיר אחר, בלי המתווך.", "law": "מוסקוביץ נ'' ביר: המתווך הפגיש את הצדדים, והנציג הוא גורם מתערב שאינו שולל את זכאותו. הזמן שחלף לבדו אינו מנתק."}, {"type": "check", "question": "brokerage-fee-2"}, {"type": "concept", "title": "הסכם מחייב, ומה שקורה אחריו", "text": "שושני נ'' אברון: הזכאות מתגבשת כשנכרת הסכם מחייב. הפרה וביטול אחר כך אינם מבטלים אותה. בתנאי מתלה, ההסכם מחייב כשהתנאי מתקיים.", "icon": "📑"}, {"type": "check", "question": "brokerage-fee-3"}, {"type": "concept", "title": "14(ב): החזקה של הבלעדיות", "text": "מתווך בבלעדיות שביצע את פעולות השיווק: חזקה שהוא הגורם היעיל לכל עסקה שנכרתה בתקופה, גם אם המוכר מצא קונה בעצמו (שמואלי נ'' סמוכה, סיטי נ'' פרי).", "icon": "🛡️"}, {"type": "check", "question": "brokerage-fee-4"}, {"type": "concept", "title": "סעיף 12: לא עורכים מסמכים משפטיים", "text": "לא לערוך, לא לסייע לערוך, ולא לייצג במשא ומתן משפטי. מי שמפר מאבד את דמי התיווך, ועלול להיות מורשע לפי חוק לשכת עורכי הדין (אופז). תקנה 23 חוזרת על זה.", "icon": "🚫"}, {"type": "check", "question": "brokerage-fee-5"}]'::jsonb, 'סעיפים 12 ו-14 לחוק', null, false, true
  from public.course_chapters c where c.slug = 'brokers-law'
