insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'brokerage-fee-1', l.chapter_id, l.id, 'practice', null, 'מתווך שרישיונו אינו בתוקף פגש במקרה מוכרת, הציע לעזור, מצא קונה, והדירה נמכרה מהר, לפני שחידש את הרישיון ולפני ששלח לה הזמנה לחתימה. כעבור חודש דרש 2% דמי תיווך. האם היא חייבת?', '["כן. הוא היה הגורם היעיל, וזה התנאי המרכזי לזכאות לדמי תיווך.", "כן, כי היא יזמה את הפנייה אליו ולכן החוק רואה אותה כמי שהזמינה את השירות.", "לא. חסרים שני תנאים: רישיון בתוקף בעת העיסוק והזמנה בכתב, ודי בכל אחד מהם.", "לא, כי מתווך שרישיונו אינו בתוקף אינו יכול להיות הגורם היעיל בעסקה."]'::jsonb, 2, null, 'סעיף 14(א) דורש שלושה תנאים מצטברים. המתווך אכן היה הגורם היעיל, אבל לא היה לו רישיון בתוקף (תנאי 1) ולא הייתה הזמנה בכתב (תנאי 2), וכל אחד מהחסרים שולל את הזכאות. יוזמת הלקוח אינה תנאי בחוק, והעיסוק בלי רישיון הוא גם עבירה לפי סעיף 2. זו שאלה 2 במבחן פברואר 2025.', 'סעיפים 2, 9 ו-14(א) לחוק', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'brokerage-fee'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'brokerage-fee-2', l.chapter_id, l.id, 'practice', null, 'מתווך ראשון הפגיש מוכר וקונה, שלא הגיעו להסכמה ונפרדו ממנו. אחרי כמה שבועות מתווך שני ליווה את אותו קונה לפגישה עם אותו מוכר, ניהל את המשא ומתן, וההסכם נחתם. מי זכאי לדמי תיווך לפי יצחקוב נ'' מרדכי אביב?', '["רק הראשון. הוא יצר את ההיכרות, ובלעדיה לא הייתה עסקה.", "רק השני. הוא הביא להסכמה על המחיר, ובלעדיה לא הייתה עסקה.", "שניהם עשויים להיות זכאים: הראשון הפגיש בין הצדדים והשני הביא אותם להסכמה.", "אף אחד. כשאי אפשר לומר על מתווך אחד שבלעדיו לא הייתה עסקה, אין גורם יעיל."]'::jsonb, 2, null, 'בפרשת יצחקוב (ע"א 7274/97) קבע בית המשפט העליון את מבחני הגורם היעיל, והכיר באפשרות שיותר ממתווך אחד תרם לעסקה ושניהם זכאים לשכר. כאן הראשון יצר את ההיכרות והשני הביא להסכמה. ייחוס כל השכר לאחד מהם, או שלילתו משניהם, סותר את ההלכה. זו שאלה 18 במבחן מאי 2025.', 'סעיף 14(א)(3) לחוק; ע"א 7274/97 יצחקוב נ'' מרדכי אביב', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'brokerage-fee'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'brokerage-fee-3', l.chapter_id, l.id, 'practice', null, 'מוכרת חתמה על הזמנה בכתב למתווך מורשה שהיה הגורם היעיל. הסכם המכר כלל תנאי מתלה של אישור בית משפט. בית המשפט אישר, ואז הקונה הפר את ההסכם והוא בוטל. האם המוכרת חייבת בדמי תיווך?', '["לא. ההסכם בוטל, ובלי עסקה שהושלמה אין דמי תיווך.", "לא, כי הסכם עם תנאי מתלה אינו \"הסכם מחייב\" לעניין סעיף 14 גם אחרי שהתנאי התקיים.", "כן. התנאי המתלה התקיים, ההסכם הפך מחייב, והפרה וביטול מאוחרים אינם מבטלים את הזכאות.", "כן, אבל רק למחצית מדמי התיווך, כי העסקה לא יצאה לפועל בסופו של דבר."]'::jsonb, 2, null, 'סעיף 14(א)(3) דורש שהמתווך הביא להתקשרות "בהסכם מחייב". לפי שושני נ'' אברון הזכאות מתגבשת עם ההסכם, והמתווך אינו ערב להתנהגות הצדדים אחר כך. בחוזה על תנאי מתלה ההסכם הופך מחייב במלואו כשהתנאי מתקיים, וכאן בית המשפט אישר. אין בדין "חצי דמי תיווך". זו שאלה 18 במבחן אוגוסט 2024.', 'סעיף 14(א) לחוק; סעיף 27 לחוק החוזים (חלק כללי); רע"א שושני נ'' אברון', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'brokerage-fee'
