insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'brokerage-fee-4', l.chapter_id, l.id, 'practice', null, 'בעלת דירה חתמה על הזמנה ועל בלעדיות נפרדת, והמתווך תלה שלט ופרסם באתר. היא פרסמה את הדירה גם בקבוצת וואטסאפ. קונה שראה את ההודעה הגיע לנכס, התקשר למספר שעל השלט, קיבל מהמתווך את כל הפרטים, וקנה. היא טוענת שמצאה את הקונה בעצמה. מה הדין?', '["היא צודקת. בעלים שמצא את הקונה בעצמו סותר את חזקת הגורם היעיל, גם כשיש בלעדיות ופעולות שיווק.", "היא צודקת, כי פרסום בקבוצת וואטסאפ של הבעלים הוא פעולת שיווק שמוציאה את המתווך מהתמונה.", "המתווך זכאי. הבלעדיות ופעולות השיווק מקימות חזקה שלא נסתרה: הקונה הגיע דרך השלט והחליט אחרי השיחה איתו.", "המתווך זכאי מכוח הבלעדיות בלבד, גם אם הקונה לא דיבר איתו מעולם ולא ראה את השלט."]'::jsonb, 2, null, 'סעיף 14(ב): מתווך בבלעדיות שביצע את פעולות השיווק, חזקה שהוא הגורם היעיל לעסקה שנכרתה בתקופה. בסיטי נ'' פרי (ת"א 945-12-11) נקבע שהחזקה לא נסתרה: הקונה הגיע בעקבות השלט ופנה למתווך, וההחלטה לרכוש התקבלה אחרי שקיבל ממנו את המידע. החזקה ניתנת לסתירה, ולכן "בכל מקרה" אינו נכון. זו שאלה 14 במבחן פברואר 2025.', 'סעיף 14(ב) לחוק; ת"א 945-12-11 סיטי נ'' פרי', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'brokerage-fee'
