insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'brokerage-fee-5', l.chapter_id, l.id, 'practice', null, 'מוכר וקונה הגיעו להסכמה בנוכחות מתווך שמחזיק הזמנה בכתב חתומה, וביקשו ממנו לנסח זיכרון דברים. הוא ניסח, הם חתמו, ואחר כך נחתם חוזה אצל עורך דין. האם המתווך זכאי לדמי תיווך?', '["כן. הוא היה הגורם היעיל, ההזמנה בכתב תקינה, וזיכרון דברים אינו חוזה מכר.", "כן, כי המסמך נערך לבקשת הצדדים ובידיעתם, ובסוף עורך דין ערך את החוזה.", "לא. עריכת זיכרון דברים אסורה לפי סעיף 12 ושוללת דמי תיווך, ולפי אופז היא גם עבירה.", "לא, אלא אם המתווך הוא גם עורך דין, ואז מותר לו לערוך את המסמך ולגבות דמי תיווך."]'::jsonb, 2, null, 'סעיף 12 אוסר על מתווך לערוך או לסייע לערוך מסמכים בעלי אופי משפטי הנוגעים לעסקה, וקובע שהמפר לא יהיה זכאי לדמי תיווך. זיכרון דברים הוא הסכם מחייב לכל דבר. סעיף 15 אינו מעניש על סעיף 12, אבל סעיף 12 עצמו מפנה לחוק לשכת עורכי הדין, ובמדינת ישראל נ'' אופז הורשע מתווך שערך זיכרון דברים. תקנה 23(ב) לתקנות האתיקה אוסרת זאת גם על מתווך שהוא עורך דין. זו שאלה 20 במבחן יולי 2025.', 'סעיף 12 לחוק; חוק לשכת עורכי הדין; תקנה 23 לתקנות האתיקה', 5, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
