insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'personal-interest', 'סעיפים 10-11: עניין אישי, קרובים וסודיות', 7, 'מתווך שמוכר לבן שלו, מתווכת שמוכרת דירה של החברה שלה, ומזכירה שמדברת יותר מדי. שני סעיפים קצרים שמגיעים כמעט בכל מועד.', '<h3>סעיף 10: גילוי עניין אישי</h3><p>מתווך לא יתווך בעסקה אם יש לו <strong>עניין אישי</strong> במקרקעין או בעסקה, אלא אם <strong>גילה ללקוחו</strong> את העניין האישי <strong>וקיבל את הסכמת הלקוח בכתב</strong>. "עניין אישי" כולל גם עניין של <strong>קרוב</strong> (בן זוג, הורה, הורה הורה, אח, צאצא, צאצא של בן זוג ובני זוגם, ומי שסמוך על שולחנו, וכן שותף, מעביד או עובד) ושל <strong>גוף שהמתווך או קרובו בעלי שליטה בו</strong> (מנהל, עובד אחראי, או מי שמחזיק מעל 5% מההון או מהרווחים).</p><p>שימו לב להבדל מתקנה 25 לתקנות האתיקה: סעיף 10 מתיר לתווך אחרי גילוי והסכמה בכתב, אבל תקנה 25 אוסרת לגבות דמי תיווך בעסקה שבה למתווך עצמו זכות במקרקעין. מי שמוכר את ביתו אינו מתווך בו.</p><p>תקנה 9 לתקנות האתיקה מוסיפה חובת גילוי בכתב על כל תשלום או טובת הנאה מגורם שאינו צד לעסקה (למשל משקיעים בפרויקט).</p><h3>סעיף 11: איסור גילוי ידיעה</h3><p>מתווך, <strong>או המועסק על ידו</strong>, לא יגלה לאיש, בלי הסכמת הלקוח, כל ידיעה שהובאה לידיעתו מהלקוח או מטעמו, זולת אם חייב לגלותה לפי דין. הסודיות אינה מכסה הסתרת עובדה שהופכת את העסקה למטעה כלפי הלקוח האחר (סעיף 8), ותקנה 11 לתקנות האתיקה מטילה על המתווך לדאוג שגם עובדיו המינהליים ישמרו עליה.</p>', '["סעיף 10: אין תיווך בעסקה עם עניין אישי, אלא אחרי גילוי ללקוח והסכמתו בכתב.", "עניין אישי כולל קרוב (בן זוג, הורה, אח, צאצא ועוד) וגוף שהמתווך או קרובו שולטים בו (מעל 5%).", "תקנה 25 לתקנות האתיקה: בעסקה שבה למתווך עצמו זכות במקרקעין אין דמי תיווך בכלל.", "סעיף 11: המתווך ועובדיו אינם מגלים ידיעה שהגיעה מהלקוח בלי הסכמתו, אלא אם הדין מחייב.", "סודיות כלפי לקוח אחד אינה מתירה להטעות את הלקוח האחר."]'::jsonb, '[{"type": "concept", "title": "עניין אישי: גילוי והסכמה בכתב", "text": "סעיף 10: מתווך לא יתווך בעסקה שיש לו בה עניין אישי, אלא אם גילה ללקוח וקיבל הסכמה בכתב. גילוי בעל פה אינו מספיק.", "icon": "📝"}, {"type": "concept", "title": "גם של קרוב, גם של חברה", "text": "עניין אישי כולל קרוב (בן זוג, הורה, אח, צאצא, סמוך על שולחנו, שותף, מעביד, עובד) וגוף שהמתווך או קרובו בעלי שליטה בו: מנהל, או מעל 5% מההון.", "icon": "👨‍👩‍👧"}, {"type": "example", "title": "שאלה 8, ינואר 2023", "text": "שירן חתמה למתווך אבנר על הזמנה למכירת דירתה. אבנר הציג את הדירה לבנו דניאל, ונחתם הסכם מכר.", "law": "בן הוא קרוב. אבנר היה חייב לגלות לשירן את העניין האישי ולקבל את הסכמתה בכתב לפני שתיווך. בלי זה הפר את סעיף 10."}, {"type": "check", "question": "personal-interest-1"}, {"type": "check", "question": "personal-interest-2"}, {"type": "concept", "title": "הנכס שלכם: לא מתווכים בו", "text": "תקנה 25 לתקנות האתיקה: אין דמי תיווך בעסקה שבה למתווך זכות במקרקעין. גילוי והסכמה מתירים לתווך בעסקה של קרוב, אבל לא לגבות על הבית של עצמכם.", "icon": "🏠"}, {"type": "check", "question": "personal-interest-3"}, {"type": "concept", "title": "סעיף 11: סודיות, גם של העובדים", "text": "המתווך או המועסק על ידו לא יגלה ידיעה שהגיעה מהלקוח בלי הסכמתו, אלא אם הדין מחייב. תקנה 11 לתקנות האתיקה: המתווך אחראי שגם המזכירות ישמרו.", "icon": "🤐"}, {"type": "check", "question": "personal-interest-4"}]'::jsonb, 'סעיפים 10 ו-11 לחוק', null, false, true
  from public.course_chapters c where c.slug = 'brokers-law'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'personal-interest-1', l.chapter_id, l.id, 'practice', null, 'מתווכת מוסמכת מחזיקה 40% ממניות חברה פרטית, והחברה רוצה למכור דירה. היא מתכוונת לתווך במכירה. מה הדין?', '["אסור לה לתווך בשום מקרה. עניין אישי בעסקה פוסל מתווך, ואין דרך להכשיר זאת.", "מותר לה בלי הגבלה. העניין האישי הוא של החברה, שהיא אישיות משפטית נפרדת ממנה.", "מותר לה רק אם תגלה ללקוחות את העניין האישי ותקבל את הסכמתם בכתב, כי היא בעלת שליטה בחברה.", "מותר לה, ובלבד שתגבה מחצית מדמי התיווך המוסכמים בלבד."]'::jsonb, 2, null, 'סעיף 10 מגדיר עניין אישי כך שהוא כולל גוף שהמתווך הוא בעל שליטה בו, ו"בעל שליטה" לפי סעיף 4א(ד) הוא מי שמחזיק מעל 5% מההון או מהזכות לרווחים. האיסור אינו מוחלט: גילוי והסכמה בכתב מכשירים את התיווך. אין בחוק הפחתה למחצית. זו שאלה 7 במבחן מאי 2023.', 'סעיף 10 וסעיף 4א(ד) לחוק', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'personal-interest'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'personal-interest-2', l.chapter_id, l.id, 'practice', null, 'חברה יזמית מממנת את הפרויקט שלה דרך משקיעים פרטיים, והמשקיעים שכרו מתווך לשווק את הדירות. המתווך החתים רוכשים על הזמנות ולא גילה להם שהוא מקבל שכר גם מהמשקיעים. האם פעל כדין?', '["כן. המשקיעים אינם משלמים לו על עסקה ספציפית של רוכש מסוים, ולכן אין מה לגלות.", "כן, כי הוא חב סודיות למשקיעים, ודי שיגלה להם שהוא מקבל עמלה גם מהרוכשים.", "לא. הוא חייב לגלות לרוכשים בכתב שהוא מקבל שכר מגורם שאינו צד לעסקה שלהם.", "לא, ונוסף על השכר היה עליו לחשוף לרוכשים גם את המידע העסקי שקיבל מהמשקיעים."]'::jsonb, 2, null, 'סעיף 10 לחוק, ותקנה 9 לתקנות האתיקה שמפרטת אותו, מחייבים לגלות בכתב ללקוח כל תשלום או טובת הנאה שהמתווך מקבל או עשוי לקבל בקשר לעסקה מגורם שאינו צד לה. המשקיעים אינם צד לעסקת המכר שבין הרוכש לחברה. אין חובה לחשוף מידע עסקי סודי של המשקיעים, רק את עצם השכר. זו שאלה 1 במבחן יולי 2026.', 'סעיף 10 לחוק; תקנה 9 לתקנות האתיקה', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'personal-interest'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'personal-interest-3', l.chapter_id, l.id, 'practice', null, 'מתווך בעל רישיון ואשתו הם הבעלים של בית. הוא פרסם אותו למכירה, הציג רישיון תיווך לקונה שהתעניינה, החתים אותה על הזמנה עם 2% דמי תיווך, והראה לה את הבית. האם פעל כדין?', '["כן. הוא הציג רישיון, החתים את הקונה על הזמנה כדין, והיה הגורם היעיל בעסקה הזו.", "כן, ובלבד שיגלה לקונה בכתב שהוא בן זוגה של הבעלים השנייה.", "לא. הוא חייב לגלות את העניין האישי, ומעבר לכך הוא הבעלים, ועל בית שלו אין דמי תיווך.", "לא, אלא אם אשתו תחתום על הזמנה נפרדת כלקוחה שמזמינה את שירותיו."]'::jsonb, 2, null, 'סעיף 10 דורש גילוי של העניין האישי והסכמה בכתב, והמתווך כאן אינו רק "בן זוג" אלא בעלים. ותקנה 25 לתקנות האתיקה מוסיפה: אין לגבות דמי תיווך בעסקה שבה למתווך זכות במקרקעין. מי שמוכר את ביתו אינו מתווך בו, ורישיון וטופס אינם משנים זאת. זו שאלה 6 במבחן מאי 2025.', 'סעיף 10 לחוק; תקנה 25 לתקנות האתיקה', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'personal-interest'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'personal-interest-4', l.chapter_id, l.id, 'practice', null, 'מוכר סיפר למתווכת שלו שהוא לחוץ למכור ויסכים גם למיליון ש"ח, אף שביקש 1.2 מיליון. המתווכת סיפרה זאת לקונה כדי "לסגור מהר". האם הייתה רשאית?', '["כן. חובת הגינות כלפי הקונה מחייבת למסור לו כל מידע שמשפיע על המחיר.", "כן, כי המחיר המבוקש אינו \"ידיעה\" אלא עניין שבמשא ומתן, שהמתווכת רשאית לנהל לפי שיקול דעתה.", "לא. זו ידיעה שהגיעה מהלקוח, ואסור לגלותה בלי הסכמתו אלא אם הדין מחייב, וכאן אינו מחייב.", "לא, אלא אם הקונה חתם גם הוא על הזמנה בכתב, ואז שני הלקוחות זכאים לאותו מידע."]'::jsonb, 2, null, 'סעיף 11: מתווך לא יגלה לאיש, בלי הסכמת הלקוח, כל ידיעה שהובאה לידיעתו מהלקוח, זולת אם חייב לגלותה לפי דין. המחיר שהמוכר מוכן לרדת אליו הוא ידיעה כזו, והיא אינה "מידע מהותי על הנכס" שסעיף 8 מחייב למסור לקונה. ייצוג שני צדדים (תקנה 17 לתקנות האתיקה) אינו מתיר לחשוף את הקווים האדומים של האחד לשני.', 'סעיף 11 לחוק', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'personal-interest'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'discipline', 'משמעת: עבירות, ועדה, אמצעים, התליה וערעור', 8, 'תיקון 2012 הוסיף לחוק שלושים סעיפי משמעת. מהבחינה מעניינים כמה מספרים ושלוש הבחנות: מי מתלה, מי מעניש, ומה קורה למי שפרש.', '<h3>סעיף 14א: עבירות משמעת</h3><p>התנהגות שאינה הולמת; הפרת סעיפים 8 ו-10 עד 12; הפרת כללי האתיקה או כל דין שמטיל חובה על מתווך; השגת רישיון במצג שווא; הרשעה סופית בעבירה שבגללה אינו ראוי; חוסר אחריות או רשלנות חמורה.</p><h3>סעיף 14ב: ועדת המשמעת</h3><p>שלושה חברים: מי שכשיר להיות שופט שלום, והוא היושב ראש; מתווך בעל ותק של חמש שנים לפחות; עובד מדינה שהוא עורך דין מומחה במקרקעין. התובע הוא עורך דין שהיועץ המשפטי לממשלה הסמיך (14יא), והקובלנה מוגשת על ידו.</p><h3>סעיף 14יט: אמצעי המשמעת</h3><p>התראה; נזיפה; קנס; <strong>התליית רישיון עד שלוש שנים</strong>; ביטול רישיון. מי שרישיונו בוטל לא יבקש רישיון חדש לפני <strong>שבע שנים</strong>. קנס והתליה יכולים להיות על תנאי לתקופה של שנה עד שלוש שנים (14כ).</p><h3>סעיף 14כג: ערעור</h3><p>על החלטת ועדת המשמעת מערערים לבית המשפט המחוזי בתוך <strong>45 ימים</strong>, ועל פסק דינו לעליון ברשות. ערעור אינו מעכב ביצוע אלא אם הוחלט אחרת (14כד).</p><h3>סעיף 14כז: התליה זמנית על ידי הרשם</h3><p>כשיש לרשם יסוד סביר לחשד לעבירת משמעת, או כשמתנהלים נגד המתווך הליכים פליליים או משמעתיים, הוא רשאי, אם חומרת העניין או טובת הציבור מחייבות, <strong>אחרי התייעצות בוועדה המייעצת ומתן הזדמנות לטעון</strong>, להתלות זמנית את הרישיון. ההתליה בטלה אם תוך שישה חודשים לא הוחלט על העמדה לדין, אבל הרשם רשאי להאריך עד <strong>12 חודשים</strong> בסך הכל. זו סמכות של הרשם; אמצעי המשמעת שייכים לוועדה.</p><h3>סעיף 14ל: גם מי שפרש</h3><p>מתווך שרישיונו בוטל, גם לבקשתו, או שלא חידש אותו, או שרישיונו הותלה, ממשיך להיות נתון לשיפוט משמעתי על מה שאירע לפני כן. התליה מרצון (17א) אינה מפלט.</p><h3>סעיף 16: בית משפט פלילי</h3><p>הורשע מתווך בעבירה לפי החוק, לפי חוק הגנת הצרכן או לפי סימנים ו''-ז'' לפרק י"א לחוק העונשין, רשאי בית המשפט, נוסף על כל עונש, לבטל או להתלות את רישיונו, גם על תנאי עד שלוש שנים.</p>', '["ועדת המשמעת: שלושה, בראשות מי שכשיר להיות שופט שלום, עם מתווך בעל ותק חמש שנים ועורך דין עובד מדינה.", "אמצעי משמעת: התראה, נזיפה, קנס, התליה עד שלוש שנים, ביטול. אחרי ביטול, שבע שנים עד בקשה חדשה.", "ערעור על הוועדה: למחוזי בתוך 45 ימים; לעליון ברשות. ערעור אינו מעכב ביצוע מאליו.", "הרשם מתלה זמנית (14כז) אחרי התייעצות ושימוע: שישה חודשים, ובהארכה עד 12. הוועדה מענישה, הרשם מתלה.", "סעיף 14ל: מי שפרש, ביטל או התלה את רישיונו עדיין נשפט על מה שעשה לפני כן."]'::jsonb, '[{"type": "concept", "title": "מה היא עבירת משמעת", "text": "התנהגות שאינה הולמת, הפרת סעיפים 8 ו-10 עד 12, הפרת כללי האתיקה או כל דין שמחייב מתווך, רישיון במצג שווא, הרשעה סופית בעבירה שמונעת, ורשלנות חמורה.", "icon": "📜"}, {"type": "concept", "title": "מי יושב בוועדה", "text": "שלושה: יושב ראש שכשיר להיות שופט שלום, מתווך עם חמש שנות ותק, ועורך דין עובד מדינה שמומחה במקרקעין. התובע הוא עורך דין שהיועץ המשפטי לממשלה הסמיך.", "icon": "🏛️"}, {"type": "check", "question": "discipline-1"}, {"type": "concept", "title": "חמישה אמצעים, ושבע שנים", "text": "התראה, נזיפה, קנס, התליה עד שלוש שנים, ביטול. קנס והתליה יכולים להיות על תנאי (שנה עד שלוש). אחרי ביטול: שבע שנים לפני בקשה חדשה.", "icon": "⚖️"}, {"type": "check", "question": "discipline-2"}, {"type": "concept", "title": "הרשם מתלה, הוועדה מענישה", "text": "סעיף 14כז: בחשד סביר או בהליך פלילי תלוי, הרשם רשאי להתלות זמנית, אחרי התייעצות בוועדה המייעצת ושימוע. עד שישה חודשים, ובהארכה עד 12 בסך הכל.", "icon": "⏸️"}, {"type": "example", "title": "שאלה 10, יולי 2026", "text": "נגד מתווך ותיק נפתחה חקירה פלילית בחשד לעבירות מין. הוא מבקש לשלם אגרה ולחדש את הרישיון לשנה הבאה.", "law": "הרשם רשאי להתלות זמנית את הרישיון אחרי התייעצות בוועדה המייעצת. אמצעי המשמעת (נזיפה, קנס, ביטול) הם של ועדת המשמעת, והרשם אינו שומע עדים."}, {"type": "check", "question": "discipline-3"}, {"type": "concept", "title": "פרישה אינה מפלט", "text": "סעיף 14ל: מי שרישיונו בוטל, גם לבקשתו, או לא חודש, או הותלה, נשאר נתון לשיפוט משמעתי על מה שקרה לפני כן. ערעור על הוועדה: למחוזי תוך 45 ימים.", "icon": "🚪"}, {"type": "check", "question": "discipline-4"}]'::jsonb, 'סעיפים 14א עד 14ל, 16 ו-17א לחוק', null, false, true
  from public.course_chapters c where c.slug = 'brokers-law'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'discipline-1', l.chapter_id, l.id, 'practice', null, 'מתווכת קיבלה החלטה של ועדת המשמעת שמבטלת את רישיונה. היא רוצה לערער, ובינתיים להמשיך לעבוד. מה נכון?', '["היא מערערת לבית המשפט המחוזי בתוך 45 ימים, והגשת הערעור מעכבת מאליה את הביטול עד להכרעה בו.", "היא מערערת למחוזי בתוך 45 ימים, אבל הערעור אינו מעכב את הביטול אלא אם הוועדה או בית המשפט החליטו אחרת.", "היא מערערת לבית המשפט העליון בתוך 30 ימים, כי החלטת ועדה ממשלתית נדונה ישירות בעליון.", "אין ערעור על החלטות ועדת המשמעת, ורק הרשם רשאי לבקש את ביטולן."]'::jsonb, 1, null, 'סעיף 14כג(א): על החלטת ועדת המשמעת מערערים לבית המשפט המחוזי בתוך 45 ימים, ועל פסק דינו לעליון רק ברשות. סעיף 14כד(א): הגשת ערעור אינה מעכבת את ביצוע ההחלטה, אלא אם הוועדה או בית המשפט שלערעור החליטו אחרת.', 'סעיפים 14כג ו-14כד לחוק', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'discipline'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'discipline-2', l.chapter_id, l.id, 'practice', null, 'ועדת המשמעת מצאה שמתווך גילה רשלנות חמורה. היא שוקלת להתלות את רישיונו לחמש שנים. האם היא רשאית?', '["כן. אין בחוק תקרה להתליה, והוועדה קובעת את משכה לפי חומרת המעשה.", "כן, ובלבד שהתקופה שמעבר לשלוש שנים תהיה על תנאי.", "לא. התליה בידי ועדת המשמעת מוגבלת לשלוש שנים; מעבר לכך האמצעי הוא ביטול, ואז שבע שנים עד בקשה חדשה.", "לא, כי הוועדה רשאית להתלות לשנה לכל היותר, וביטול רישיון שמור לבית המשפט בלבד."]'::jsonb, 2, null, 'סעיף 14יט(א)(4): התליית רישיון לתקופה קצובה שלא תעלה על שלוש שנים. האמצעי החמור יותר הוא ביטול (14יט(א)(5)), ואז אי אפשר לבקש רישיון חדש לפני שחלפו שבע שנים (14יט(ב)). אמצעי על תנאי (14כ) חל על קנס והתליה בתוך התקרה, לא מעבר לה.', 'סעיפים 14יט ו-14כ לחוק', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'discipline'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'discipline-3', l.chapter_id, l.id, 'practice', null, 'לרשם המתווכים הגיע מידע שמתווך מואשם בעבירת מרמה, וכתב האישום תלוי ועומד. מה הרשם מוסמך לעשות?', '["לבטל את הרישיון לצמיתות, כי הגשת כתב אישום בעבירת מרמה מוכיחה שאינו ראוי לשמש מתווך.", "להטיל עליו קנס או נזיפה עד לסיום ההליך הפלילי, כאמצעי ביניים.", "להתלות זמנית את הרישיון אחרי התייעצות בוועדה המייעצת ושימוע, אם חומרת העניין מחייבת.", "לכלום עד להרשעה. סמכות ההתליה הזמנית שמורה לוועדת המשמעת בלבד."]'::jsonb, 2, null, 'סעיף 14כז(א): כשמתנהלים נגד מתווך הליכים פליליים בעבירה כאמור בסעיף 14א(5), הרשם רשאי, אם חומרת העניין או טובת הציבור מחייבות, אחרי התייעצות בוועדה המייעצת ומתן הזדמנות לטעון, להתלות זמנית את הרישיון. ביטול וקנס הם אמצעי משמעת של הוועדה (14יט), לא של הרשם. ההתליה בטלה אחרי שישה חודשים בלי החלטה על העמדה לדין, בהארכה עד 12.', 'סעיף 14כז לחוק', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'discipline'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'discipline-4', l.chapter_id, l.id, 'practice', null, 'מתווך פרש מהמקצוע והודיע לרשם על התליית רישיונו מרצון. אחרי כן הוגשה נגדו תלונה על עבירות משמעת שביצע לכאורה בתקופה שלפני ההתליה. האם ועדת המשמעת מוסמכת לדון בקובלנה?', '["לא. משהותלה הרישיון מרצון הוא אינו \"מתווך\", ושיפוט משמעתי חל רק על בעלי רישיון בתוקף.", "לא, אלא אם התלונה נוגעת לעבירה לפי חוק הגנת הצרכן או לפי חוק העונשין.", "כן. השיפוט המשמעתי נמשך על מה שאירע לפני ההתליה, אחרת כל מתווך היה נמלט ממנו בהתליה.", "כן, אבל הוועדה לא תוכל להטיל התליה או ביטול, כי הרישיון כבר אינו בתוקף."]'::jsonb, 2, null, 'סעיף 14ל: מתווך שרישיונו בוטל, גם לבקשתו או משלא חודש, ומתווך שרישיונו הותלה, ממשיכים להיות נתונים לשיפוט משמעתי על מה שאירע לפני כן. הוועדה מוסמכת להטיל את כל אמצעי המשמעת, ואין בחוק סייג על התליה או ביטול במקרה כזה. זו שאלה 12 במבחן יולי 2026.', 'סעיפים 14ל ו-17א לחוק', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'brokers-law' and l.slug = 'discipline'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

