  position = excluded.position, published = true;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'definitions', 'למי התקנות חלות, ומה המילים אומרות', 1, 'התקנות נפתחות בהגדרות, וזה לא סתם: חצי מהשאלות בבחינה מוכרעות לפי מי נחשב "מתווך" ומה נחשב "עסקת תיווך". נתחיל מהן.', '<h3>מכוח מה התקנות קיימות</h3><p>התקנות הותקנו מכוח <strong>סעיפים 14כט ו-19 לחוק המתווכים במקרקעין, התשנ"ו-1996</strong>, בהתייעצות עם הרשם ועם הוועדה המייעצת ובאישור ועדת הפנים והגנת הסביבה של הכנסת. הן נוספות על החובות שבחוק ואינן מחליפות אותן: כמה תקנות פותחות במילים "נוסף על" או "בלי לגרוע מ" סעיף בחוק, וזו דרך לומר שהחוק ממשיך לחול במלואו.</p><h3>ההגדרות שחוזרות בבחינה</h3><ul><li><strong>מתווך במקרקעין</strong>: אדם שקיבל רישיון לפי סעיף 5 לחוק. בלי רישיון בתוקף אין "מתווך", גם אם האדם עוסק בתיווך בפועל.</li><li><strong>עסקת תיווך</strong>: ההתקשרות בין המתווך/ת ללקוח/ה לצורך תיווך. להבדיל מ<strong>עסקה במקרקעין</strong>, שהיא העסקה בזכות עצמה (מכר, שכירות) בין הצדדים.</li><li><strong>טופס הזמנה בכתב</strong>: ההזמנה בכתב לביצוע פעולת תיווך לפי סעיף 9(א) לחוק. בלעדיו אין זכאות לדמי תיווך.</li><li><strong>הסכם בלעדיות</strong>: מסמך הבלעדיות שנחתם לפי סעיף 9(ב) לחוק. שימו לב למילה "מסמך": הבלעדיות היא מסמך נפרד מטופס ההזמנה, וזה נושא לשאלה חוזרת.</li><li><strong>נכס</strong>: הזכות במקרקעין שהיא נושא עסקת התיווך.</li><li><strong>פעולות שיווק</strong>: כמשמעותן בסעיף 9(ב)(2) לחוק, הפעולות שמתווך/ת בבלעדיות חייב/ת לבצע.</li><li><strong>מסמך הצעה להסכם</strong>: מסמך שהוא הצעה כדין להתקשר בחוזה לעסקה במקרקעין. ההגדרה הזו משרתת את תקנה 23, האיסור על מתווך/ת לערוך מסמכים משפטיים.</li></ul><h3>מתי התקנות נכנסו לתוקף</h3><p>תקנה 28: <strong>שישה חודשים מיום פרסומן</strong>. בבחינה לא ישאלו על תאריך, אבל ישאלו האם התקנות חלות, והתשובה היא כן.</p>', '["התקנות מכוח סעיפים 14כט ו-19 לחוק המתווכים, ונוספות על החוק ולא במקומו.", "\"מתווך במקרקעין\" = מי שקיבל רישיון לפי סעיף 5 לחוק.", "עסקת תיווך (מתווך-לקוח) שונה מעסקה במקרקעין (מוכר-קונה).", "הסכם בלעדיות הוא מסמך נפרד שנחתם לפי סעיף 9(ב) לחוק.", "תחילה: שישה חודשים מהפרסום (תקנה 28)."]'::jsonb, '[{"type": "concept", "title": "התקנות נוספות על החוק", "text": "הותקנו מכוח סעיפים 14כט ו-19 לחוק המתווכים. הן לא מחליפות את סעיפי החוק, הן מוסיפות עליהם.", "icon": "⚖️"}, {"type": "concept", "title": "\"מתווך במקרקעין\" = בעל/ת רישיון", "text": "מי שקיבל רישיון לפי סעיף 5 לחוק. עיסוק בפועל בלי רישיון לא הופך אדם למתווך לעניין התקנות.", "icon": "🪪"}, {"type": "check", "question": "ethics-def-1"}, {"type": "concept", "title": "עסקת תיווך לעומת עסקה במקרקעין", "text": "עסקת תיווך: ההתקשרות ביניכם ללקוח/ה. עסקה במקרקעין: המכר או השכירות בין הצדדים. חובות שונות חלות על כל אחת.", "icon": "🔀"}, {"type": "check", "question": "ethics-def-2-case"}, {"type": "concept", "title": "בלעדיות היא מסמך נפרד", "text": "\"הסכם בלעדיות\" מוגדר כמסמך שנחתם לפי סעיף 9(ב) לחוק. סעיף בתוך טופס ההזמנה אינו הסכם בלעדיות.", "icon": "📄"}, {"type": "example", "title": "שאלה 14, יולי 2026", "text": "הבלעדיות נכתבה כסעיף בתוך הסכם ההזמנה. הלקוח מכר לבד אחרי שבועיים, והמתווך ביצע את כל פעולות השיווק.", "law": "המתווך לא זכאי לדמי תיווך: בלי מסמך נפרד אין בלעדיות, ובלי בלעדיות אין חזקת ''גורם יעיל''."}, {"type": "check", "question": "ethics-def-3"}]'::jsonb, 'תקנות 1 ו-28', null, true, true
  from public.course_chapters c where c.slug = 'ethics-regulations'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-def-1', l.chapter_id, l.id, 'practice', null, 'דנה עוסקת בתיווך דירות בעיר מגוריה כבר שנתיים, אך מעולם לא עברה את בחינת הרשם ואין לה רישיון. לעניין תקנות המתווכים (אתיקה וחובות מקצועיות), האם דנה היא "מתווכת במקרקעין"?', '["כן, כי היא עוסקת בתיווך בפועל ומקבלת דמי תיווך על העסקאות שהיא סוגרת.", "כן, אם היא פועלת במשרד תיווך שבעליו מחזיק ברישיון ואחראי לעבודתה.", "לא. \"מתווך במקרקעין\" לפי התקנות הוא אדם שקיבל רישיון לפי סעיף 5 לחוק.", "לא, אלא אם היא מתווכת בפועל יותר מחמש עסקאות בשנה ומדווחת עליהן לרשם."]'::jsonb, 2, null, 'תקנה 1 מגדירה "מתווך במקרקעין" כאדם שקיבל רישיון לפי סעיף 5 לחוק. העיסוק בפועל, ההכנסה או המשרד שבו עובדים אינם רלוונטיים להגדרה. (ועיסוק בתיווך בלי רישיון הוא בעצמו עבירה לפי החוק.)', 'תקנה 1, סעיף 5 לחוק', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'definitions'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-def-2-case', l.chapter_id, l.id, 'practice', null, 'רונית חתמה אצל מתווך על הזמנה בכתב למכירת דירתה. כעבור חודש חתמה עם קונה על חוזה מכר. לפי ההגדרות בתקנות, מה מהשניים הוא "עסקת תיווך"?', '["חוזה המכר בין רונית לקונה, כי זו העסקה שהמתווך הביא אליה.", "ההתקשרות בין רונית למתווך לצורך התיווך. חוזה המכר הוא \"עסקה במקרקעין\".", "שתיהן יחד, כי בלי חוזה מכר אין עסקת תיווך שהושלמה.", "אף אחת מהן, כי עסקת תיווך קיימת רק כשנחתם הסכם בלעדיות."]'::jsonb, 1, null, 'תקנה 1: "עסקת תיווך" היא ההתקשרות בין מתווך לאדם לצורך תיווך במקרקעין, ו"עסקה במקרקעין" היא העסקה בזכות עצמה, כמו המכר. ההבחנה חשובה כי חובות בתקנות חלות על כל אחת מהן בנפרד: חובת ההסבר לפני חתימה על עסקת התיווך, וגילוי מידע מהותי על הנכס לקראת העסקה במקרקעין.', 'תקנה 1', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'definitions'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-def-3', l.chapter_id, l.id, 'practice', null, 'לפי ההגדרות בתקנות, "הסכם בלעדיות" הוא:', '["סעיף בטופס ההזמנה בכתב שבו הלקוח מסכים לבלעדיות.", "מסמך בלעדיות שנחתם לפי סעיף 9(ב) לחוק.", "כל הסכמה בעל פה של הלקוח שלא לפנות למתווכים אחרים.", "הסכם בין שני מתווכים לחלוקת דמי התיווך."]'::jsonb, 1, null, 'תקנה 1 מגדירה הסכם בלעדיות כ"מסמך בלעדיות שנחתם לפי סעיף 9(ב) לחוק". סעיף 9(ב) דורש מסמך נפרד, ולכן בלעדיות שנכתבה כסעיף בתוך טופס ההזמנה אינה הסכם בלעדיות. זו בדיוק הסוגיה של שאלה 14 במבחן יולי 2026.', 'תקנה 1, סעיף 9(ב) לחוק', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'definitions'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'professional-conduct', 'התנהגות מקצועית, השפעה בלתי הוגנת והטעיה', 2, 'שלוש התקנות האלה הן הבסיס של כל פרק ב''. כמעט כל שאלת "האם המתווך פעל כדין" נוגעת באחת מהן.', '<h3>תקנה 2: התנהגות מקצועית</h3><p>נוסף על סעיף 8 לחוק (נאמנות, הגינות ודרך מקובלת), מתווך/ת חייב/ת להעניק <strong>שירות מקצועי</strong>, תוך הקפדה על <strong>יושר ותום לב</strong>, שמירה על <strong>כבוד המקצוע</strong>, יחס של כבוד ללקוח/ה ושירות נאות <strong>בסטנדרט מקצועי מקובל</strong>. התקנה כללית בכוונה: היא הרשת שתופסת התנהגות פסולה שאין לה תקנה ספציפית.</p><h3>תקנה 3: איסור השפעה בלתי הוגנת</h3><p>אסור להפעיל על <strong>יחיד</strong> השפעה בלתי הוגנת, כמשמעותה ב<strong>סעיף 3 לחוק הגנת הצרכן</strong>, כדי שיתקשר בעסקת תיווך. סעיף 3 לחוק הגנת הצרכן מונה, בין היתר, פניות חוזרות ונשנות למרות סירוב, ניצול מצוקה, חולשה או אי-ידיעת השפה, והפעלת לחץ בדרך שמגבילה את חופש הבחירה. הדוגמה מהבחינה: מתווך שפנה לבעלת דירה שלוש פעמים אחרי שסירבה, ואף הגיע לביתה, הפר את התקנה.</p><p>שימו לב שהתקנה מדברת על יחיד (אדם פרטי), ועל ההתקשרות <strong>בעסקת התיווך</strong>, כלומר על הדרך שבה משיגים את הלקוח/ה.</p><h3>תקנה 4: איסור הטעיה</h3><p>אסור לעשות דבר, <strong>במעשה או במחדל</strong>, בכתב או בעל פה או בכל דרך אחרת, שעלול להטעות אדם <strong>בעניין מהותי</strong> לעסקת התיווך או לעסקת המקרקעין. התקנה נותנת דוגמה מפורשת: <strong>הצגת נכס ביודעין שאינו מיועד למכירה או להשכרה</strong> ("נכס פיתיון"). שימו לב לשלוש הרחבות: גם שתיקה (מחדל) היא הטעיה, לא נדרש שההטעיה תצליח ("עלול להטעות"), והאיסור חל כלפי כל אדם ולא רק כלפי הלקוח/ה.</p>', '["תקנה 2: שירות מקצועי, יושר, תום לב, כבוד המקצוע, סטנדרט מקצועי מקובל. נוסף על סעיף 8 לחוק.", "תקנה 3: אסור להפעיל השפעה בלתי הוגנת (לפי סעיף 3 לחוק הגנת הצרכן) על יחיד כדי שיתקשר בעסקת תיווך. פניות חוזרות אחרי סירוב הן הדוגמה הקלאסית.", "תקנה 4: אסור להטעות בעניין מהותי, גם במחדל, גם אם ההטעיה לא הצליחה. הצגת נכס שאינו למכירה היא הטעיה.", "האיסורים חלים כלפי כל אדם, לא רק כלפי הלקוח/ה."]'::jsonb, '[{"type": "concept", "title": "תקנה 2: הסטנדרט המקצועי", "text": "שירות מקצועי, יושר, תום לב, כבוד המקצוע, וכבוד ללקוח/ה. זו הרשת שתופסת כל התנהגות פסולה שאין לה תקנה משלה.", "icon": "🤝"}, {"type": "check", "question": "ethics-conduct-5"}, {"type": "concept", "title": "תקנה 3: אין השפעה בלתי הוגנת", "text": "כמשמעותה בסעיף 3 לחוק הגנת הצרכן: פניות חוזרות אחרי סירוב, ניצול מצוקה, לחץ שמגביל את חופש הבחירה. חל על יחיד, לצורך ההתקשרות בעסקת התיווך.", "icon": "🚫"}, {"type": "example", "title": "שאלה 23, יולי 2026", "text": "שרה סירבה לחתום ואמרה שאינה מעוניינת בתיווך. יוסי התקשר פעמים רבות והגיע לביתה שלוש פעמים. בסוף היא חתמה.", "law": "הפרה של תקנה 3. האיסור הוא על הפניות החוזרות עצמן, לא רק על הביקור בבית, וגם לא משנה שבסוף חתמה."}, {"type": "check", "question": "ethics-conduct-4"}, {"type": "check", "question": "ethics-conduct-2"}, {"type": "concept", "title": "תקנה 4: אין הטעיה, גם בשתיקה", "text": "כל מעשה או מחדל שעלול להטעות בעניין מהותי. לא נדרש שההטעיה תצליח, והיא חלה כלפי כל אדם.", "icon": "🙊"}, {"type": "example", "title": "נכס פיתיון", "text": "מודעה על דירה במחיר נמוך מאוד. למתקשרים אומרים ש\"בדיוק נמכרה\" ומציעים אחרות. הדירה מעולם לא הוצעה.", "law": "הדוגמה המפורשת שבתקנה 4: הצגת נכס ביודעין שאינו מיועד למכירה."}, {"type": "check", "question": "ethics-conduct-1"}, {"type": "check", "question": "ethics-conduct-3"}]'::jsonb, 'תקנות 2-4', null, false, true
  from public.course_chapters c where c.slug = 'ethics-regulations'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-conduct-1', l.chapter_id, l.id, 'practice', null, 'מתווך פרסם מודעה על דירת 4 חדרים במחיר נמוך מאוד. כשהתקשרו מתעניינים, אמר שהדירה "בדיוק נמכרה" והציע דירות אחרות. למעשה, הדירה מעולם לא הוצעה למכירה. איזו תקנה הופרה?', '["תקנה 3, איסור הפעלת השפעה בלתי הוגנת.", "תקנה 4, איסור הטעיה: הצגת נכס ביודעין שאינו מיועד למכירה.", "תקנה 19, חובת ציון היותו מתווך בפרסום.", "אף תקנה לא הופרה, כי המתעניינים לא התקשרו עם המתווך בעסקת תיווך."]'::jsonb, 1, null, 'תקנה 4 אוסרת כל מעשה או מחדל העלול להטעות בעניין מהותי, ומביאה בדיוק את הדוגמה הזו: הצגת נכס ביודעו שאינו מיועד למכירה או להשכרה. האיסור חל כלפי כל אדם, ולא רק כלפי מי שכבר לקוח/ה.', 'תקנה 4', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'professional-conduct'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
