insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-conduct-2', l.chapter_id, l.id, 'practice', null, 'תקנה 3 אוסרת על מתווך להפעיל השפעה בלתי הוגנת. לפי איזה חוק מוגדרת "השפעה בלתי הוגנת" לעניין התקנה?', '["חוק החוזים (חלק כללי), התשל\"ג-1973.", "חוק הגנת הצרכן, התשמ\"א-1981, סעיף 3.", "חוק המתווכים במקרקעין, סעיף 8.", "חוק הגנת הפרטיות, התשמ\"א-1981."]'::jsonb, 1, null, 'תקנה 3 מפנה במפורש לסעיף 3 לחוק הגנת הצרכן, שמונה מהי השפעה בלתי הוגנת (פניות חוזרות למרות סירוב, ניצול מצוקה או חולשה, לחץ שמגביל את חופש הבחירה ועוד).', 'תקנה 3, סעיף 3 לחוק הגנת הצרכן', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'professional-conduct'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-conduct-3', l.chapter_id, l.id, 'practice', null, 'מתווכת יודעת שבדירה שהיא מציעה למכירה יש בעיית רטיבות חמורה. היא לא שיקרה לקונים, פשוט לא אמרה דבר. האם זו הטעיה לפי תקנה 4?', '["לא, הטעיה מחייבת אמירה אקטיבית שאינה נכונה, ושתיקה אינה אמירה.", "לא, כל עוד הקונים לא שאלו על רטיבות ולא ביקשו לבדוק את הדירה.", "כן. התקנה אוסרת הטעיה גם במחדל, ורטיבות היא עניין מהותי.", "כן, אבל רק אם הקונים חתמו בסוף על חוזה והסתמכו על השתיקה."]'::jsonb, 2, null, 'תקנה 4 אוסרת הטעיה "במעשה או במחדל". שתיקה על עניין מהותי היא הטעיה. התקנה גם אומרת "העלול להטעות", ולכן לא נדרש שהעסקה תיחתם. (רטיבות מופיעה גם בתוספת השנייה כנושא שחייב להופיע בשאלון הבעלים, תקנה 7(ד).)', 'תקנה 4, תוספת שנייה', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'professional-conduct'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-conduct-4', l.chapter_id, l.id, 'practice', null, 'בעלת דירה סירבה פעמיים להצעת מתווך לחתום עמו על הזמנת שירותי תיווך. המתווך המשיך להתקשר אליה מדי יום, ולבסוף הגיע לביתה ללא תיאום. בנסיבות אלה:', '["המתווך פעל כדין: מותר לפנות ללקוח פוטנציאלי שוב ושוב עד שהוא משתכנע, כל עוד הוא מנומס.", "המתווך פעל כדין, כל עוד לא איים עליה ולא הציג לה מידע כוזב על הנכס או על השוק.", "המתווך פעל בניגוד לדין רק אם בסוף היא חתמה על ההזמנה בעקבות הלחץ.", "המתווך פעל בניגוד לדין: פניות חוזרות ונשנות אחרי סירוב הן השפעה בלתי הוגנת האסורה בתקנה 3."]'::jsonb, 3, null, 'זו סוגיית שאלה 23 במבחן יולי 2026. תקנה 3 מפנה לסעיף 3 לחוק הגנת הצרכן, שכולל פניות חוזרות ונשנות למרות סירוב. האיסור הוא על ההתנהגות עצמה, ואינו תלוי בשאלה אם הלקוחה חתמה בסוף.', 'תקנה 3', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'professional-conduct'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-conduct-5', l.chapter_id, l.id, 'practice', null, 'מוכר ביקש ממתווך למצוא קונה לדירתו, בתנאי שבחוזה המכר יירשם מחיר נמוך מהמחיר האמיתי כדי לחסוך במס. המתווך הסכים, מצא קונה, וסיכם איתו על מחיר אמיתי ועל מחיר נמוך יותר לחוזה. האם פעל כדין?', '["כן. המתווך חייב נאמנות ללקוח, ותוכן חוזה המכר אינו באחריותו.", "כן. מתווך רשאי לנהל משא ומתן על המחיר, וזה כל מה שעשה כאן.", "לא. חובת היושר ותום הלב בתקנה 2 אוסרת לשתף פעולה עם חוזה למראית עין.", "לא, אבל רק אם המתווך עצמו הרוויח מההפרש בין שני המחירים."]'::jsonb, 2, null, 'תקנה 2 מחייבת שירות ביושר ובתום לב, וסעיף 8(א) לחוק מחייב לפעול בנאמנות, בהגינות ובדרך מקובלת. חוזה שהמחיר בו שונה מהאמיתי כדי להונות את רשויות המס הוא חוזה למראית עין (סעיף 13 לחוק החוזים) ועבירה, ונאמנות ללקוח אינה מתירה שיתוף פעולה בעבירה. משא ומתן על המחיר מותר; הפסול הוא בחוזה הכוזב. זו שאלה 1 במבחן יולי 2025.', 'תקנה 2, סעיף 8 לחוק', 5, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'professional-conduct'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'disclosure-and-explanation', 'גילוי, הצגת רישיון, והסבר לפני חתימה', 3, 'מתי מתווך חייב להגיד "אני מתווך"? ומה חובה להסביר לפני שלקוח חותם? שתי תקנות קצרות, ושאלה כמעט קבועה בבחינה.', '<h3>תקנה 5: חובת גילוי וחובת הצגת רישיון</h3><p><strong>(א)</strong> בפנייה <strong>ראשונה</strong> של מתווך/ת לאדם בנוגע לנכס מסוים, המתווך/ת מציין/ת את <strong>שמו/ה ואת עובדת היותו/ה מתווך/ת</strong>. זה חל כלפי כל אדם, כולל מי שאינו לקוח/ה: מתווך שפונה לבעל דירה שפרסם "למכירה" ומסתיר שהוא מתווך מפר את התקנה (שאלה 2 במבחן יולי 2026).</p><p><strong>(ב)</strong> לפי דרישת אדם המעוניין להתקשר בעסקת תיווך, המתווך/ת מציג/ה <strong>רישיון בתוקף</strong>, בהזדמנות הראשונה אחרי הדרישה.</p><h3>תקנה 6: חובת הסבר ותרגום</h3><p><strong>(א)</strong> לפני שאדם חותם על טופס הזמנה בכתב, המתווך/ת מסביר/ה לו, <strong>בשפה פשוטה ומובנת</strong>, את מהות עסקת התיווך, כולל הפרטים שבטופס. אם יש בעסקה תנאי בלעדיות, מסבירים גם את משמעויות הבלעדיות כמפורט בסעיף 9 לחוק.</p><p><strong>(ב)</strong> אסור להחתים אדם על טופס הזמנה אלא אחרי שהפרטים הוסברו לו <strong>בשפה המובנת לו</strong>. מכאן "תרגום" שבכותרת התקנה: לקוח/ה שאינו/ה מבין/ה עברית צריך/ה לקבל את ההסבר בשפה שמובנת לו/ה, ואחרת החתמה אסורה.</p>', '["פנייה ראשונה לכל אדם בנוגע לנכס: שם + \"אני מתווך/ת\". גם כלפי מי שאינו לקוח/ה.", "רישיון בתוקף מוצג לפי דרישה, בהזדמנות הראשונה.", "לפני חתימה על טופס הזמנה: הסבר בשפה פשוטה על מהות העסקה והפרטים, ועל משמעות הבלעדיות אם יש.", "אסור להחתים מי שלא קיבל/ה את ההסבר בשפה המובנת לו/ה."]'::jsonb, '[{"type": "concept", "title": "פנייה ראשונה: שם + \"אני מתווך/ת\"", "text": "בפנייה ראשונה לכל אדם בנוגע לנכס מסוים. ''אדם'', לא ''לקוח'': גם מול בעלים שפרסם לבד.", "icon": "👋"}, {"type": "example", "title": "שאלה 2, יולי 2026", "text": "רפאל מתקשר לבעלי דירות שפרסמו ''למכירה'', בלי לומר שהוא מתווך, ואז מציע את הדירות ללקוחותיו.", "law": "הפרה של תקנה 5(א). וגם של תקנה 18: שיווק בלי הסכמת הבעלים."}, {"type": "check", "question": "ethics-disclosure-1"}, {"type": "concept", "title": "רישיון בתוקף מציגים לפי דרישה", "text": "בהזדמנות הראשונה אחרי הדרישה. גם לפני שנחתם משהו.", "icon": "🪪"}, {"type": "check", "question": "ethics-disclosure-2"}, {"type": "concept", "title": "לפני חתימה: הסבר בשפה פשוטה", "text": "מהות עסקת התיווך, הפרטים שבטופס, ואם יש בלעדיות גם את משמעותה. ובשפה שהלקוח/ה מבין/ה, אחרת אסור להחתים.", "icon": "🗣️"}, {"type": "check", "question": "ethics-disclosure-3"}]'::jsonb, 'תקנות 5-6', null, false, true
  from public.course_chapters c where c.slug = 'ethics-regulations'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-disclosure-1', l.chapter_id, l.id, 'practice', null, 'מתווך רואה שלט "למכירה" על דירה ומתקשר לבעלים כדי לברר פרטים, בלי לומר שהוא מתווך. בכוונתו להציע את הדירה ללקוחותיו. האם פעל כדין?', '["כן. חובת הגילוי חלה רק כלפי מי שחתם עמו על טופס הזמנה, ובעל הדירה טרם חתם.", "כן, כל עוד לא גבה מבעל הדירה דמי תיווך ולא החתים אותו על טופס הזמנה.", "לא. בפנייה ראשונה לאדם בנוגע לנכס מסוים מציינים שם ועובדת היותו מתווך, גם כלפי מי שאינו לקוח.", "לא, אלא אם בעל הדירה מיוצג על ידי מתווך אחר, ואז חובה לפנות דרכו בלבד."]'::jsonb, 2, null, 'תקנה 5(א): בפנייה ראשונה של מתווך לאדם בנוגע לנכס מסוים יציין המתווך את שמו ואת עובדת היותו מתווך. התקנה אומרת "לאדם", לא "ללקוח". זו שאלה 2 במבחן יולי 2026.', 'תקנה 5(א)', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'disclosure-and-explanation'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-disclosure-2', l.chapter_id, l.id, 'practice', null, 'לקוח ביקש ממתווכת להציג לו את רישיון התיווך שלה. מה חובתה?', '["להציג רישיון בתוקף בהזדמנות הראשונה לאחר הדרישה.", "לשלוח לו את מספר הרישיון בלבד, בלי להציג את הרישיון עצמו.", "אין חובה, הרישיון רשום אצל הרשם וכל אחד יכול לבדוק.", "להציג את הרישיון רק אם הלקוח חתם כבר על טופס הזמנה."]'::jsonb, 0, null, 'תקנה 5(ב): לפי דרישת אדם המעוניין להתקשר בעסקת תיווך, המתווך מציג רישיון תיווך בתוקף בהזדמנות הראשונה לאחר הדרישה. הדרישה יכולה לבוא לפני החתימה, וזה בדיוק הזמן שבו היא חשובה.', 'תקנה 5(ב)', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'disclosure-and-explanation'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-disclosure-3', l.chapter_id, l.id, 'practice', null, 'זוג עולים חדשים שאינם קוראים עברית ביקשו ממתווך לעזור להם למכור דירה. המתווך הגיש להם טופס הזמנה בעברית, אמר "זה סטנדרטי" והם חתמו. בנסיבות אלה:', '["המתווך פעל כדין: הטופס בעברית כי זו שפת המדינה, והלקוחות יכלו לבקש תרגום.", "המתווך פעל כדין, כי הלקוחות בחרו לחתום מרצונם ולא ביקשו הסבר נוסף.", "המתווך פעל בניגוד לדין: אסור להחתים על טופס הזמנה לפני שהפרטים הוסברו בשפה שהחותם מבין.", "המתווך פעל בניגוד לדין רק אם בטופס יש סעיף בלעדיות או סעיף על גובה דמי התיווך."]'::jsonb, 2, null, 'תקנה 6(ב) אוסרת להחתים אדם על טופס הזמנה בכתב אלא לאחר שהוסברו לו הפרטים בשפה המובנת לו. אמירה כללית ("זה סטנדרטי") אינה הסבר על מהות עסקת התיווך והפרטים שבטופס כנדרש בתקנה 6(א).', 'תקנה 6', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'disclosure-and-explanation'
