insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'material-information', 'מסירת מידע מהותי: תקנה 7 ושתי התוספות', 4, 'זו התקנה הארוכה ביותר, והיא מגיעה עם שתי רשימות. הבחינה אוהבת לשאול מה נחשב "מידע מהותי" ומה חייב להופיע בשאלון הבעלים.', '<h3>תקנה 7(א): מכירה על ידי רשות</h3><p>במשא ומתן לכריתת עסקת תיווך בנוגע לנכס מסוים, המתווך/ת מגלה אם העסקה במקרקעין היא <strong>מכירה על ידי רשות</strong> (כונס נכסים, הוצאה לפועל וכדומה) כמשמעותה בסעיף 34א לחוק המכר. למכירה כזו יש כללים שונים לגבי זכויות הקונה, ולכן הגילוי חובה.</p><h3>תקנה 7(ב): התוספת הראשונה היא מידע מהותי</h3><p>סעיף 8 לחוק מחייב למסור ללקוח כל מידע מהותי. תקנה 7(ב) קובעת שהמידע שב<strong>תוספת הראשונה</strong> נחשב מידע מהותי שחובה למסור ללקוח/ה <strong>שאינו/ה בעל/ת הזכות</strong> (כלומר לקונה או לשוכר), בשפה פשוטה וברורה:</p><ul><li>מידע רשמי על בעלי הזכויות וזיהוי הנכס: <strong>נסח רישום</strong> מעודכן, ואם הזכויות לא נרשמו, אישור זכויות מרשות מקרקעי ישראל, ובהיעדרו אישור מ"נותן שירות" (חברה משכנת).</li><li><strong>שטח הנכס והמקור</strong> לקביעתו: חשבון ארנונה, מרשם המקרקעין, רמ"י או נותן השירות, או דוח מדידה של מודד.</li><li>מספר חדרים, מרפסות, חניות ומחסנים ומיקומם, הקומה, וקיומה של מעלית.</li><li>קיומו של <strong>מחזיק שאינו הבעלים</strong>, מועד יציאתו ומועד מסירת החזקה.</li><li>בקרקע שאינה זמינה לבנייה: פעולה לפי תקנות הגנת הצרכן (חובת גילוי במכירת קרקע שאינה זמינה לבנייה) ומידע על חוסר הזמינות.</li><li>היות הנכס <strong>דירה שאינה ראויה למגורים</strong> לפי סעיף 25א לחוק השכירות והשאילה.</li><li><strong>המחיר המבוקש</strong>.</li><li>בשכירות: <strong>תשלומי החובה הנוספים</strong> בקירוב (ארנונה, ותשלומים של הבעלים שיחולו על השוכר, כגון ועד בית).</li></ul><h3>תקנה 7(ג): מידע תכנוני רק עם המקור</h3><p>אסור למסור מידע על <strong>המצב התכנוני</strong> (תוכניות מאושרות והיתרים) או על <strong>אפשרויות תכנוניות</strong> (תוכניות מופקדות, בקשות להיתר, הכרזות התחדשות עירונית) אלא אם המתווך/ת <strong>מציין/ת את הפרסום הרשמי שעליו הסתמך/ה</strong>. "אפשר לבנות עוד קומה" בלי הפניה לתוכנית היא הפרה.</p><h3>תקנה 7(ד): שאלון הבעלים והתוספת השנייה</h3><p>ללקוח/ה שמבקש/ת לרכוש או לשכור, המתווך/ת מוסר/ת <strong>שאלון שמילא/ה בעל/ת הזכות בנכס</strong>, הכולל את נושאי <strong>התוספת השנייה</strong>:</p><ul><li>רטיבויות.</li><li>חריגות בנייה.</li><li>ליקויים מהותיים בתשתיות (מים, חשמל, ביוב, גז).</li><li>מידע רשמי ממחלקת ההנדסה על סטטוס <strong>"בניין מסוכן"</strong>.</li><li>תביעות והליכים (כולל פליליים) הנוגעים לנכס או לבנייתו.</li><li>חוות דעת מקצועיות על נושאים מהותיים, <strong>למעט חוות דעת שמאיות</strong>.</li><li>צורך בהחזקה מיוחדת או שימוש מיוחד כדי למנוע פגיעה.</li><li>ליקויים אחרים.</li><li>מטרדי רעש, ריח, קרינה ומטרדים אחרים.</li></ul><p>אם הבעלים <strong>סירב/ה</strong> להתייחס לנושא כלשהו, המתווך/ת מציין/ת את הסירוב, אחרי שעשה/תה מאמץ סביר לקבל את ההתייחסות. הרשם רשאי לפרסם נוסח שאלון באתרו.</p>', '["7(א): לגלות אם מדובר במכירה על ידי רשות (סעיף 34א לחוק המכר).", "7(ב): התוספת הראשונה = מידע מהותי שחובה למסור לקונה/שוכר: נסח, שטח ומקורו, חדרים/חניות/מחסנים/קומה/מעלית, מחזיק, קרקע לא זמינה, דירה לא ראויה למגורים, מחיר מבוקש, תשלומי חובה בשכירות.", "7(ג): מידע תכנוני רק בציון הפרסום הרשמי שעליו הסתמכו.", "7(ד): שאלון בעלים לפי התוספת השנייה (רטיבות, חריגות בנייה, תשתיות, בניין מסוכן, תביעות, חוות דעת למעט שמאיות, החזקה מיוחדת, ליקויים, מטרדים). סירוב הבעלים מצוין אחרי מאמץ סביר.", "חוות דעת שמאיות מוחרגות מהשאלון."]'::jsonb, '[{"type": "concept", "title": "מכירה על ידי רשות: מגלים", "text": "כונס נכסים, הוצאה לפועל. סעיף 34א לחוק המכר נותן לקונה זכויות שונות, ולכן זה מידע שחובה לגלות כבר במשא ומתן.", "icon": "🏛️"}, {"type": "concept", "title": "התוספת הראשונה = מידע מהותי", "text": "נסח רישום, שטח ומקורו, חדרים וחניות ומחסנים וקומה ומעלית, מחזיק שאינו הבעלים, קרקע לא זמינה לבנייה, דירה לא ראויה למגורים, מחיר מבוקש, ותשלומי חובה בשכירות.", "icon": "📋"}, {"type": "check", "question": "ethics-material-5-case"}, {"type": "check", "question": "ethics-material-3-case"}, {"type": "concept", "title": "מידע תכנוני רק עם המקור", "text": "מותר לומר מה המצב התכנוני, רק אם מציינים את הפרסום הרשמי שעליו הסתמכתם. \"כולם בשכונה הוסיפו קומה\" אינו מקור.", "icon": "🗺️"}, {"type": "check", "question": "ethics-material-1"}, {"type": "concept", "title": "שאלון הבעלים: התוספת השנייה", "text": "רטיבות, חריגות בנייה, תשתיות, בניין מסוכן, תביעות, חוות דעת (לא שמאיות), החזקה מיוחדת, ליקויים, מטרדים. סירוב הבעלים מצוין אחרי מאמץ סביר.", "icon": "📝"}, {"type": "check", "question": "ethics-material-2-case"}, {"type": "check", "question": "ethics-material-4"}]'::jsonb, 'תקנה 7, התוספת הראשונה והתוספת השנייה', null, false, true
  from public.course_chapters c where c.slug = 'ethics-regulations'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-material-1', l.chapter_id, l.id, 'practice', null, 'מתווך אמר לקונים שאפשר להוסיף קומה לבית שהוא מציע למכירה, "כולם בשכונה עשו את זה". הוא לא הפנה לשום תוכנית או היתר. האם פעל כדין?', '["כן. מידע תכנוני כללי על מה שנהוג בשכונה אינו מידע מהותי שהתקנות עוסקות בו.", "לא. מידע על המצב התכנוני או על אפשרויות תכנוניות נמסר רק בציון הפרסום הרשמי שעליו הסתמך.", "כן, כל עוד המידע נכון בפועל והקונים יכולים לבדוק אותו בעצמם בוועדה המקומית.", "לא, כי מתווך אינו רשאי למסור מידע תכנוני בשום מקרה, גם לא בהפניה לתוכנית."]'::jsonb, 1, null, 'תקנה 7(ג): לא ימסור מתווך מידע על המצב התכנוני ועל אפשרויות תכנוניות אלא אם ציין את הפרסום הרשמי שעליו הסתמך. מותר למסור מידע תכנוני, אבל רק עם המקור הרשמי (תוכנית, היתר, הכרזה).', 'תקנה 7(ג)', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'material-information'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-material-2-case', l.chapter_id, l.id, 'practice', null, 'מתווכת מוסרת לבעל דירה את שאלון הבעלים לפי התוספת השנייה, והוא שואל לאילו נושאים הוא חייב להתייחס. על איזה נושא השאלון אינו דורש התייחסות?', '["רטיבויות שידועות לו בנכס.", "חוות דעת שמאית על שווי הנכס.", "חריגות בנייה שידועות לו בנכס.", "הכרזה על הבניין כבניין מסוכן."]'::jsonb, 1, null, 'התוספת השנייה כוללת חוות דעת מקצועיות על נושאים מהותיים "למעט חוות דעת שמאיות". רטיבות, חריגות בנייה ובניין מסוכן כלולים כולם.', 'תקנה 7(ד), תוספת שנייה פרט (6)', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'material-information'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
