  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-material-3-case', l.chapter_id, l.id, 'practice', null, 'יעל שוכרת דירה דרך מתווך. בעל הדירה נקב בדמי שכירות של 5,000 ש"ח לחודש. מה חייב המתווך למסור ליעל נוסף על המחיר, לפי התוספת הראשונה?', '["הערכה שמאית של דמי השכירות הראויים לדירה דומה באותו אזור ובאותה תקופה.", "תשלומי החובה בקירוב שיחולו עליה כמחזיקה: ארנונה, ודמי ניהול של הבית המשותף.", "את שמות השוכרים הקודמים ואת דמי השכירות ששילמו בשנים האחרונות.", "את המחיר ששילם בעל הדירה כשרכש אותה ואת שנת הרכישה."]'::jsonb, 1, null, 'התוספת הראשונה, פרט (8): בעסקת שכירות, תשלומי החובה הנוספים בקירוב החלים על המחזיק, ובכלל זה ארנונה, וכן תשלומים שחלים על הבעלים ושיחולו על השוכר, כגון השתתפות בהוצאות ניהול ואחזקה של הרכוש המשותף.', 'תוספת ראשונה (8)', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'material-information'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
