insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-material-4', l.chapter_id, l.id, 'practice', null, 'בעל דירה סירב למלא את החלק בשאלון שעוסק בתביעות הנוגעות לנכס. מה על המתווך לעשות?', '["להשמיט את החלק הזה מהשאלון שנמסר לקונה, כי הבעלים אחראי למה שהוא מוסר.", "למלא את החלק בעצמו לפי מיטב ידיעתו, ולציין שהבעלים לא השיב.", "לציין בפני הקונה את הסירוב למסור התייחסות, לאחר שעשה מאמץ סביר לקבלה.", "לסרב לתווך בנכס, כי בלי שאלון מלא אסור לבצע פעולות תיווך."]'::jsonb, 2, null, 'תקנה 7(ד): סירב בעל הזכות למסור התייחסות, כולה או חלקה, יציין המתווך את הסירוב, לאחר שעשה מאמץ סביר לקבלה. השמטה בשקט הייתה הטעיה במחדל לפי תקנה 4.', 'תקנה 7(ד)', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'material-information'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
