  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-material-5-case', l.chapter_id, l.id, 'practice', null, 'בעל בית טוען בפני מתווך שהבית רשום על שמו, ומציע להראות לו את חשבון הארנונה. מהו המקור שממנו המתווך חייב למסור לקונה מידע על בעלי הזכויות?', '["הצהרת הבעלים, אם נמסרה בכתב וחתומה בידו.", "נסח רישום מעודכן, ואם הזכויות טרם נרשמו, אישור זכויות מרשות מקרקעי ישראל.", "חשבון הארנונה האחרון, כי הוא מסמך רשמי של הרשות המקומית.", "חוזה הרכישה שבו הבעלים קנה את הבית, בצירוף קבלות על התשלום."]'::jsonb, 1, null, 'התוספת הראשונה, פרט (1): נסח רישום, ואם טרם נרשמו הזכויות, אישור זכויות מרשות מקרקעי ישראל, ובהיעדר רישום ברמ"י, אישור נותן שירות. חשבון הארנונה הוא מקור לשטח (פרט 2), לא לבעלות.', 'תוספת ראשונה (1)', 5, true
