  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'documents-and-information', 'מסמכים, טובות הנאה מצד שלישי, ושימוש במידע', 5, 'ארבע תקנות שעוסקות במה שהמתווך מחזיק בידיים: ניירות, כסף מגורם חיצוני, ופרטים של אנשים. שאלה 1 במבחן יולי 2026 יושבת בדיוק כאן.', '<h3>תקנה 8: מסירת מסמכים ושמירתם</h3><p>המתווך/ת מוסר/ת ללקוח/ה <strong>העתק</strong> מטופס ההזמנה בכתב, מהסכם הבלעדיות ומכל מסמך אחר שנדרש לערוך בכתב לפי דין, ו<strong>שומר/ת עותק שבע שנים לפחות</strong> מיום החתימה.</p><h3>תקנה 9: גילוי על קשר עם גורמים אחרים</h3><p>המתווך/ת מגלה, <strong>בכתב</strong>, לאדם שמבקש להתקשר עמו/ה בעסקת תיווך, על <strong>כל תשלום או טובת הנאה</strong>, בכסף או בשווה כסף, שהוא/היא מקבל/ת או <strong>עשוי/ה לקבל</strong> מגורם <strong>שאינו צד לעסקת המקרקעין</strong>, בקשר לעסקה. ופועל/ת לפי סעיף 10 לחוק. הדוגמה מהבחינה: מתווך ששכרו משולם על ידי משקיעים בפרויקט חייב לגלות זאת לרוכשים.</p><h3>תקנה 10: שימוש במידע רק למטרה שלשמה נמסר</h3><p><strong>(א)</strong> אסור להשתמש במידע שהלקוח/ה מסר/ה, כולל פרטי התקשרות ומידע על נכס מסוים, שלא לצורך שלשמו נמסר, אלא בהסכמה מפורשת.</p><p><strong>(ב)</strong> פרטי התקשרות של מתעניין/ת בעסקה אחת מותר לנצל כדי להציע עסקה <strong>אחרת</strong> רק אם התקיימו <strong>שני</strong> תנאים: (1) המתווך/ת הודיע/ה שהפרטים ישמשו להצעות דומות, ו-(2) הודיע/ה במפורש על <strong>הזכות לסרב</strong>, נתן/ה הזדמנות לסרב, והאדם לא סירב.</p><p><strong>(ג)</strong> מי שלא סירב/ה בהתחלה יכול/ה לסרב <strong>בכל עת</strong>, ומאותו רגע זה סירוב.</p><h3>תקנה 11: סודיות של עובדים מינהליים</h3><p>המתווך/ת נוקט/ת אמצעים מתאימים כדי שמי שמועסק/ת אצלו/ה במשימות מינהליות (מזכירות, הנהלת חשבונות) ישמור/תשמור סודיות כאמור בסעיף 11 לחוק. האחריות על המתווך/ת, לא על העובד/ת בלבד.</p>', '["תקנה 8: העתק של כל מסמך ללקוח/ה, ושמירת עותק שבע שנים לפחות.", "תקנה 9: גילוי בכתב על כל תשלום או טובת הנאה מגורם שאינו צד לעסקה, גם כזו שרק \"עשוי לקבל\".", "תקנה 10: מידע מהלקוח/ה רק למטרה שלשמה נמסר. הצעת עסקה אחרת למתעניין/ת רק אחרי הודעה + זכות סירוב, וסירוב אפשרי בכל עת.", "תקנה 11: המתווך/ת אחראי/ת לסודיות של העובדים המינהליים (סעיף 11 לחוק)."]'::jsonb, '[{"type": "concept", "title": "העתק ללקוח/ה, ועותק אצלכם 7 שנים", "text": "טופס הזמנה, הסכם בלעדיות וכל מסמך שחובה לערוך בכתב. שבע שנים לפחות מיום החתימה.", "icon": "🗄️"}, {"type": "check", "question": "ethics-docs-1"}, {"type": "concept", "title": "טובת הנאה מצד שלישי: גילוי בכתב", "text": "כל תשלום שאתם מקבלים או עשויים לקבל ממי שאינו צד לעסקה. לפני ההתקשרות, בכתב, ולפי סעיף 10 לחוק.", "icon": "💰"}, {"type": "example", "title": "שאלה 1, יולי 2026", "text": "משקיעים שמממנים חברה יזמית שכרו מתווך לפרויקט. הוא התקשר עם רוכשים ולא גילה שהוא מקבל שכר גם מהמשקיעים.", "law": "לא פעל כדין. המשקיעים אינם צד לעסקת המכר, ולכן השכר מהם הוא טובת הנאה מצד שלישי שחובה לגלות."}, {"type": "check", "question": "ethics-docs-2"}, {"type": "concept", "title": "מידע מהלקוח/ה רק למטרה שלשמה נמסר", "text": "פרטי התקשרות ממתעניין/ת בדירה אחת אפשר לנצל לדירה אחרת רק אחרי שהודעתם על כך, הודעתם על הזכות לסרב, ולא סירבו. סירוב אפשרי בכל עת.", "icon": "🔒"}, {"type": "check", "question": "ethics-docs-3"}, {"type": "concept", "title": "הסודיות של העובדים היא עליכם", "text": "מתווך/ת נוקט/ת אמצעים כדי שמי שמועסק/ת במשימות מינהליות ישמור/תשמור סודיות לפי סעיף 11 לחוק.", "icon": "🧑‍💼"}, {"type": "check", "question": "ethics-docs-4"}]'::jsonb, 'תקנות 8-11', null, false, true
  from public.course_chapters c where c.slug = 'ethics-regulations'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-docs-1', l.chapter_id, l.id, 'practice', null, 'כמה זמן לפחות חייב מתווך לשמור עותק מטופס ההזמנה בכתב ומהסכם הבלעדיות?', '["שלוש שנים מיום החתימה.", "חמש שנים מיום סיום העסקה.", "שבע שנים לפחות מיום חתימתם.", "אין חובת שמירה, החובה היא רק למסור העתק ללקוח."]'::jsonb, 2, null, 'תקנה 8: המתווך ישמור עותק ממסמכים אלה לתקופה של שבע שנים לפחות מיום חתימתם, בלי לפגוע בהוראות חוק אחר.', 'תקנה 8', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'documents-and-information'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-docs-2', l.chapter_id, l.id, 'practice', null, 'חברה יזמית משלמת למתווך עמלה על כל דירה שהוא מתווך בפרויקט שלה. המתווך מתקשר בעסקאות תיווך עם רוכשים ואינו מספר להם על העמלה מהיזם. בנסיבות אלה:', '["פעל כדין, כי היזם הוא צד לעסקת המקרקעין ותשלום מצד לעסקה אינו טעון גילוי.", "לא פעל כדין. תשלום או טובת הנאה בקשר לעסקה מגורם שאינו צד לה מחייבים גילוי בכתב ללקוח.", "פעל כדין, כי חובת הגילוי בתקנות חלה רק על תשלומים שהמתווך גובה מהרוכשים עצמם.", "לא פעל כדין רק אם העמלה מהיזם גבוהה מדמי התיווך שהוא גובה מהרוכשים."]'::jsonb, 1, null, 'תקנה 9 מחייבת גילוי בכתב על כל תשלום או טובת הנאה שהמתווך מקבל או עשוי לקבל מגורם שאינו צד לעסקת המקרקעין (כמו המשקיעים בשאלה 1 במבחן יולי 2026), ופעולה לפי סעיף 10 לחוק. הגובה של העמלה אינו רלוונטי.', 'תקנה 9, סעיף 10 לחוק', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'documents-and-information'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-docs-3', l.chapter_id, l.id, 'practice', null, 'קונה התעניין אצל מתווכת בדירה מסוימת והשאיר מספר טלפון. כעבור חודש היא רוצה להציע לו דירה אחרת. מה עליה לוודא מראש כדי שזה יהיה מותר?', '["שהדירה החדשה דומה במחיר, בגודל ובאזור לדירה הראשונה שבה התעניין.", "שהודיעה לו שהפרטים ישמשו להצעות דומות, והודיעה לו על זכותו לסרב ונתנה לו הזדמנות לסרב.", "שעברו לפחות 30 יום מאז הפנייה הראשונה, ושהוא לא ביקש בינתיים למחוק את פרטיו.", "אין צורך בדבר: פרטי התקשרות שנמסרו מרצון מותרים לכל שימוש עסקי סביר."]'::jsonb, 1, null, 'תקנה 10(ב) קובעת שני תנאים מצטברים: הודעה שהפרטים ישמשו להצעות דומות, והודעה מפורשת על הזכות לסרב עם הזדמנות לסרב. ותקנה 10(ג): גם מי שלא סירב יכול להודיע על סירוב בכל עת.', 'תקנה 10(ב)-(ג)', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'documents-and-information'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-docs-4', l.chapter_id, l.id, 'practice', null, 'מזכירה במשרד תיווך העבירה לחברה פרטים על לקוח של המשרד. האם למתווך בעל המשרד יש אחריות לפי התקנות?', '["לא. סעיף 11 לחוק חל על המתווך עצמו, והמזכירה אחראית למעשיה כעובדת.", "כן. המתווך חייב לנקוט אמצעים כדי שעובד במשימות מינהליות ישמור על סודיות לפי סעיף 11 לחוק.", "לא, כי המזכירה אינה בעלת רישיון תיווך והתקנות חלות רק על בעלי רישיון.", "כן, אבל רק אם המזכירה קיבלה תמורה על המידע או מסרה אותו למתווך מתחרה."]'::jsonb, 1, null, 'תקנה 11 מטילה על המתווך את החובה לנקוט אמצעים מתאימים כדי שמי שמועסק אצלו במשימות מינהליות יפעל לפי סעיף 11 לחוק (סודיות). האחריות לארגון המשרד היא על המתווך.', 'תקנה 11, סעיף 11 לחוק', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'documents-and-information'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'service-rules', 'התניית שירות, שירותים נוספים, העברת הצעות וקשר ישיר', 6, 'חמש תקנות קצרות על מה שמתווך לא יכול לעשות ללקוח שלו: לא לכפות, לא להסתיר הצעות, ולא לחסום אותו מהצד השני.', '<h3>תקנה 12: איסור התניית שירות בשירות</h3><p>אסור להתנות שירותי תיווך בקניית שירות אחר, מהמתווך/ת או מאדם אחר (למשל "אני מתווך רק אם תיקחו את עורך הדין שלי").</p><h3>תקנה 13: תיווך ושירותים נוספים</h3><p>מתווך/ת שנותן/ת גם שירותים שאינם תיווך (ייעוץ משכנתאות, הום סטיילינג) <strong>מבחין/ה במפורש ובכתב</strong> בין דמי התיווך לבין הסכומים בעד השירותים הנוספים, ומעדכן/ת את הלקוח/ה. בלי ערבוב במחיר אחד.</p><h3>תקנה 14: חובת העברת הצעות</h3><p>המתווך/ת מעביר/ה ללקוח/ה <strong>בתוך זמן סביר כל הצעה</strong> שקיבל/ה מצד שמבקש להתקשר בעסקה, ופועל/ת לפי הוראות הלקוח/ה. ההחלטה אם ההצעה טובה היא של הלקוח/ה, לא של המתווך/ת. מתווך שלא העביר למוכרת הצעה נמוכה מהמחיר המבוקש הפר את התקנה (שאלה 3 במבחן יולי 2026).</p><h3>תקנה 15: איסור הערמת קשיים לקשר ישיר</h3><p>מתווך/ת שהתקשר/ה עם לקוח/ה לא ימנע/תמנע ולא יקשה/תקשה על לקוח/ה שמבקש/ת לקיים <strong>קשר ישיר</strong> עם הצד האחר במשא ומתן, <strong>אלא אם הצד האחר סירב</strong> לקשר ישיר.</p><h3>תקנה 16: חוק השכירות והשאילה</h3><p>אסור לפעול בניגוד לסעיף 25ט(ב)(3) לחוק השכירות והשאילה. הסעיף הזה נמצא בפרק "שכירות למגורים" ועוסק בתשלומים שאסור להטיל על שוכר/ת של דירה. למעשה, התקנה אומרת: מתווך/ת לא יהיה/תהיה הצינור שדרכו גובים משוכר/ת תשלום שהחוק אוסר להטיל עליו/ה.</p>', '["תקנה 12: אין התניית תיווך בקניית שירות אחר.", "תקנה 13: שירות נוסף שאינו תיווך מתומחר בנפרד, בכתב.", "תקנה 14: כל הצעה עוברת ללקוח/ה בזמן סביר, גם נמוכה. ההחלטה שלו/ה.", "תקנה 15: לא חוסמים קשר ישיר בין הצדדים, אלא אם הצד האחר סירב.", "תקנה 16: לא פועלים בניגוד לסעיף 25ט(ב)(3) לחוק השכירות והשאילה (תשלומים אסורים על שוכר/ת דירה)."]'::jsonb, '[{"type": "concept", "title": "כל הצעה עוברת ללקוח/ה", "text": "בתוך זמן סביר, גם הצעה נמוכה מהמחיר המבוקש. ההחלטה של הלקוח/ה, לא שלכם.", "icon": "📨"}, {"type": "example", "title": "שאלה 3, יולי 2026", "text": "קונה הציעה 150,000 ₪ פחות מהמבוקש וביקשה להעביר. המתווך סירב להעביר הצעות נמוכות, לחץ עליה, והיא שילמה בסוף מחיר מלא.", "law": "הפרה של תקנה 14. התוצאה הטובה לכאורה אינה מרפאה את ההפרה."}, {"type": "check", "question": "ethics-service-1"}, {"type": "concept", "title": "לא מתנים שירות בשירות", "text": "אין \"אני מתווך רק אם תיקחו את עורך הדין שלי\". ושירות נוסף שאתם נותנים מתומחר בנפרד, בכתב.", "icon": "🧾"}, {"type": "check", "question": "ethics-service-4"}, {"type": "check", "question": "ethics-service-2"}, {"type": "concept", "title": "לא חוסמים קשר ישיר", "text": "לקוח/ה שרוצה לדבר ישירות עם הצד השני רשאי/ת, אלא אם הצד השני סירב. זה החריג היחיד.", "icon": "☎️"}, {"type": "check", "question": "ethics-service-3"}]'::jsonb, 'תקנות 12-16', null, false, true
  from public.course_chapters c where c.slug = 'ethics-regulations'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-service-1', l.chapter_id, l.id, 'practice', null, 'מוכרת חתמה עם מתווך על הזמנת שירותי תיווך. קונה הציעה מחיר נמוך ב-150,000 ש"ח מהמבוקש וביקשה להעביר את ההצעה. המתווך סירב להעביר הצעות נמוכות מהמחיר המבוקש, ולחץ על הקונה להעלות את הצעתה. האם פעל כדין?', '["פעל כדין, לא היה עליו להעביר הצעה שנמוכה מהמחיר המבוקש.", "לא פעל כדין, מתווך לא צריך להיות מעורב כלל במשא ומתן.", "לא פעל כדין, היה עליו להעביר ללקוחה כל הצעה שקיבל.", "פעל כדין, כי בסוף השיג למוכרת את המחיר המבוקש."]'::jsonb, 2, null, 'תקנה 14: מתווך יעביר ללקוחו בתוך זמן סביר כל הצעה שקיבל, ויפעל לפי הוראות הלקוח. התוצאה הטובה לכאורה אינה מכשירה את ההפרה. זו שאלה 3 במבחן יולי 2026.', 'תקנה 14', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'service-rules'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-service-2', l.chapter_id, l.id, 'practice', null, 'מתווך מציע ללקוחותיו גם ייעוץ משכנתאות בתשלום. מה מחייבת אותו תקנה 13?', '["להפסיק לתת ייעוץ משכנתאות, כי מתווך רשאי לעסוק בתיווך בלבד ולא בשירות אחר.", "להבחין במפורש ובכתב בין דמי התיווך לבין הסכום בעד השירות הנוסף, ולעדכן את הלקוח.", "לכלול את מחיר הייעוץ בדמי התיווך כדי לפשט ללקוח את התשלום.", "לתת את הייעוץ בחינם ללקוחות תיווך, כי אסור לגבות עליו בנפרד."]'::jsonb, 1, null, 'תקנה 13 מתירה שירותים נוספים, בתנאי שהמתווך מבחין במפורש ובכתב בין דמי התיווך לבין הסכומים הנגבים בעד השירותים הנוספים ומעדכן את הלקוח. (ותקנה 12 אוסרת להתנות את התיווך בקניית השירות הנוסף.)', 'תקנות 12-13', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'service-rules'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-service-3', l.chapter_id, l.id, 'practice', null, 'קונה שחתם עם מתווכת ביקש את מספר הטלפון של המוכר כדי לדבר איתו ישירות. המוכר הודיע למתווכת שהוא מעדיף שכל הקשר יעבור דרכה. מה מותר למתווכת?', '["חובה עליה למסור את המספר, תקנה 15 אוסרת למנוע קשר ישיר בכל מקרה.", "מותר לה שלא למסור, כי הצד האחר סירב לקיים קשר ישיר.", "מותר לה שלא למסור רק אם הקונה טרם שילם דמי תיווך.", "חובה עליה למסור, אבל רק אחרי חתימת החוזה."]'::jsonb, 1, null, 'תקנה 15 אוסרת למנוע או להקשות על קשר ישיר "אלא אם כן סירב הצד האחר לקיים עימו קשר ישיר". סירוב המוכר הוא בדיוק החריג.', 'תקנה 15', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'service-rules'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-service-4', l.chapter_id, l.id, 'practice', null, 'מתווך אמר למוכר שיש לו קונה לדירה, אבל שיפגיש ביניהם רק אם המוכר יזמין ממנו גם את תיווך הרכישה של הדירה הבאה שלו. המוכר הסכים וחתם על שני טופסי הזמנה. האם יש פסול בהתנהלות המתווך?', '["אין פסול. המתווך הציג רישיון והחתים את המוכר על טופסי הזמנה כדין.", "אין פסול, כל עוד לא דרש בלעדיות על תיווך הדירה הבאה.", "יש פסול. אסור להתנות שירות תיווך בעסקה אחת בקניית שירות בעסקה אחרת.", "יש פסול רק אם המוכר לא קרא את שני הטפסים לפני שחתם עליהם."]'::jsonb, 2, null, 'תקנה 12 אוסרת להתנות מתן שירותי תיווך בקניית שירות אחר, והחוק אוסר להתנות תיווך בעסקה אחת בתיווך בעסקה אחרת. רישיון וטפסים חתומים אינם מכשירים את ההתניה, ופיצול לשני טפסים אינו משנה את מהותה. זו שאלה 5 במבחן מאי 2025.', 'תקנה 12', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'service-rules'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
