  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'representation-marketing-ads', 'ייצוג שני צדדים, שיווק בלי הסכמה, ופרסום', 7, 'מתי מותר לייצג גם את המוכר וגם את הקונה? מה צריך לפני שמעלים דירה ליד2? ומה חייב להופיע בכל מודעה? שלוש תקנות שכל מתווך פוגש כל יום.', '<h3>תקנה 17: ייצוג של יותר מצד אחד</h3><p>מותר לתת שירותי תיווך ליותר מצד אחד באותה עסקה, אבל בשני תנאים: <strong>(א)</strong> ליידע <strong>מראש ובכתב</strong> את כל הלקוחות בעסקה שהמתווך/ת משרת/ת יותר מצד אחד, ו<strong>(ב)</strong> לתעד בכתב את <strong>כל ההצעות</strong> שהועברו דרכו/ה בין הצדדים.</p><h3>תקנה 18: שיווק נכס שלא בהסכמת הבעלים</h3><p><strong>(א)</strong> אסור לבצע פעולות שמטרתן תיווך, כולל פעולות שיווק, <strong>בלא הסכמת בעל/ת הזכות</strong>. ואם הנכס <strong>דירת מגורים</strong> או בבעלות <strong>יחיד</strong>, ההסכמה חייבת להיות <strong>בכתב או בדרך מתועדת אחרת</strong> (הודעת וואטסאפ מתועדת, למשל).</p><p><strong>(ב)</strong> אם הבעלים ביקש/ה להפסיק, מפסיקים. החריג: פעולות שיווק <strong>בתוך תקופת בלעדיות</strong> שהמתווך/ת רשאי/ת לבצע מכוח ההסכם. ובתום הבלעדיות מפסיקים, אלא אם התקבלה הסכמה חדשה לפי (א).</p><h3>תקנה 19: חובת פרסום היות המפרסם מתווך</h3><p><strong>(א)</strong> בכל פרסום מטעם המתווך/ת שהוא פעולת שיווק: <strong>שם, היותו/ה מתווך/ת, ומספר הרישיון</strong>.</p><p><strong>(ב)</strong> בכל פרסום של נכס שבו מופיעים פרטי התקשרות עם מתווך/ת, אותם פרטים. בפרסום <strong>בעיתון</strong> די בציון עובדת היותו/ה מתווך/ת.</p><p><strong>(ג)</strong> נכס שכבר אינו למכירה או להשכרה: מסירים או מעדכנים את הפרסום <strong>בהקדם האפשרי</strong>. פרסום שנשאר באוויר אחרי שהדירה נמכרה הופך גם להטעיה לפי תקנה 4.</p>', '["תקנה 17: ייצוג שני צדדים מותר רק עם יידוע מראש ובכתב של כולם, ותיעוד בכתב של כל ההצעות.", "תקנה 18: אין שיווק בלי הסכמת הבעלים. דירת מגורים או בעלות של יחיד: הסכמה בכתב או בדרך מתועדת. בקשה להפסיק מכובדת, חוץ מבתוך תקופת בלעדיות.", "תקנה 19: בכל פרסום שם + \"מתווך/ת\" + מספר רישיון. בעיתון מספיק \"מתווך/ת\". מודעה על נכס שנמכר מוסרת בהקדם."]'::jsonb, '[{"type": "concept", "title": "שני צדדים: מותר, בשני תנאים", "text": "יידוע מראש ובכתב של כל הלקוחות בעסקה, ותיעוד בכתב של כל ההצעות שעברו דרככם.", "icon": "⚖️"}, {"type": "check", "question": "ethics-rep-1"}, {"type": "concept", "title": "אין שיווק בלי הסכמת הבעלים", "text": "ובדירת מגורים או בנכס של יחיד: ההסכמה בכתב או בדרך מתועדת (הודעה שמורה).", "icon": "🏠"}, {"type": "check", "question": "ethics-rep-2"}, {"type": "concept", "title": "בקשה להפסיק: מפסיקים, חוץ מבבלעדיות", "text": "בתוך תקופת הבלעדיות ממשיכים את פעולות השיווק שבהסכם. בתום הבלעדיות מפסיקים, אלא אם התקבלה הסכמה חדשה.", "icon": "⏸️"}, {"type": "check", "question": "ethics-rep-3"}, {"type": "concept", "title": "בכל פרסום: שם, \"מתווך/ת\", מספר רישיון", "text": "בעיתון די בציון העובדה שאתם מתווכים. ומודעה על נכס שנמכר מסירים בהקדם, אחרת זו הטעיה.", "icon": "📰"}, {"type": "check", "question": "ethics-rep-4"}]'::jsonb, 'תקנות 17-19', null, false, true
  from public.course_chapters c where c.slug = 'ethics-regulations'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-rep-1', l.chapter_id, l.id, 'practice', null, 'מתווך מייצג גם את המוכר וגם את הקונה באותה עסקה. מה חובתו לפי תקנה 17?', '["אסור לו לייצג שני צדדים באותה עסקה בשום מקרה, גם אם שניהם הסכימו לכך בכתב.", "ליידע מראש ובכתב את כל לקוחותיו בעסקה שהוא משרת יותר מצד אחד, ולתעד בכתב כל הצעה שעברה דרכו.", "לגבות דמי תיווך רק מאחד הצדדים, ולהודיע לצד השני שהוא אינו מייצג אותו.", "לקבל אישור מראש מרשם המתווכים, ולצרף אותו לטופסי ההזמנה של שני הצדדים."]'::jsonb, 1, null, 'תקנה 17 מתירה ייצוג של יותר מצד אחד, בשני תנאים: יידוע מראש ובכתב של כל הלקוחות בעסקה, ותיעוד בכתב של כל ההצעות שעברו דרכו.', 'תקנה 17', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'representation-marketing-ads'
