insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-rep-2', l.chapter_id, l.id, 'practice', null, 'מתווכת ראתה דירה שבעליה הפרטיים פרסמו למכירה, ובלי לפנות אליהם העלתה את הדירה לאתר המשרד עם פרטיה שלה. האם פעלה כדין?', '["כן. מידע שהבעלים עצמם פרסמו ברבים מותר לפרסום חוזר, כל עוד הפרטים נכונים.", "כן, כל עוד ציינה במודעה שהיא מתווכת ואת מספר רישיונה, כנדרש בתקנה 19.", "לא. אין פעולות שיווק בלי הסכמת בעל הזכות, ובדירת מגורים של יחיד ההסכמה בכתב או בדרך מתועדת.", "לא, אלא אם הדירה הייתה בבלעדיות של מתווך אחר, ואז נדרשת הסכמתו."]'::jsonb, 2, null, 'תקנה 18(א): אין פעולות תיווך או שיווק בלא הסכמת בעל הזכות, ובדירת מגורים או בנכס של יחיד ההסכמה בכתב או בדרך מתועדת. ציון מספר הרישיון (תקנה 19) אינו מרפא היעדר הסכמה.', 'תקנה 18(א)', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'representation-marketing-ads'
