  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-rep-3', l.chapter_id, l.id, 'practice', null, 'בעל דירה שחתם על הסכם בלעדיות לשישה חודשים ביקש מהמתווך אחרי חודש להפסיק לפרסם את הדירה. מה הדין?', '["המתווך חייב להפסיק מיד כל פעולת שיווק, כי הסכמת הבעלים ניתנת לביטול בכל עת.", "המתווך רשאי להמשיך בפעולות השיווק שהוא רשאי לבצע מכוח הסכם הבלעדיות, בתוך תקופת הבלעדיות.", "המתווך רשאי להמשיך לפרסם גם אחרי תום הבלעדיות בלי הסכמה חדשה, עד למכירה.", "המתווך חייב להפסיק, אך זכאי לפיצוי מהבעלים על ההוצאות שהוציא עד אז."]'::jsonb, 1, null, 'תקנה 18(ב): בקשת הבעלים להפסיק מכובדת, למעט פעולות שיווק בתוך תקופת בלעדיות שהמתווך רשאי לבצע מכוח ההסכם. בתום הבלעדיות מפסיקים, אלא אם התקבלה הסכמה חדשה.', 'תקנה 18(ב)', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'representation-marketing-ads'
