insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-rep-4', l.chapter_id, l.id, 'practice', null, 'מתווך פרסם מודעה על דירה בעיתון היומי. מה המינימום שחובה לציין במודעה לפי תקנה 19?', '["שם מלא, מספר רישיון וכתובת המשרד.", "עובדת היותו מתווך במקרקעין.", "מספר הרישיון בלבד.", "אין חובה לציין דבר בפרסום בעיתון."]'::jsonb, 1, null, 'תקנה 19(ב): בפרסום של נכס עם פרטי התקשרות של מתווך מציינים שם, היותו מתווך ומספר רישיון, "ואולם בפרסום כאמור בעיתון די אם יציין המתווך את עובדת היותו מתווך במקרקעין".', 'תקנה 19(ב)', 4, true
