insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'prohibitions', 'עמיתים, כבוד הזולת, והאיסורים: משפטי, שמאי, כסף', 8, 'הפרק האחרון בתקנות אוסף את הגבולות של המקצוע: מה מתווך לא עושה גם אם הלקוח מבקש. כאן נמצאות שאלות ה"אסור" הקלאסיות.', '<h3>תקנות 20-22: כבוד</h3><ul><li><strong>תקנה 20:</strong> כבוד והגינות כלפי <strong>עמיתים</strong> למקצוע, בלי לפגוע בחובת הנאמנות ללקוחות.</li><li><strong>תקנה 21:</strong> מותר <strong>לשתף פעולה</strong> עם מתווכים אחרים, ובלבד שהשיתוף אינו פוגע בלקוח/ה.</li><li><strong>תקנה 22:</strong> כבוד, הגינות ומקצועיות גם כלפי <strong>הצד שאינו לקוח/ה</strong> (הקונה כשמייצגים את המוכר, ולהפך).</li></ul><h3>תקנה 23: איסור פעולות משפטיות</h3><p><strong>(א)</strong> מתווך/ת לא יערוך/תערוך ולא ימסור/תמסור <strong>מסמך הצעה להסכם או זיכרון דברים</strong>. זה נוסף על סעיף 12 לחוק (איסור לערוך מסמכים משפטיים). מסמך "לא מחייב" שהמתווך ניסח לצדדים הוא הפרה.</p><p><strong>(ב)</strong> מתווך/ת שהוא/היא <strong>עורך/ת דין</strong>: לא יבצע/תבצע פעולות משפטיות לגבי נכס שתיווך/ה בו, ולא יתווך/תתווך בנכס שטיפל/ה בו משפטית, אלא אם חלפו <strong>3 שנים</strong> בין השניים.</p><h3>תקנה 24: איסור פעולות שמאיות</h3><p><strong>(א)</strong> מתווך/ת שאינו/ה שמאי/ת לא יעסוק/תעסוק בשומת מקרקעין (סעיף 13 לחוק שמאי מקרקעין). הערכת מחיר שיווקית לצורך התיווך אינה "שומה", אבל מסמך שמתיימר להיות שומה הוא הפרה.</p><p><strong>(ב)</strong> מתווך/ת שהוא/היא <strong>שמאי/ת</strong>: אותו כלל של 3 שנים בין השומה לתיווך באותו נכס.</p><h3>תקנה 25: לא גובים דמי תיווך כצד לעסקה</h3><p>אסור לגבות דמי תיווך בעד עסקה שבה למתווך/ת עצמו/ה יש <strong>זכות במקרקעין</strong>. מי שמוכר/ת את הדירה שלו/ה אינו/ה מתווך/ת בה.</p><h3>תקנה 26: כספים שאינם דמי תיווך</h3><p><strong>(א)</strong> אין גבייה בעד תיווך אלא לפי סעיף 14 לחוק, ובפרט <strong>לא דמי קדימה, לא דמי רצינות</strong>, ולא תשלום בשל <strong>חידוש חוזה או מימוש אופציה</strong>. <strong>(ב)</strong> גם לא מתנים את השירות בתשלומים כאלה.</p><h3>תקנה 27: המלצה על בעל מקצוע</h3><p>כשיש צורך בבעל/ת מקצוע אחר/ת (שמאי/ת, עו"ד, מהנדס/ת) בנוגע למאפיין מהותי של העסקה או הנכס, המתווך/ת <strong>מעדכן/ת את הלקוח/ה בצורך</strong>, כדי שהלקוח/ה יזמין/תזמין לפי שיקול דעתו/ה. לא בוחרים במקום הלקוח/ה (ולפי תקנה 12 גם לא מתנים).</p>', '["תקנות 20-22: כבוד לעמיתים, שיתוף פעולה שלא פוגע בלקוח/ה, וכבוד לצד השני גם כשאינו לקוח/ה.", "תקנה 23: לא עורכים ולא מוסרים הצעה להסכם או זיכרון דברים. מתווך/ת-עו\"ד: 3 שנים הפרדה באותו נכס.", "תקנה 24: לא עוסקים בשומה. מתווך/ת-שמאי/ת: 3 שנים הפרדה באותו נכס.", "תקנה 25: אין דמי תיווך בעסקה שבה למתווך/ת זכות בנכס.", "תקנה 26: גבייה רק לפי סעיף 14 לחוק. לא דמי קדימה, לא דמי רצינות, לא על חידוש חוזה או אופציה.", "תקנה 27: מעדכנים בצורך בבעל/ת מקצוע, והלקוח/ה בוחר/ת."]'::jsonb, '[{"type": "concept", "title": "כבוד: לעמיתים ולצד השני", "text": "תקנות 20-22: הגינות כלפי מתווכים אחרים, שיתוף פעולה שלא פוגע בלקוח/ה, וכבוד גם למי שאינו לקוח/ה שלכם.", "icon": "🤝"}, {"type": "concept", "title": "לא עורכים הצעה להסכם או זיכרון דברים", "text": "גם לא \"רק כדי לסגור את העניין\", וגם אם הצדדים ביקשו. מתווך/ת שהוא/היא עו\"ד: 3 שנים הפרדה באותו נכס.", "icon": "✍️"}, {"type": "check", "question": "ethics-prohib-1"}, {"type": "concept", "title": "לא עוסקים בשומה", "text": "מתווך/ת שאינו/ה שמאי/ת לא יעסוק/תעסוק בשומת מקרקעין. שמאי/ת שגם מתווך/ת: 3 שנים הפרדה באותו נכס.", "icon": "📐"}, {"type": "check", "question": "ethics-prohib-2"}, {"type": "concept", "title": "אין דמי תיווך על נכס שלכם", "text": "כשיש לכם זכות במקרקעין בעסקה, אתם צד ולא מתווך/ת. גילוי לא מכשיר גבייה.", "icon": "🚷"}, {"type": "check", "question": "ethics-prohib-4"}, {"type": "concept", "title": "כסף רק לפי סעיף 14 לחוק", "text": "לא דמי קדימה, לא דמי רצינות, לא תשלום על חידוש חוזה או מימוש אופציה. ולא מתנים את השירות בתשלומים כאלה.", "icon": "💸"}, {"type": "check", "question": "ethics-prohib-3"}, {"type": "concept", "title": "בעל/ת מקצוע: מעדכנים, לא בוחרים", "text": "כשצריך שמאי/ת, עו\"ד או מהנדס/ת, מעדכנים את הלקוח/ה בצורך. הוא/היא מזמין/ה לפי שיקול דעתו/ה.", "icon": "🧑‍🔧"}, {"type": "check", "question": "ethics-prohib-5"}]'::jsonb, 'תקנות 20-27', null, false, true
  from public.course_chapters c where c.slug = 'ethics-regulations'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-prohib-1', l.chapter_id, l.id, 'practice', null, 'מוכר וקונה הגיעו להסכמה על מחיר בנוכחות המתווך וביקשו ממנו לנסח זיכרון דברים קצר "כדי לסגור את העניין". המתווך ניסח ומסר להם. האם פעל כדין?', '["כן. זיכרון דברים אינו חוזה מחייב, ולכן מותר למתווך לנסח אותו לבקשת הצדדים.", "כן, אם הצדדים ביקשו זאת במפורש והמתווך לא גבה על כך תשלום נוסף.", "לא. אסור למתווך לערוך או למסור לצדדים מסמך הצעה להסכם או זיכרון דברים.", "לא, אלא אם המתווך הוא גם עורך דין, ואז מותר לו לערוך את המסמך."]'::jsonb, 2, null, 'תקנה 23(א), בלי לגרוע מסעיף 12 לחוק: מתווך לא יערוך ולא ימסור מסמך הצעה להסכם או זיכרון דברים. גם מתווך שהוא עורך דין אינו רשאי לעשות זאת בנכס שבו הוא מתווך (תקנה 23(ב)).', 'תקנה 23, סעיף 12 לחוק', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'prohibitions'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-prohib-2', l.chapter_id, l.id, 'practice', null, 'מתווך שהוא גם שמאי מקרקעין ערך שומה לדירה בינואר 2025. מתי יהיה רשאי לתווך במכירת אותה דירה?', '["מיד, אם יגלה ללקוח שערך את השומה.", "רק אחרי שחלפו 3 שנים מעריכת השומה.", "רק אחרי שנה מעריכת השומה.", "לעולם לא."]'::jsonb, 1, null, 'תקנה 24(ב): מתווך שהוא שמאי לא יעסוק בתיווך בנכס שערך לגביו שומה, זולת אם חלפו 3 שנים בין עריכת השומה לפעולות התיווך. אותו כלל בדיוק חל על מתווך שהוא עורך דין (תקנה 23(ב)).', 'תקנה 24(ב)', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'prohibitions'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
