insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-prohib-3', l.chapter_id, l.id, 'practice', null, 'מתווכת דורשת מלקוחות "דמי רצינות" של 1,000 ש"ח לפני שהיא מתחילה לחפש להם דירה, והסכום מוחזר אם נחתמת עסקה. האם זה מותר?', '["כן, כל עוד הסכום מוחזר בסוף או מקוזז מדמי התיווך כשנחתמת עסקה.", "כן, אם הלקוח חתם על כך בטופס ההזמנה והסכום סביר ביחס לדמי התיווך.", "לא. אסור לגבות דמי קדימה או דמי רצינות בעד שירותי תיווך, ואסור להתנות בהם את השירות.", "לא, אלא אם הסכום נמוך מ-5% מדמי התיווך הצפויים ומוחזר בכל מקרה."]'::jsonb, 2, null, 'תקנה 26(א) אוסרת לגבות בעד תיווך דמי קדימה או דמי רצינות (וגם תשלום על חידוש חוזה או מימוש אופציה), ותקנה 26(ב) אוסרת להתנות את השירות בתשלומים כאלה. הגבייה מותרת רק לפי סעיף 14 לחוק.', 'תקנה 26', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'prohibitions'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-prohib-4', l.chapter_id, l.id, 'practice', null, 'מתווך מוכר דירה שבבעלותו החלקית (יחד עם אחיו). הוא מצא קונה ודורש מהקונה דמי תיווך. האם זכאי?', '["כן, כי הקונה חתם על טופס הזמנה והמתווך הוא שהביא אותו לעסקה.", "כן, אבל רק על החלק של האח, שלגביו המתווך אינו בעל זכות.", "לא. אסור לגבות דמי תיווך בעד עסקה שבה למתווך זכות במקרקעין.", "לא, אלא אם גילה לקונה מראש ובכתב שהוא בעלים חלקי של הדירה."]'::jsonb, 2, null, 'תקנה 25: מתווך לא יגבה דמי תיווך מלקוח בעד עסקה במקרקעין שבה קיימת לו זכות במקרקעין. בעלות חלקית היא זכות במקרקעין, והגילוי אינו מכשיר את הגבייה.', 'תקנה 25', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'ethics-regulations' and l.slug = 'prohibitions'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
