insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'ethics-prohib-5', l.chapter_id, l.id, 'practice', null, 'מתווכת סבורה שבדירה שהיא מתווכת בה יש חריגת בנייה שמצריכה בדיקה של מהנדס. מה עליה לעשות לפי תקנה 27?', '["לשלוח את המהנדס שהיא עובדת איתו ולחייב את הלקוח, כי זו בדיקה הכרחית.", "לעדכן את הלקוח בצורך בבעל מקצוע, כדי שיוכל להזמין אחד לפי שיקול דעתו.", "לבדוק בעצמה ולתת חוות דעת, כי חריגות בנייה הן חלק מידיעותיה המקצועיות.", "לשתוק, כי בדיקת מצב הנכס היא באחריות הקונה ויועציו."]'::jsonb, 1, null, 'תקנה 27: כשיש צורך בשירות של בעל מקצוע אחר בנוגע למאפיין מהותי של העסקה או הנכס, המתווך מעדכן את הלקוח בצורך זה כדי שהלקוח יוכל להזמין בעל מקצוע לפי שיקול דעתו. שתיקה הייתה הטעיה במחדל (תקנה 4), והתניית השירות אסורה (תקנה 12).', 'תקנה 27', 5, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
