  position = excluded.position, published = true;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'land-basics', 'מקרקעין, בעלות ושכירות: המילים שהחוק בנוי עליהן', 1, 'חוק המקרקעין הוא החוק השני הכי נשאל בבחינה, אחרי חוק המתווכים. הוא מתחיל בהגדרות, וחצי מהשאלות עליו נפתרות כשיודעים אותן בעל פה: חכירה לדורות, חלק מסוים, ושלושים יום.', '<h3>סעיפים 1-2: מקרקעין ובעלות</h3><p><strong>מקרקעין</strong> הם קרקע, כל הבנוי והנטוע עליה, וכל דבר המחובר אליה חיבור של קבע, חוץ ממחוברים שאפשר להפריד. <strong>בעלות</strong> היא הזכות להחזיק, להשתמש ולעשות כל עסקה, בכפוף להגבלות לפי דין או הסכם.</p><h3>סעיף 3: שכירות, חכירה, חכירה לדורות</h3><p>שכירות היא זכות בתמורה להחזיק ולהשתמש שלא לצמיתות. <strong>למעלה מחמש שנים: חכירה. למעלה מעשרים וחמש שנים: חכירה לדורות.</strong> המונח עוסק באורך התקופה בלבד.</p><h3>סעיפים 11 ו-14א-14ח: עומק, גובה וחלקה תלת-ממדית</h3><p>הבעלות בקרקע מתפשטת בכל העומק ובחלל הרום, בכפוף לדינים על מים, נפט ומחצבים ובלי למנוע מעבר באוויר. מאז תיקון 2018 אפשר לרשום <strong>חלקה תלת-ממדית</strong>: יחידה נפחית מתחת לקרקע או מעליה, שהבעלות בה מוגבלת לגבולותיה הרשומים, ונרשמת רק לפי תכנית, תשריט או הפקעה. דירה בבית משותף אינה נרשמת כחלקה תלת-ממדית (14ז).</p><h3>סעיף 13: אין עסקה בחלק מסוים</h3><p>עסקה חלה על הקרקע עם כל המחובר אליה, <strong>ואין תוקף לעסקה בחלק מסוים במקרקעין</strong>. החריגים בחוק עצמו: דירה בבית משותף (54), חלקה תלת-ממדית (14ד), שכירות של חלק מסוים (78), וזיקת הנאה בחלק מסוים (93(ג)). קומה בבית פרטי שלא נרשם כבית משותף אינה נמכרת לבד.</p><h3>סעיף 18: כוח סביר, ושלושים יום</h3><p>מחזיק כדין רשאי להשתמש בכוח סביר כדי <strong>למנוע</strong> הסגת גבול. מי שכבר נתפסו ממנו המקרקעין רשאי להוציא את התופס בכוח סביר רק <strong>תוך 30 ימים מיום התפיסה</strong>, לא מיום שגילה. אחר כך, רק בית משפט.</p>', '["מקרקעין: קרקע, הבנוי, הנטוע וכל מחובר של קבע (סעיף 1).", "שכירות מעל חמש שנים היא חכירה; מעל עשרים וחמש שנים, חכירה לדורות (סעיף 3).", "הבעלות מתפשטת לעומק ולגובה; חלקה תלת-ממדית נרשמת בגבולות נפחיים, ולא לדירה בבית משותף.", "אין תוקף לעסקה בחלק מסוים במקרקעין (סעיף 13), חוץ מדירה בבית משותף, חלקה תלת-ממדית, שכירות וזיקת הנאה.", "כוח סביר להוצאת פולש: תוך 30 ימים מיום התפיסה, לא מיום הגילוי (סעיף 18(ב))."]'::jsonb, '[{"type": "concept", "title": "מקרקעין ובעלות", "text": "מקרקעין: קרקע וכל המחובר אליה חיבור של קבע. בעלות: להחזיק, להשתמש ולעשות כל עסקה, בכפוף להגבלות לפי דין או הסכם.", "icon": "🏞️"}, {"type": "concept", "title": "חמש ועשרים וחמש", "text": "שכירות מעל חמש שנים נקראת חכירה, ומעל עשרים וחמש שנים חכירה לדורות. זה עניין של אורך התקופה, לא של דורות במשפחה.", "icon": "📏"}, {"type": "check", "question": "land-basics-1"}, {"type": "concept", "title": "חלק מסוים: אין עסקה", "text": "סעיף 13: עסקה חלה על הקרקע כולה עם כל המחובר אליה, ואין תוקף לעסקה בחלק מסוים. חריגים: דירה בבית משותף, שכירות של חלק, וזיקת הנאה.", "icon": "🧩"}, {"type": "example", "title": "שאלה 8, יולי 2025", "text": "נעמי ירשה בית פרטי בן שתי קומות שאינו ניתן לחלוקה, ורוצה לפצל אותו לשתי דירות ולמכור קומה אחת.", "law": "אי אפשר: אין תוקף לעסקה בחלק מסוים במקרקעין. קומה נמכרת לבד רק אחרי שהבית נרשם כבית משותף והקומה היא דירה רשומה."}, {"type": "check", "question": "land-basics-2"}, {"type": "concept", "title": "לעומק ולגובה, ובנפח", "text": "הבעלות מתפשטת מתחת לקרקע ומעליה. חלקה תלת-ממדית מפרידה נפח מוגדר, למשל מנהרה או חניון תת-קרקעי, ונרשמת לפי תכנית; דירה בבית משותף אינה נרשמת כך.", "icon": "🧊"}, {"type": "check", "question": "land-basics-3"}, {"type": "concept", "title": "שלושים יום מהתפיסה", "text": "סעיף 18: כוח סביר מותר תמיד כדי למנוע פלישה. אחרי שמישהו כבר תפס את הנכס, מותר להוציאו בכוח סביר רק תוך 30 ימים מיום התפיסה.", "icon": "⏳"}, {"type": "example", "title": "שאלה 20, יולי 2026", "text": "ניר פרץ לדירה של אורי ב-1 ביוני, כשאורי היה בחו\"ל. אורי גילה ב-20 ביוני, ופינה את ניר עם מאבטחים בכוח סביר ב-5 ביולי.", "law": "לא חוקי: המניין הוא מיום התפיסה ולא מיום הגילוי, וב-5 ביולי חלפו יותר משלושים יום. היה עליו לפנות לבית המשפט."}, {"type": "check", "question": "land-basics-4"}]'::jsonb, 'סעיפים 1-3, 11-14ח ו-18 לחוק המקרקעין', null, false, true
  from public.course_chapters c where c.slug = 'land-law'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-basics-1', l.chapter_id, l.id, 'practice', null, 'חברה שכרה חנות בקניון לתקופה של שלושים שנה, ואין לה אופציה לקנות אותה. איך מכנה חוק המקרקעין את הזכות שלה?', '["בעלות, כי בפועל היא מחזיקה בחנות לאורך כל חיי הבניין.", "שכירות רגילה, כי חכירה קיימת רק בקרקע של רשות מקרקעי ישראל.", "חכירה לדורות, כי זו שכירות לתקופה של למעלה מעשרים וחמש שנים.", "חכירה, אבל לא לדורות, כי חכירה לדורות עוברת בירושה."]'::jsonb, 2, null, 'סעיף 3 לחוק המקרקעין: שכירות לתקופה של למעלה מחמש שנים היא חכירה, ולמעלה מעשרים וחמש שנים היא חכירה לדורות. המונח נקבע רק לפי אורך התקופה, לא לפי בעל הקרקע ולא לפי ירושה, וזכות שהוקנתה שלא לצמיתות אינה בעלות.', 'סעיף 3 לחוק המקרקעין', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-basics'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-basics-2', l.chapter_id, l.id, 'practice', null, 'בבית פרטי בחלקה אחת, שלא נרשם כבית משותף, יש יחידת דיור בקומת הקרקע עם כניסה נפרדת. הבעלים רוצה למכור רק את היחידה הזו ולהשאיר את שאר הבית. האם אפשר?', '["כן. ליחידה יש כניסה נפרדת, ולכן היא נחשבת דירה שאפשר למכור לבד.", "כן, אם הקונה והמוכר יחתמו על הסכם שיתוף שמחלק ביניהם את השימוש.", "לא כעסקה בחלק מסוים. קודם צריך שהבית יירשם כבית משותף והיחידה תהיה דירה רשומה.", "לא, כי בית פרטי אינו ניתן לפיצול בשום דרך גם אם יירשם בעתיד."]'::jsonb, 2, null, 'סעיף 13: אין תוקף לעסקה בחלק מסוים במקרקעין. דירה בבית משותף היא נושא נפרד לעסקאות (סעיף 54), ולכן הדרך היא רישום הבית כבית משותף. הסכם שיתוף מסדיר שימוש בין שותפים בחלקים בלתי מסוימים, ואינו הופך יחידה לנכס נפרד. כניסה נפרדת לבדה אינה משנה את הדין.', 'סעיפים 13 ו-54 לחוק המקרקעין', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-basics'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-basics-3', l.chapter_id, l.id, 'practice', null, 'עירייה רוצה למכור לחברה פרטית קומת חניון שתיבנה מתחת לגן ציבורי, ולהשאיר את הגן בבעלותה. האם אפשר להפריד את הבעלות בחניון מהבעלות בקרקע?', '["לא. הבעלות בקרקע מתפשטת לכל העומק בלי חריגים, ולכן החניון שייך לבעל הקרקע.", "כן, ברישום חלקה תלת-ממדית לפי תכנית מאושרת, והבעלות בה מוגבלת לגבולותיה הרשומים.", "כן, בהסכם שכירות ארוך, אבל הבעלות עצמה לעולם לא נפרדת מהקרקע.", "לא, כי חלקה תלת-ממדית מותרת רק כשהמדינה מפקיעה את השטח לצורכי ציבור."]'::jsonb, 1, null, 'סעיף 11 קובע שהבעלות מתפשטת לעומק ולגובה, וסימן א''1 (סעיפים 14א-14ח) מאפשר לרשום חלקה תלת-ממדית כנושא נפרד לבעלות, בגבולותיה הרשומים בלבד, על פי תכנית, תשריט או הפקעה. הפקעה היא רק אחת משלוש הדרכים. שאלה דומה על המטרו נשאלה ב-2024.', 'סעיפים 11 ו-14א-14ח לחוק המקרקעין', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-basics'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-basics-4', l.chapter_id, l.id, 'practice', null, 'דנה מחזיקה כדין בחלקה. היא רואה שכן מתחיל להציב עמודי גדר בתוך החלקה שלה, ועוד באותה שעה עוצרת אותו בכוח סביר ומפרקת את העמודים. האם פעלה כדין?', '["לא. דין עצמי אסור, והיה עליה להזמין משטרה או לפנות לבית משפט.", "כן, אבל רק אם החלקה רשומה על שמה בטאבו ולא רק בחזקתה.", "כן. מחזיק כדין רשאי להשתמש בכוח סביר כדי למנוע הסגת גבול.", "לא, כי כוח סביר מותר רק כעבור שלושים יום, אחרי שנכשל ניסיון לפנות בדרכי שלום."]'::jsonb, 2, null, 'סעיף 18(א): המחזיק במקרקעין כדין רשאי להשתמש בכוח במידה סבירה כדי למנוע הסגת גבולו. הדרישה היא החזקה כדין, לא רישום. מגבלת שלושים הימים שבסעיף 18(ב) חלה על הוצאת מי שכבר תפס את המקרקעין, ונמנית מיום התפיסה.', 'סעיף 18 לחוק המקרקעין', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-basics'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'land-writing', 'סעיפים 7-8: עסקה נגמרת ברישום, והתחייבות טעונה כתב', 2, 'כמעט כל מתווך נתקל בזה: הצדדים לחצו ידיים, נתנו מקדמה, ואחד מהם מתחרט. סעיף 8 והלכת רבינאי קובעים מתי יש עסקה ומתי אין.', '<h3>סעיפים 6-7: עסקה נגמרת ברישום</h3><p>עסקה במקרקעין היא הקניה של בעלות או זכות אחרת לפי רצון המקנה (לא ירושה על פי צוואה). היא <strong>טעונה רישום ונגמרת ברישום</strong>; עד אז רואים אותה כהתחייבות לעשות עסקה.</p><h3>סעיף 8: התחייבות טעונה מסמך בכתב</h3><p>התחייבות לעשות עסקה במקרקעין <strong>טעונה מסמך בכתב</strong>. זו דרישה מהותית: הסכמה בעל פה, גם עם מקדמה ולחיצת יד, אינה התחייבות שאפשר לאכוף.</p><h3>רבינאי נ'' מן שקד: זיכרון דברים מחייב</h3><p>זיכרון דברים הוא חוזה מחייב כשיש בו <strong>גמירות דעת</strong> ו<strong>מסוימות</strong>: הנכס, המחיר, התשלומים והמסירה. המשפט "חוזה מפורט ייחתם אצל עורך דין" אינו שולל גמירות דעת כשעיקרי העסקה סוכמו. החתימה היא ראיה לגמירות דעת ולא תנאי לה, ולכן גם אישור בכתב בדוא"ל יכול להשלים חוזה. זיכרון דברים כזה מקיים את סעיף 8, ועל פיו אפשר לרשום הערת אזהרה.</p><h3>סעיף 79: שכירות קצרה</h3><p>שכירות לתקופה <strong>שאינה עולה על חמש שנים</strong> אינה טעונה רישום, וההתחייבות לה אינה טעונה כתב. בחישוב התקופה נכללת <strong>האופציה להארכה</strong>: שכירות שיחד עם הברירה עולה על חמש שנים טעונה כתב ורישום, גם לפני שהאופציה מומשה.</p>', '["עסקה במקרקעין נגמרת ברישום; עד אז היא התחייבות לעשות עסקה (סעיף 7).", "התחייבות לעשות עסקה במקרקעין טעונה מסמך בכתב, ובלעדיו אין התחייבות אכיפה (סעיף 8).", "רבינאי: זיכרון דברים עם גמירות דעת ומסוימות הוא חוזה מחייב, גם אם נאמר שחוזה מפורט ייחתם.", "חתימה היא ראיה לגמירות דעת ולא תנאי לה; אישור בכתב בדוא\"ל יכול להשלים חוזה.", "שכירות עד חמש שנים, כולל האופציה, אינה טעונה כתב ורישום (סעיף 79)."]'::jsonb, '[{"type": "concept", "title": "עסקה נגמרת ברישום", "text": "סעיף 7: עסקה במקרקעין טעונה רישום ונגמרת ברישום. עד אז רואים אותה כהתחייבות לעשות עסקה, ולכן היא חשופה לעסקה נוגדת.", "icon": "📝"}, {"type": "concept", "title": "בלי כתב אין התחייבות", "text": "סעיף 8: התחייבות לעשות עסקה במקרקעין טעונה מסמך בכתב. לחיצת יד, מקדמה ועדים אינם מחליפים מסמך.", "icon": "✍️"}, {"type": "check", "question": "land-writing-1"}, {"type": "concept", "title": "זיכרון דברים: גמירות דעת ומסוימות", "text": "רבינאי נ'' מן שקד: זיכרון דברים שסוכמו בו הנכס, המחיר, התשלומים והמסירה הוא חוזה מחייב, גם אם נכתב שחוזה מפורט ייחתם בהמשך.", "icon": "🤝"}, {"type": "example", "title": "שאלה 4, יולי 2023", "text": "משה ויוסי חתמו אצל עורך דין על זיכרון דברים עם מחיר, מועדי תשלום, מסירה ומיסים, ויוסי שילם מקדמה. ביום חתימת החוזה הרשמי משה לא הגיע: הציעו לו יותר.", "law": "חוזה מחייב: הפרטים המהותיים סוכמו והייתה גמירות דעת, ולכן החוזה הרשמי הוא פורמליות. הצעה גבוהה יותר מצד שלישי אינה עילה לחזור בו."}, {"type": "check", "question": "land-writing-2"}, {"type": "concept", "title": "החתימה היא ראיה, לא תנאי", "text": "הצעה כתובה וחתומה, ואישור כתוב בדוא\"ל של הצד השני, יכולים להשלים חוזה מחייב. השאלה היא גמירות דעת, לא מקום החתימה על הדף.", "icon": "📧"}, {"type": "check", "question": "land-writing-3"}, {"type": "concept", "title": "שכירות קצרה: בלי כתב ובלי רישום", "text": "סעיף 79: שכירות עד חמש שנים אינה טעונה כתב ורישום. האופציה להארכה נספרת: שלוש שנים ועוד אופציה לשלוש הן שש, וזה כבר טעון כתב ורישום.", "icon": "🔑"}, {"type": "check", "question": "land-writing-4"}]'::jsonb, 'סעיפים 6-8 ו-79 לחוק המקרקעין; ע"א 158/77 רבינאי נ'' מן שקד', null, false, true
  from public.course_chapters c where c.slug = 'land-law'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-writing-1', l.chapter_id, l.id, 'practice', null, 'מוכר וקונה סיכמו בעל פה בבית קפה על מכירת דירה, לחצו ידיים והקונה העביר מקדמה בהעברה בנקאית. שבוע אחר כך המוכר מודיע שהוא חוזר בו. האם הקונה יכול לאכוף את העסקה?', '["כן. המקדמה מוכיחה גמירות דעת, וזה כל מה שנדרש לחוזה מחייב במקרקעין.", "כן, אם יביא עדים לשיחה, כי עדות מחליפה את המסמך בעסקת מקרקעין.", "לא. התחייבות לעשות עסקה במקרקעין טעונה מסמך בכתב, ובלעדיו אין מה לאכוף.", "לא, אלא אם רשם הערת אזהרה לפני שהמוכר חזר בו מההסכמה."]'::jsonb, 2, null, 'סעיף 8 לחוק המקרקעין: התחייבות לעשות עסקה במקרקעין טעונה מסמך בכתב, וזו דרישה מהותית ולא ראייתית. בלי מסמך אין התחייבות שאפשר לאכוף, והקונה יכול לדרוש את המקדמה בחזרה (ואולי פיצוי לפי דיני החוזים, אבל לא את הדירה). הערת אזהרה נרשמת רק על התחייבות בכתב (סעיף 126), ולכן אי אפשר לרשום אותה כאן. שאלה דומה נשאלה ביולי 2025.', 'סעיפים 7 ו-8 לחוק המקרקעין', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-writing'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-writing-2', l.chapter_id, l.id, 'practice', null, 'קונה ומוכרת חתמו על זיכרון דברים: הכתובת, המחיר, מועדי התשלום ומועד המסירה, ובסופו "חוזה מפורט ייחתם אצל עורכי הדין". אחרי יומיים קיבלה המוכרת הצעה גבוהה יותר ומסרבת להמשיך. מה הדין?', '["היא רשאית לחזור בה, כי הצדדים עצמם קבעו שהחוזה המחייב ייחתם רק בהמשך.", "היא רשאית לחזור בה, ובלבד שתשיב מקדמה כפולה כפיצוי מוסכם על הנזק.", "זיכרון הדברים מחייב: יש בו גמירות דעת ומסוימות, והחוזה המפורט הוא פורמליות.", "זיכרון הדברים מחייב רק אם נערך בידי עורך דין, כי אחרת אינו מסמך בכתב."]'::jsonb, 2, null, 'לפי רבינאי נ'' מן שקד, זיכרון דברים שיש בו גמירות דעת ומסוימות, כלומר הפרטים המהותיים של העסקה, הוא חוזה מחייב, והמשפט על חוזה מפורט אינו שולל את גמירות הדעת. סעיף 8 דורש מסמך בכתב, לא עורך דין. אין בדין כלל של מקדמה כפולה.', 'סעיף 8 לחוק המקרקעין; ע"א 158/77 רבינאי נ'' מן שקד', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-writing'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-writing-3', l.chapter_id, l.id, 'practice', null, 'מוכר שלח לקונה בדוא"ל הסכם מכר מלא וחתום. הקונה לא חתם על המסמך, אבל השיב בכתב "אני מאשר את ההסכם ומעביר את התשלום הראשון מחר". המוכר מתחרט. האם נכרת חוזה?', '["לא. חוזה במקרקעין נכרת רק כשהקונה חותם על המסמך במקום המיועד לכך.", "לא, אלא אם ההסכם עצמו קבע שאישור בדוא\"ל יחליף את חתימת הקונה.", "כן. ההצעה הכתובה והאישור הכתוב מעידים על גמירות דעת, והחתימה אינה תנאי.", "כן, אבל רק אחרי שהמוכר יאשר שוב בכתב שהוא מקבל את אישור הקונה."]'::jsonb, 2, null, 'בהלכת רבינאי חתימה היא ראיה לגמירות דעת ולא תנאי לה. ההסכם המפורט נשלח בכתב, ולכן דרישת סעיף 8 מתקיימת, והאישור הכתוב של הקונה הוא קיבול שמשלים את החוזה. התנאים שבשאר החלופות אינם בדין. זו הסוגיה של שאלה 4 במבחן פברואר 2025.', 'סעיפים 1, 2 ו-5 לחוק החוזים (חלק כללי); סעיף 8 לחוק המקרקעין', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-writing'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-writing-4', l.chapter_id, l.id, 'practice', null, 'משכיר ושוכרת סיכמו בעל פה על שכירות חנות לשלוש שנים, עם אופציה לשוכרת להאריך בשלוש שנים נוספות. האם השכירות טעונה מסמך בכתב ורישום?', '["לא. התקופה המוסכמת היא שלוש שנים, והאופציה נספרת רק כשהיא ממומשת.", "לא, כי שכירות חנות לעולם אינה טעונה כתב, להבדיל משכירות דירה.", "כן. עם האופציה התקופה הכוללת עולה על חמש שנים, ולכן הפטור לשכירות קצרה אינו חל.", "כן, אבל רק אם אחד הצדדים יבקש את הרישום, אחרת אין חובה כלל."]'::jsonb, 2, null, 'סעיף 79(א) פוטר מכתב ומרישום שכירות שאינה עולה על חמש שנים, וסעיף 79(ב) קובע שהפטור לא חל על שכירות שיש עמה ברירה להאריך אותה לתקופה כוללת העולה על חמש שנים. שלוש ועוד שלוש הן שש. אין בחוק הבחנה בין חנות לדירה. שאלה דומה, עם אופציה ל-20 שנה, נשאלה באוגוסט 2024.', 'סעיפים 8 ו-79 לחוק המקרקעין', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-writing'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'land-conflicting', 'עסקאות נוגדות והערת אזהרה', 3, 'מוכר שמכר את אותה דירה פעמיים הוא תרחיש שהבחינה חוזרת אליו כמעט בכל מועד. סעיף 9 קובע מי זוכה, סעיפים 126-127 אומרים איך מגינים, והלכת גנז מוסיפה את תום הלב.', '<h3>סעיף 9: הראשון בזמן, וחריג אחד</h3><p>התחייב אדם לעסקה ולפני שנרשמה התחייב לעסקה נוגדת: <strong>זכות הראשון עדיפה</strong>, אלא אם <strong>השני פעל בתום לב ובתמורה, והעסקה לטובתו נרשמה</strong> בעודו בתום לב. שלושת התנאים מצטברים. <strong>הערת אזהרה אינה רישום העסקה</strong>, ולכן קונה שני שרשם הערה בלבד עדיין לא גבר.</p><h3>גנז נ'' בריטיש קולוניאל</h3><p>קונה ראשון שנמנע במשך שנים מלרשום הערת אזהרה, ובכך אפשר את "התאונה המשפטית", עלול לאבד את עדיפותו מכוח עקרון תום הלב כלפי קונה שני תם לב שרשם הערה, גם לפני שהשני השלים רישום. הראשון נשאר עם תביעת פיצויים נגד המוכר.</p><h3>סעיף 126: הערת אזהרה</h3><p>כשהוכח לרשם שבעל מקרקעין או בעל זכות <strong>התחייב בכתב</strong> לעשות עסקה או להימנע ממנה, הרשם רושם הערה <strong>לפי בקשת מי שהתחייב או לפי בקשת הזכאי</strong>. הקונה יכול לבקש לבד, על סמך החוזה, והרשם מודיע למוכר.</p><h3>סעיף 127: מה ההערה עושה</h3><p>כל עוד ההערה רשומה <strong>לא תירשם עסקה הסותרת אותה</strong>, אלא בהסכמת הזכאי או בצו בית משפט. ו<strong>עיקול, פשיטת רגל או פירוק שבאו אחריה</strong> אינם פוגעים בזכויות הזכאי.</p><h3>סעיפים 128, 10 ו-125</h3><p>הערה על צורך בהסכמה (128) נרשמת כשעסקה מותנית בהסכמת צד שלישי, לפי בקשתו, וגם היא חוסמת עסקה סותרת. במקרקעין מוסדרים הרישום הוא ראיה חותכת (125), ומי שרכש בתמורה בהסתמך בתום לב על הרישום, זכותו עומדת גם אם הרישום לא היה נכון (10).</p>', '["עסקאות נוגדות: הראשון גובר, אלא אם השני בתום לב, בתמורה, ורשם את העסקה בעודו בתום לב (סעיף 9).", "הערת אזהרה אינה רישום העסקה: קונה שני עם הערה בלבד עוד לא השלים את החריג.", "גנז: קונה ראשון שלא רשם הערה במשך שנים עלול להפסיד לקונה שני תם לב, ונשאר עם פיצויים.", "הערת אזהרה נרשמת על התחייבות בכתב, לפי בקשת המתחייב או הזכאי לבדו (סעיף 126).", "אחרי הערה לא תירשם עסקה סותרת, ועיקול מאוחר אינו פוגע בזכאי (סעיף 127)."]'::jsonb, '[{"type": "concept", "title": "הראשון גובר, אלא אם", "text": "סעיף 9: בעסקאות נוגדות זכות הראשון עדיפה, אלא אם השני פעל בתום לב, שילם תמורה, והעסקה שלו נרשמה בעודו בתום לב. שלושה תנאים, כולם.", "icon": "⚖️"}, {"type": "example", "title": "שאלה 7, יולי 2026", "text": "שמשון מכר את דירתו לשני קונים. שניהם שילמו, והשני גם רשם הערת אזהרה. שמשון נעלם.", "law": "הראשון גובר, אלא אם השני בתום לב, בתמורה, והשלים את רישום העסקה. הערת אזהרה אינה רישום העסקה, ולכן לבדה אינה מכריעה."}, {"type": "check", "question": "land-conflicting-1"}, {"type": "concept", "title": "גנז: מי שישן על זכויותיו", "text": "קונה ראשון שלא רשם הערת אזהרה במשך שנים ואפשר לקונה שני תם לב לקנות, עלול להפסיד את הדירה מכוח תום הלב ולהישאר עם פיצויים מהמוכר.", "icon": "😴"}, {"type": "example", "title": "שאלה 16, מאי 2023", "text": "מנשה קנה דירה ב-2010, שילם הכל ולא רשם הערת אזהרה. ב-2023 המוכר מכר אותה שוב לחיים, שלא ידע, שילם ורשם הערה.", "law": "חיים זוכה: לפי גנז, הקונה הראשון שהזניח את הרישום שלוש עשרה שנה מאבד את עדיפותו כלפי קונה שני תם לב שרשם הערה."}, {"type": "concept", "title": "הערת אזהרה: גם בלי המוכר", "text": "סעיף 126: על התחייבות בכתב, הרשם רושם הערה לפי בקשת המתחייב או לפי בקשת הזכאי לבדו. הקונה לא צריך חתימה נוספת של המוכר.", "icon": "🛡️"}, {"type": "check", "question": "land-conflicting-2"}, {"type": "concept", "title": "מה ההערה חוסמת", "text": "סעיף 127: כל עוד ההערה רשומה לא תירשם עסקה סותרת בלי הסכמת הזכאי או צו בית משפט, ועיקול או פשיטת רגל שבאו אחריה אינם פוגעים בזכאי.", "icon": "🔒"}, {"type": "check", "question": "land-conflicting-3"}, {"type": "concept", "title": "הסתמכות על הרישום", "text": "סעיף 10: במקרקעין מוסדרים, מי שרכש בתמורה בהסתמך בתום לב על הרישום, זכותו עומדת גם אם הרישום לא היה נכון. במקרקעין מוסדרים הרישום הוא ראיה חותכת.", "icon": "📖"}, {"type": "check", "question": "land-conflicting-4"}]'::jsonb, 'סעיפים 9, 10, 125-128 לחוק המקרקעין; ע"א 2643/97 גנז נ'' בריטיש קולוניאל', null, false, true
  from public.course_chapters c where c.slug = 'land-law'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-conflicting-1', l.chapter_id, l.id, 'practice', null, 'מוכר חתם על חוזה עם קונה ראשון וקיבל את מלוא התמורה. חודש אחר כך מכר את הדירה שוב לקונה שני, שלא ידע על הראשון, שילם ורשם הערת אזהרה. איש מהם לא נרשם כבעלים. מי גובר?', '["הקונה השני, כי רשם הערת אזהרה ראשון ופעל בתום לב ובתמורה.", "הקונה הראשון. השני לא השלים את העסקה ברישום, והערת אזהרה אינה רישום כזה.", "אף אחד, והדירה תימכר וכל אחד יקבל מחצית מהתמורה.", "הקונה שישלם ראשון את מס הרכישה, כי זה השלב שמשלים את העסקה."]'::jsonb, 1, null, 'סעיף 9: זכות הראשון עדיפה, אלא אם השני פעל בתום לב ובתמורה והעסקה לטובתו נרשמה. הערת אזהרה אינה רישום העסקה, ולכן החריג לא התקיים. חודש אחד אינו ההזנחה הממושכת של גנז. אין בדין חלוקה של הדירה, ותשלום המס אינו רישום.', 'סעיף 9 לחוק המקרקעין', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-conflicting'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-conflicting-2', l.chapter_id, l.id, 'practice', null, 'קונה חתם על חוזה מכר בלי עורכי דין. החוזה אינו מזכיר הערת אזהרה, והמוכר מסרב לחתום על בקשה לרשום אותה. האם הקונה יכול לרשום הערת אזהרה לבד?', '["לא. רק הבעלים הרשום מגיש בקשה להערת אזהרה, כדי למנוע הונאות.", "כן, אם יוכיח לרשם שהמוכר התחייב בכתב לעשות את העסקה, והרשם יודיע למוכר.", "לא בלי צו של בית משפט, כי המוכר הביע התנגדות מפורשת לרישום.", "כן, אבל רק אחרי שישלם למוכר את מלוא התמורה ויקבל ממנו קבלה."]'::jsonb, 1, null, 'סעיף 126(א): הוכח לרשם שבעל המקרקעין התחייב בכתב לעשות עסקה, ירשום הרשם הערה לפי בקשת המתחייב או לפי בקשת הזכאי. לפי סעיף 126(ב), כשההערה נרשמה לבקשת הזכאי בלבד, הרשם מודיע למתחייב. אין דרישה לצו או לתשלום מלא. זו הסוגיה של שאלה 6 במבחן ינואר 2023.', 'סעיף 126 לחוק המקרקעין', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-conflicting'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-conflicting-3', l.chapter_id, l.id, 'practice', null, 'רוכשת חתמה על חוזה ורשמה הערת אזהרה. לפני העברת הבעלות, נושה של המוכר הטיל עיקול על הדירה, וחודש אחר כך ניתן צו פשיטת רגל נגד המוכר. מה מצבה?', '["העיקול גובר, כי הדירה עדיין רשומה על שם המוכר ועיקול חל על נכסיו.", "העיקול ופשיטת הרגל אינם פוגעים בזכויותיה שנובעות מההתחייבות, כי ההערה קדמה להם.", "העיקול אינו פוגע בה, אבל צו פשיטת הרגל מבטל את החוזה ומחזיר לה את הכסף.", "מצבה תלוי בשאלה אם הנושה ידע על החוזה שלה כשהטיל את העיקול."]'::jsonb, 1, null, 'סעיף 127(ב): נרשמה הערת אזהרה ולאחר מכן הוטל עיקול, ניתן צו פשיטת רגל או צו פירוק, הם אינם פוגעים בזכויות הזכאי הנובעות מההתחייבות (בכפוף לטענת ביטול שהייתה עומדת גם אילו בוצעה העסקה במועדה). ידיעת הנושה אינה תנאי. זו התכלית של ההערה, ונשאלה בינואר 2023.', 'סעיף 127 לחוק המקרקעין', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-conflicting'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-conflicting-4', l.chapter_id, l.id, 'practice', null, 'קונה קנתה דירה במקרקעין מוסדרים מאדם שהיה רשום כבעלים בנסח. היא שילמה מחיר מלא ובדקה את הנסח. אחר כך התברר שהרישום על שם המוכר נעשה בטעות של לשכת הרישום. מה מעמד זכותה לפי סעיף 10?', '["זכותה בטלה, כי מי שאינו בעלים אמיתי אינו יכול להעביר בעלות לאחר.", "זכותה עומדת: רכשה בתמורה ובהסתמך בתום לב על הרישום במקרקעין מוסדרים.", "זכותה עומדת רק אם הבעלים האמיתי ידע על הטעות ולא פעל לתקן אותה.", "זכותה עומדת רק אם תשלם לבעלים האמיתי את ההפרש בין המחיר לשווי."]'::jsonb, 1, null, 'סעיף 10: מי שרכש זכות במקרקעין מוסדרים בתמורה ובהסתמך בתום לב על הרישום, כוחה של זכותו יפה אף אם הרישום לא היה נכון. במקרקעין מוסדרים הרישום הוא ראיה חותכת (סעיף 125(א)). התנאים שבחלופות האחרות אינם בסעיף.', 'סעיפים 10 ו-125 לחוק המקרקעין', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-conflicting'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'land-coownership', 'שותפים במקרקעין: מושע, הסכם שיתוף ופירוק', 4, 'מגרש של אחים, דירה של בני זוג, בניין ישן של ארבעה שותפים. פרק השיתוף מלא במספרים: רוב לניהול רגיל, חמש שנים להגבלת מכירה, שלוש שנים להגבלת פירוק.', '<h3>סעיפים 27-28: מושע</h3><p>במקרקעין של כמה בעלים, בעלותו של כל אחד מתפשטת בכל אתר ואתר, ו<strong>אין לשום שותף חלק מסוים</strong>. חזקה שהחלקים שווים.</p><h3>סעיף 29: הסכם שיתוף</h3><p>הסכם בין השותפים על ניהול ושימוש ניתן לרישום. <strong>נרשם: מחייב גם מי שנעשה שותף אחר כך</strong> וכל אדם. לא נרשם: מחייב רק את הצדדים לו.</p><h3>סעיפים 30-35: ניהול, שימוש וכסף</h3><p>בעלי רוב החלקים קובעים בניהול ובשימוש <strong>הרגילים</strong>; דבר החורג מהרגיל טעון הסכמת כולם. שותף יחיד רשאי לשימוש סביר ולפעולה דחופה. שותף שהשתמש <strong>חייב שכר ראוי</strong> לשאר לפי חלקיהם (33), וכל שותף זכאי לחלק מהפירות (35).</p><h3>סעיף 34: מכירת חלק</h3><p>כל שותף רשאי להעביר את חלקו <strong>בלי הסכמת השאר</strong>. תניה בהסכם שיתוף שמגבילה זאת אין כוחה יפה לתקופה <strong>העולה על חמש שנים</strong>.</p><h3>סעיף 37: פירוק</h3><p>כל שותף זכאי <strong>בכל עת</strong> לדרוש פירוק. תניה שמגבילה פירוק לתקופה העולה על <strong>שלוש שנים</strong>: כעבור שלוש שנים בית המשפט רשאי לצוות על פירוק אם הדבר צודק.</p><h3>סעיפים 38-42: דרכי הפירוק</h3><p>בהסכם, ובאין הסכם בצו בית משפט: חלוקה בעין אם אפשר (39); מכירה וחלוקת הפדיון אם אי אפשר או שהחלוקה תגרום הפסד ניכר (40); ובבית הראוי להירשם כבית משותף, <strong>רישום כבית משותף והקצאת דירות</strong> לשותפים לפי חלקיהם (42). בדירת מגורים של בני זוג, מכירה מתעכבת עד שנמצא הסדר מגורים לילדים הקטינים ולהורה שמחזיק בהם (40א).</p>', '["מושע: לכל שותף חלק בלתי מסוים בכל המקרקעין, וחזקה שהחלקים שווים (27-28).", "הסכם שיתוף שנרשם מחייב גם שותף עתידי; שלא נרשם, רק את הצדדים (29).", "שותף שהשתמש לבד חייב לשאר שכר ראוי, וכל שותף זכאי לחלקו בפירות (33, 35).", "הגבלה על מכירת חלק תקפה עד חמש שנים; הגבלה על פירוק, בית משפט רשאי לעקוף אחרי שלוש (34, 37).", "פירוק: חלוקה בעין, מכירה, או רישום כבית משותף והקצאת דירות (39-42)."]'::jsonb, '[{"type": "concept", "title": "מושע: הכל של כולם", "text": "סעיף 27: לכל שותף חלק בלתי מסוים בכל אתר ואתר, ואין לשום שותף חלק מסוים. כדי שחלקה מסוימת תירשם על שם אחד, צריך פירוק שיתוף.", "icon": "🧑‍🤝‍🧑"}, {"type": "concept", "title": "שימוש לבד עולה כסף", "text": "סעיף 33: שותף שהשתמש במקרקעין חייב לשאר שכר ראוי לפי חלקיהם, וסעיף 35 נותן לכל שותף חלק מהפירות. היעדר הסכם שיתוף לא פוטר.", "icon": "💰"}, {"type": "check", "question": "land-coownership-1"}, {"type": "concept", "title": "חמש שנים למכירה, שלוש לפירוק", "text": "סעיף 34: הגבלה על מכירת חלק אינה תקפה מעבר לחמש שנים. סעיף 37: הגבלה על פירוק לתקופה מעל שלוש שנים, בית המשפט רשאי לפרק כעבור שלוש אם זה צודק.", "icon": "🗓️"}, {"type": "example", "title": "שאלה 11, יולי 2025", "text": "נוי ועמית חתמו על הסכם שיתוף שאוסר לפרק את השיתוף לעשר שנים. אחרי חמש שנים הן הסתכסכו, ועמית רוצה לפרק.", "law": "בית המשפט רשאי לצוות על פירוק אם זה צודק: התניה מגבילה ליותר משלוש שנים, ושלוש כבר חלפו. אין צורך בהסכמת נוי."}, {"type": "check", "question": "land-coownership-2"}, {"type": "check", "question": "land-coownership-3"}, {"type": "concept", "title": "הסכם שיתוף: לרשום אותו", "text": "סעיף 29: הסכם שיתוף שנרשם מחייב גם מי שיהיה שותף בעתיד. הסכם שלא נרשם מחייב רק את מי שחתם, ולא קונה שהסתמך על הנסח.", "icon": "📒"}, {"type": "concept", "title": "פירוק בדרך של בית משותף", "text": "סעיף 42: כשעיקר המקרקעין בית שראוי להירשם כבית משותף, בית המשפט רשאי לפרק ברישום והקצאת דירות לשותפים לפי חלקיהם, בלי למכור.", "icon": "🏢"}, {"type": "example", "title": "שאלה 6, יולי 2026", "text": "ארבעה שותפים שווים בבניין ישן בן ארבע דירות. אחד תובע פירוק במכירה, שלושה רוצים שכל אחד יקבל דירה.", "law": "אפשר להימנע מהמכירה: בית המשפט רשאי לפרק בדרך של רישום הבניין כבית משותף והקצאת דירה לכל שותף."}, {"type": "check", "question": "land-coownership-4"}]'::jsonb, 'סעיפים 27-42 לחוק המקרקעין', null, false, true
  from public.course_chapters c where c.slug = 'land-law'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-coownership-1', l.chapter_id, l.id, 'practice', null, 'שלושה אחים יורשים מגרש בחלקים שווים. אחד מהם הפעיל במגרש כולו מגרש חניה בתשלום במשך שנתיים, והאחרים לא התנגדו. עכשיו הם דורשים חלק מהרווחים. מה הדין?', '["אין להם כלום. הם לא התנגדו, והעסק הוא של האח שהשקיע ועבד בו.", "הם זכאים רק לשכר ראוי על הקרקע, בלי קשר לרווחים שהפיק מהחניה.", "הם זכאים לשכר ראוי בעד השימוש ולחלקם בפירות, לפי חלקיהם במגרש.", "אין להם כלום כל עוד אין הסכם שיתוף שמגדיר מה החלק של כל אחד."]'::jsonb, 2, null, 'סעיף 33: שותף שהשתמש במקרקעין משותפים חייב ליתר השותפים שכר ראוי בעד השימוש, וסעיף 35: כל שותף זכאי לחלק מהפירות לפי חלקו. אי-התנגדות אינה ויתור, והיעדר הסכם שיתוף מחיל את ברירת המחדל של החוק. זו הסוגיה של שאלה 5 במבחן אוגוסט 2024.', 'סעיפים 33 ו-35 לחוק המקרקעין', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-coownership'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-coownership-2', l.chapter_id, l.id, 'practice', null, 'לפני שבע שנים חתמו שותפים במגרש על הסכם שיתוף, ובו הוראה שאף שותף לא ימכור את חלקו בלי הסכמת האחרים. עכשיו אחד מהם רוצה למכור את חלקו לזר, והשאר מתנגדים. האם הוא רשאי?', '["לא. ההסכם חתום, והמתנגדים יכולים לבקש צו מניעה נגד המכירה.", "כן. הגבלה כזו אין כוחה יפה לתקופה העולה על חמש שנים, והן כבר חלפו.", "לא, אלא אם יציע את חלקו קודם לשותפים במחיר שהזר הציע.", "כן, אבל רק אחרי שבית המשפט יאשר את המכירה כצודקת בנסיבות."]'::jsonb, 1, null, 'סעיף 34(א): כל שותף רשאי להעביר את חלקו בלי הסכמת השאר. סעיף 34(ב): תניה בהסכם שיתוף השוללת או מגבילה זכות זו אין כוחה יפה לתקופה העולה על חמש שנים. אין בסעיף זכות קדימה כללית לשותפים ואין צורך באישור בית משפט. זו הסוגיה של שאלה 3 במבחן מאי 2024.', 'סעיף 34 לחוק המקרקעין', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-coownership'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-coownership-3', l.chapter_id, l.id, 'practice', null, 'שני שותפים חתמו לפני שנה על הסכם שיתוף שאין בו שום הגבלה על פירוק. עכשיו הם מסוכסכים, ואחד רוצה לפרק את השיתוף והשני מסרב. מה הדין?', '["הוא אינו יכול לדרוש פירוק לפני שחלפו שלוש שנים מחתימת ההסכם.", "הוא יכול לדרוש פירוק רק אם השותף השני יסכים לדרך הפירוק.", "הוא זכאי לדרוש פירוק בכל עת, ובאין הסכמה יפורק השיתוף בצו בית משפט.", "הוא יכול לפרק את השיתוף בפנייה לרשם המקרקעין, בלי בית משפט."]'::jsonb, 2, null, 'סעיף 37(א): כל שותף זכאי בכל עת לדרוש פירוק השיתוף, וסעיף 38(ב): באין הסכם, הפירוק על פי צו בית המשפט. מגבלת שלוש השנים שבסעיף 37(ב) חלה רק כשבהסכם יש תניה שמגבילה פירוק, וכאן אין. זו הסוגיה של שאלה 5 במבחן ינואר 2023.', 'סעיפים 37 ו-38 לחוק המקרקעין', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-coownership'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-coownership-4', l.chapter_id, l.id, 'practice', null, 'שתי שותפות שוות בבית סיכמו בכתב שאחת מהן תשתמש לבד בחצר האחורית עשר שנים, אבל לא רשמו את ההסכם. השנייה מכרה את חלקה לקונה שלא ידע עליו והסתמך על הנסח. האם ההסכם מחייב את הקונה?', '["כן. הסכם שיתוף בכתב מחייב כל מי שנכנס לנעלי אחד הצדדים.", "כן, אם הוא נחתם לפני מכירת החלק ודווח לרשות המקומית.", "לא. הסכם שיתוף שלא נרשם אינו מחייב מי שנעשה שותף אחר כך.", "לא, כי הסכם שנותן לשותף שימוש בחלק מסוים בטל ממילא."]'::jsonb, 2, null, 'סעיף 29(א): הסכם שיתוף ניתן לרישום, ומשנרשם כוחו יפה גם כלפי מי שנעשה שותף לאחר מכן וכלפי כל אדם. הסכם שלא נרשם מחייב רק את הצדדים לו. ההסכם עצמו תקף בין שתי השותפות, ולכן אינו "בטל". זו הסוגיה של שאלה 22 במבחן יולי 2026.', 'סעיף 29 לחוק המקרקעין', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-coownership'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'land-condo-property', 'בית משותף: רכוש משותף, הצמדות ומה שאי אפשר להצמיד', 5, 'הצמדות הן מוקש קבוע בבחינה: הרבה חלופות שואלות "איזה רוב צריך", כשהתשובה הנכונה היא שאין רוב שמכשיר את זה. ארבעה דברים לעולם לא מוצמדים.', '<h3>סעיף 52: מה זה בית משותף ומה רכוש משותף</h3><p><strong>בית משותף</strong> הוא בית עם שתי דירות או יותר <strong>שנרשם בפנקס הבתים המשותפים</strong>. <strong>רכוש משותף</strong> הוא כל מה שאינו רשום כדירה: הקרקע, הגגות, הקירות החיצוניים, המסד, חדרי המדרגות, המעליות, המקלטים, ומיתקנים שמיועדים לשמש את כל בעלי הדירות או את מרביתם, גם אם הם בתוך דירה.</p><h3>סעיפים 54-55: הדירה והחלק הצמוד</h3><p>דירה בבית משותף היא נושא נפרד לבעלות ולעסקאות. לכל דירה צמוד חלק בלתי מסוים ברכוש המשותף, <strong>ואין תוקף לעסקה ברכוש המשותף בנפרד מהדירה</strong>.</p><h3>סעיף 55(ג): הצמדה, ומה שאסור</h3><p>בתקנון אפשר להצמיד חלק מסוים מהרכוש המשותף לדירה פלונית (חניה, מחסן, גג, גינה), ומאותו רגע הוא חלק מהדירה לכל דבר. <strong>לעולם לא: חדרי מדרגות, מעליות, מקלטים, ומיתקנים שמיועדים לשמש את כל בעלי הדירות</strong>, גם לא בהסכמת כולם.</p><h3>סעיף 62: תקנון מוסכם</h3><p>עורכים ומשנים תקנון <strong>ברוב בעלי הדירות ששני שלישים מהרכוש המשותף צמודים לדירותיהם</strong>, אבל <strong>הצמדה חדשה רק בהסכמת כל בעלי הדירות</strong>, חוץ מהצמדה לשם בנייה שמרחיבה דירה, שיש לה רוב משלה (71ב, בשיעור הבא). חלק שכבר הוצמד אפשר להעביר <strong>לדירה אחרת באותו בית</strong> בלי הסכמת השאר, בתיקון צו הרישום (62(א1), 145). למי שאינו בעל דירה בבית, אי אפשר.</p><h3>סעיף 57: החלק ברכוש המשותף</h3><p>לפי יחס שטח רצפת הדירה לשטח הרצפה של כל הדירות, אלא אם התקנון קבע אחרת. גזוזטראות וקירות חיצוניים לא נכנסים לחישוב.</p><h3>סעיפים 143 ו-145: צו הרישום ותיקונו</h3><p>צו רישום בית בפנקס נותן <strong>המפקח</strong>, לבקשת בעלים ששטח דירותיהם למעלה ממחצית השטח. תיקון צו הרישום נעשה גם הוא <strong>בידי המפקח, לבקשת כל בעל דירה או בעל זכות בדירה</strong>, אחרי הודעה לשאר.</p>', '["רכוש משותף: כל מה שאינו רשום כדירה, כולל קרקע, גג, קירות חיצוניים, מדרגות, מעליות ומקלטים (52).", "אין עסקה ברכוש המשותף בנפרד מהדירה; הצמוד עובר עם הדירה (55).", "אסור להצמיד חדרי מדרגות, מעליות, מקלטים ומיתקנים לכולם, גם בהסכמת כולם (55(ג)).", "שינוי תקנון ברוב שני שלישים מהרכוש המשותף; הצמדה חדשה רק בהסכמת כולם (62(א)), חוץ מהרחבת דירה (71ב).", "הצמדה קיימת עוברת רק לדירה אחרת באותו בית, בתיקון צו רישום אצל המפקח (62(א1), 145)."]'::jsonb, '[{"type": "concept", "title": "מה רכוש משותף", "text": "סעיף 52: כל חלקי הבית שאינם רשומים כדירות, ובהם הקרקע, הגגות, הקירות החיצוניים, חדרי המדרגות, המעליות והמקלטים. בית משותף הוא בית שנרשם בפנקס.", "icon": "🏢"}, {"type": "concept", "title": "הצמוד הולך עם הדירה", "text": "סעיף 55: לכל דירה צמוד חלק ברכוש המשותף, ואין תוקף לעסקה בו בנפרד. מחסן או חניה צמודים עוברים עם הדירה שנמכרת.", "icon": "🔗"}, {"type": "check", "question": "land-condo-property-1"}, {"type": "concept", "title": "ארבעה שאסור להצמיד", "text": "סעיף 55(ג): חדרי מדרגות, מעליות, מקלטים ומיתקנים שמיועדים לשמש את כולם לא מוצמדים לדירה, גם לא ב-100% הסכמה. כשהחלופות שואלות על רוב, זו המלכודת.", "icon": "⛔"}, {"type": "example", "title": "שאלה 3, יולי 2025", "text": "אסיפת הדיירים בבית משותף בעפולה הצביעה פה אחד להצמיד את המקלט לדירה אחת, תמורת תשלום לקופת הבית.", "law": "אי אפשר: מקלט נמצא ברשימה הסגורה של סעיף 55(ג). שום רוב, גם לא מאה אחוז, אינו מכשיר את ההצמדה."}, {"type": "check", "question": "land-condo-property-2"}, {"type": "concept", "title": "הצמדה חדשה: כולם", "text": "סעיף 62(א): תקנון משנים ברוב בעלי הדירות שבידם שני שלישים מהרכוש המשותף, אבל הצמדה של חלק מסוים לדירה פלונית רק בהסכמת כל בעלי הדירות. החריג: הצמדה לשם בנייה שמרחיבה את הדירה (71ב).", "icon": "🗳️"}, {"type": "check", "question": "land-condo-property-3"}, {"type": "concept", "title": "העברת הצמדה: רק בתוך הבית", "text": "חניה או מחסן צמודים אפשר להעביר לדירה אחרת באותו בית, בתיקון צו הרישום אצל המפקח. למי שאינו בעל דירה בבית אי אפשר למכור אותם.", "icon": "🚗"}, {"type": "example", "title": "שאלה 11, יולי 2026", "text": "אילן מוכר את דירתו לסיגל, ואת החניה הצמודה רוצה למכור לראובן, שיש לו משרד בבניין הסמוך.", "law": "אי אפשר: הצמדה היא חלק מהדירה, ואפשר להעביר אותה רק לדירה אחרת באותו בית משותף. ראובן אינו בעל נכס בבניין."}, {"type": "check", "question": "land-condo-property-4"}]'::jsonb, 'סעיפים 52-57, 62, 143 ו-145 לחוק המקרקעין', null, false, true
  from public.course_chapters c where c.slug = 'land-law'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-condo-property-1', l.chapter_id, l.id, 'practice', null, 'מוכר דירה בבית משותף, שאליה צמוד מחסן, כתב בחוזה שהמחסן אינו כלול במכירה ויישאר שלו. אין לו דירה אחרת בבניין. מה דין המחסן?', '["המחסן נשאר בבעלות המוכר, כי הצדדים רשאים להגדיר מה נמכר בחוזה ביניהם.", "המחסן עובר עם הדירה. אין תוקף לעסקה ברכוש המשותף בנפרד מהדירה שהוא צמוד אליה.", "המחסן חוזר להיות רכוש משותף של כל הבניין, כי הוצא ממכירת הדירה.", "המחסן נשאר אצל המוכר, אם נציגות הבית תאשר זאת בהחלטה ברוב רגיל."]'::jsonb, 1, null, 'סעיף 55(ב) ו-(ג): חלק מהרכוש המשותף שהוצמד לדירה דינו כדין הדירה, ועסקה בדירה חלה גם עליו; אין תוקף לעסקה ברכוש המשותף בנפרד. אפשר להעביר הצמדה רק לדירה אחרת באותו בית, ולמוכר אין כזו. זו הסוגיה של שאלה 11 במבחן ינואר 2023.', 'סעיף 55 לחוק המקרקעין', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-condo-property'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-condo-property-2', l.chapter_id, l.id, 'practice', null, 'בעל דירה בקומה החמישית מבקש להצמיד לדירתו את חלק חדר המדרגות שמול הדלת שלו, כדי להרחיב את המבואה. כל השכנים מסכימים בכתב. האם אפשר לרשום את ההצמדה?', '["כן. הסכמת כל בעלי הדירות מספיקה לכל הצמדה של רכוש משותף.", "כן, ברוב בעלי הדירות שבידם שני שלישים מהרכוש המשותף, וממילא יש כאן יותר.", "לא. חדר מדרגות אינו ניתן להצמדה לדירה, גם לא בהסכמת כל בעלי הדירות.", "לא, אלא אם המפקח על המקרקעין יאשר שההצמדה אינה פוגעת בבטיחות הבניין."]'::jsonb, 2, null, 'סעיף 55(ג): בעלי הדירות רשאים להצמיד חלק מהרכוש המשותף לדירה, ובלבד שלא יעשו זאת ביחס לחדרי מדרגות, מעליות, מקלטים ומיתקנים המיועדים לשמש את כל בעלי הדירות. זו רשימה סגורה שאף רוב אינו גובר עליה. זו הסוגיה של שאלה 22 במבחן מאי 2025.', 'סעיף 55(ג) לחוק המקרקעין', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-condo-property'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-condo-property-3', l.chapter_id, l.id, 'practice', null, 'בעלת הפנטהאוז מבקשת להצמיד לדירתה את חלק הגג שמעליה, כדי להשתמש בו כמרפסת פרטית בלי לבנות עליו. בעלי הדירות שבידם שלושה רבעים מהרכוש המשותף תומכים, ושני שכנים מתנגדים. האם אפשר לקבוע את ההצמדה בתקנון?', '["כן. הרוב גבוה משני שלישים מהרכוש המשותף, וזה הרוב לשינוי תקנון.", "לא. הגג הוא רכוש משותף שאסור להצמיד לדירה, גם לא בהסכמת כולם.", "לא. הצמדה של חלק מסוים מהרכוש המשותף לדירה פלונית טעונה הסכמת כל בעלי הדירות.", "כן, ובלבד שבעלת הפנטהאוז תשלם לשכנים פיצוי שיקבע שמאי מקרקעין."]'::jsonb, 2, null, 'סעיף 62(א): תקנון משנים ברוב בעלי הדירות ששני שלישים מהרכוש המשותף צמודים לדירותיהם, אבל "אין לקבוע הצמדה של חלק מסויים מהרכוש המשותף לדירה פלונית אלא בהסכמת כל בעלי הדירות". הגג אינו ברשימת האיסור של 55(ג), ולכן ההצמדה אפשרית, אבל רק פה אחד. הרוב המיוחד של סעיף 71ב חל רק על הצמדה לשם בנייה שמטרתה הרחבת הדירה, וכאן אין בנייה. זו הסוגיה של שאלה 9 במבחן יולי 2023.', 'סעיפים 55(ג) ו-62(א) לחוק המקרקעין', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-condo-property'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-condo-property-4', l.chapter_id, l.id, 'practice', null, 'בעל דירה בבית משותף רוצה להעביר את המחסן הצמוד לדירתו אל דירה אחרת שקנה באותו בניין, ושאר הדיירים מתנגדים. מה הדרך?', '["אי אפשר. הצמדה שנקבעה בתקנון נשארת עם הדירה המקורית לתמיד.", "רק בהחלטת אסיפה כללית של בעלי הדירות ברוב שני שלישים מהרכוש המשותף.", "בקשה למפקח על רישום מקרקעין לתקן את צו הרישום, בלי הסכמת שאר הדיירים.", "תביעה בבית משפט השלום, שמוסמך לשנות הצמדות בבית משותף."]'::jsonb, 2, null, 'סעיף 62(א1): חלק שהוצמד לדירה אפשר להעביר לדירה אחרת בבית בלי הסכמת בעלי הדירות האחרים, ובלבד שמתקיימות הוראות סעיף 145, שלפיו המפקח מתקן את צו הרישום לבקשת בעל דירה, אחרי הודעה והזדמנות לטעון. הגוף המוסמך הוא המפקח, לא בית משפט השלום. שאלה 10 במבחן יולי 2023 שאלה מי מגיש ולמי.', 'סעיפים 62(א1) ו-145 לחוק המקרקעין', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-condo-property'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
