  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'land-condo-management', 'בית משותף: הוצאות, מעלית, הרחבות, סכסוכים ותמ"א 38', 6, 'כאן גרים רוב המספרים של הפרק: יחס שטח רצפה, שני שלישים למעלית, שלושה רבעים להרחבה, שישים אחוז לממ"ד, ושני שלישים או ארבע חמישיות בתמ"א 38.', '<h3>סעיף 58: הוצאות לפי שטח</h3><p>כל בעל דירה משתתף בהוצאות ההחזקה התקינה והניהול של הרכוש המשותף <strong>לפי יחס שטח רצפת דירתו לשטח כל הדירות</strong>, אלא אם התקנון קבע אחרת. לא לפי קומה ולא לפי שימוש.</p><h3>סעיף 59ו: מעלית</h3><p>בעלי <strong>שני שלישים מהדירות</strong> רשאים להחליט באסיפה על התקנת מעלית (אם אפשר היתר ואין פגיעה מהותית). <strong>את ההתקנה משלמים המחליטים</strong>, ובעלי דירות בקומת הקרקע לא משלמים עליה גם אם החליטו. <strong>את ההחזקה וההפעלה משלמים כולם</strong>.</p><h3>סעיף 59א: דוד שמש</h3><p>בעל דירה רשאי להתקין דוד על הגג בלי הסכמה, עם היתר, במקום שלא שימש לדבר אחר ובפגיעה מזערית בחזות. אם <strong>הגג אינו מספיק לדוד לכל דירה</strong>, נדרשת הסכמת כל בעלי הדירות, והמפקח רשאי להתיר אם ההתנגדות אינה סבירה.</p><h3>סעיף 59ג: התאמות לאדם עם מוגבלות</h3><p>ברכוש המשותף, על חשבון בעל הדירה, באישור רופא, פיזיותרפיסט או מרפא בעיסוק ובהודעה של 40 יום: חלק א'' בלי הסכמה (מאחז יד, אינטרקום, כבש עד 8 מטר והפרש גובה עד 75 ס"מ), חלק ב'' ברוב בעלי הדירות (שינוי שער, הרחבת שביל, מעלון), <strong>חלק ג'' בהסכמת 60% מהדירות</strong> (חניה).</p><h3>סעיף 71ב: הרחבת דירה</h3><p>הוצאת רכוש משותף והצמדתו לשם הרחבה: <strong>שלושה רבעים מהדירות ושני שלישים מהרכוש המשותף</strong>. לשם ממ"ד: <strong>60% מהדירות</strong>. מתנגד שטוען לפגיעה מהותית פונה למפקח תוך 30 יום.</p><h3>סעיף 72: מי מכריע</h3><p>סכסוך בין בעלי דירות על התקנון, ההוצאות וההתאמות: <strong>המפקח</strong>, שסמכויותיו כשל שופט שלום. הסגת גבול בדירה או ברכוש המשותף: התובע <strong>בוחר</strong> בין בית משפט מוסמך למפקח. כל בעל דירה רשאי לתבוע, לא רק הנציגות.</p><h3>חוק החיזוק (תמ"א 38)</h3><p>עבודה ברכוש המשותף על פי תמ"א 38: שינוי ברכוש המשותף, רוב בעלי הדירות; הרחבת דירות, 60%; <strong>בניית דירות חדשות</strong>, כל בעלי הדירות, אבל <strong>המפקח רשאי לאשר</strong> בתביעה של בעלי שני שלישים מהדירות ושני שלישים מהרכוש המשותף; ובלבד שאם אחד מבעלי הדירות קשיש (בן 80 ביום שנחתמה העסקה הראשונה בפרויקט) או מרותק לביתו, הוצעו לו מגורים חלופיים לתקופת העבודות (5(ב1)); <strong>הריסה ובנייה מחדש</strong>, המפקח רשאי לאשר בארבע חמישיות מהדירות וארבע חמישיות מהרכוש המשותף (5א). <strong>הסכמה ניתנת בכתב ומאומתת בידי עורך דין</strong> כמו שטר עסקה.</p>', '["הוצאות הרכוש המשותף לפי יחס שטח רצפת הדירה, אלא אם התקנון קבע אחרת (58).", "מעלית: החלטה ברוב שני שלישים מהדירות; ההתקנה על המחליטים וקומת קרקע פטורה; ההחזקה על כולם (59ו).", "הרחבה: שלושה רבעים מהדירות ושני שלישים מהרכוש המשותף; ממ\"ד: 60% מהדירות (71ב).", "סכסוך בין דיירים אצל המפקח; הסגת גבול: לבחירת התובע, מפקח או בית משפט (72).", "תמ\"א 38 עם דירות חדשות: המפקח רשאי לאשר בשני שלישים ושני שלישים, ובתנאי מגורים חלופיים לקשיש."]'::jsonb, '[{"type": "concept", "title": "הוצאות לפי שטח הרצפה", "text": "סעיף 58: כל בעל דירה משלם לפי יחס שטח רצפת דירתו לשטח כל הדירות, אלא אם התקנון קבע אחרת. לא לפי קומה, לא לפי שימוש במעלית ולא בחלקים שווים.", "icon": "📐"}, {"type": "example", "title": "שאלה 21, נובמבר 2024", "text": "ועד הבית דרש מבעל דירת גג, שגדולה פי שניים משאר הדירות, לשלם פי שניים דמי ועד. הבית מתנהל לפי התקנון המצוי.", "law": "הדרישה כדין: בלי הוראה אחרת בתקנון, ההשתתפות בהוצאות היא לפי יחס שטח הרצפה, ולכן דירה כפולה משלמת כפול."}, {"type": "check", "question": "land-condo-management-1"}, {"type": "concept", "title": "מעלית: מי מחליט ומי משלם", "text": "סעיף 59ו: שני שלישים מהדירות מחליטים. את ההתקנה משלמים המחליטים, וקומת הקרקע פטורה גם אם החליטה. את ההחזקה וההפעלה משלמים כולם.", "icon": "🛗"}, {"type": "check", "question": "land-condo-management-2"}, {"type": "concept", "title": "הרחבה וממ\"ד", "text": "סעיף 71ב: הוצאת רכוש משותף לשם הרחבת דירה טעונה שלושה רבעים מהדירות ושני שלישים מהרכוש המשותף. כשההרחבה היא לבניית ממ\"ד, 60% מהדירות.", "icon": "🧱"}, {"type": "check", "question": "land-condo-management-3"}, {"type": "concept", "title": "מפקח או בית משפט", "text": "סעיף 72: סכסוך על התקנון וההוצאות מכריע המפקח. הסגת גבול ברכוש המשותף: התובע בוחר בין המפקח לבית משפט מוסמך. כל בעל דירה רשאי לתבוע.", "icon": "🏛️"}, {"type": "check", "question": "land-condo-management-4"}, {"type": "concept", "title": "תמ\"א 38: מי מאשר", "text": "דירות חדשות: כל בעלי הדירות, אבל המפקח רשאי לאשר בתביעת שני שלישים מהדירות ושני שלישים מהרכוש המשותף. בעל דירה קשיש או מרותק לביתו: רק אם הוצעו לו מגורים חלופיים. הריסה ובנייה מחדש: ארבע חמישיות.", "icon": "🏗️"}, {"type": "example", "title": "שאלה 11, יולי 2023", "text": "כל הדיירים חתמו על תמ\"א 38 עם דירות חדשות, חוץ מחנה, קשישה נכה המרותקת לביתה. הקבלן לא מציע לה דיור חלופי.", "law": "המפקח אינו מוסמך לאשר את העבודות כל עוד לא הוצעו לחנה מגורים חלופיים לתקופת הביצוע, גם כשהרוב קיים."}, {"type": "check", "question": "land-condo-management-5"}]'::jsonb, 'סעיפים 58, 59א-59ו, 71ב, 72 לחוק המקרקעין; חוק החיזוק מפני רעידות אדמה, התשס"ח-2008', null, false, true
  from public.course_chapters c where c.slug = 'land-law'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
