insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-condo-management-1', l.chapter_id, l.id, 'practice', null, 'בבית משותף שש דירות של 80 מ"ר ודירת גג של 160 מ"ר. בתקנון אין הוראה על חלוקת ההוצאות, ונציגות הבית מחלקת את התיקון של הגג בין כל הדירות בחלקים שווים. מה הדין?', '["החלוקה תקינה: כל דירה היא יחידה אחת ומשלמת חלק שווה ברכוש המשותף.", "החלוקה שגויה: את תיקון הגג משלמת לבדה דירת הגג, שנמצאת ישירות מתחתיו.", "החלוקה שגויה: כל דירה משלמת לפי יחס שטח רצפתה לשטח כל הדירות, ודירת הגג פי שניים.", "החלוקה תקינה, אם הנציגות החליטה עליה ברוב רגיל של חבריה."]'::jsonb, 2, null, 'סעיף 58(א): בעל דירה משתתף בהוצאות ההחזקה התקינה של הרכוש המשותף לפי יחס שטח רצפת דירתו לשטח הרצפה של כל הדירות, אלא אם נקבע בתקנון שיעור אחר. הגג הוא רכוש משותף של כולם (סעיף 52), ולכן כולם משתתפים בתיקונו. שאלה 2 במבחן ינואר 2023 עסקה בגג שדולף.', 'סעיפים 52 ו-58 לחוק המקרקעין', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-condo-management'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-condo-management-2', l.chapter_id, l.id, 'practice', null, 'בבית משותף של 12 דירות החליטו בעלי 9 דירות להתקין מעלית. בעלת דירה בקומה השנייה הצביעה נגד. מה היא חייבת לשלם?', '["את חלקה בהתקנה ובהחזקה, כי ההחלטה התקבלה כדין והמעלית רכוש משותף.", "כלום, כי מי שהתנגד אינו חייב בשום הוצאה של המעלית.", "את חלקה בהחזקה ובהפעלה בלבד. את ההתקנה משלמים בעלי הדירות שהחליטו עליה.", "את חלקה בהתקנה בלבד, כי ההחזקה מוטלת רק על מי שמשתמש במעלית."]'::jsonb, 2, null, 'סעיף 59ו(ב): בעלי הדירות המחליטים על התקנת המעלית נושאים בהוצאות ההתקנה, ובעלי דירות בקומת הקרקע פטורים מהן גם אם החליטו; כל בעלי הדירות חייבים להשתתף בהוצאות החזקתה והפעלתה, לפי יחס שטח הרצפה. ההחלטה עצמה דורשת שני שלישים מהדירות, ו-9 מ-12 עומדים בכך. שאלה 7 במבחן מאי 2025 עסקה בדייר קומת הקרקע.', 'סעיף 59ו לחוק המקרקעין', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-condo-management'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
