insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-condo-management-3', l.chapter_id, l.id, 'practice', null, 'בעלי דירה רוצים להוציא חלק מהחצר המשותפת ולהצמיד אותו לדירתם כדי לבנות בה ממ"ד. איזה רוב בבית המשותף נדרש להחלטה?', '["בעלי 60% מהדירות, כי מטרת ההרחבה היא בניית מרחב מוגן דירתי.", "בעלי שלושה רבעים מהדירות שבידם שני שלישים מהרכוש המשותף.", "כל בעלי הדירות, כי מדובר בהצמדה חדשה של רכוש משותף.", "רוב רגיל של בעלי הדירות באסיפה כללית שכונסה כדין."]'::jsonb, 0, null, 'סעיף 71ב(א): ההחלטה להוציא רכוש משותף ולהצמידו לדירה לשם הרחבה טעונה בעלי שלושה רבעים מהדירות ושני שלישים מהרכוש המשותף, אבל כשנושא ההחלטה הוא הרחבה לשם מרחב מוגן דירתי או קומתי, די בבעלי שישים אחוזים מהדירות. סעיף 71ב גובר כאן על הדרישה להסכמת כולם שבסעיף 62(א).', 'סעיף 71ב לחוק המקרקעין', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-condo-management'
