insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-condo-management-4', l.chapter_id, l.id, 'practice', null, 'בעל דירה בקומה העליונה סגר חלק מהגג המשותף והפך אותו למרפסת פרטית. שכן מקומה שנייה רוצה לתבוע אותו, ונציגות הבית לא מתכוונת לעשות דבר. מה האפשרויות שלו?', '["רק הנציגות רשאית לתבוע בשם הבית, ולכן עליו לשכנע אותה לפעול.", "הוא רשאי לתבוע בעצמו, לבחירתו בבית משפט מוסמך או אצל המפקח על רישום המקרקעין.", "עליו לפנות לוועדה המקומית לתכנון ובנייה, שמוסמכת להורות על פירוק.", "הוא רשאי לתבוע רק בבית המשפט המחוזי, כי מדובר בזכויות קניין."]'::jsonb, 1, null, 'סעיף 72(ב): סכסוך בין בעלי דירות על הסגת גבול מצד בעל דירה לגבי הרכוש המשותף, רשאי התובע להביא לפי בחירתו לבית משפט מוסמך או למפקח. כל בעל דירה הוא צד שרשאי לתבוע (סעיף 73), לא רק הנציגות. הוועדה המקומית עוסקת בהיתרים ולא בסכסוך הקנייני. זו הסוגיה של שאלה 8 במבחן מאי 2025.', 'סעיפים 72(ב) ו-73 לחוק המקרקעין', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-condo-management'
