insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-condo-management-5', l.chapter_id, l.id, 'practice', null, 'בבית משותף של 12 דירות, בעלי 8 דירות שבידם שני שלישים מהרכוש המשותף רוצים פרויקט תמ"א 38 עם חיזוק ובניית דירות חדשות. בעלי 4 דירות מתנגדים, ואף אחד מהם אינו קשיש או מרותק לביתו. האם הפרויקט יכול לצאת לדרך?', '["לא. בניית דירות חדשות על הרכוש המשותף טעונה תמיד הסכמת כל בעלי הדירות.", "כן, המפקח רשאי לאשר את העבודה בתביעה שלהם, אחרי שנתן למתנגדים לטעון.", "כן, הרוב רשאי להחליט לבד באסיפה כללית, בלי לפנות למפקח.", "לא, כי נדרש רוב של ארבע חמישיות מהדירות לכל פרויקט של תמ\"א 38."]'::jsonb, 1, null, 'חוק החיזוק, סעיף 5(א): עבודה שמטרתה בניית דירה חדשה טעונה החלטה של כל בעלי הדירות, אבל המפקח רשאי לאשר אותה על פי תביעה של בעלי שני שלישים מהדירות ששני שלישים מהרכוש המשותף צמודים לדירותיהם, אחרי שנתן לכל בעל דירה לטעון. ארבע חמישיות נדרשות להריסה ובנייה מחדש (סעיף 5א), לא לחיזוק עם דירות חדשות.', 'סעיפים 5 ו-5א לחוק המקרקעין (חיזוק בתים משותפים מפני רעידות אדמה)', 5, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
