insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'land-others-rights', 'שכירות, משכנתה, זיקת הנאה וזכות קדימה', 7, 'ארבע זכויות שאדם מחזיק בנכס של מישהו אחר. כל אחת עם מספר אחד שחוזר בבחינה: חמש שנים, פדיון לפני המועד, שלושים שנה, ושלושים יום.', '<h3>סעיפים 79-80: שכירות קצרה ושכירויות נוגדות</h3><p>שכירות עד חמש שנים, כולל אופציה, אינה טעונה כתב ורישום (79). שני שוכרים בשכירות קצרה שלא נרשמה: <strong>הראשון עדיף, אלא אם השני שכר וקיבל את המקרקעין בתום לב</strong> (80). כאן החזקה היא מה שמכריע, כי אין רישום.</p><h3>סעיפים 4, 85-91: משכנתה</h3><p><strong>משכנתה היא מישכון של מקרקעין</strong> (4), ואת המקרקעין או שכירות רשומה ממשכנים רק במשכנתה (91). זכות שאינה רשומה בפנקסי המקרקעין, למשל בדירה שנקנתה מקבלן ועוד לא נרשמה, ממושכנת במשכון ולא במשכנתה. המשכנתה אינה מונעת מהבעלים לעשות עסקה, אבל העסקה אינה גורעת מזכות המימוש (85). <strong>אי אפשר לשלול את הזכות לפדות לפני המועד</strong> (88), ואם בעל המשכנתה מסרב לקבל, מפקידים בידי הרשם והוא מפקיע את המשכנתה במידה שנפדתה (89).</p><h3>סעיפים 5, 92-98: זיקת הנאה</h3><p>שעבוד מקרקעין להנאה <strong>בלי זכות להחזיק</strong>: מעבר, חניה, איסור בנייה. לטובת מקרקעין או לטובת אדם. <strong>שימוש של שלושים שנים רצופות</strong> מקנה את הזיקה וזכות לרשום אותה, ו<strong>הודעה בכתב של הבעלים שהוא מתנגד מפסיקה את מניין השנים</strong> (94). זיקה לטובת אדם עוברת רק בהסכמת בעל המקרקעין הכפופים, אלא אם תנאי הזיקה קבעו אחרת (95). הזיקה <strong>לתקופה בלתי מוגבלת</strong> אם לא נקבעה תקופה, ובית המשפט רשאי לבטלה בגלל אי-שימוש או שינוי נסיבות (96).</p><h3>סעיפים 99-104: זכות קדימה</h3><p>זכות קדימה על פי הסכם נרשמת (99). <strong>בין בני זוג מכוח החוק</strong>: במשק חקלאי, בבית עסק שהם מנהלים יחד או בדירה שמשמשת להם למגורים, בן זוג לא יעביר את חלקו לאחר בלי להציע לבן הזוג קודם (101). ההצעה בכתב בדואר רשום עם המחיר; לבעל הזכות <strong>30 ימים</strong> לשלם או להפקיד, ואחר כך רואים אותו כמסרב (102). אחרי סירוב אפשר למכור <strong>תוך שישה חודשים, ולא במחיר נמוך מההצעה</strong>; לא נמכר בתקופה, מציעים שוב (103).</p>', '["שכירות קצרה נוגדת: הראשון עדיף, אלא אם השני שכר וקיבל חזקה בתום לב (80).", "משכנתה היא משכון של מקרקעין; זכות שלא נרשמה ממושכנת אצל רשם המשכונות (4, 91).", "אין לשלול פדיון לפני המועד; בעל משכנתה שמסרב, מפקידים אצל הרשם (88, 89).", "זיקת הנאה נרכשת בשלושים שנות שימוש רצופות, והתנגדות בכתב מפסיקה את המניין (94).", "זכות קדימה: הצעה בכתב, 30 יום להשיב, ואחרי סירוב מכירה תוך שישה חודשים ולא בפחות (102-103)."]'::jsonb, '[{"type": "concept", "title": "שכירות קצרה נוגדת", "text": "סעיף 80: שני שוכרים בשכירות קצרה שלא נרשמה? הראשון עדיף, אלא אם השני שכר וקיבל את המקרקעין בתום לב. בלי רישום, החזקה מכריעה.", "icon": "🔑"}, {"type": "example", "title": "שאלה 17, מאי 2024", "text": "דני התחייב להשכיר לדינה לשנה, והיא שילמה מראש ולא קיבלה חזקה. יום אחר כך השכיר ליפית, שילמה וקיבלה את הדירה.", "law": "אם יפית לא ידעה על דינה, זכותה גוברת: השכירות לשנה אינה טעונה רישום, והיא שכרה וקיבלה חזקה בתום לב."}, {"type": "check", "question": "land-others-rights-1"}, {"type": "concept", "title": "משכנתה ומשכון", "text": "משכנתה היא משכון של מקרקעין רשומים. זכות שעוד אינה רשומה, כמו דירה מקבלן שזכויותיה בחברה משכנת, ממושכנת במשכון אצל רשם המשכונות.", "icon": "🏦"}, {"type": "concept", "title": "פדיון לפני המועד", "text": "סעיף 88: תנאי המשכנתה אינם יכולים לשלול פירעון מוקדם. סעיף 89: בעל המשכנתה מסרב לקבל? מפקידים בידי הרשם, והוא מפקיע את המשכנתה במידה שנפדתה.", "icon": "💳"}, {"type": "check", "question": "land-others-rights-2"}, {"type": "concept", "title": "זיקת הנאה: שלושים שנה", "text": "סעיף 94: מי שהשתמש בזכות הראויה להיות זיקת הנאה שלושים שנים רצופות רכש אותה ורשאי לרשום. הודעה בכתב של הבעלים שהוא מתנגד מפסיקה את המניין.", "icon": "🚶"}, {"type": "check", "question": "land-others-rights-3"}, {"type": "concept", "title": "בלי תאריך תפוגה", "text": "סעיף 96: זיקת הנאה היא לתקופה בלתי מוגבלת, אלא אם נקבעה תקופה. רק בית משפט רשאי לבטל או לשנות אותה, בגלל אי-שימוש או שינוי נסיבות.", "icon": "♾️"}, {"type": "check", "question": "land-others-rights-4"}, {"type": "concept", "title": "זכות קדימה: 30 יום ושישה חודשים", "text": "בני זוג בדירת מגוריהם, במשק חקלאי או בעסק משותף מציעים זה לזה קודם. הצעה בכתב, 30 יום להשיב. אחרי סירוב: מכירה תוך שישה חודשים ולא במחיר נמוך מההצעה.", "icon": "💍"}, {"type": "example", "title": "שאלה 12, ינואר 2023", "text": "רחל ויעקב, זוג נשוי, בעלים של דירת מגוריהם. יעקב מכר את חלקו ליצחק בלי להציע אותו קודם לרחל.", "law": "יעקב היה חייב להציע את חלקו לרחל לפני שהציע לאחר: זכות קדימה מכוח סעיף 101, בלי צורך ברישום ובלי מגבלת זמן."}, {"type": "check", "question": "land-others-rights-5"}]'::jsonb, 'סעיפים 4, 5, 78-106 לחוק המקרקעין', null, false, true
  from public.course_chapters c where c.slug = 'land-law'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-others-rights-1', l.chapter_id, l.id, 'practice', null, 'משכיר חתם עם שוכר ראשון על שכירות דירה לשלוש שנים, וקיבל ממנו שכר דירה לחצי שנה, אבל המפתחות עוד לא נמסרו. למחרת השכיר את אותה דירה לשוכרת שנייה, שלא ידעה דבר, שילמה וקיבלה את המפתחות ונכנסה. מי גובר?', '["השוכר הראשון, כי חוזה השכירות שלו נחתם קודם ושולם עליו כסף.", "השוכרת השנייה, כי שכרה וקיבלה את הדירה בתום לב, והשכירות אינה טעונה רישום.", "השוכר הראשון, אלא אם השנייה רשמה הערת אזהרה לפני שנכנסה לדירה.", "אף אחד, והמשכיר יבחר למי להשכיר ויחזיר לשני את כספו בכפל."]'::jsonb, 1, null, 'סעיף 80: הושכרו מקרקעין בשכירות שאינה טעונה רישום ולא נרשמה, ולפני שנמסרו לשוכר הושכרו לאחר בשכירות נוגדת, זכות הראשון עדיפה, אבל אם השני שכר וקיבל את המקרקעין בתום לב, זכותו עדיפה. שכירות לשלוש שנים אינה טעונה רישום (סעיף 79), ולכן ההערה אינה התנאי כאן.', 'סעיפים 79 ו-80 לחוק המקרקעין', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-others-rights'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-others-rights-2', l.chapter_id, l.id, 'practice', null, 'בעל דירה רוצה למכור אותה ולסלק את יתרת המשכנתה לפני המועד. הבנק מסרב לקבל את הכסף וטוען שההלוואה חייבת להימשך עד סופה לפי ההסכם. מה הדין?', '["הבנק צודק: תנאי ההלוואה שנחתמו קובעים, והפירעון המוקדם תלוי בהסכמתו.", "הבנק טועה, אבל הדרך היחידה היא תביעה בבית משפט לצו שיחייב אותו לקבל.", "הבנק טועה: אי אפשר לשלול פדיון מוקדם, והבעלים רשאי להפקיד את הסכום אצל הרשם.", "הבנק טועה, והקונה רשאי לגרור את המשכנתה לשמו בלי הסכמת הבנק."]'::jsonb, 2, null, 'סעיף 88: אין בכוח תנאי המשכנתה לגרוע מהזכות לפדות את המקרקעין לפני המועד (לפי סעיף 13(ב) לחוק המשכון). סעיף 89: בעל המשכנתה לא קיבל את הפירעון, רשאי בעל המקרקעין להפקיד את המגיע בידי הרשם ולבקש שיפקיע את המשכנתה במידה שנפדתה. גרירת משכנתה היא הסדר עם הבנק, לא זכות של הקונה. זו הסוגיה של שאלה 8 במבחן יולי 2026.', 'סעיפים 88, 89 ו-91 לחוק המקרקעין', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-others-rights'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-others-rights-3', l.chapter_id, l.id, 'practice', null, 'שכן עובר בשביל שבחצר של בעל הבית כבר שלושים ושתיים שנה. לפני עשר שנים שלח לו בעל הבית מכתב שבו כתב שהוא מתנגד למעבר, אבל השכן המשיך לעבור. האם השכן רכש זיקת הנאה?', '["כן. הוא השתמש בשביל יותר משלושים שנה, וזה מספיק לרכישת הזיקה.", "כן, כי ההתנגדות לא לוותה בגדר או בפעולה שמנעה פיזית את המעבר.", "לא. ההודעה בכתב הפסיקה את מניין השנים, ומאז חלפו רק עשר.", "לא, כי זכות מעבר בחצר פרטית אינה יכולה להיות זיקת הנאה."]'::jsonb, 2, null, 'סעיף 94(א): שימוש של שלושים שנים רצופות בזכות הראויה להוות זיקת הנאה מקנה את הזיקה. סעיף 94(ב): הודעה בכתב של בעל המקרקעין שהוא מתנגד לשימוש מפסיקה את התקופה. אחרי ההודעה המניין מתחיל מחדש. זכות מעבר היא הדוגמה הקלאסית לזיקת הנאה, כפי שנשאל במאי 2023.', 'סעיפים 5 ו-94 לחוק המקרקעין', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-others-rights'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-others-rights-4', l.chapter_id, l.id, 'practice', null, 'על חלקה רשומה זיקת הנאה של מעבר לטובת החלקה הסמוכה, בלי תקופה. הבעלים החדש של החלקה הכפופה טוען שהזיקה פקעה, כי עברו שלושים שנה מאז נרשמה. מה הדין?', '["הוא צודק: זיקת הנאה שלא נקבעה לה תקופה פוקעת אחרי שלושים שנה.", "הוא צודק: הזיקה פקעה כשהחלקה הכפופה נמכרה לבעלים חדש.", "הוא טועה: זיקה בלי תקופה אינה מוגבלת בזמן, ורק בית משפט רשאי לבטלה.", "הוא טועה, אבל הזיקה תפקע כשהחלקה הזכאית תימכר לאחר."]'::jsonb, 2, null, 'סעיף 96: זיקת הנאה היא לתקופה בלתי מוגבלת, זולת אם נקבעה לה תקופה, ובית המשפט רשאי לבטלה או לשנות תנאיה בגלל אי-הפעלתה או שינוי נסיבות. זיקה לטובת מקרקעין עוברת עם הקרקע, ולכן מכירה של אחת החלקות אינה מבטלת אותה. השלושים שנה של סעיף 94 הן לרכישה, לא לפקיעה. זו הסוגיה של שאלה 15 במבחן יולי 2023.', 'סעיפים 93 ו-96 לחוק המקרקעין', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-others-rights'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'land-others-rights-5', l.chapter_id, l.id, 'practice', null, 'בני זוג בעלים של דירת מגוריהם. האישה הציעה לבעלה בדואר רשום את חלקה ב-900 אלף ש"ח, והוא לא השיב תוך 30 יום. שמונה חודשים אחר כך היא רוצה למכור את חלקה לזר ב-900 אלף. מה עליה לעשות?', '["כלום: הבעל סירב, ומאותו רגע היא חופשייה למכור כרצונה בכל עת.", "למכור לזר רק במחיר גבוה מ-900 אלף, כדי לא לפגוע בזכות הקדימה.", "להציע שוב לבעל, כי לא מכרה בתוך שישה חודשים מיום הסירוב.", "לבקש מבית המשפט לבטל את זכות הקדימה, כי בעלה ויתר עליה."]'::jsonb, 2, null, 'סעיף 102: בעל זכות קדימה שלא שילם או הפקיד תוך שלושים יום מקבלת ההצעה רואים אותו כמסרב. סעיף 103: אחרי סירוב המציע רשאי להעביר את המקרקעין תוך שישה חודשים, ולא במחיר נמוך מזה שבהצעה; לא העביר בתקופה, לא יעביר אלא אחרי שהציע שוב. זכות הקדימה בין בני זוג מכוח סעיף 101 אינה טעונה רישום.', 'סעיפים 101-103 לחוק המקרקעין', 5, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'land-law' and l.slug = 'land-others-rights'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
