  position = excluded.position, published = true;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'exam-2023-01', 'מבחן ינואר 2023', -3, 'מועד חורף 2023 הוא מבחן של חוק המקרקעין: שליש מהשאלות עוסקות ברישום, בבתים משותפים, בהערות אזהרה ובשיתוף, ושני פסקי דין על "הגורם היעיל" מופיעים עם מספרי התיק בגוף השאלה.', '<p>25 שאלות, ציון עובר 60. המשקל במועד הזה נטה בבירור לחוק המקרקעין, והבחינה פנתה גם לחוקים שלא כל קורס מכסה: חוק הירושה, חוק הגנת הדייר וההגדרות של רשות מקרקעי ישראל.</p><ul><li>חוק המקרקעין (רישום, בית משותף, הערת אזהרה, פירוק שיתוף, זכות קדימה, שכירות, משכון) - 8 שאלות</li><li>חוק המתווכים ותקנותיו, כולל שני פסקי דין על דמי תיווך - 5 שאלות</li><li>חוק התכנון והבנייה (היטל השבחה, הגדרת בניין, שימוש חורג) - 3 שאלות</li><li>מיסוי מקרקעין ואישורי העברה לטאבו - 2 שאלות</li><li>מקרקעי ישראל (נחלה במושב, קרקע עירונית) - 2 שאלות</li><li>רישום זכויות ביהודה ושומרון - שאלה אחת</li><li>חוק החוזים (תרופות), חוק הגנת הדייר, חוק המכר (דירות), חוק הירושה - שאלה אחת מכל חוק</li></ul>', '["שליש מהבחינה הוא חוק המקרקעין, ורוב השאלות שם הן על סעיפים ספורים: 37 (פירוק שיתוף), 55 (הצמדה), 79 (שכירות עד חמש שנים), 101 (זכות קדימה בין בני זוג), 126-127 (הערת אזהרה).", "שני פסקי דין על דמי תיווך (כהן נ'' גולן, הנשיא סוכנויות נדל\"ן נ'' בקרמן) נבחנים דרך אותו מבחן: הזמנה בכתב עם כל הפרטים, והמתווך כגורם היעיל. מי שמכיר את סעיף 14 לחוק עונה גם בלי להכיר את פסק הדין.", "מלכודת חוזרת: החלופה שמוסיפה תנאי שאינו בחוק (\"ולא קיבל תשלום\", \"רק בשנתיים הראשונות\", \"65% מהתמורה\") נראית מחמירה ולכן נכונה, והיא שגויה.", "בשאלת העבירה הפלילית, רק הפעולה בלי רישיון (או העסקת מי שאין לו רישיון) היא עבירה עם מאסר; גילוי עניין אישי, סודיות ומידע מהותי הם הפרות אזרחיות ומשמעתיות.", "שאלה 14 (שווי מכירה למיסוי) התקבלה בכל תשובה: בחלופה הנכונה נפלה טעות הקלדה (1,300,00). גם במבחן אמיתי שווה לקרוא את המספרים פעמיים."]'::jsonb, '[]'::jsonb, 'רשם המתווכים במקרקעין, מועד 22.01.2023, גרסה 1', null, false, true
  from public.course_chapters c where c.slug = 'past-exams'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q01', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 1', 'רחלי וינון מכרו את דירת מגוריהם. עורך הדין המייצג את הקונים בעיסקה ביקש לקבל לידיו "אישורי העברה לטאבו" על מנת שיוכל לטפל ברישום הדירה על שם הקונים.
איזה מהמשפטים הבאים מתאר בצורה הנכונה ביותר את המסמכים שעורך הדין של הקונים ביקש מרחלי וינון?', '["מסמך בחתימת יד של רחלי ושל ינון המאשר שהם מסכימים שהדירה תעבור על שם הקונים.", "אישור מרשות המיסים כי הקונים שילמו את מלוא מס הרכישה המוטל עליהם.", "אישור עירייה המעיד, בין היתר, על היעדר חובות לעירייה וכן אישור מרשות המיסים על היעדר חובות במיסוי מקרקעין.", "אישורי העברה בנקאית על תשלום מלוא תמורת הדירה."]'::jsonb, 2, null, 'רישום העברת זכויות בלשכת רישום המקרקעין מותנה בשני אישורים שהמוכרים צריכים להמציא: אישור מרשות המיסים לפי סעיף 16 לחוק מיסוי מקרקעין (שאין חובות מס שבח ומס רכישה בגין העיסקה), ואישור העירייה לפי סעיף 324 לפקודת העיריות על היעדר חובות ארנונה והיטל השבחה. חלופה ב חלקית, כי היא מתייחסת רק למס הרכישה של הקונים ולא למס השבח של המוכרים; חלופות א ו-ד הן מסמכים שאינם תנאי לרישום.', 'סעיף 16 לחוק מיסוי מקרקעין; סעיף 324 לפקודת העיריות', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q02', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 2', 'רועי הינו הבעלים של דירה בקומה האחרונה בבית משותף. מידי שנה בעונת החורף מי הגשמים מחלחלים וגורמים לרטיבות מאסיבית מגג הבניין לשטח של דירתו של רועי. רועי פנה אל בעלי הדירות בבקשה לתקן את הרטיבות, אך פניו הושבו ריקם.
האם רועי יכול לחייב את הדיירים לתקן את הרטיבות שנגרמה לו?', '["כן; רועי צריך לפנות לממונה על פניות הציבור ברשות מקרקעי ישראל.", "לא; רועי צריך לתקן את הנזק בעצמו, שכן דירתו מצויה בקומה האחרונה ויתר הדיירים אינם מחויבים לשאת בעלויות התיקון של הגג.", "לא; רועי צריך לשאת בעלות ובתיקון בעצמו ולאחר מכן לדרוש מיתר הדיירים את ההשתתפות בתיקון.", "כן; רועי נדרש להגיש תביעה כנגד בעלי הדירות, שתתנהל בפני המפקח על הבתים המשותפים על מנת שיורה לבעלי הדירות לתקן את הרטיבות שבגג הבניין המשותף."]'::jsonb, 3, null, 'הגג הוא רכוש משותף (סעיף 52 לחוק המקרקעין), וכל בעלי הדירות חייבים להשתתף בהוצאות הדרושות להחזקתו התקינה ולתיקונו לפי שיעור חלקם (סעיף 58). סכסוך בין בעלי דירות בבית משותף בעניין זכויותיהם וחובותיהם לפי החוק והתקנון נדון בפני המפקח על רישום המקרקעין, שלו סמכות שיפוטית בעניין (סעיף 72). רשות מקרקעי ישראל (חלופה א) אינה צד לעניין, וחלופות ב ו-ג מטילות על רועי חובה שאין בחוק.', 'סעיפים 52, 58 ו-72 לחוק המקרקעין', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q03', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 3', 'סמדר רכשה דירה מקבלן ולצורך כך נטלה הלוואה מבנק. הבניין בו מצויה הדירה טרם נרשם כבית משותף וזכויותיה של סמדר מתנהלות בספרי החברה המשכנת. הבנק מעוניין לרשום שיעבוד על זכויותיה של סמדר בדירה.
בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["ניתן לרשום משכנתא על הדירה, בתנאי שסמדר שילמה לפחות 65% מהתמורה לקבלן.", "הבנק לא יוכל לרשום שיעבוד על זכויותיה של סמדר אם הדירה אינה רשומה בטאבו.", "הבנק לא יוכל לרשום משכנתא על הדירה, אלא משכון ברשם המשכונות על זכויותיה של סמדר וכן לרשום התחייבות לרישום משכנתא בספרי החברה המשכנת.", "לא ניתן לרשום שיעבוד על הדירה בנסיבות המקרה."]'::jsonb, 2, null, 'משכנתא היא משכון של מקרקעין (סעיף 4 לחוק המקרקעין) ונרשמת רק על זכות רשומה בלשכת רישום המקרקעין. כשהבניין טרם נרשם כבית משותף, זכותה של סמדר היא זכות חוזית המתנהלת בספרי החברה המשכנת, ולכן הדרך לשעבד אותה היא משכון של הזכויות ברשם המשכונות לפי חוק המשכון, לצד רישום התחייבות לרישום משכנתא בספרי החברה המשכנת (ובדרך כלל גם הערת אזהרה כשיש רישום). חלופה א ממציאה תנאי של 65% שאינו קיים בדין, וחלופות ב ו-ד שוללות כל שיעבוד, בניגוד לפרקטיקה הקבועה בהלוואות לדיור.', 'סעיף 4 לחוק המקרקעין; חוק המשכון', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q04', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 4', 'אביתר רכש דירה חדשה באזור יהודה ושומרון.
היכן יירשמו זכויותיו?', '["זכויות בדירה הרשומה באזור יהודה ושומרון נרשמות בלשכת רישום המקרקעין (טאבו) בירושלים.", "זכויות בדירה באזור יהודה ושומרון נרשמות בפנקס הבתים המשותפים.", "זכויות בדירה באזור יהודה ושומרון נרשמות אצל הממונה על הרכוש הממשלתי והנטוש באזור יהודה ושומרון או במשרדי רישום המקרקעין במינהל האזרחי.", "לא ניתן כלל לרשום זכויות בדירה באזור יהודה ושומרון."]'::jsonb, 2, null, 'חוק המקרקעין הישראלי ולשכות רישום המקרקעין של משרד המשפטים אינם חלים באזור יהודה ושומרון. הרישום שם נעשה לפי תחיקת הביטחון: קרקע פרטית ורשומה נרשמת בלשכות רישום המקרקעין של המינהל האזרחי, וזכויות בקרקע שהוכרזה כרכוש ממשלתי מתנהלות אצל הממונה על הרכוש הממשלתי והנטוש. פנקס הבתים המשותפים (חלופה ב) הוא פנקס בתוך מערכת הרישום הישראלית ואינו רלוונטי, ורישום באזור בהחלט אפשרי (בניגוד לחלופה ד).', 'תחיקת הביטחון באזור יהודה ושומרון; חוק המקרקעין אינו חל באזור', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q05', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 5', 'אלעד וערן רכשו מגרש וחתמו על הסכם שיתוף המסדיר את היחסים המשפטיים ביניהם ביחס למגרש. לאחר כשנתיים הסתכסכו אלעד וערן ואלעד מעוניין לפרק את השיתוף.
האם רשאי אלעד לדרוש כעת את פירוק השיתוף?', '["לא; אלעד אינו רשאי לדרוש את פירוק השיתוף כל עוד לא עברו 3 שנים מיום חתימת ההסכם.", "כן; אלעד רשאי לדרוש את פירוק השיתוף אך ורק אם ערן יסכים לכך.", "כן; אלעד רשאי להגיש תביעה לפירוק השיתוף.", "לא; אלעד לא יכול לדרוש את פירוק השיתוף, מכיוון שלא מדובר בבית משותף."]'::jsonb, 2, null, 'סעיף 37(א) לחוק המקרקעין קובע שכל שותף במקרקעין משותפים זכאי בכל עת לדרוש את פירוק השיתוף, ובהיעדר הסכמה בין השותפים הפירוק נעשה על פי צו בית המשפט (סעיף 38). מגבלת שלוש השנים שבחלופה א לקוחה מסעיף 37(ב), אך היא חלה רק כשהסכם השיתוף מכיל תניה השוללת או מגבילה את הזכות לדרוש פירוק, ואז בית המשפט רשאי להורות על פירוק כעבור שלוש שנים חרף התניה; בשאלה לא נאמר שיש תניה כזו. הסכמת השותף אינה תנאי (חלופה ב), וההוראה חלה על כל מקרקעין משותפים ולא רק על בית משותף (חלופה ד).', 'סעיפים 37 ו-38 לחוק המקרקעין', 5, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q06', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 6', 'בעיסקת מקרקעין, האם ניתן לרשום הערת אזהרה לטובת הקונה, גם כאשר המוכר לא חתם על בקשה לרישום להערת אזהרה בטאבו בגין העיסקה?', '["לא; כי העיסקה טרם הסתיימה.", "לא; ניתן לרשום הערת אזהרה בגין עיסקת מקרקעין רק לאחר השלמת העיסקה.", "כן; בתנאי שיצורף מכתב המסביר מדוע המוכר לא חתם על הבקשה לרישום הערת אזהרה.", "כן; בתנאי שיוכח לרשם כי בעל המקרקעין התחייב בכתב לבצע את העיסקה."]'::jsonb, 3, null, 'לפי סעיף 126(א) לחוק המקרקעין, כשהוכח להנחת דעתו של הרשם שבעל המקרקעין התחייב בכתב לעשות בהם עיסקה, הרשם רושם הערת אזהרה לפי בקשת מי שהתחייב או לפי בקשת הזכאי לפי ההתחייבות. כלומר הקונה יכול לבקש את הרישום בעצמו, על סמך חוזה המכר החתום, גם בלי חתימת המוכר על הבקשה. הערת אזהרה נרשמת דווקא לפני השלמת העיסקה כדי להגן על הקונה עד הרישום (ולכן חלופות א ו-ב הפוכות), ומכתב הסבר (חלופה ג) אינו דרישה בחוק.', 'סעיף 126(א) לחוק המקרקעין', 6, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q07', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 7', 'בגין מה מהבאים ניתן לגבות היטל השבחה?', '["תוכנית חדשה החלה על מקרקעין המקנה זכויות בנייה נוספות.", "עליית מחירים כללית הרלוונטית לנכס.", "שיפור תשתיות לנכס.", "מס שבח מקרקעין."]'::jsonb, 0, null, 'היטל השבחה מוסדר בתוספת השלישית לחוק התכנון והבנייה: הוא משולם לוועדה המקומית בגין השבחה, כלומר עליית שווי המקרקעין עקב אישור תוכנית, מתן הקלה או התרת שימוש חורג. עליית מחירים כללית בשוק (חלופה ב) או שיפור תשתיות (חלופה ג) אינם אירוע תכנוני המקים חבות בהיטל. מס שבח (חלופה ד) הוא מס נפרד לפי חוק מיסוי מקרקעין על הרווח במכירה, ולא עילה להיטל השבחה.', 'התוספת השלישית לחוק התכנון והבנייה', 7, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q08', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 8', 'שירן חתמה על טופס הזמנה לשירותי תיווך עם אבנר המתווך על מנת שימכור את דירתה. אבנר הציג את דירתה בפני בנו דניאל, והסכם מכר נחתם בין הצדדים.
בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["מתווך במקרקעין לא יתווך בעיסקת מקרקעין אם יש לו עניין אישי במקרקעין או בעיסקה, לרבות לבנו.", "מתווך במקרקעין לא יתווך בעיסקת מקרקעין אם יש לו עניין אישי במקרקעין או בעיסקה, לרבות עניין אישי של קרובו - אלא אם גילה ללקוחו את עניינו האישי כאמור וקיבל את הסכמת הלקוח לכך בכתב.", "מתווך במקרקעין לא יתווך בעיסקת מקרקעין אם יש לו עניין אישי במקרקעין או בעיסקה, לרבות עניין אישי של קרובו - אלא אם גילה ללקוחו את עניינו האישי כאמור, קיבל את הסכמת הלקוח לכך בכתב, ולא קיבל תשלום עבור התיווך.", "מתווך במקרקעין רשאי לתווך בעיסקת מקרקעין אם יש לו עניין אישי ולא מחויב לעדכן שבנו מעורב בעיסקה."]'::jsonb, 1, null, 'סעיף 10 לחוק המתווכים קובע שמתווך לא יתווך בעיסקה שיש לו בה עניין אישי במקרקעין או בעיסקה, לרבות עניין אישי של קרובו, אלא אם גילה ללקוחו את עניינו האישי וקיבל את הסכמת הלקוח לכך בכתב. חלופה ב היא לשון הסעיף. חלופה א קוטעת את הסעיף ומשמיטה את החריג של גילוי והסכמה; חלופה ג מוסיפה תנאי של ויתור על התשלום שאינו בסעיף; חלופה ד מתירה בדיוק את מה שהסעיף אוסר. מאז 2024 מצטרפת לכך תקנה 25 לתקנות האתיקה, שלפיה מתווך שיש לו זכות בנכס עצמו אינו זכאי לדמי תיווך בעיסקה בו; כאן הזכות היא של הבן ולא של אבנר, ולכן הכלל שחל הוא סעיף 10.', 'סעיף 10 לחוק המתווכים במקרקעין', 8, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q09', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 9', 'שרון וגדעון כרתו חוזה, שבמסגרתו רכש גדעון את דירתה של שרון. סוכם כי התמורה תשולם בחמישה תשלומים. שלושה תשלומים שולמו במועד. כשהגיע מועד התשלום הרביעי הודיע גדעון, כי הוא יאחר בתשלום. חלף חודש וגדעון טרם ביצע את התשלום. בחוזה אין התייחסות לאיחור בתשלום. הניחו כי לא מדובר בהפרה יסודית של החוזה.
בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["שרון לא יכולה לבטל את החוזה מיד - עליה לתת לגדעון אורכה לתיקון ההפרה בתוך זמן סביר.", "שרון לא יכולה לבטל את החוזה, מכיוון שהחוזה הופר. אין צורך במתן אורכה לקיומו.", "שרון יכולה לבטל את החוזה ואין צורך במתן אורכה לקיומו.", "שרון יכולה לבטל את החוזה, מכיוון שחלף חודש ממועד ההפרה."]'::jsonb, 0, null, 'חוק החוזים (תרופות בשל הפרת חוזה) מבחין בין הפרה יסודית, שמקנה זכות ביטול מיידית (סעיף 7(א)), לבין הפרה שאינה יסודית, שבה הנפגע זכאי לבטל את החוזה רק לאחר שנתן למפר אורכה לקיומו והחוזה לא קוים בתוך זמן סביר (סעיף 7(ב)). השאלה מורה להניח שההפרה אינה יסודית, ולכן שרון חייבת קודם לתת אורכה. חלופות ג ו-ד מדלגות על האורכה, וחלופה ב שוללת את הביטול לגמרי, בעוד שלאחר אורכה שלא קוימה הביטול מותר.', 'סעיף 7 לחוק החוזים (תרופות בשל הפרת חוזה)', 9, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q10', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 10', 'פנינה רכשה מאברהם דירה שרשומה בטאבו, ובין השניים נכרת חוזה כדין. בזמן הרכישה, נסח הטאבו היה נקי מכל חוב ומשכנתא. פנינה רשמה הערת אזהרה לטובתה בטאבו. טרם השלמת העיסקה הוטל עיקול על הדירה על ידי נושה של אברהם.
האם העיקול פוגע בזכויותיה של פנינה?', '["העיקול לא יפגע בזכויותיה של פנינה - הערת האזהרה מגינה עליה.", "העיקול יפגע בזכויותיה של פנינה, כי הדירה טרם נרשמה על שמה.", "העיקול לא יפגע בזכויותיה של פנינה, אלא אם יוכח כי המעקל ידע כי רכשה את הדירה.", "העיקול יפגע בזכויותיה של פנינה - הערת האזהרה אינה מגינה מפני עיקול מאוחר."]'::jsonb, 0, null, 'סעיף 127(ב) לחוק המקרקעין קובע שכשנרשמה הערת אזהרה, ולאחר מכן הוטל עיקול על המקרקעין (או ניתן צו כינוס נכסים או פשיטת רגל נגד בעל המקרקעין), אין בעיקול כדי לפגוע בזכויות הזכאי לפי ההערה. זה בדיוק התפקיד של הערת האזהרה: להגן על הקונה בתקופה שבין החוזה לרישום. העובדה שהדירה טרם נרשמה על שמה (חלופה ב) היא הסיבה לרשום הערה, לא סיבה לפגיעה; ידיעת המעקל (חלופה ג) אינה תנאי בסעיף.', 'סעיף 127(ב) לחוק המקרקעין', 10, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q11', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 11', 'גילה רכשה ממשה דירה בבית משותף, שאליה מוצמד מחסן. בחוזה המכר נקבע כי המכירה אינה חלה על המחסן, וכי המחסן יישאר בבעלות משה.
האם בחוזה מכר זה ניתן להפריד את המחסן מהבעלות על הדירה?', '["לא ניתן להפריד בעיסקת המכירה בין הדירה לבין המחסן, אלא אם משה הינו בעל דירה אחרת בבית המשותף.", "אם הצדדים הסכימו על כך, ניתן להשאיר את המחסן בבעלות משה.", "המחסן אינו חלק מהדירה ולכן ניתן להפריד בינו לבין הדירה בעיסקת המכירה בכל מקרה.", "לא ניתן להפריד בין המחסן לבין הדירה משום שהמחסן נבנה בצמוד לדירה ללא מרווח."]'::jsonb, 0, null, 'מחסן המוצמד לדירה הוא חלק מהרכוש המשותף שהוצמד לדירה, וסעיף 55(ג) לחוק המקרקעין קובע שעיסקה בדירה חלה גם על החלק ברכוש המשותף הצמוד אליה, ואין תוקף לעיסקה ברכוש המשותף בנפרד מן הדירה. הצמדה אינה יכולה להתקיים "באוויר": אפשר להעביר אותה רק לדירה אחרת באותו בית משותף, באמצעות תיקון צו רישום הבית המשותף. לכן אם למשה דירה אחרת בבניין ניתן להצמיד אליה את המחסן, ואחרת המחסן עובר עם הדירה. הסכמת הצדדים לבדה (חלופה ב) אינה מספיקה, והנימוק הפיזי בחלופה ד אינו משפטי.', 'סעיף 55(ג) לחוק המקרקעין', 11, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q12', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 12', 'רחל ויעקב הם זוג נשוי שבבעלותם דירה המשמשת אותם למגורים. יעקב מכר את חלקו בדירה ליצחק ללא שהציע לרחל קודם לכן לרכוש את חלקו בדירה.
בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["יעקב רשאי לעשות כן, כי רחל תישאר דיירת מוגנת בדירה.", "יעקב חייב להציע את חלקו בדירה לרחל לפני שיציע את חלקו לאחר.", "יעקב חייב להציע את חלקו בדירה לרחל רק במהלך השנתיים הראשונות מעת הרכישה.", "יעקב רשאי לעשות כן, אלא אם בין השניים סוכם אחרת בעל פה."]'::jsonb, 1, null, 'סעיף 101 לחוק המקרקעין קובע זכות קדימה מכוח החוק בין בני זוג: במקרקעין שבבעלות משותפת של בני זוג, שהם דירה המשמשת להם למגורים (וכן משק חקלאי או בית עסק המתנהל על ידיהם), בן זוג אינו זכאי להעביר את חלקו לאחר אלא אם הציע אותו תחילה לבן זוגו. אין לזכות זו מגבלת זמן של שנתיים (חלופה ג), היא אינה תלויה בהסכמה בעל פה (חלופה ד), וחוק הגנת הדייר (חלופה א) אינו נוגע לבעלים של דירה.', 'סעיף 101 לחוק המקרקעין', 12, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
