  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q13', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 13', 'יונה שכר חנות מישעיהו לתקופה של שלוש שנים, עם אופציה להארכה לשנה וחצי נוספות.
האם עיסקת השכירות חייבת להיות בכתב?', '["כן, הסכם השכירות מחייב כתב, בשל האופציה להארכה.", "לא, הסכם השכירות אינו מחייב כתב, שכן מדובר בשכירות קצרה מחמש שנים.", "לא, הסכם השכירות מחייב כתב, כי מדובר בעיסקה במקרקעין.", "לא, הסכמי שכירות אינם מחייבים כתב, לא משנה מה משך השכירות."]'::jsonb, 1, null, 'סעיף 79 לחוק המקרקעין מוציא שכירות לתקופה שאינה עולה על חמש שנים מחובת הרישום ומדרישת הכתב שבסעיף 8 לחוק. לעניין חישוב התקופה מביאים בחשבון גם את תקופת האופציה להארכה, ולכן כאן התקופה היא שלוש שנים ועוד שנה וחצי, כלומר ארבע שנים וחצי, עדיין פחות מחמש. האופציה לבדה אינה מחייבת כתב (חלופה א), אלא רק אם היא מעבירה את התקופה הכוללת מעבר לחמש שנים; חלופה ד שגויה כי שכירות ארוכה מחמש שנים כן טעונה כתב ורישום. שימו לב שבשכירות של דירת מגורים חל מאז 2017 כלל נפרד בחוק השכירות והשאילה המחייב חוזה בכתב, אך כאן מדובר בחנות.', 'סעיף 79 לחוק המקרקעין', 13, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q14', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 14', 'איציק ואפרת רכשו דירה. שווי הרכישה לפי החוזה היה 1.3 מיליון שקל. על הדירה רובצת משכנתא שיתרתה לסילוק בסך של 300,000 ש"ח. השמאי העריך את הדירה בסך של 900,000 ש"ח.
מהו שווי המכירה לצורכי מיסוי מקרקעין במקרה זה?', '["1,000,000 ש\"ח - המשכנתא אינה חלק משווי המכירה של הנכס.", "1,300,00 ש\"ח - שווי המכירה כפי שקבעו הצדדים בחוזה.", "900,000 ש\"ח - לפי הערכת השמאי.", "1,200,000 ש\"ח - לפי הערכת השמאי בתוספת המשכנתא."]'::jsonb, 1, null, 'במפתח הרשמי של המועד נרשם לשאלה זו "כל התשובות מתקבלות", ככל הנראה בגלל טעות ההקלדה בחלופה ב (1,300,00 במקום 1,300,000). לגופו של דין, "שווי" לפי סעיף 1 לחוק מיסוי מקרקעין הוא הסכום שהיה מתקבל במכירה ממוכר מרצון לקונה מרצון, אך כשהמנהל שוכנע שהתמורה בחוזה נקבעה בתום לב ובלא שהושפעה מיחסים מיוחדים בין הצדדים, שווי המכירה הוא התמורה שנקבעה בחוזה, כלומר 1,300,000 ש"ח. המשכנתא שרובצת על הנכס אינה מופחתת מהשווי ואינה מתווספת אליו, והערכת השמאי אינה גוברת על תמורה חוזית בתום לב. לכן התשובה המכוונת היא ב, והיא מסומנת כאן כנכונה.', 'סעיף 1 לחוק מיסוי מקרקעין (הגדרת "שווי") וסעיף 17 (שווי המכירה)', 14, false
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q15', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 15', 'איזו מבין העבירות הבאות תגרור עונש מאסר למתווך במקרקעין?', '["אי מסירת מידע מהותי ללקוח בעיסקת מקרקעין.", "גילוי ידיעה אישית של לקוח, האסורה בגילוי לצד השני בעיסקת מקרקעין.", "אי גילוי עניין אישי בעיסקת מקרקעין.", "העסקת אדם אחר בתיווך במקרקעין כשהוא אינו בעל רישיון תיווך במקרקעין."]'::jsonb, 3, null, 'העבירה הפלילית היחידה בחוק המתווכים היא בסעיף 13: תיווך במקרקעין בלא רישיון, וכן העסקת אדם בתיווך במקרקעין ביודעין שאין לו רישיון, ושתיהן נושאות עונש מאסר. שלוש החלופות האחרות הן חובות אזרחיות ומשמעתיות: מסירת מידע מהותי (סעיף 8), סודיות (סעיף 11) וגילוי עניין אישי (סעיף 10). הפרתן יכולה לשלול דמי תיווך, להקים אחריות בנזיקין ולהוביל להליך משמעתי, ומאז 2024 גם להפרת תקנות האתיקה (תקנות 7 ו-10), אך לא למאסר.', 'סעיף 13 לחוק המתווכים במקרקעין', 15, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q16', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 16', 'יוסי הוא בעלים של נחלה במושב, הכוללת את חלקה א'' בה הוא מתגורר, ואת חלקה ב'', שבה הוא מגדל מילונים. יוסי מעוניין לבנות צימרים לאירוח כפרי בחלקה ב''.
האם יוסי רשאי לעשות כן?', '["לא; חלקה ב'' מיועדת לעיבוד חקלאי וחל בה איסור בנייה.", "לא; בחלקה ב'' ניתן לעשות שימוש למגורים בלבד, ואסור להקים בה מסחר.", "כן; חלקה ב'' מיועדת למסחר.", "כן; חלקה ב'' שייכת ליוסי, והוא רשאי לעשות בה כל שימוש."]'::jsonb, 0, null, 'בנחלה במושב, חלקה א'' היא חלקת המגורים (ובה בלבד מותרת, לפי החלטות מועצת מקרקעי ישראל, גם פעילות לא חקלאית כמו צימרים), ואילו חלקה ב'' היא חלקה חקלאית שייעודה לפי התוכנית הוא עיבוד חקלאי בלבד. בנייה ושימוש חייבים להתאים לייעוד שבתוכנית ולהיתר (חוק התכנון והבנייה), ולכן בניית צימרים בחלקה ב'' אסורה בלי שינוי ייעוד. חלופה ד שגויה גם משום שאדמת הנחלה היא בדרך כלל מקרקעי ישראל המוחכרים לבעל הנחלה, ולא בעלות שמקנה חופש שימוש.', 'חוק התכנון והבנייה (שימוש בהתאם לתוכנית ולהיתר); החלטות מועצת מקרקעי ישראל בעניין נחלות', 16, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q17', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 17', 'בבית משותף המכיל 40 דירות (להלן: "הבניין") הציעה המתווכת חני מספר דירות להשכרה. רז, המחפש לשכור דירת 4 חדרים, פנה לחני, אשר החתימה אותו על טופס הזמנת שירותי תיווך. בטופס ההזמנה נכתב כי קיימות מספר דירות בבניין במחיר וקומה משתנים. רז חתם על הטופס וחני לא מסרה לו עותק של טופס ההזמנה. לאחר התלבטות, רז הישהה את חיפושו. כעבור כשלושה חודשים שכר דירה אחרת בבניין, אליה הגיע ישירות דרך הבעלים אשר פרסם מודעה בפייסבוק.
עפ"י פסק דין ת"ק 41268-09-12 כהן נ'' גולן, האם זכאית חני לעמלת תיווך?', '["כן; חני זכאית לעמלת תיווך כי רז חתם על טופס כללי לבניין.", "לא; חני אינה זכאית לעמלת תיווך, מכיוון שרז לא קיבל העתק של טופס הזמנת שירותי תיווך, לא פורטו בהזמנה פרטים מלאים, וחני לא הייתה הגורם היעיל שהביא להתקשרות הצדדים בחוזה.", "לא; חני אינה זכאית לעמלת תיווך מכיוון שרז הוכיח שבעלי הדירה פרסמו את הדירה באופן עצמאי בפייסבוק.", "כן; לפי פסק הדין חני זכאית למחצית עמלת התיווך בעיסקה זו, כי חני הציגה ללקוח את הבניין."]'::jsonb, 1, null, 'סעיף 14(א) לחוק המתווכים מתנה את הזכאות לדמי תיווך בשלושה תנאים מצטברים: רישיון, הזמנה בכתב לפי סעיף 9 עם הפרטים שנקבעו בתקנות המתווכים (פרטי הזמנה בכתב), והיות המתווך הגורם היעיל שהביא להתקשרות. בכהן נ'' גולן הטופס תיאר "מספר דירות בבניין" בלי לזהות נכס ובלי מחיר, הלקוח לא קיבל עותק, והדירה שנשכרה הגיעה אליו ישירות מהבעלים כעבור שלושה חודשים, ולכן נכשלו גם דרישת הפרטים וגם דרישת הגורם היעיל. חלופה ג מצביעה רק על הפרסום בפייסבוק, שאינו כשלעצמו שולל זכאות; חלופה ד ממציאה חלוקה למחצית שאינה בפסק הדין. מאז 2024, תקנה 8 לתקנות האתיקה גם מחייבת במפורש מסירת העתק של כל מסמך ללקוח.', 'סעיפים 9 ו-14 לחוק המתווכים במקרקעין; תקנות המתווכים במקרקעין (פרטי הזמנה בכתב)', 17, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q18', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 18', 'רונית מעוניינת לרכוש דירה. בעת חיפושיה יצרה קשר עם איציק, מתווך במקרקעין. איציק פרסם דירה למכירה. בעת הביקור בדירה חתמה רונית על הסכם הזמנת תיווך עם אפרת, שהיא מתווכת במשרדו של איציק. שמה של אפרת ומספר ת.ז./רישיון תיווך לא הופיעו בהסכם. אפרת הראתה לרונית את הדירה. תוך כדי הביקור טענה אפרת כי המחיר המבוקש בגין הדירה הינו מיליון ש"ח. עוד נטען כי המפתחות לדירה ניתנו בבלעדיות למשרד התיווך. רונית ביקשה מאפרת לדבר עם המוכר ולנסות להוריד את המחיר, אך אפרת סירבה וטענה כי המחיר "קשיח". רונית המשיכה לחפש דירה והקשר בין רונית למשרד התיווך לא התקיים יותר. לאחר כחודש יצרה רונית קשר עם ליאור ממשרד תיווך אחר. ליאור הציג לרונית מספר דירות, ובין היתר גם את הדירה אותה ראתה עם אפרת. לאחר משא ומתן, ובעזרתו הרבה של ליאור, רכשה רונית את הדירה במחיר של 885,000 ש"ח. המוכר מצידו טען כי הדירה לא הייתה מעולם בבלעדיות. רונית שילמה עמלת תיווך לליאור.
בנסיבות העניין ועל פי פסק דין תא"מ מספר 10272/02/11 ב.פ. הנשיא סוכנויות נדלן בע"מ נגד בקרמן ואח'', האם זכאים איציק ואפרת לעמלת תיווך?', '["כן; אפרת החתימה והראתה לראשונה את הדירה לרונית.", "כן; מקובל לשלם מחצית מעמלת התיווך במקרה שכזה לכל אחד מהמתווכים.", "לא; לרונית הזכות לבחור דרך איזה מתווך להתקדם, ולכן איציק ואפרת אינם זכאים לעמלת תיווך.", "לא; אפרת לא ניהלה בשם רונית משא ומתן עם המוכר, ובנסיבות אלה אינה הגורם היעיל בעיסקת התיווך."]'::jsonb, 3, null, 'המבחן לזכאות הוא שוב סעיף 14(א) לחוק המתווכים: מי שהביא בפועל להתקשרות הוא הגורם היעיל, ולא בהכרח מי שהראה את הדירה ראשון. בפסק הדין נקבע שהצגת הדירה לבדה, כשהמתווכת סירבה לנהל משא ומתן, מסרה מידע שגוי על בלעדיות והקשר ניתק, אינה הופכת אותה לגורם היעיל; מי שהביא לעיסקה במחיר נמוך ב-115,000 ש"ח היה ליאור. לכך מצטרף פגם בהזמנה: שם המתווכת ומספר רישיונה לא הופיעו בטופס, בניגוד לתקנות פרטי הזמנה בכתב. חלופה א מבטאת את הטענה שנדחתה ("מי שהראה ראשון"), חלופה ב ממציאה חלוקה למחצית, וחלופה ג מנמקת בבחירת הלקוחה, שאינה המבחן המשפטי. מאז 2024 תקנה 4 לתקנות האתיקה גם אוסרת הטעיה בעניין מהותי, כמו טענת בלעדיות שאינה קיימת.', 'סעיפים 9 ו-14 לחוק המתווכים במקרקעין; תקנות המתווכים במקרקעין (פרטי הזמנה בכתב)', 18, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q19', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 19', 'בעלים של מגרש מעוניין לבנות עליו בניין מעץ.
האם בנייה מעץ יכולה להיכלל תחת הגדרת ''בניין'' לעניין תכנון ובנייה?', '["בהתאם לחוק התכנון והבנייה, כל מבנה, בין שהוא בנוי אבן ובין שהוא בנוי בטון, ברזל, עץ או כל חומר אחר, ייחשב כבניין.", "בהתאם לחוק התכנון והבנייה, כל מבנה, בין שהוא בנוי אבן ובין שהוא בנוי בטון, ברזל, למעט עץ, ייחשב כבניין.", "במרכז עיר אסורה הבנייה בעץ, על כל מרכיביו, ועל כן בנייה כזו לא יכולה להיחשב כבניין לעניין חוק התכנון והבנייה.", "בניין הינו מבנה בבנייה קשיחה בלבד, הכולל לפחות 2 יחידות דיור, ולכן לא ניתן לבנות בניין מעץ."]'::jsonb, 0, null, 'סעיף 1 לחוק התכנון והבנייה מגדיר "בנין" כ"כל מבנה, בין שהוא בנוי אבן ובין שהוא בנוי ביטון, טיט, ברזל, עץ או כל חומר אחר", לרבות חלקים של מבנה, גדר, קיר וכדומה. ההגדרה רחבה במכוון כדי שכל מבנה יהיה טעון היתר. עץ נכלל במפורש (ולכן חלופה ב הפוכה), אין בחוק איסור כללי על בנייה בעץ במרכז עיר (חלופה ג), ואין דרישה למספר יחידות דיור או לבנייה קשיחה (חלופה ד).', 'סעיף 1 לחוק התכנון והבנייה (הגדרת "בנין")', 19, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
