insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q20', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 20', 'עליזה, אלמנה ואם לשני ילדים, מתגוררת בדמי מפתח בדירת מגורים (להלן: "הדירה"). לפני כשנה הכירה עליזה בן זוג, והוא עבר להתגורר עימה בדירה לפני 3 חודשים. למרבה הצער, נפטרה עליזה.
האם בן הזוג ייחשב כדייר מוגן בדירה?', '["כן; במקרה של פטירתה של עליזה, בן הזוג יהיה דייר מוגן בדירה בה התגוררו ביחד, שכן השניים היו בני זוג למשך תקופה העולה על שישה חודשים סמוך לפטירתה של עליזה.", "כן; במקרה של פטירתה של עליזה, בן הזוג יהיה דייר מוגן בדירה בה התגוררו, למעט אם היתה לו בזמן פטירתה של עליזה דירה אחרת למגוריו.", "לא; במקרה של פטירתה של עליזה, בן הזוג לא ייחשב לדייר מוגן, שכן, הזכות עוברת לילדיה של עליזה, זאת במקרה שלא היתה להם בזמן פטירתה של עליזה דירה אחרת למגורים.", "לא; במקרה של פטירתה של עליזה, בן הזוג לא ייחשב לדייר מוגן, משום שלא די בכך שהשניים היו בני זוג למשך יותר משישה חודשים לצורך העברת הזכות לבן הזוג במקרה המתואר."]'::jsonb, 3, null, 'סעיף 20(א) לחוק הגנת הדייר [נוסח משולב] קובע שדייר של דירה שנפטר, בן זוגו יהיה לדייר, ובלבד שהשניים היו בני זוג לפחות שישה חודשים סמוך לפטירה והיו מתגוררים יחד באותה תקופה. כאן הם בני זוג כשנה, אך גרו יחד רק שלושה חודשים, ולכן תנאי המגורים המשותפים של שישה חודשים לא התקיים ובן הזוג אינו נכנס לנעליה. חלופה א מתעלמת מתנאי המגורים המשותפים, וחלופה ב משמיטה את תנאי ששת החודשים. חלופה ג מתארת את זכות הילדים לפי סעיף 20(ב), אך זו אינה הסיבה לשלילת זכותו של בן הזוג, והשאלה אינה מספרת אם הילדים גרו בדירה.', 'סעיף 20 לחוק הגנת הדייר [נוסח משולב]', 20, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q21', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 21', 'משה רכש דירה מקבלן וביקש לתקן את מפרט הדירה.
מה נדרש כדי לתקן מפרט של דירה?', '["על הצדדים למלא טופס שקבע השר בצו באישור ועדת הכלכלה של הכנסת.", "כל תיקון במפרט טעון חתימת שני הצדדים.", "לא ניתן לתקן את המפרט לאחר חתימתו.", "כל תיקון במפרט טעון חתימת המוכר בלבד."]'::jsonb, 1, null, 'חוק המכר (דירות) מחייב את המוכר לצרף לחוזה מפרט חתום בידו ולמסור לקונה העתק ממנו, וקובע במפורש שכל תיקון במפרט טעון חתימת שני הצדדים (סעיף 2). המפרט הוא חלק מהחוזה, ולכן שינוי חד-צדדי של המוכר (חלופה ד) אינו תופס, ותיקון מוסכם בהחלט אפשרי (בניגוד לחלופה ג). הטופס שקובע השר באישור ועדת הכלכלה (סעיף 3) הוא צורת המפרט עצמו, לא הליך לתיקונו.', 'סעיף 2 לחוק המכר (דירות)', 21, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q22', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 22', 'בקרקעות שבבעלות המדינה, מהי ההגדרה של "קרקע עירונית"?', '["קרקע שהייעוד שלה הוא למגורים או לתעסוקה.", "קרקע שהייעוד שלה הוא למלונאות.", "קרקע שנמצאת בשטח של עיר.", "קרקע שהייעוד שלה הוא לפעילות עירונית בלבד."]'::jsonb, 0, null, 'במקרקעי ישראל ההבחנה המרכזית היא בין קרקע חקלאית לקרקע עירונית, והיא נקבעת לפי הייעוד התכנוני ולא לפי המיקום הגיאוגרפי: "קרקע עירונית" היא קרקע שייעודה לפי תוכנית הוא למגורים או לתעסוקה (מסחר, תעשייה, משרדים, מלונאות ושירותים), גם אם היא מחוץ לתחום עיר. כך בהגדרות חוק רשות מקרקעי ישראל ובקובץ החלטות מועצת מקרקעי ישראל. חלופה ג מבלבלת בין המונח לבין גבולות מוניציפליים, וחלופות ב ו-ד מצמצמות את ההגדרה לשימוש אחד.', 'הגדרת "קרקע עירונית" בחוק רשות מקרקעי ישראל ובהחלטות מועצת מקרקעי ישראל', 22, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
