  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q23', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 23', 'מהו ״שימוש חורג״ בקרקע או בבניין?', '["שימוש השונה מזה שנקבע בתוכנית החלה במקום או בהיתר הבנייה.", "שינוי של הוראות לפי תוכנית בדבר בינוי או עיצוב אדריכליים.", "שינוי חלוקת שטחי הבנייה המותרים בתוכנית אחת, שהיא תוכנית שאישרה הוועדה המחוזית.", "הגדלת מספר יחידות הדיור, ללא הגדלת סך השטחים למטרות עיקריות."]'::jsonb, 0, null, 'סעיף 1 לחוק התכנון והבנייה מגדיר "שימוש חורג" בקרקע או בבניין כשימוש למטרה שלא הותר להשתמש בהם לפי כל תוכנית או תקנה החלות עליהם, או לפי היתר שניתן לבניין. כלומר העניין הוא השימוש (למשל מרפאה בדירת מגורים), והתרתו נעשית בהליך לפי סעיפים 146-149 לחוק. שלוש החלופות האחרות מתארות שינויים בהוראות הבינוי, בחלוקת השטחים ובמספר יחידות הדיור, שהם עניין של הקלה או של שינוי תוכנית, לא של שימוש.', 'סעיף 1 לחוק התכנון והבנייה (הגדרת "שימוש חורג")', 23, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
