  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q24', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 24', 'משה הוא מתווך במקרקעין. משה צירף מיוזמתו את לקוחותיו למאגר בתשלום הקרוי "פרסום דירות מקומי", ונתן להם הטבה של חודש ראשון רישום חינם למאגר. יוזמת הצירוף למאגר אינה מצוינת בהזמנת התיווך, או בכל חוזה אחר שמשה עורך עם לקוחותיו.
החל מהחודש השני נדרשים לקוחותיו של משה לשלם 100 ש"ח לחודש בגין הרישום למאגר.
האם משה רשאי לרשום את לקוחותיו למאגר זה בנסיבות המתוארות?', '["כן; מכיוון שמדובר בהטבה, משה רשאי לנצל בשם לקוחותיו ובעבורם הטבה של חודש ראשון חינם בעניינים הנובעים ישירות מהסכם הזמנת התיווך שנחתם, גם אם ההטבה אינה מצוינת בו במפורש.", "כן; מדובר בפעולת תיווך מותרת.", "לא; משה אינו יכול למסור פרטים לגבי לקוחותיו למתווכים אחרים.", "לא; משה אינו יכול לצרף לקוח לשירות בתשלום ללא הסכמתו המפורשת של הלקוח, גם אם מדובר בהטבה של חודש ראשון חינם שהלקוח נהנה ממנה."]'::jsonb, 3, null, 'המתווך מחויב להגינות כלפי לקוחו (סעיף 8 לחוק המתווכים), והיקף השירות והתשלום נקבעים בהזמנה בכתב (סעיף 9). צירוף לקוח לשירות בתשלום שלא הוזמן, בלי הסכמה מפורשת, הוא חיוב בלי הסכמה, ולפי חוק הגנת הצרכן אסור לחייב צרכן בעד שירות שלא הסכים לו, וחודש "חינם" שהופך לחיוב קבוע הוא הדוגמה הקלאסית. חלופה א הופכת את ההטבה להצדקה, אך היא אינה נובעת מהסכם התיווך; חלופה ג עוסקת במסירת מידע, שאינה הבעיה שבשאלה. מאז 2024 הכלל כתוב במפורש בתקנות האתיקה: שירות נוסף שאינו תיווך מתומחר בנפרד ובכתב (תקנה 13), ומידע שנמסר מהלקוח משמש רק למטרה שלשמה נמסר (תקנה 10).', 'סעיפים 8 ו-9 לחוק המתווכים במקרקעין; חוק הגנת הצרכן', 24, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-01-q25', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, ינואר 2023, שאלה 25', 'לאחר מותה של הגב'' לוי מונה לעזבונה מנהל עיזבון. העיזבון כולל דירת מגורים הרשומה במרשם המקרקעין. כעת מנהל העיזבון רוצה למכור את הדירה.
מי מהבאים מוסמך למכור את הדירה?', '["מנהל העיזבון, ללא תנאי.", "מנהל העיזבון, לאחר שבית המשפט אישר את פעולת המכירה.", "המפקח על הבתים המשותפים.", "רשם המקרקעין."]'::jsonb, 1, null, 'סעיף 97 לחוק הירושה מסמיך את מנהל העיזבון לעשות את הפעולות הדרושות לניהול העיזבון, אך מונה פעולות הטעונות אישור מראש של בית המשפט, ובהן פעולה שתוקפה תלוי ברישום בפנקס המתנהל על פי חוק, כמו מכירת דירה הרשומה במרשם המקרקעין. לכן מנהל העיזבון מוסמך למכור, אבל רק באישור בית המשפט (ולא "ללא תנאי" כבחלופה א). המפקח על הבתים המשותפים ורשם המקרקעין הם גורמי רישום ושיפוט בענייני מקרקעין ואינם מוסמכים למכור נכס של עיזבון.', 'סעיף 97 לחוק הירושה', 25, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-01'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
