  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'exam-2023-05', 'מבחן מאי 2023', -2, 'מועד מאי 2023 הוא מבחן של דיני מקרקעין יותר מאשר של חוק המתווכים: רק חמש שאלות על החוק שלנו, ועשרים מפוזרות על חוק המקרקעין, מיסוי, תכנון ובנייה, רשות מקרקעי ישראל וחוקים שלא כל קורס מכסה. ארבעה פסקי דין מופיעים עם מספרי התיק בגוף השאלה.', '<p>25 שאלות, ציון עובר 60. המבחן נערך לפני תקנות האתיקה תשפ"ד-2024, ולכן ההסברים כאן מבוססים על החוק כפי שחל אז; במקום שבו התקנות החדשות מוסיפות או מחזקות את התשובה, זה מצוין בהסבר. החלוקה לפי חוקים:</p><ul><li>חוק המקרקעין (זיקת הנאה, חכירה לדורות, שיתוף במושע, בית משותף, עסקאות נוגדות, התאמות לאדם עם מוגבלות) - 6 שאלות (1, 3, 4, 5, 16, 25)</li><li>חוק המתווכים, תקנותיו והפסיקה על דמי תיווך - 5 שאלות (6, 7, 11, 12, 23)</li><li>חוק מיסוי מקרקעין (ניכויים מהשבח, דירת מגורים מזכה, הורשה) - 3 שאלות (9, 10, 15)</li><li>חוק התכנון והבנייה (היטל השבחה ושינוי ייעוד, הוועדה המקומית) - 3 שאלות (13, 17, 24)</li><li>רשות מקרקעי ישראל ושיכון ציבורי (הסכם משבצת, אישור שיכון ציבורי) - 2 שאלות (8, 22)</li><li>חוק מס ערך מוסף, חוק המכר (דירות) (הבטחת השקעות), חוק שמאי מקרקעין, חוק הגנת הצרכן, חוק הירושה, חוק הגנת הדייר - שאלה אחת מכל חוק (2, 14, 18, 19, 20, 21)</li></ul><p>שאלה 2 (מע"מ) נפסלה בידי הרשם ו"כל התשובות מתקבלות" לפי המפתח הרשמי.</p>', '["רק 5 מתוך 25 שאלות על חוק המתווכים. מי שלומד/ת רק את החוק ותקנותיו מגיע/ה לציון 20, הרבה מתחת לציון העובר.", "ארבעה פסקי דין בשמם (כהן נ'' גולן, שמואלי נ'' סמוכה, גנז נ'' בריטיש קולוניאל, מאיר נ'' שושן). לא צריך לזכור מספרי תיק, צריך לזכור את העיקרון: הזמנה בכתב מלאה והגורם היעיל, חזקת הבלעדיות, תום לב של קונה ראשון שלא רשם הערת אזהרה, ומידע מהותי שמתווך חייב לבדוק.", "דמי תיווך נשללים משלושה כיוונים באותו מבחן: הזמנה בכתב חסרה (שאלה 6), עניין אישי בלי הסכמה בכתב (שאלה 7) ומידע מהותי שלא נבדק (שאלה 23). חזקת הגורם היעיל בבלעדיות (שאלה 12) היא הצד השני של אותו מטבע.", "מספרים שחוזרים כמעט בכל מועד: למעלה מ-25 שנים לחכירה לדורות, 30 שנים לזיקה מכוח שנים, 7% בחוק המכר (דירות), 2% דמי תיווך בניכוי מהשבח, 50% היטל השבחה, גיל 18 ושישה חודשים ממאסר בתנאי הרישיון.", "הבחינו בין הגופים: היטל השבחה לוועדה המקומית, מס שבח לרשות המיסים, דמי היתר ודמי הסכמה לרשות מקרקעי ישראל, שיכון ציבורי לשר הבינוי והשיכון, ודו\"ח מנהל עיזבון לאפוטרופוס הכללי."]'::jsonb, '[]'::jsonb, 'רשם המתווכים במקרקעין, מועד 11.05.2023, גרסה 1', null, false, true
  from public.course_chapters c where c.slug = 'past-exams'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q01', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 1', 'בנימין הינו הבעלים של דירה וחצר הרשומים על שמו במרשם המקרקעין. ינון, שכנו של בנימין, הבעלים של החלקה הסמוכה, נוהג לעבור בחצר של בנימין כדי לקצר את הדרך לחלקתו. כעבור 30 שנה טוען ינון כי יש לו זיקת הנאה במקרקעין של בנימין.
האם זכות המעבר יכולה להירשם כזיקת הנאה? מדוע?', '["כן, זכות מעבר יכולה להירשם כזיקת הנאה משום שמדובר בזכות במקרקעין.", "לא, זכות מעבר אינה יכולה להירשם משום שלא מדובר בשיעבוד.", "לא, זכות מעבר אינה יכולה להירשם מכיוון שהרישום לא נעשה בתמורה ובתום לב.", "כן, זכות מעבר יכולה להירשם בתנאי שהשביל מגודר ומסומן למעבר בחלקה."]'::jsonb, 0, null, 'זיקת הנאה היא שעבוד של מקרקעין להנאה שאין עמו זכות להחזיק בהם (סעיף 5 לחוק המקרקעין), וזכות מעבר היא הדוגמה הקלאסית לה. לפי סעיף 94 לחוק המקרקעין, מי שהשתמש בזכות הראויה להוות זיקת הנאה במשך שלושים שנים רצופות רכש את הזיקה והוא זכאי לדרוש את רישומה ("זיקה מכוח שנים"), וזה בדיוק מצבו של ינון. חלופה ב שגויה כי זיקת הנאה היא בעצמה שעבוד; חלופה ג מערבבת את דרישות התמורה ותום הלב של תקנת השוק (סעיף 10), שאינן נוגעות לרכישה מכוח שנים; חלופה ד ממציאה תנאי של גידור וסימון שאינו קיים בחוק.', 'סעיפים 5 ו-94 לחוק המקרקעין', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q02', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 2', 'מוטי ורונית הציעו למכירה את דירתם הפרטית, שבה הם מתגוררים. הם הגיעו להסכמה עם קונה, שישלם את המחיר המבוקש על ידם: 1,800,000 ש"ח. הקונה הינו עצמאי, ועוסק במקצוע חופשי. הקונה ביקש לקנות את הדירה למטרת מגורים תוך קיזוז מס ערך מוסף.
האם הקונה רשאי לקזז מס ערך מוסף בעסקה זו? אם כן, מדוע?', '["כן, מס ערך מוסף חל בשיעור של 17% בכל עיסקה בישראל וניתן לקזזו בהתאם.", "לא, מס ערך מוסף אינו חל על דירת המגורים, מכיוון שאינה מלאי עסקי ואינה משמשת לעסק ולפיכך לא ניתן לקזזו.", "כן, יש לשלם מס ערך מוסף בחישוב לינארי, שלפיו יקוזז הסכום בהתאמה.", "לא, מס ערך מוסף אינו חל על דירת המגורים, משום שלא מדובר בעיסקת אקראי."]'::jsonb, 1, null, 'שימו לב: במפתח התשובות הרשמי של מועד זה נרשם לשאלה זו "כל התשובות מתקבלות", כלומר הרשם פסל את השאלה והעניק את הנקודה לכל הנבחנים. החלופה המסומנת כאן (ב) היא ההסבר המשפטי המדויק ביותר: מכירת דירת מגורים פרטית בידי יחידים שאינם "עוסק" אינה "עסקה" לפי חוק מס ערך מוסף, ולכן לא מוטל עליה מע"מ ואין מס תשומות שניתן לנכות; וגם אילו היה מע"מ, רכישה למטרת מגורים אינה לצורכי העסק של הקונה ומס התשומות בגינה אינו מותר בניכוי. חלופה א שגויה כי מע"מ אינו חל על כל עסקה בישראל אלא על עסקה של עוסק במהלך עסקיו (או עסקת אקראי); חלופה ג ממציאה "חישוב לינארי" שאינו קיים במע"מ; חלופה ד נכונה בתוצאה אך נימוקה חלקי, שכן גם עסקת אקראי במקרקעין חייבת במע"מ רק כשהקונה הוא עוסק, מלכ"ר או מוסד כספי.', 'חוק מס ערך מוסף, התשל"ו-1975 (הגדרות "עסקה", "עוסק" ו"עסקת אקראי"; ניכוי מס תשומות)', 2, false
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q03', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 3', 'מהי "חכירה לדורות"?', '["חכירה לדורות היא שכירות להחזקה ושימוש במשק חקלאי.", "חכירה לדורות היא זכות שכירות לדורות הבאים.", "חכירה לדורות היא שכירות לתקופה של עשרים וחמש שנים לכל הפחות.", "חכירה לדורות היא שכירות למשך כל תקופת חיי הדייר, אשר לא ניתן להעבירה בירושה יותר מדור אחד בלבד."]'::jsonb, 2, null, 'סעיף 3 לחוק המקרקעין מגדיר: שכירות לתקופה שלמעלה מחמש שנים נקראת "חכירה", ושכירות לתקופה שלמעלה מעשרים וחמש שנים נקראת "חכירה לדורות". המונח הוא עניין של אורך התקופה בלבד, ואינו קשור לדורות של אדם, למשק חקלאי או להגבלות ירושה, ולכן חלופות א, ב ו-ד שגויות. הבחינה מקבלת את הניסוח "עשרים וחמש שנים לכל הפחות" כהגדרה, אף שלשון החוק המדויקת היא "למעלה מעשרים וחמש שנים".', 'סעיף 3 לחוק המקרקעין', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q04', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 4', 'דני וימית הם בעלים במשותף במקרקעין (בעלים ב''מושע''), ואין ביניהם הסכם לפירוק שותפות.
האם ניתן לרשום חלק מסוים מהמקרקעין על שם דני בלבד? אם כן, מה נדרש על מנת שיירשם חלק מסוים מהמקרקעין על שם דני בלבד?', '["אם דני וימית רוצים לרשום חלק מסוים מהמקרקעין על שם דני בלבד, עליהם לנקוט הליך של \"פירוק שיתוף\" בבית משפט, או לערוך ביניהם הסכם לפירוק שיתוף במושע.", "לדני יש חלק במקרקעין, ולכן אין צורך בנקיטת צעד כלשהו לשם רישום חלק מסוים במרשם המקרקעין.", "בעלות במושע אינה ניתנת לפירוק.", "משמעות המושע היא שלכל אחד מהשותפים יש חלק מסוים במקרקעין, ולכן נדרש כעת לקבל אישור מרשות המיסים והרשות המקומית לצורך ביצוע הרישום בפועל."]'::jsonb, 0, null, 'בעלות משותפת ("מושע") פירושה שלכל שותף חלק בלתי מסוים בכל המקרקעין (סעיף 27 לחוק המקרקעין), ואף שותף אינו יכול להצביע על חלק פיזי מסוים כשלו. כדי שחלק מסוים יירשם על שם דני בלבד יש לפרק את השיתוף: בהסכם בין השותפים (סעיף 38), ובאין הסכמה בבית המשפט, שכן כל שותף זכאי לדרוש פירוק בכל עת (סעיף 37). חלופה ב מתעלמת מכך שחלקו של דני אינו מסוים; חלופה ג שגויה כי הזכות לדרוש פירוק שיתוף היא מיסודות ההסדר; חלופה ד הופכת את משמעות המושע ומציעה אישורי מיסים ורשות מקומית, שהם תנאי לרישום עסקה ולא דרך לפירוק שיתוף.', 'סעיפים 27, 37 ו-38 לחוק המקרקעין', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q05', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 5', 'באסיפה כללית של בעלי הדירות בבית משותף הרשום בפנקס הבתים המשותפים (להלן: "הבניין"), התעורר ויכוח בקשר לאופן חלוקת תשלום הוצאות ההחזקה התקינה של הרכוש המשותף. יוסי, בעלי דירה בקומה הראשונה, טען שבעלי הדירות בקומות העליונות צריכים לשלם סכום גבוה יותר מבעלי הדירות בקומות התחתונות עבור הוצאות ההחזקה, מאחר שהם עושים יותר שימוש ברכוש המשותף (חדר מדרגות, מעליות וכו''). שולי, שהיא בעלת דירת הפנטהאוז בבניין, טענה שתשלום ההוצאות צריך להתחלק בין כל בעלי הדירות בהתאם לגודל הדירה של כל אחד מהבעלים, ביחס לשטח של כל הדירות בבניין. בתקנון הבית המשותף אין התייחסות לנושא.
בנסיבות העניין, לפי מה יחושב חלקה של כל דירה בהוצאות ההחזקה התקינה של הבניין?', '["אופן חלוקת הוצאות ההחזקה בבניין נקבע בהתאם להחלטת הקבלן שהקים את הבניין.", "לפי החוק, רק דיירי הקומות העליונות שמשתמשים במעלית נושאים בהוצאות החזקה, ולכן מי שגר בקומות התחתונות בבניין ישלם פחות, בלי קשר לגודל דירתו.", "כל בעלי דירה בבניין חייב לשאת בהוצאות החזקת הרכוש המשותף לפי יחס שטח רצפת דירתו אל מול שטח הרצפה של כל הדירות בבניין.", "בעלי דירה חייב לשאת בהוצאות החזקת הרכוש המשותף לפי יחס שטח רצפת דירתו אל מול שטח הרצפה של הרכוש המשותף בבניין."]'::jsonb, 2, null, 'סעיף 58(א) לחוק המקרקעין: בעל דירה חייב להשתתף בהוצאות הדרושות להחזקתו התקינה ולניהולו של הרכוש המשותף לפי יחס שטח רצפת דירתו אל שטח הרצפה של כל הדירות שבבית המשותף, זולת אם נקבע בתקנון שיעור השתתפות אחר. מאחר שהתקנון שותק, חל הכלל שבחוק, וזו בדיוק עמדתה של שולי. חלופה א שגויה כי הקבלן אינו קובע את החלוקה; חלופה ב ממציאה הבחנה לפי קומה ושימוש במעלית שאינה בחוק; חלופה ד משווה לשטח הרכוש המשותף במקום לשטח כל הדירות.', 'סעיף 58(א) לחוק המקרקעין', 5, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
