insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q06', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 6', 'בן, מתווך במקרקעין, הראה דירה למטרת שכירות ללקוח בבניין מגורים. בן לא ציין את מספר הדירה בטופס הזמנת שירותי התיווך שהחתים עליו את הלקוח, ולא מסר ללקוח העתק מטופס זה.
בהמשך הסתבר לבן כי הלקוח שכר דירה אחרת באותו בניין.
האם על פי פסק דין כהן נ'' גולן (ת"ק 41268-09-12), זכאי בן לקבל עמלת תיווך במקרה זה? מדוע?', '["כן, משום שהלקוח חתם על טופס הזמנת שירותי תיווך ואין על כך מחלוקת.", "לא, מכיוון שבן המתווך לא מסר ללקוח עותק של טופס הזמנת שירותי תיווך, לא ציין את מספר הדירה הספציפית ולא היה הגורם היעיל שהביא להתקשרות.", "כן, בן היה הגורם היעיל בביצוע העיסקה, מכיוון שהכיר ללקוח את הבניין, והזמנת התיווך נערכה כדין.", "לא, כי בן לא החתים את הלקוח על טופס בלעדיות."]'::jsonb, 1, null, 'הזכאות לדמי תיווך מותנית בשלושה תנאים מצטברים שבסעיף 14(א) לחוק המתווכים: רישיון בתוקף, הזמנה בכתב העומדת בדרישות סעיף 9 ותקנות המתווכים (פרטי הזמנה בכתב), והיות המתווך הגורם היעיל שהביא להתקשרות. התקנות דורשות לציין בהזמנה את פרטי הנכס, ובן לא ציין את מספר הדירה ואף לא מסר ללקוח העתק מהטופס; מעבר לכך, הלקוח שכר דירה אחרת שבן כלל לא הציג לו, ולכן בן לא היה הגורם היעיל. חלופה א מסתפקת בעצם החתימה; חלופה ג טוענת שההזמנה נערכה כדין בניגוד לעובדות; חלופה ד שגויה כי בלעדיות אינה תנאי לדמי תיווך. בתקנות האתיקה תשפ"ד-2024 (תקנה 8) נקבעו במפורש חובת מסירת העתק ללקוח ושמירתו שבע שנים, והתוצאה זהה.', 'סעיפים 9 ו-14(א) לחוק המתווכים; תקנות המתווכים במקרקעין (פרטי הזמנה בכתב), התשנ"ז-1997', 6, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q07', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 7', 'ליה, מתווכת מוסמכת ובעלת שליטה בחברה פרטית בע"מ, מעוניינת לטפל במכירת דירה השייכת לאותה חברה.
האם רשאית ליה לתווך בעסקה זאת?', '["לא, ליה אינה רשאית לתווך בעיסקה, מכיוון שיש לה בה עניין אישי.", "כן, אם ליה היא זו שאיתרה את הקונה והראתה לו את הדירה, אין מניעה שתתווך בעסקה זאת.", "כן, במקרה כזה ליה תוכל לתווך בעיסקה, אך תהיה זכאית לקבל מחצית מדמי התיווך המוסכמים בלבד.", "לא, מכיוון שיש לליה עניין אישי בעיסקה. אולם אם ליה עדכנה את הלקוחות וקיבלה את הסכמתם בכתב לגבי העניין האישי שלה בנכס, ליה זכאית לתווך בעיסקה."]'::jsonb, 3, null, 'סעיף 10 לחוק המתווכים אוסר על מתווך לתווך בעסקה שיש לו בה עניין אישי, אלא אם גילה ללקוחו את עניינו האישי וקיבל את הסכמת הלקוח לכך בכתב. "עניין אישי" כולל גם עניין של תאגיד שהמתווך בעל שליטה בו, ולכן דירה של החברה שליה שולטת בה היא בדיוק המקרה שהסעיף מדבר עליו. חלופה א נכונה רק בחציה: האיסור אינו מוחלט וניתן להסירו בגילוי ובהסכמה בכתב; חלופה ב מתעלמת מהעניין האישי; חלופה ג ממציאה הפחתה של מחצית מדמי התיווך שאינה קיימת בחוק.', 'סעיף 10 לחוק המתווכים', 7, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q08', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 8', 'מהו "הסכם משבצת"?', '["הסכם הקובע את שיבוצן ומיקומן של הדירות, שיקבלו בעלי המקרקעין בבניין חדש במסגרת עיסקת קומבינציה.", "הסכם הקובע את חלוקת האזורים השונים במסגרת תוכנית בניין עיר.", "הסכם לחלוקת שטחים משותפים במקרקעין, שהינו דו צדדי בין הרשות המקומית לבין יזם תמ\"א, או הסכם משולש (שאליו מתווספים גם הדיירים כצד להסכם).", "הסכם חכירה שנחתם בין רשות מקרקעי ישראל לבין אגודה שיתופית ומגדיר את שטח הקרקע המוחכר לאגודה."]'::jsonb, 3, null, '"הסכם משבצת" הוא הסכם החכירה שרשות מקרקעי ישראל (לשעבר מינהל מקרקעי ישראל) חותמת עם אגודה שיתופית חקלאית, קיבוץ או מושב, והוא מגדיר את "המשבצת": שטח הקרקע הכולל המוחכר לאגודה, שבתוכו מצויות הנחלות, השטחים החקלאיים ושטחי הציבור של היישוב. המונח שייך לדיני רשות מקרקעי ישראל וההתיישבות החקלאית, ואינו קשור לעסקאות קומבינציה (א), לתכנון עירוני (ב) או לתמ"א 38 (ג).', 'החלטות מועצת מקרקעי ישראל והסכמי החכירה של רשות מקרקעי ישראל עם אגודות שיתופיות', 8, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
