  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q09', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 9', 'אודי מעוניין למכור את דירת המגורים שבבעלותו.
אילו הוצאות רשאי אודי לנכות לשם קביעת סכום מס השבח שיהיה עליו לשלם לרשויות המס בגין המכירה?', '["אודי יכול לנכות מסכום השבח את שכר הטרחה ששילם לעורך דין ברכישה ובמכירה, ואלה לא יהיו יותר מ-2% מערך הנכס.", "אודי יכול לנכות מסכום השבח אגרות ששולמו על ידו לרשם המקרקעין, דמי תיווך ששילם ברכישה בגובה של עד 2% מסכום הנכס, וכן את שכר טרחת שמאי מקרקעין ששולם על ידו בקשר עם מכירת הדירה.", "אודי יוכל לנכות מסכום השבח את שכר הטרחה ששילם לעורך דין ברכישה ובמכירה, וכן את דמי התיווך ששילם עד גובה 3% מערך הנכס במכירה.", "אודי יכול לנכות מסכום השבח את שכר הטרחה ששילם לעורך דין ברכישה בלבד, אך לא במכירה."]'::jsonb, 1, null, 'סעיף 39 לחוק מיסוי מקרקעין מונה את הניכויים המותרים מהשבח, ובהם: אגרות ששולמו בקשר לרכישת הזכות, דמי תיווך ברכישה ובמכירה עד 2% מהתמורה (במכירה, אלא אם שוכנע המנהל שהיה מוצדק לשלם יותר), שכר טרחת עורך דין ברכישה ובמכירה, ושכר טרחת שמאי מקרקעין ומודד מוסמך בקשר לרכישה, להשבחה ולמכירה. חלופה ב היא היחידה שכל פרטיה נכונים. חלופה א מגבילה את שכר טרחת עורך הדין ל-2%, ואין מגבלה כזו; חלופה ג נוקבת ב-3% לדמי תיווך במקום 2%; חלופה ד שוללת את שכר הטרחה במכירה, שהחוק מתיר במפורש.', 'סעיף 39 לחוק מיסוי מקרקעין (שבח ורכישה)', 9, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
