  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q10', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 10', 'נילי וגדעון הם בעלי זכות חכירה ל- 99 שנים של דירת מגורים בת 5 חדרים, המשמשת למגוריהם. נילי מפעילה מכון יופי באחד מחדרי הדירה, ואילו גדעון מפעיל בחדר אחר בדירה משרד רואי חשבון. כעת הם מעוניינים למכור את הדירה.
האם במקרה הנדון, הדירה תיחשב כ"דירת מגורים מזכה" לעניין מס שבח?', '["כן, משום שמדובר בדירה ששימשה בעיקרה למגוריהם של נילי וגדעון.", "לא, משום שנעשה שימוש ב- 50% מהדירה לצורך פעילות עסקית שאינה מגורים.", "לא, מאחר שלנילי וגדעון זכות חכירה בלבד, הם לא יוכלו למכור את הדירה כדירת מגורים מזכה.", "כן, אבל נילי וגדעון מחזיקים בזכויות בדירה ביחד ולכן, בכל מקרה, לא יכולים להיחשב כ\"יחיד\" לצורך הגדרת \"דירת מגורים\"."]'::jsonb, 0, null, '"דירת מגורים" לפי סעיף 1 לחוק מיסוי מקרקעין היא דירה שבנייתה נסתיימה והיא משמשת למגורים או מיועדת לכך לפי טיבה, וחכירה לתקופה העולה על 25 שנים היא "זכות במקרקעין" לעניין החוק, ולכן גם חוכרים ל-99 שנים הם מוכרי דירת מגורים. "דירת מגורים מזכה" לפי סעיף 49 היא דירה ששימשה בעיקרה למגורים בתקופה הקבועה בחוק. כאן שניים מתוך חמישה חדרים משמשים לעסק, כלומר רוב הדירה (60%) משמש למגורים והיא "בעיקרה" למגורים. חלופה ב טועה בחישוב (40% ולא 50%); חלופה ג שגויה כי חכירה לדורות היא זכות במקרקעין; חלופה ד ממציאה דרישה שהמוכר יהיה אדם יחיד ולא בני זוג.', 'סעיפים 1 ו-49 לחוק מיסוי מקרקעין (שבח ורכישה)', 10, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
