  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q11', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 11', 'מי מבין הבאים אינו רשאי לקבל רישיון תיווך?', '["מי שטרם מלאו לו 21 שנה.", "מי שריצה עונש מאסר בפועל בששת חודשים שקדמו להגשת הבקשה לרישיון תיווך.", "מי שנפתחו כנגדו חמישה ויותר תיקי הוצאה לפועל.", "מי שנכשל בבחינה לקראת קבלת רישיון תיווך במקרקעין יותר מארבע פעמים."]'::jsonb, 1, null, 'סעיף 5 לחוק המתווכים קובע את התנאים לרישיון: אזרח או תושב ישראל (או תושב חוץ בעל היתר), בן 18 לפחות, אינו פושט רגל, לא הורשע בחמש השנים שקדמו לבקשה בעבירה שיש עמה קלון, ואם נידון למאסר בפועל, סיים לרצותו לפחות שישה חודשים לפני הגשת הבקשה, ועמד בבחינה. מי שריצה מאסר בפועל בששת החודשים שקדמו לבקשה אינו עומד בתנאי. חלופה א שגויה כי גיל המינימום הוא 18 ולא 21; חלופה ג שגויה כי תיקי הוצאה לפועל אינם מונעים רישיון (רק פשיטת רגל); חלופה ד שגויה כי החוק אינו מגביל את מספר הניסיונות בבחינה.', 'סעיף 5 לחוק המתווכים', 11, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q12', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 12', 'מתווך מחזיק בהזמנת תיווך ובהסכם בלעדיות שנערכו כדין, ומבצע את פעולות התיווך שסוכמו מול הלקוחות בהסכם הבלעדיות מולו.
לפי פסק הדין בבר"ע 2285/05 אבנר שמואלי ואח'' נ'' דורון סמוכה ואח'', במקרה שהדירה נמכרה לקונים, שלא באמצעות המתווך, במהלך תקופת הבלעדיות, האם המוכר חייב לשלם את דמי התיווך למתווך?', '["לא, מכיוון שהמתווך לא היה הגורם היעיל בעיסקה, הוא לא זכאי לדמי תיווך בגינה.", "כן, אך במקרה כזה המתווך יהיה זכאי לכל היותר לדמי תיווך בשיעור של 70% מדמי התיווך המוסכמים.", "לא, שכן בכל מקרה לא ניתן היה להסכים על תקופת בלעדיות למכירה.", "כן, משום שקיימת חזקה שהמתווך הינו הגורם היעיל במכירה."]'::jsonb, 3, null, 'סעיף 14(ב) לחוק המתווכים: מתווך שקיבל בלעדיות וביצע בתקופתה את פעולות השיווק שנקבעו לפי סעיף 9(ד), חזקה שהיה הגורם היעיל לעסקה שנעשתה בתקופת הבלעדיות, אלא אם הוכח אחרת. בפסק דין שמואלי נ'' סמוכה נפסק שמוכר שמכר בעצמו בתקופת הבלעדיות חייב בדמי התיווך מכוח החזקה הזו. חלופה א מתעלמת מהחזקה שהחוק יוצר; חלופה ב ממציאה שיעור של 70% שאינו קיים; חלופה ג שגויה כי סעיף 9(ב) מתיר במפורש הסכם בלעדיות בכתב.', 'סעיפים 9(ב), 9(ד) ו-14(ב) לחוק המתווכים', 12, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q13', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 13', 'דינה ירשה מאביה את הזכויות בשטח חקלאי, בבעלות המדינה, ששימש לגידול תותים בפאתי פתח תקווה. דינה מעוניינת "להפשיר" את הקרקע, על ידי שינוי יעודה של הקרקע מחקלאות למגורים.
אילו מהתשלומים הבאים יהיה על דינה לשלם, ולאיזו רשות, במידה וישונה יעוד הקרקע כאמור?', '["דמי הסכמה לרשות מקרקעי ישראל, בגין הסכמתה למהלך של שינוי הייעוד בקרקע.", "דמי היוון לרשות מקרקעי ישראל, המגלמים את הערך הכלכלי של שינוי הייעוד.", "דמי היתר לרשות מקרקעי ישראל והיטל השבחה לועדה המקומית, בשיעור של 50% מערך ההשבחה שנקבעה בשל שינוי הייעוד.", "מס שבח בשיעור של 25% משווי הקרקע החדש לאחר ההפשרה, לרשות המיסים."]'::jsonb, 2, null, 'שינוי ייעוד של קרקע חכורה מרשות מקרקעי ישראל גורר שני תשלומים: דמי היתר לרשות מקרקעי ישראל, תמורת הסכמתה לשינוי הייעוד והניצול של הקרקע לפי החלטות מועצת מקרקעי ישראל, והיטל השבחה לוועדה המקומית לתכנון ולבנייה בשיעור של מחצית ההשבחה שנוצרה מאישור התוכנית (התוספת השלישית לחוק התכנון והבנייה). "דמי הסכמה" (א) משולמים לרשות בעת העברת זכויות חכירה לאחר, לא בשינוי ייעוד; "דמי היוון" (ב) הם היוון של דמי החכירה השנתיים; וחלופה ד ממציאה מס שבח על שווי לאחר ההפשרה, אף שמס שבח חל רק במכירה של זכות במקרקעין.', 'התוספת השלישית לחוק התכנון והבנייה (היטל השבחה); החלטות מועצת מקרקעי ישראל (דמי היתר)', 13, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q14', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 14', 'במכירת דירה חדשה, אילו מהתנאים הבאים חייבים להתקיים על מנת שחברה קבלנית תהיה רשאית לגבות מרוכש דירה חדשה סכום הגבוה מ- 7% מערך הדירה?', '["מסירת ערבות בנקאית, או פוליסת ביטוח, או רישום שיעבוד, או רישום הערת אזהרה על הדירה הנרכשת.", "מסירת המפתח של הדירה הנרכשת.", "מסירת המפתח של הדירה הנרכשת ורישום הערת אזהרה לטובת הקונה.", "מסירת ערבות אישית לטובת הרוכש מטעם הקבלן."]'::jsonb, 0, null, 'סעיף 2 לחוק המכר (דירות) (הבטחת השקעות של רוכשי דירות): מוכר לא יקבל מקונה סכום העולה על 7% ממחיר הדירה אלא אם הבטיח את כספי הקונה באחת הבטוחות שבחוק: ערבות בנקאית, פוליסת ביטוח, שעבוד הדירה במשכנתה ראשונה, רישום הערת אזהרה, או העברת הבעלות על שם הקונה. חלופה א מונה בדיוק את הבטוחות האלה. מסירת המפתח (ב, ג) אינה בטוחה לפי החוק, וערבות אישית של הקבלן (ד) אינה מופיעה ברשימה הסגורה.', 'סעיף 2 לחוק המכר (דירות) (הבטחת השקעות של רוכשי דירות), התשל"ה-1974', 14, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q15', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 15', 'בבעלותה של אסתר דירת מגורים יחידה בישראל, שבה היא חיה לבדה. שווי הדירה כ- 2.5 מיליון ש"ח. לאסתר יש בת יחידה בשם יסמין. יסמין חיה בשכירות, ואין לה דירת מגורים.
כמה מס יהיה על יסמין לשלם בגין קבלת הדירה בעתיד בירושה?', '["הורשה מהווה מכירה ולכן תהיה חבות מלאה הן במס שבח והן במס רכישה.", "הורשה אינה מהווה מכירה, ולכן אין חבות במס בזמן ההורשה.", "החבות במס שבח תיגזר משווי הדירה (2.5 מיליון ש\"ח). אין חבות במס רכישה.", "לא ניתן לקבל פטור ממס שבח, היות שמדובר בדירת ירושה."]'::jsonb, 1, null, 'סעיף 4 לחוק מיסוי מקרקעין קובע ש"הורשה איננה מכירה" לעניין החוק, ולכן קבלת הדירה בירושה אינה אירוע מס: אין מס שבח ואין מס רכישה. חבות במס שבח עשויה להתעורר רק כשיסמין תמכור את הדירה בעתיד, ואז תיבחן זכאותה לפטור (ובפרט הפטור לדירה שנתקבלה בירושה לפי סעיף 49ב(5), שיסמין עונה על תנאיו: יורשת של המורישה, שלמורישה הייתה דירה יחידה). חלופות א ו-ג מתייחסות לירושה כאל מכירה; חלופה ד שוללת פטור במכירה עתידית בניגוד לחוק.', 'סעיפים 4 ו-49ב(5) לחוק מיסוי מקרקעין (שבח ורכישה)', 15, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q16', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 16', 'עמית חתם על חוזה למכירת דירתו למנשה בשנת 2010. שווי המכירה היה מיליון ש"ח. מנשה שילם לעמית את מלוא התמורה, אך לא פעל לרישום הערת אזהרה לטובתו בלשכת רישום המקרקעין, ואף השאיר את הדירה ריקה. בשנת 2023 מכר עמית את אותה דירה לחיים. שווי המכירה היה מיליון ושמונה מאות אלף ש"ח. חיים שילם לעמית את מלוא התמורה, לא ידע על עיסקת המכירה למנשה, ורשם הערת אזהרה לטובתו בלשכת רישום המקרקעין.
לפי ע"א 2643/97 שלמה גנז נ'' בריטיש קולוניאל חברה בע"מ ואח'', מי מבין השניים (מנשה או חיים) יזכה בדירה?', '["מנשה יזכה בדירה, שכן הוא היה הראשון שחתם על חוזה הרכישה.", "חיים יזכה בדירה, מכיוון שהשני בזמן גובר תמיד, אלא אם הקונה הראשון השלים את העברת הבעלות על שמו בתמורה ובתום לב.", "מנשה יזכה בדירה, כל עוד חיים לא השלים רישום מלא של הבעלות על שמו.", "חיים יזכה בדירה, שכן שילם את התמורה, פעל בתום לב והספיק לרשום הערת אזהרה ראשון על הנכס."]'::jsonb, 3, null, 'סעיף 9 לחוק המקרקעין מסדיר עסקאות נוגדות: זכותו של הקונה הראשון עדיפה, אלא אם השני פעל בתום לב ובתמורה והעסקה לטובתו נרשמה בעודו בתום לב. בפסק דין גנז נ'' בריטיש קולוניאל נקבע שקונה ראשון שנמנע במשך שנים מרישום הערת אזהרה, ובכך אפשר את "התאונה המשפטית", מאבד את עדיפותו מכוח עקרון תום הלב כלפי קונה שני שלא ידע ולא יכול היה לדעת על העסקה הקודמת. מנשה לא רשם הערת אזהרה במשך 13 שנה ואף השאיר את הדירה ריקה; חיים שילם, פעל בתום לב ורשם הערת אזהרה, ולכן ידו על העליונה. חלופה א מיישמת את כלל הראשון בזמן בלי החריג; חלופה ב מנמקת הפוך (השני בזמן אינו גובר "תמיד"); חלופה ג מתנה את הכול ברישום בעלות מלא, בעוד שהערת אזהרה הספיקה.', 'סעיף 9 לחוק המקרקעין; ע"א 2643/97 גנז נ'' בריטיש קולוניאל', 16, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q17', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 17', 'איזה גוף שלטוני מבין הבאים מוסמך לגבות היטל השבחה?', '["רשות המיסים.", "ועדה מקומית לתכנון ובנייה שבשטחה מצויים המקרקעין.", "משרד האוצר.", "עיריות שבשטחן יותר מ- 25,000 תושבים."]'::jsonb, 1, null, 'היטל השבחה מוטל ונגבה על ידי הוועדה המקומית לתכנון ולבנייה שבמרחב תכנונה נמצאים המקרקעין, לפי סעיף 196א לחוק התכנון והבנייה והתוספת השלישית, בעקבות אישור תוכנית, מתן הקלה או התרת שימוש חורג. רשות המיסים (א) גובה מס שבח ומס רכישה, שהם מסים אחרים לגמרי; משרד האוצר (ג) אינו גובה היטלים מקומיים; וחלופה ד ממציאה סף תושבים שאינו קיים, שכן ההיטל נגבה בכל מרחב תכנון בלי קשר לגודל הרשות.', 'סעיף 196א והתוספת השלישית לחוק התכנון והבנייה', 17, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
