insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q18', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 18', 'מתווך התבקש על ידי לקוח להכין לו דו"ח בתשלום, שבו יעריך את שווי דירתו, וזאת לשם הגשת ההערכה לבית המשפט.
האם למתווך מותר לערוך הערכת שווי מקרקעין (שומה), במקרה דנן?', '["מתווך רשאי לבצע הערכת מקרקעין בתשלום, אך ורק ביחס לדירות המצויות באזור עיסוקו, ושיש לו ידע ומיומנות להעריך את שוויין.", "מתווך רשאי לבצע הערכה בתשלום של מקרקעין כחלק מעבודתו.", "מתווך רשאי לבצע הערכת שווי מקרקעין בתשלום, ובלבד שלא תוגש לבית המשפט.", "למתווך אסור לערוך הערכת שווי מקרקעין בתשלום המוגשת לבית המשפט."]'::jsonb, 3, null, 'חוק שמאי מקרקעין, התשס"א-2001, מייחד את העיסוק בשומת מקרקעין בתמורה, ובפרט הגשת שומה לבית משפט, לשמאי מקרקעין רשומים בלבד. מתווך שאינו שמאי אינו רשאי לערוך הערכת שווי בתשלום לצורך הליך משפטי, ולכן חלופה ד נכונה. חלופות א ו-ג מתירות הערכת שווי בתשלום בתנאים שאינם בחוק, וחלופה ב הופכת את השומה ל"חלק מהעבודה" של המתווך. תקנות האתיקה תשפ"ד-2024 (תקנה 24) הרחיבו את הכלל: מתווך שאינו שמאי לא יעסוק כלל בשומת מקרקעין, ומתווך שהוא גם שמאי לא יתווך בנכס שערך לגביו שומה אלא אם חלפו שלוש שנים. הערכת מחיר שיווקית לצורך התיווך עצמו אינה שומה ונשארה מותרת.', 'חוק שמאי מקרקעין, התשס"א-2001 (ייחוד העיסוק); תקנה 24 לתקנות המתווכים (אתיקה וחובות מקצועיות), התשפ"ד-2024', 18, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q19', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 19', 'האם מתווך במקרקעין (המוגדר "עוסק" עפ"י החוק) מחויב לגלות ללקוח את שמו ומספר הזהות שלו, כשהוא מציע ללקוחו לכרות עימו חוזה?', '["כן, בכל הצעה לכריתת חוזה מתווך חייב לגלות את שמו ומספר הזהות שלו.", "לא, החובה קיימת רק בטופס בלעדיות.", "כן, אלא אם המתווך כתב את מספר רישיון התיווך שלו.", "לא, עוסק אינו מחויב למסור שמו ואת מספר תעודת הזהות שלו."]'::jsonb, 0, null, 'השאלה משתמשת במונח "עוסק" של חוק הגנת הצרכן, שחל גם על מתווך כמי שנותן שירות דרך עיסוק. חוק הגנת הצרכן מחייב עוסק המציע לצרכן לכרות עמו חוזה לגלות לו את שמו ואת מספר הזהות שלו (ובתאגיד, את מספר הרישום), בכל הצעה כזו ולא רק בטופס בלעדיות. חלופה ב מצמצמת את החובה לבלעדיות בלי בסיס; חלופה ג מחליפה את מספר הזהות במספר הרישיון; חלופה ד שוללת את החובה. תקנות האתיקה תשפ"ד-2024 הוסיפו לכך את תקנה 5: בפנייה ראשונה לאדם בנוגע לנכס מסוים יציין המתווך את שמו ואת היותו מתווך, ויציג את רישיונו לפי דרישה, כך שהתשובה כיום רק מתחזקת.', 'חוק הגנת הצרכן, התשמ"א-1981 (חובת גילוי של עוסק המציע לכרות חוזה); תקנה 5 לתקנות המתווכים (אתיקה וחובות מקצועיות), התשפ"ד-2024', 19, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q20', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 20', 'האם מנהל עיזבון נדרש להגיש דו"ח לאפוטרופוס הכללי בגין פעילותו במקרקעין?', '["כן, מנהל עיזבון נדרש להגיש לאפוטרופוס הכללי דין וחשבון לפחות אחת לשנה, וכן בעת פקיעת משרתו.", "לא, מנהל עיזבון נדרש להגיש דו\"ח רק לבית המשפט ולא לאפוטרופוס הכללי.", "כן, מנהל עיזבון נדרש להגיש דו\"ח לאפוטרופוס הכללי, אך רק בעת סיום תפקידו במכירת הנכס.", "לא, מנהל עיזבון לא נדרש להגיש לאפוטרופוס הכללי דו\"ח, אלא אם חויב לעשות כן על ידי בית המשפט בעת מינויו."]'::jsonb, 0, null, 'חוק הירושה מעמיד את מנהל העיזבון תחת פיקוחו של האפוטרופוס הכללי: מנהל העיזבון חייב להגיש לו פרטה של נכסי העיזבון בתחילת תפקידו, ודין וחשבון על פעולותיו, לרבות פעולות במקרקעי העיזבון, אחת לשנה לפחות ובסיום תפקידו. החובה קבועה בחוק ואינה תלויה בהוראה מיוחדת של בית המשפט, ולכן חלופות ב ו-ד שגויות; חלופה ג מצמצמת את החובה לסיום התפקיד בלבד.', 'חוק הירושה, התשכ"ה-1965 (חובות מנהל העיזבון כלפי האפוטרופוס הכללי)', 20, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
