  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q21', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 21', 'תהילה שוכרת חנות בדמי מפתח (לאחר שהחליפה דייר קודם כדין). תהילה לא משלמת דמי מפתח לבעלים של החנות מזה 10 שנים, וזאת ללא כל סיבה. הבעלים פינה את תהילה מהחנות והגיש תביעה כנגדה לתשלום דמי המפתח עבור מלוא התקופה שתהילה נמנעה מלשלם לו דמי מפתח.
עבור איזו תקופה של אי תשלום זכאי הבעלים לקבל מתהילה דמי מפתח?', '["הבעלים זכאי לדמי מפתח עבור השנה האחרונה בלבד.", "הבעלים זכאי לדמי מפתח עבור שלוש השנים האחרונות בלבד.", "הבעלים זכאי לדמי מפתח עבור שבע השנים האחרונות בלבד.", "הבעלים זכאי לדמי מפתח עבור מלוא התקופה."]'::jsonb, 0, null, 'לפי המפתח הרשמי, הבעלים זכאי לתשלום עבור השנה האחרונה בלבד. השאלה עוסקת בדייר מוגן לפי חוק הגנת הדייר שהפסיק לשלם את התשלומים התקופתיים לבעל הבית (השאלה מכנה אותם "דמי מפתח" אף שדמי מפתח משולמים פעם אחת, בכניסה לנכס). ההסדר המיוחד של חוק הגנת הדייר מגביל את התקופה שבגינה בעל בית שהשלים עם אי התשלום במשך שנים יכול לגבות למפרע לשנה אחת, וזה הסדר ספציפי הגובר על תקופת ההתיישנות הכללית של שבע שנים (חלופה ג) שבחוק ההתיישנות. חלופה ד, גבייה בעד מלוא עשר השנים, מתעלמת גם מההתיישנות הכללית. אי התשלום הוא גם עילת פינוי של דייר מוגן, ולכן הפינוי עצמו היה כדין.', 'חוק הגנת הדייר [נוסח משולב], התשל"ב-1972', 21, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q22', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 22', 'למי נתונה הסמכות לאשר מקרקעין כ"שיכון ציבורי"?', '["לשר הבינוי והשיכון.", "לוועדה המחוזית לתכנון ולבנייה.", "לשר האוצר.", "לוועדה המקומית לתכנון ולבנייה."]'::jsonb, 0, null, 'חוק רישום שיכונים ציבוריים (הוראת שעה), התשכ"ד-1964, מסמיך את שר הבינוי והשיכון לאשר מקרקעין שבהם נבנה שיכון בידי המדינה או מטעמה כ"שיכון ציבורי", ואישור זה פותח את הליך הרישום המיוחד (חלוקה, איחוד ורישום בית משותף בלי תוכנית מאושרת) שהחוק קובע. ועדות התכנון (ב, ד) עוסקות באישור תוכניות ובמתן היתרים, ושר האוצר (ג) אינו הגורם המאשר לפי חוק זה.', 'חוק רישום שיכונים ציבוריים (הוראת שעה), התשכ"ד-1964', 22, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q23', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 23', 'בני הזוג מאיר רצו לרכוש דירה "ללא פגמים או הפתעות", ולשם כך שכרו את שירותיה של מתווכת מוסמכת. המתווכת מצאה עבור בני הזוג דירה, ונחתם הסכם לרכישת הדירה. מספר ימים לאחר חתימת ההסכם, קיבלו בני הזוג מידע מהשמאי מטעם הבנק, שלפיו יותר ממחצית מהדירה שרכשו נבנתה ללא היתר, ומייד ביטלו את החוזה. המתווכת לא ידעה על כך, ושמעה על הדברים לראשונה מבני הזוג.
לפי בר"ע 209/01 זיוה וזאב מאיר נ'' טלי שושן ואח'', האם זכאית המתווכת לדמי תיווך במקרה זה?', '["כן, המתווכת זכאית לדמי תיווך מרגע שהביאה את הצדדים לידי הסכם מחייב.", "לא, המתווכת אינה זכאית לדמי התיווך, מכיוון שהחוזה בוטל על ידי הרוכש.", "לא, המתווכת אינה זכאית לדמי התיווך, מאחר שמדובר במידע מהותי שהיה עליה לבדוק ולגלות ללקוח.", "כן, המתווכת זכאית לדמי התיווך, מאחר שאין זה באחריותה לבדוק אם הדירה בנויה בהיתר."]'::jsonb, 2, null, 'סעיף 8 לחוק המתווכים מחייב מתווך לפעול בנאמנות, בהגינות ובדרך מקובלת, ולמסור ללקוחו כל מידע שיש בידו בעניין מהותי הנוגע לנכס. העובדה שיותר ממחצית הדירה נבנתה ללא היתר היא מידע מהותי מובהק, ומתווכת שנשכרה כדי למצוא דירה "ללא פגמים או הפתעות" הייתה חייבת לבדוק ולגלות זאת; אי ידיעתה אינה הגנה, כי חובת הזהירות דורשת בירור. בפסק דין מאיר נ'' שושן נשללו דמי התיווך בגלל הפרת חובה זו. חלופות א ו-ד מנתקות את דמי התיווך מחובות המתווך; חלופה ב מנמקת בעצם ביטול החוזה, אך העילה היא הפרת חובת הגילוי והזהירות ולא הביטול. תקנות האתיקה תשפ"ד-2024 (תקנה 7 והתוספת הראשונה) מונות היתרי בנייה וחריגות בנייה במפורש כמידע מהותי שהמתווך חייב לברר ולמסור, כך שהתוצאה זהה גם כיום.', 'סעיף 8 לחוק המתווכים; תקנה 7 והתוספת הראשונה לתקנות המתווכים (אתיקה וחובות מקצועיות), התשפ"ד-2024', 23, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q24', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 24', 'מי מהבאים אינו בעל דעה מייעצת בדיוני ועדה מקומית לתכנון ולבנייה?', '["נציג רשות מקרקעי ישראל.", "נציג השר לאיכות הסביבה.", "נציג לשכת רישום המקרקעין.", "נציג שר התחבורה."]'::jsonb, 2, null, 'חוק התכנון והבנייה קובע את הרכב הוועדה המקומית ומונה את הנציגים שיש להם דעה מייעצת בלבד, בלי זכות הצבעה: נציגי השרים (הבינוי והשיכון, הגנת הסביבה, הבריאות, התחבורה ועוד), ונציג רשות מקרקעי ישראל במרחב תכנון שיש בו מקרקעי ישראל. לשכת רישום המקרקעין (הטאבו) היא גוף רישומי במשרד המשפטים, שאינו חבר בוועדה ואינו משתתף בדיוניה, ולכן נציגה אינו "בעל דעה מייעצת" ושלוש החלופות האחרות הן חברים מייעצים אמיתיים.', 'חוק התכנון והבנייה (הרכב הוועדה המקומית ובעלי הדעה המייעצת בה)', 24, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
