  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-05-q25', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2023, שאלה 25', 'בבניין הרשום בפנקס הבתים המשותפים ולו תקנון מצוי, ישנן חניות משותפות.
האם ניתן לייחד או להקצות מקום חנייה קיים לדירה מסוימת שהשוכר המתגורר בה הוא אדם עם מוגבלות? אם כן, מהו הרוב הדרוש מבין בעלי הדירות לאישור הפעולה?', '["לא ניתן לייחד או להקצות מקום חניה קיים לבעל דירה מסוים, שכן מדובר בשטח משותף.", "ניתן לעשות כן ברוב של 100% מבעלי הדירות.", "ניתן לעשות כן ברוב של 75% מבעלי הדירות.", "ניתן לעשות כן ברוב של 60% מבעלי הדירות."]'::jsonb, 3, null, 'חוק המקרקעין מאפשר לאדם עם מוגבלות המתגורר בדירה בבית משותף (בעלים או שוכר) לבצע התאמות ברכוש המשותף כדי לאפשר לו גישה סבירה לדירה, והתוספת לחוק מונה את ההתאמות ואת ההסכמה הנדרשת לכל אחת: חלקן ללא הסכמה, חלקן ברוב רגיל, וייחוד מקום חניה קיים לאדם עם מוגבלות טעון הסכמה של בעלי 60% מהדירות. חלופה א שגויה כי החוק מתיר ייחוד כזה במפורש; חלופה ב דורשת פה אחד שאינו נדרש; חלופה ג (75%) היא הרוב להצמדת חלק מהרכוש המשותף לדירה לשם הרחבתה (סעיף 71ב, יחד עם שני שלישים מהרכוש המשותף), שהיא פעולה אחרת.', 'חוק המקרקעין, התאמות ברכוש המשותף לאדם עם מוגבלות (הפרק על בתים משותפים והתוספת); סעיף 71ב לחוק המקרקעין (להשוואה)', 25, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'exam-2023-07', 'מבחן יולי 2023', -1, 'מועד קיץ 2023 הוא מבחן של דיני מקרקעין יותר מאשר של חוק המתווכים: כמעט חצי מהשאלות יושבות בחוק המקרקעין, במיסוי מקרקעין ובתכנון ובנייה, ושתי שאלות (1 ו-12) בוטלו בדיעבד על ידי הרשם, כך שבפועל הציון חושב על 23 שאלות. הוא נערך לפני תקנות האתיקה של 2024, ולכן שאלות הגילוי בו נשענות על סעיף 8 לחוק בלבד.', '<p>25 שאלות, ואלה החוקים שמהם הגיעו (לפי הספירה שלנו):</p><ul><li><strong>חוק המתווכים ופסיקת דמי התיווך</strong> - 7 שאלות (7, 8, 12, 13, 14, 19, 25): חובת הגילוי לפי סעיף 8, תקופת הבלעדיות בנכס שאינו דירה, הגורם היעיל ומוסקוביץ נ'' ביר, ולקוח שלא משלם.</li><li><strong>חוק המקרקעין</strong> - 5 שאלות (6, 9, 10, 15, 16): עסקאות נוגדות והערת אזהרה, תקנון בית משותף והצמדות, תיקון צו רישום, זיקת הנאה, משכנתא מול משכון. ועוד שאלה אחת (11) בחוק חיזוק בתים משותפים מפני רעידות אדמה.</li><li><strong>מיסוי מקרקעין</strong> - 3 שאלות (1, 2, 3): מועד תשלום מס שבח (בוטלה), דירה חלופית לצורך מס רכישה, וחלוקת עיזבון בין יורשים.</li><li><strong>תכנון ובנייה ותמ"א 38</strong> - 3 שאלות (17, 20, 23): מסמכי תוכנית, תנאי תמ"א 38/2, ושימוש חורג.</li><li><strong>חוק החוזים</strong> - 2 שאלות (4, 5): זכרון דברים לפי רבינאי נ'' מן שקד, והצעה עם מועד לקיבול.</li><li><strong>קרקע חקלאית וירושה</strong> - 2 שאלות (18, 21): בר רשות והרחבת יחידת מגורים, והורשת נחלה לבן ממשיך אחד.</li><li><strong>חוק המכר (דירות)</strong> - שאלה אחת (22): אי אפשר לקצר תקופת בדק.</li><li><strong>חוק הגנת הדייר</strong> - שאלה אחת (24): החוק אינו חל על משק חקלאי.</li></ul><p>שאלות 1 ו-12 סומנו בדו"ח הגרסאות של הרשם "כל התשובות מתקבלות". הן מופיעות כאן עם התשובה הקרובה ביותר לדין, ומסומנות בהסבר.</p>', '["ארבע שאלות גילוי (7, 8, 14, 25) נענות כולן באותו כלל: סעיף 8 לחוק המתווכים מחייב למסור כל מידע מהותי, בלי קשר למי הלקוח, למי משלם, או למי זה יזיק. מאז 2024 תקנה 7 והתוספות מפרטות את הרשימה, אבל התשובה לא השתנתה.", "שתי שאלות פסיקה קבועות: רבינאי נ'' מן שקד (זכרון דברים מחייב כשיש גמירות דעת ומסוימות) ומוסקוביץ נ'' ביר (הגורם היעיל, וגורם מתערב שאינו מנתק את הזכאות).", "בלעדיות: דירת מגורים עד 6 חודשים (ברירת מחדל 30 יום), נכס אחר עד שנה (ברירת מחדל 9 חודשים). הסכם \"בלתי מוגבל\" אינו בטל אלא מתוקן לברירת המחדל.", "בית משותף: הצמדת רכוש משותף לדירה דורשת הסכמת כולם (סעיף 62), תיקון צו רישום מוגש למפקח על ידי כל בעל דירה (סעיף 145), ותמ\"א 38 עם מתנגד קשיש או נכה דורשת הצעת דיור חלופי.", "מלכודת הנימוק: בשאלות 2, 7, 8 ו-24 יש חלופה שמגיעה לתשובה הנכונה (כן/לא) מנימוק שגוי. קודם מכריעים כן או לא, ואז בוחרים את הנימוק שמופיע בחוק."]'::jsonb, '[]'::jsonb, 'רשם המתווכים במקרקעין, מועד 31.07.2023, גרסה 1', null, false, true
  from public.course_chapters c where c.slug = 'past-exams'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q01', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 1', 'ביום 1.1.2015 רכש ראובן דירת מגורים בסכום של 1,000,000 ש"ח. ביום 1.1.2022 מכר ראובן את הדירה לשמעון בסכום של 1,500,000 ש"ח. הדירה לא הייתה דירתו היחידה של ראובן, והוא לא זכאי לפטור ממס שבח. בהסכם המכר נקבע כי במועד החתימה על הסכם המכר יקבל ראובן 50% מהתמורה, ואת היתרה יקבל בתוך 8 חודשים. בנסיבות העניין, מתי חייב ראובן לשלם מס שבח?', '["ראובן חייב לשלם מס שבח בתוך 6 חודשים מיום חתימת ההסכם.", "ראובן חייב לשלם מס שבח בתוך 8 חודשים מיום קבלת התשלום הראשון.", "ראובן חייב לשלם מס שבח במועד קבלת התשלום הראשון.", "ראובן חייב לשלם מס שבח רק עם קבלת התשלום המלא."]'::jsonb, 2, null, 'בדו"ח הגרסאות הרשמי של הרשם שאלה זו סומנה "כל התשובות מתקבלות", כלומר כל נבחן קיבל עליה את הנקודות. הדין: המוכר מגיש הצהרה ושומה עצמית בתוך 30 ימים מיום המכירה ומשלם לפיה, אך סעיף 51 לחוק מיסוי מקרקעין מאפשר לו לדחות את התשלום עד שמתקיים אחד התנאים שבו, ובהם קבלת חלק מהותי מהתמורה או מסירת החזקה. כאן ראובן מקבל 50% מהתמורה כבר בחתימה, ולכן הדחייה מסתיימת עם התשלום הראשון, והחלופה הקרובה ביותר לדין היא ג. אף חלופה אינה מנוסחת במדויק לפי החוק, וזו כנראה הסיבה שהשאלה בוטלה.', 'סעיפים 51 ו-73 לחוק מיסוי מקרקעין (שבח ורכישה)', 1, false
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q02', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 2', 'שמואל הוא בעלים של דירת מגורים יחידה ברמת גן, אותה רכש לפני 10 שנים (להלן - "הדירה הראשונה"). ביום 1.1.2023 רכש שמואל מקבלן דירת מגורים נוספת, בפתח תקווה (להלן - "הדירה הנוספת"). את החזקה בדירה הנוספת שמואל יקבל לפני 31.12.2023. שמואל מכר את הדירה הראשונה בתוך 10 חודשים מקבלת החזקה בדירה הנוספת. האם תיחשב הדירה הנוספת כ"דירה יחידה" לצורך מס רכישה? מדוע?', '["כן; הואיל ובסופו של דבר נותרה לשמואל דירה אחת, הוא חייב במס רכישה בשיעורים של דירה יחידה.", "לא; בעת רכישת הדירה הנוספת מהקבלן הפכה דירה זו לדירה נוספת ולכן לא מדובר בדירה יחידה.", "כן; הואיל ושמואל מכר את הדירה הראשונה בתוך פחות משנה מהרגע שקיבל את החזקה בדירה הנוספת.", "לא; דירה שנרכשת מקבלן לא נחשבת כדירה יחידה, והרוכש חייב במס רכישה מלא."]'::jsonb, 2, null, 'חוק מיסוי מקרקעין מכיר ב"דירה חלופית": מי שרוכש דירה נוספת ומוכר את הדירה הקודמת בתוך התקופה הקבועה בחוק נחשב כבעל דירה יחידה לצורך מס רכישה. כשהדירה הנוספת נרכשה מקבלן, התקופה נספרת מהמועד שבו החזקה אמורה הייתה להימסר, והיא 12 חודשים. שמואל מכר בתוך 10 חודשים ממסירת החזקה, ולכן עומד בתנאי. חלופה א מגיעה לתוצאה נכונה אך מנימוק שגוי (ההקלה תלויה בעמידה בתקופה, לא ב"סופו של דבר"), וחלופות ב ו-ד סותרות את הוראת הדירה החלופית.', 'סעיף 9(ג1ג) לחוק מיסוי מקרקעין (שבח ורכישה) - הגדרת "דירה יחידה" ודירה חלופית', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q03', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 3', 'האחיות גילה ולילי ירשו מאימן דירת מגורים ברמת גן. לכל אחת מהן יש 2 דירות נוספות. בהתאם לצו ירושת אימן, היו זכאיות גילה ולילי להירשם כבעלות הדירה באופן הבא: גילה - מחצית; לילי - מחצית. מאחר שהעיזבון טרם חולק, גילה ולילי הסכימו לחלק ביניהן בהסכם את הדירה באופן שונה מכפי שמופיע בצו הירושה: גילה - 2/5; לילי - 3/5. גילה ולילי לא שילמו זו לזו כספים בגין החלוקה עליה הסכימו. האם גילה ולילי חייבות במס שבח בגין רישום הדירה על שמן בלשכת רישום המקרקעין על פי החלוקה עליה הסכימו?', '["כל העברה בלשכת רישום מקרקעין, בגין ירושה, תמיד חייבת במס שבח ולכן האחיות חייבות במס.", "כל העברה במקרקעין חייבת במס שבח, ולכן האחיות חייבות במס.", "אין חובה לשלם מס שבח במקרה זה, מכיוון שבנסיבות המתוארות לא רואים כמכירה חלוקת נכסי עיזבון בין יורשים.", "רק לילי חייבת במס שבח במקרה זה, מכיוון שהיא קיבלה חלק גדול יותר מגילה ולכן מדובר בעסקת מקרקעין לכל דבר ועניין."]'::jsonb, 2, null, 'הורשה אינה "מכירה" לעניין חוק מיסוי מקרקעין (סעיף 4), וסעיף 5(ג)(4) קובע שגם חלוקת נכסי עיזבון בין יורשים אינה נחשבת מכירה, ובלבד שלא ניתנה במסגרת החלוקה תמורה בכסף או בשווה כסף מחוץ לנכסי העיזבון. כאן העיזבון טרם חולק והאחיות לא שילמו זו לזו דבר, ולכן אין אירוע מס גם אם החלוקה שונה מצו הירושה. חלופות א ו-ב מתעלמות מהחריג, וחלופה ד הייתה נכונה רק אילו לילי שילמה לגילה מכספה על החלק העודף.', 'סעיפים 4 ו-5(ג)(4) לחוק מיסוי מקרקעין (שבח ורכישה)', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q04', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 4', 'משה הוא בעלים של דירת מגורים (להלן - "הדירה"). יוסי מעוניין לרכוש את הדירה. ביום 1.1.2021, לאחר שיוסי בדק את הדירה, נפגשו משה ויוסי במשרדו של עו"ד ישראלי וחתמו על זכרון דברים, לפיו התחייב משה למכור ליוסי את הדירה בסכום של 1,500,000 ש"ח. כן נקבעו מועדי מסירת החזקה, מועדי התשלומים, אילו מיסים חייב כל צד לשלם ומתי, וכל יתר התנאים הרלוונטיים להשלמת העיסקה. בעת החתימה על זכרון הדברים, שילם יוסי למשה מקדמה על חשבון הדירה בסך של 100,000 ש"ח. הצדדים קבעו ביניהם כי ייפגשו עד ליום 11.1.2021 אצל עו"ד ישראלי כדי לחתום על הסכם מכר רשמי. ביום 11.1.2021 הגיע יוסי למשרדו של עו"ד ישראלי כדי לחתום על הסכם המכר, אולם משה לא הגיע לפגישה. בשיחת טלפון שערך עו"ד ישראלי עם משה, הודיע משה כי הציעו לו סכום גבוה יותר מהסכום שנקבע בזכרון הדברים, ולכן הוא לא רוצה למכור ליוסי את הדירה בסכום שהציע. לפי פסק דין רבינאי נ'' מן שקד, ובהתאם לנסיבות המתוארות לעיל, האם משה יכול לחזור בו מההסכם?', '["מאחר שלא נחתם הסכם מכר רשמי, משה לא חייב למכור את הדירה ליוסי.", "מדובר בהסכם מחייב, הואיל ובזכרון הדברים הסדירו הצדדים את כל הפרטים המהותיים לעיסקה, וגם קבעו כי זכרון הדברים מחייב.", "מאחר שיש קונה המוכן לשלם סכום גבוה יותר, משה רשאי לחזור בו מן העיסקה.", "הואיל והצדדים עדיין לא דיווחו על העיסקה לרשויות המס, העיסקה לא מחייבת אותם."]'::jsonb, 1, null, 'בפסק דין רבינאי נ'' מן שקד קבע בית המשפט העליון שני מבחנים לזכרון דברים מחייב: גמירות דעת של הצדדים להתקשר כבר עכשיו, ומסוימות, כלומר שהפרטים המהותיים (הנכס, המחיר, מועדי התשלום והמסירה) מוסכמים. כאן שני המבחנים מתקיימים, הייתה גם מקדמה, והמסמך כתוב כנדרש בסעיף 8 לחוק המקרקעין, ולכן נכרת חוזה מחייב וה"הסכם הרשמי" הוא רק פורמליות. הצעה גבוהה יותר מצד שלישי אינה עילה לביטול (ג), והדיווח למיסוי מקרקעין הוא חובה שלאחר הכריתה ואינו תנאי לתוקפה (ד).', 'ע"א 158/77 רבינאי נ'' מן שקד; סעיפים 1-5 לחוק החוזים (חלק כללי); סעיף 8 לחוק המקרקעין', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q05', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 5', 'ביום 1.1.2021 הציע ראובן למכירה את דירתו בכתב לשמעון בסכום של 1,600,000 ש"ח ונתן לשמעון 14 ימים להודיע לו האם הוא מקבל את ההצעה. לאחר 10 ימים, בטרם ניתנה תשובתו של שמעון, הודיע ראובן לשמעון כי אינו מעוניין עוד למכור לו את הדירה. מהו הדין ביחס לאפשרות של ראובן לחזור בו מן ההצעה?', '["ההצעה ניתנה בכתב, ולכן לא ניתן לבטלה יותר.", "ראובן אינו יכול לחזור בו מהצעתו למכור את הדירה לשמעון, כי נתן מועד לקיבולה.", "ראובן רשאי לחזור בו מן ההצעה בכל עת.", "ראובן רשאי לחזור בו מן ההצעה בכל עת, ובלבד שמסר לשמעון הודעה בכתב על כך."]'::jsonb, 1, null, 'סעיף 3(א) לחוק החוזים (חלק כללי) מתיר למציע לחזור בו מהצעה כל עוד הניצע לא קיבל אותה, אך סעיף 3(ב) קובע חריג: הצעה שהמציע קבע בה שהיא ללא חזרה, או שקבע בה מועד לקיבולה, אינה ניתנת לחזרה לאחר שנמסרה לניצע. ראובן קבע 14 ימים לקיבול, ולכן ההצעה "בלתי הדירה" עד תום התקופה. העובדה שההצעה בכתב (א) אינה הטעם, וחלופות ג ו-ד מתארות את הכלל הרגיל בלי החריג.', 'סעיף 3(ב) לחוק החוזים (חלק כללי), התשל"ג-1973', 5, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q06', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 6', 'ביום 1.1.2021 הציעה לאה למשה לקנות את דירתה בקרית-אונו במחיר של 1,600,000 ש"ח. באותו יום נפגשו משה ולאה והיא הראתה לו את הדירה. בו במקום הודיע משה ללאה כי הוא מעוניין לרכוש את דירתה בסכום שהוצע. שבוע לאחר מכן, נפגשו לאה ומשה במשרדו של עו"ד ישראלי וחתמו על הסכם מכר. באותו מעמד שילם משה ללאה 10% מהתמורה (160,000 ש"ח) על חשבון הרכישה. באותו יום רשם עו"ד ישראלי הערת אזהרה לטובת משה. יום למחרת, נפגשה לאה עם חברתה, ליאורה, וסיפרה לה על העיסקה. ליאורה, אשר אהבה מאוד את דירתה של לאה, הציעה ללאה עבורה סכום של 1,800,000 ש"ח (200,000 ש"ח יותר ממשה), ואף אמרה לה שתוכל לשלם את הכסף בתוך שבוע ימים בלבד. לאה שמחה על ההצעה של ליאורה ושתיהן חתמו בו במקום על הסכם מכר לדירה. זכותו של מי עדיפה לקבלת הדירה, ואיזה הסכם מבין ההסכמים מחייב?', '["מאחר שלאה וליאורה חתמו על הסכם מכר מאוחר בזמן ובתמורה גבוהה יותר, זכותה של ליאורה עדיפה.", "הואיל ומשה עדיין לא שילם ללאה את מלוא התמורה על פי הסכם המכר, לאה היא עדיין הבעלים של הדירה ולכן היא יכולה למכור את הדירה למי שהיא רוצה.", "הסכם המכר בין לאה לבין משה מחייב את הצדדים, מכיוון שנחתם מוקדם יותר ונרשמה הערת אזהרה לפיו ולכן זכותו של משה עדיפה.", "הואיל והבעלות עדיין לא נרשמה על שם משה בטאבו, אין כל מניעה למכור את הדירה לליאורה, וההסכם עימה מחייב."]'::jsonb, 2, null, 'זו "עסקה נוגדת" לפי סעיף 9 לחוק המקרקעין: כשבעל מקרקעין התחייב לעשות עסקה ואחר כך התחייב לעסקה נוגדת, זכותו של הראשון עדיפה, אלא אם השני פעל בתום לב ובתמורה והעסקה לטובתו נרשמה קודם. משה הוא הראשון בזמן, ומעבר לכך נרשמה לטובתו הערת אזהרה (סעיף 126), שלפי סעיף 127 מונעת רישום עסקה סותרת ושוללת מליאורה את טענת תום הלב. מחיר גבוה יותר (א) או אי-רישום הבעלות (ב, ד) אינם מבטלים התחייבות חוזית תקפה; לאה חשופה לתביעה מליאורה, אך הדירה למשה.', 'סעיפים 9, 126 ו-127 לחוק המקרקעין, התשכ"ט-1969', 6, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q07', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 7', 'חנה, מתווכת מקרקעין בעלת רישיון תיווך, חתמה על הסכם תיווך עם ראובן, אשר הציע בית למכירה בהרצליה, בסכום של 7 מיליון ש"ח. בדרכה לפגישה עם הקונה שמעון, התקשר אליה עו"ד ישראלי והוכיח לה כי הבעלים האמיתי של הבית הוא יהודה ולא ראובן. חנה המשיכה בדרכה לפגישה עם שמעון, החתימה גם אותו על הסכם תיווך, אך לא שיתפה את שמעון בשיחת הטלפון עם עו"ד ישראלי. האם חלה חובה על חנה לגלות לשמעון הקונה את המידע שנתגלה לה? מדוע?', '["כן; מאחר שיהודה הוא לא הלקוח של המתווכת.", "לא; חנה מחויבת בסודיות ללקוח שלה, ראובן.", "לא; מדובר בייעוץ משפטי שאינו בסמכותה של המתווכת.", "כן; אם לא תגלה את המידע, חנה תיתן מידע שגוי באופן מהותי ותפר את חובת תום הלב וההתנהלות בדרך המקובלת כלפי שמעון."]'::jsonb, 3, null, 'סעיף 8(א) לחוק המתווכים מחייב מתווך לפעול בנאמנות, בהגינות ובדרך מקובלת ולמסור ללקוחו כל מידע שבידו בעניין מהותי הנוגע לנכס. שמעון חתם על הסכם תיווך ולכן הוא לקוח של חנה, וזהות הבעלים האמיתי של הנכס היא המידע המהותי ביותר שיש. חובת הסודיות (ב) אינה מכסה הסתרת עובדה שהופכת את העסקה כולה למטעה, ובדיקת זהות הבעלים אינה ייעוץ משפטי (ג) אלא ליבת תפקיד המתווך. חלופה א מגיעה ל"כן" מנימוק לא רלוונטי. תקנות האתיקה תשפ"ד-2024 מחזקות את אותה תוצאה: תקנה 4 אוסרת הטעיה בעניין מהותי גם במחדל, ותקנה 7 מחייבת למסור לקונה נסח רישום, שבו מופיע הבעלים הרשום.', 'סעיף 8(א) לחוק המתווכים במקרקעין, התשנ"ו-1996; תקנות 4 ו-7 לתקנות המתווכים (אתיקה וחובות מקצועיות), התשפ"ד-2024', 7, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q08', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 8', 'האם מתווך חייב לגלות ללקוחו ברכישת נכס שבעלי הנכס נמצא בפשיטת רגל? מדוע?', '["כן; מדובר בעניין מהותי, ולכן יש לגלותו ללקוח.", "כן; בתנאי שגם המוכר הוא הלקוח של המתווך.", "לא; מדובר בעניין משפטי סודי וחסוי.", "לא; כי גילוי פשיטת רגל יפגע במוכר ובמחיר שניתן לקבל על הנכס."]'::jsonb, 0, null, 'פשיטת רגל של המוכר היא עניין מהותי לקונה: נכסי פושט הרגל עוברים לניהול הנאמן, ועסקה עם המוכר עצמו עלולה להיות חסרת תוקף או להתעכב. סעיף 8(א) לחוק המתווכים מחייב למסור ללקוח כל מידע מהותי שבידי המתווך, בלי קשר לשאלה אם המוכר הוא גם לקוחו (ב). הפגיעה במוכר או במחיר (ד) אינה פוטרת מהגילוי, והמידע אינו "חסוי" (ג): הליכי חדלות פירעון מתפרסמים ברבים ונרשמים גם בנסח. תקנות האתיקה 2024 (תקנה 7 והתוספת הראשונה) מחייבות ממילא למסור לקונה נסח רישום עדכני.', 'סעיף 8(א) לחוק המתווכים במקרקעין; תקנה 7 לתקנות המתווכים (אתיקה וחובות מקצועיות), התשפ"ד-2024', 8, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q09', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 9', 'ועד הבית החליט לערוך תקנון חדש בבית משותף, ולקבוע בו הוראה כי חלק מסוים מהרכוש המשותף יוצמד לדירת הגן בבניין. האם הדבר אפשרי?', '["הדבר אפשרי, בהחלטה של כל בעלי הדירות.", "הדבר לא אפשרי; אסור בכל מקרה להצמיד חלק מסוים מהרכוש המשותף לדירה מסוימת.", "הדבר אפשרי, ברוב של בעלי הדירות ששני שליש מהרכוש המשותף צמוד לדירותיהם.", "הדבר אפשרי, ברוב של שני שליש מכלל בעלי הדירות."]'::jsonb, 0, null, 'סעיף 62(א) לחוק המקרקעין מתיר לבעלי הדירות לערוך תקנון מוסכם ולשנותו ברוב של בעלי הדירות ששני שלישים מהרכוש המשותף צמודים לדירותיהם, אך קובע במפורש שאין לקבוע הצמדה של חלק מסוים מהרכוש המשותף לדירה פלונית אלא בהסכמת כל בעלי הדירות. לכן הצמדה אפשרית (ב שגויה), אבל לא ברוב רגיל או מיוחס (ג, ד) אלא בפה אחד. ועד הבית עצמו אינו מוסמך לערוך תקנון; זו סמכות אסיפת בעלי הדירות.', 'סעיף 62(א) לחוק המקרקעין, התשכ"ט-1969', 9, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
