  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q10', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 10', 'מי יכול להגיש בקשה לתיקון צו רישום בית משותף, ולמי מוגשת הבקשה?', '["אחד מבעלי הדירות או בעל זכות בדירה יכול להגיש את הבקשה לבית משפט השלום.", "כל אחד מבעלי הדירות או בעל זכות בדירה יכול להגיש את הבקשה למפקח על הבתים המשותפים.", "בעלי הדירות שלפחות שני שלישים מהרכוש המשותף צמוד לדירותיהם יכולים להגיש את הבקשה לבית משפט השלום או למפקח על הבתים המשותפים.", "בעלי הדירות שלפחות שני שלישים מהרכוש המשותף צמוד לדירותיהם יכולים להגיש את הבקשה למפקח על הבתים המשותפים."]'::jsonb, 1, null, 'סעיף 145 לחוק המקרקעין מסמיך את המפקח על רישום מקרקעין (המפקח על הבתים המשותפים) לתקן צו רישום של בית משותף, על פי בקשה של בעל דירה או של מי שיש לו זכות בדירה. די במבקש אחד, ואין דרישת רוב (ג, ד), והגוף המוסמך הוא המפקח ולא בית משפט השלום (א). חשוב להבחין: תיקון הצו הוא עניין רישומי שבסמכות המפקח, ואילו שינוי זכויות קנייניות (למשל הצמדה חדשה) דורש הסכמת בעלי הדירות לפי סעיף 62.', 'סעיף 145 לחוק המקרקעין, התשכ"ט-1969', 10, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q11', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 11', 'ועד הבית של בית משותף ברחוב ויטק 9 בתל אביב, החליט להתקשר עם קבלן לשם ביצוע פרויקט של חיזוק בתים משותפים מפני רעידות אדמה. במסגרת הפרויקט, ייבנו דירות חדשות לבניין (וזאת מבלי להרוס ולבנות מחדש את הבניין). כל דיירי הבניין חתמו על הסכמתם לביצוע הפרויקט, למעט חנה. חנה הינה קשישה ונכה המרותקת לביתה באופן קבוע. הקבלן לא מעוניין להציע לה דיור חלופי. האם ניתן לאשר את הפרויקט חרף התנגדותה של חנה?', '["לא ניתן לאשר את הפרויקט, מכיוון שקיומו טעון הסכמת כל בעלי הדירות.", "המפקח על הבתים המשותפים יכול לאשר ביצוע הפרויקט ברוב של 2/3 מבעלי הבתים.", "למפקח על הבתים המשותפים אין סמכות לאשר את ביצוע העבודות, אלא אם הוצעו לחנה מגורים חלופיים לתקופת ביצוע העבודות.", "המפקח על הבתים המשותפים חייב במקרה זה לאשר את הפרויקט."]'::jsonb, 2, null, 'חוק המקרקעין (חיזוק בתים משותפים מפני רעידות אדמה), התשס"ח-2008 מאפשר לבצע חיזוק עם בניית דירות חדשות (תמ"א 38/1) ברוב מיוחס של בעלי הדירות, והמפקח רשאי לאשר את העבודות חרף התנגדות המיעוט. אולם החוק מגן על בעל דירה מתנגד שהוא קשיש או אדם עם מוגבלות: המפקח לא יאשר את ביצוע העבודות אלא אם הוצעו לו מגורים חלופיים סבירים לתקופת העבודות. לכן הרוב לבדו אינו מספיק (ב, ד), אך גם אין צורך בהסכמת כולם (א). שימו לב שהחוק מדבר על "בעלי דירות" ולא על "דיירים" כפי שנכתב בשאלה.', 'סעיף 5 לחוק המקרקעין (חיזוק בתים משותפים מפני רעידות אדמה), התשס"ח-2008', 11, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q12', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 12', 'מוכרים חתמו על הזמנה לשירותי תיווך ובלעדיות למשך חצי שנה למתווך א'', אשר ביצע פעולות תיווך כדין. במהלך תקופת הבלעדיות הגיע למוכר מתווך ב'' שמצא קונה לנכס. המוכר חתם גם למתווך ב'' על טופס הזמנה לשירותי תיווך, ונחתמה עסקה בזכותו. על פי פסק דין אל הנכס נ'' שמלצר, מי מהמתווכים זכאי לדמי תיווך?', '["רק מתווך א'', שכן המוכרים חתמו על הסכמה לבלעדיות.", "רק מתווך ב'', שהיה הגורם היעיל בעיסקה.", "שני המתווכים, וכל אחד מהם יקבל דמי תיווך כפי שסוכם עימו ללא הפחתה.", "שני המתווכים, אבל עליהם לחלוק בדמי התיווך."]'::jsonb, 2, null, 'בדו"ח הגרסאות הרשמי של הרשם שאלה זו סומנה "כל התשובות מתקבלות", כלומר כל נבחן קיבל עליה את הנקודות. לפי הדין: סעיף 14(ב) לחוק המתווכים קובע שמתווך שקיבל בלעדיות וביצע פעולות שיווק כדין, חזקה שהוא הגורם היעיל להתקשרות שנעשתה בתקופת הבלעדיות, ולכן מתווך א'' זכאי לדמי התיווך שסוכמו עמו. מתווך ב'' החתים את המוכר על הזמנה בכתב והיה בפועל הגורם שהביא את הקונה, ולכן זכאי אף הוא לפי סעיף 14(א). המוכר שהתקשר עם שניים חשוף לשני התשלומים, ואין בחוק הוראה המחייבת את המתווכים לחלוק (ד). זו החלופה הקרובה ביותר לדין, אך המפתח הרשמי לא הכריע.', 'סעיפים 14(א) ו-14(ב) לחוק המתווכים במקרקעין, התשנ"ו-1996', 12, false
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q13', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 13', 'משכיר חתם למתווך על הסכם בלעדיות בלתי מוגבל בזמן להשכרת חנות. לאחר חודשיים ביקש המשכיר לבטל את הבלעדיות. לפי הדין, האם רשאי המשכיר לבטל הסכמתו לבלעדיות להשכרת החנות? מדוע?', '["כן, בלעדיות לתקופה בלתי מוגבלת בזמן היא חסרת תוקף.", "המשכיר יוכל לבטל את הסכם הבלעדיות אך ורק בתום 9 חודשים.", "המשכיר יוכל לבטל את הסכם הבלעדיות לאחר חודשיים.", "אם בוצעו 2 פעולות שיווק כדין, לא ניתן לבטל את הסכם הבלעדיות."]'::jsonb, 1, null, 'סעיף 9 לחוק המתווכים מגביל את תקופת הבלעדיות ומבחין בין דירת מגורים לנכס אחר: בדירת מגורים הבלעדיות לא תעלה על שישה חודשים, ואם לא נקבעה תקופה היא מסתיימת בתום 30 ימים; בנכס שאינו דירת מגורים, כמו חנות, הבלעדיות לא תעלה על שנה, ואם לא נקבעה תקופה היא מסתיימת בתום תשעה חודשים. הסכם "בלתי מוגבל בזמן" אינו בטל (א) אלא מתוקן לפי החוק לתשעה חודשים, ולכן המשכיר כבול עד אז. פעולות השיווק (ד) קשורות לחזקת הגורם היעיל בסעיף 14(ב), לא למשך הבלעדיות.', 'סעיף 9 לחוק המתווכים במקרקעין, התשנ"ו-1996 - תקופת הבלעדיות בנכס שאינו דירת מגורים', 13, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q14', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 14', 'לפי פסק דין שמעון נ'' סמיקון, האם קיימת חובה על מתווך להציג לקונה נסח של הנכס שהוא מציע ללקוח?', '["כן, כחלק מחובתו של המתווך לנהוג בהגינות ובזהירות ובכלל זה למסור מידע מהותי על הנכס.", "לא, נסח הוא מסמך משפטי ואסור למתווך לעסוק בו.", "כן, אבל רק אם יש עיקולים על הנכס.", "לא, זה אינו חלק מתפקידו של מתווך."]'::jsonb, 0, null, 'סעיף 8 לחוק המתווכים מחייב את המתווך לפעול בהגינות ובדרך מקובלת, למסור ללקוח כל מידע מהותי על הנכס, ולנקוט אמצעים ראויים לקבלת מידע כזה (סעיף 8(ב)). נסח הרישום הוא המקור הבסיסי למידע על הבעלים, המשכנתאות, העיקולים וההערות, ובפסיקה נקבע שמתווך שלא הציג אותו הפר את חובת הזהירות, גם בלי קשר לשאלה אם יש עיקול בפועל (ג). הוצאת נסח אינה "עיסוק משפטי" אסור (ב, ד). תקנות האתיקה 2024 הפכו זאת לחובה מפורשת: נסח הרישום הוא הפריט הראשון ברשימת המידע המהותי שבתוספת הראשונה.', 'סעיף 8 לחוק המתווכים במקרקעין; תקנה 7(ב) והתוספת הראשונה לתקנות המתווכים (אתיקה וחובות מקצועיות), התשפ"ד-2024', 14, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q15', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 15', 'על חלקתה של ליאת רשומה זיקת הנאה לטובת חלקתה של דנה, ואולם לא נקבעה תקופה בתנאיה. מה תוקף זיקת ההנאה?', '["זיקת ההנאה תקפה כל עוד לא נמחקה.", "זיקת ההנאה תקפה לזמן סביר.", "זיקת ההנאה תקפה עד שדנה תמכור את חלקתה.", "זיקת ההנאה לא תקפה שכן יש לרשום זיקת הנאה על שם בן אדם."]'::jsonb, 0, null, 'סעיף 96 לחוק המקרקעין קובע שזיקת הנאה היא לתקופה בלתי מוגבלת, זולת אם נקבעה לה תקופה בתנאיה; בית המשפט רשאי לבטלה או לשנות את תנאיה רק לפי בקשה ומטעמים שבחוק. לכן זיקה ללא תקופה עומדת בתוקפה כל עוד לא נמחקה (א). זיקת הנאה יכולה להיות לטובת מקרקעין (זיקה "לטובת חלקה") ולא רק לטובת אדם (סעיף 93), ואז היא עוברת עם המקרקעין הזכאים גם כשנמכרים (ג, ד שגויות).', 'סעיפים 93 ו-96 לחוק המקרקעין, התשכ"ט-1969', 15, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q16', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 16', 'מה ההבדל בין משכנתא למשכון?', '["משכנתא היא שעבוד על נכס מקרקעין ומשכון הוא שעבוד זכויות.", "משכנתא היא הלוואה לרכישת דירה ומשכון זו הלוואה לרכישת רכב.", "משכנתא ניתן לרשום רק אם הנכס לא רשום בטאבו, ומשכון ניתן לרשום רק אם הנכס רשום בטאבו.", "אין הבדל בין משכנתא למשכון."]'::jsonb, 0, null, 'סעיף 4 לחוק המקרקעין מגדיר: "משכנתה היא משכון של מקרקעין", כלומר שעבוד של זכות בעלות או חכירה הרשומה בלשכת רישום המקרקעין. משכון לפי חוק המשכון הוא שעבוד של מיטלטלין או של זכויות (למשל זכות חוזית לקבל דירה מקבלן), ונרשם אצל רשם המשכונות. ההבדל הוא במושא השעבוד ובמרשם, לא במטרת ההלוואה (ב). חלופה ג הפוכה: דווקא נכס שרשום בטאבו ממושכן במשכנתא, ואילו זכות שטרם נרשמה ממושכנת במשכון.', 'סעיף 4 לחוק המקרקעין, התשכ"ט-1969; חוק המשכון, התשכ"ז-1967', 16, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
