insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q17', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 17', 'מה מבין הבאים אינו עשוי להיכלל בתוכנית בניין עיר (תב"ע)?', '["תקנון.", "תשריט.", "נספח שמירה על הסביבה.", "גרמושקה של בקשה לקבלת היתר בנייה."]'::jsonb, 3, null, 'תוכנית לפי חוק התכנון והבנייה מורכבת מתקנון (ההוראות המילוליות) ומתשריט (המפה), ויכולה לכלול נספחים כמו נספח סביבתי, נספח תנועה או נספח בינוי. ה"גרמושקה" היא תוכנית ההגשה של בקשה להיתר בנייה: היא מוגשת לוועדה המקומית לפי התוכנית ולא כחלק ממנה. ההבחנה בין תוכנית (שקובעת את הזכויות) לבין היתר (שמממש אותן בבניין מסוים) חוזרת בבחינה.', 'חוק התכנון והבנייה, התשכ"ה-1965 - מסמכי התוכנית (תקנון ותשריט) לעומת בקשה להיתר', 17, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
