insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q18', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 18', 'האם חקלאי שמעמדו הוא "בר רשות" יכול להגדיל את שטח יחידת המגורים שלו?', '["לא; \"בר רשות\" לא יכול להגדיל את שטח יחידת המגורים שלו.", "כן; ל\"בר רשות\" יש רשות להגדיל את שטח יחידת המגורים שלו ללא תנאי.", "לא; \"בר רשות\" משמעותו שניתן לפנותו מהקרקע בכל רגע.", "כן; \"בר רשות\" יכול להגדיל את שטח מגוריו לפי הזכויות וההסכמים החלים על הקרקע."]'::jsonb, 3, null, 'בר רשות הוא מי שמחזיק בנחלה חקלאית מכוח הסכם (בדרך כלל הסכם המשבצת בין רשות מקרקעי ישראל, הסוכנות והאגודה השיתופית) ולא מכוח חכירה רשומה. זכויותיו אינן אפס (א, ג), אך גם אינן בלתי מוגבלות (ב): הוא רשאי לבנות ולהרחיב את יחידת המגורים לפי מה שמתירים הסכם המשבצת, החלטות מועצת מקרקעי ישראל והתוכנית החלה על הקרקע, ובכפוף להיתר בנייה. בר רשות קבועה בנחלה אינו ניתן לפינוי "בכל רגע" (ג) אלא לפי תנאי ההסכם.', 'הסכמי המשבצת והחלטות מועצת מקרקעי ישראל בנוגע לנחלות; חוק התכנון והבנייה', 18, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
