  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q19', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 19', 'צביקה הוא בעלים של בית מלון ומעוניין למכור את בית המלון. לצורך כך, צביקה התקשר בהזמנת תיווך עם יוסי המתווך. יוסי המתווך ניהל משא ומתן שלא צלח עם חברת "איתמר" בע"מ לגבי רכישת המלון. לאחר כשנה פנה נציג הבעלים אל מתווך (מתווך אחר) אשר הצליח לסגור את העיסקה עם חברת "איתמר" בע"מ במחיר חדש. יוסי המתווך לא היה מעורב במשא ומתן בשלב זה, וכן לא התבקש לסייע. בסופו של דבר נחתם חוזה רכישה בין הצדדים. בנסיבות המתוארות לעיל ולפי פסק דין ע"א 2144/91 מוסקוביץ נ'' ביר, האם זכאי יוסי המתווך לדמי תיווך?', '["יוסי לא זכאי לדמי תיווך, מכיוון שלא טיפל בעיסקה עד תומה.", "יוסי לא זכאי לדמי תיווך, מכיוון שלא סיים את המשא ומתן על המחיר בעיסקה.", "יוסי זכאי לדמי תיווך בעיסקה מכיוון שהזמנת תיווך כדין תקפה למשך שנה.", "יוסי זכאי לדמי תיווך, מכיוון שנציג הבעלים הוא \"גורם מתערב\" במשא ומתן, שאינו שולל את זכאותו של יוסי לדמי תיווך."]'::jsonb, 3, null, 'סעיף 14(א)(3) לחוק המתווכים מזכה בדמי תיווך מתווך שהיה "הגורם היעיל" שהביא להתקשרות. בפסק דין מוסקוביץ נ'' ביר פירט בית המשפט העליון את המבחנים לגורם היעיל (מי הפגיש את הצדדים, הדמיון בין העסקה שנדונה לזו שנחתמה, הזמן שחלף, ומידת הפעילות של אחרים), וקבע שהתערבות של גורם נוסף או פרק זמן שחלף אינם מנתקים מאליהם את הקשר הסיבתי כשהמתווך הראשון הוא שהביא את הקונה. יוסי הפגיש את צביקה עם "איתמר" ולכן זכאי. הזמנת תיווך אינה "תקפה לשנה" (ג), והשלמת המשא ומתן עד תומו אינה תנאי לזכאות (א, ב).', 'סעיף 14(א) לחוק המתווכים במקרקעין; ע"א 2144/91 מוסקוביץ נ'' ביר', 19, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
