  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q20', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 20', 'תמ״א 38 היא תוכנית המיתאר הארצית לחיזוק מבנים נגד רעידת אדמה. התמ״א כוללת הוראות שנועדו לחזק מבנים שנבנו לפני 1.1.1980 מפני רעידות אדמה, ומאפשרת הוספת שטחי בנייה לבניינים קיימים העוברים חיזוק באמצעות התמ״א. לערן בעלות מלאה על מבנה שנבנה בשנות ה-60, שחציו משמש למגורים וחציו משמש לעסקים ולחנויות. המבנה רשום כבית משותף. ערן מעוניין לדעת האם תמ״א 38/2 יכולה לחול על המבנה שברשותו. איזה מבין התנאים הבאים הוא תנאי מחייב להכנסת הבניין לתמ"א 38/2?', '["התנאי המחייב הוא שאין התנגדויות לתוכנית.", "התנאי המחייב הוא שעל ערן להסב את השימושים בנכס לשימוש מגורים לפני שיוכל להחיל את הוראות תמ״א 38/2 על המבנה שברשותו.", "התנאי המחייב הוא שתמ\"א 38/2 תחול על מבנה ציבור בלבד.", "התנאי המחייב הוא שהאישור שניתן לחיזוק המבוקש משתלב בתשתית הקיימת."]'::jsonb, 3, null, 'תמ"א 38 חלה על מבנים שהיתר הבנייה שלהם ניתן לפני 1.1.1980 ושמהנדס קבע כי הם טעונים חיזוק, ואינה מוגבלת למבני מגורים או למבני ציבור (ב, ג שגויות): גם בניין מעורב של מגורים ומסחר נכנס בגדרה. התנגדויות הן חלק מהליך הרישוי ואינן חוסמות מראש (א). לעומת זאת, התמ"א מתנה את מתן ההיתר, ובמיוחד בהריסה ובנייה מחדש לפי 38/2, בכך שהוועדה המקומית תשתכנע שהתוספת משתלבת בתשתיות הקיימות והמתוכננות (חניה, תנועה, ביוב) וברקמה הסביבתית, ורשאית לסרב כשאינן עומדות בעומס. לכן ד.', 'תמ"א 38 (תוכנית מיתאר ארצית לחיזוק מבנים קיימים בפני רעידות אדמה), לרבות תיקון 2 (הריסה ובנייה מחדש); חוק התכנון והבנייה', 20, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
