  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q21', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 21', 'לראובן משק חקלאי אותו הוא מעבד באגודה השיתופית ״שדה מנגו״ שבגליל. בצוואתו ביקש ראובן להוריש את הנחלה לילדיו דנה ושמעון, כדי שימשיכו לעבד את הקרקע לאחר מותו. האם ניתן להוריש נחלה חקלאית ל- 2 ילדים בצוואה? מדוע?', '["לא; יש לקבוע את היורשים כבנים ממשיכים ולחלק את הקרקע ביניהם בצוואה.", "כן; בתנאי שימונה מנהל עיזבון שיחלק את הרכוש בין האחים.", "לא; לא ניתן להוריש נחלה לשני ילדים, אלא יש לקבוע בן ממשיך אחד לנחלה.", "כן; ניתן להוריש חלק בלתי מסוים במקרקעין בצוואה לשני ילדים."]'::jsonb, 2, null, 'נחלה חקלאית היא יחידה כלכלית אחת שאינה ניתנת לפיצול: סעיף 114 לחוק הירושה קובע שמשק חקלאי שחלוקתו תפגע בכושר קיומו כמשק המפרנס משפחה יימסר ליורש אחד המוכן ומסוגל לקיימו, והוא יפצה את שאר היורשים. גם הסכמי המשבצת של רשות מקרקעי ישראל אוסרים העברת זכויות בנחלה ליותר מאדם אחד (ובן זוגו) ומכירים ב"בן ממשיך" אחד בלבד. לכן אי אפשר להוריש את הנחלה לשני ילדים יחד, לא בחלקים (א) ולא כחלק בלתי מסוים (ד), ומנהל עיזבון (ב) אינו פותר את איסור הפיצול.', 'סעיף 114 לחוק הירושה, התשכ"ה-1965; הסכמי המשבצת והחלטות מועצת מקרקעי ישראל בנוגע ל"בן ממשיך"', 21, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q22', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 22', 'נדב רכש דירה חדשה מקבלן. אל חוזה המכר צורפו מפרט והוראות תחזוקה ושימוש, כשהן חתומות על ידי הקבלן. הצדדים סיכמו בנספח מיוחד לקצר בשנה אחת את תקופת הבדק לאי-התאמה יסודית, משנתיים לשנה בעניין שקיעה של ריצוף. האם ניתן לקצר את תקופת הבדק לאי התאמה יסודית?', '["ניתן לקצר את תקופת הבדק רק בהסכמה בכתב ובנספח נפרד, ולכן הצדדים פעלו כדין.", "ניתן לקצר את תקופת הבדק אך ורק בנושא שקיעה של הריצוף.", "תקופת הבדק היא תקופה מקסימלית בחוק ומותר לקצר אותה גם בעל פה.", "לא ניתן לקצר את תקופת הבדק לאי-התאמה יסודית."]'::jsonb, 3, null, 'חוק המכר (דירות) הוא חוק קוגנטי: סעיף 7א קובע שאין להתנות על הוראותיו אלא לטובת הקונה. תקופות הבדק שבתוספת לחוק הן מינימום שהמוכר אחראי בו לתיקון אי-התאמה, ולכן ניתן להאריך אותן לטובת הקונה אך לא לקצרן, לא בנספח נפרד (א), לא בנושא מסוים (ב) ובוודאי לא בעל פה (ג). נספח כזה בטל, ונדב זכאי למלוא תקופת הבדק שבחוק. אותו עיקרון חל על תקופת האחריות שאחרי הבדק ועל חובת המסירה של מפרט והוראות תחזוקה.', 'סעיף 7א לחוק המכר (דירות), התשל"ג-1973, והתוספת לחוק (תקופות הבדק)', 22, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q23', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 23', 'מהו ״שימוש חורג״ בקרקע או בבניין?', '["שימוש בנכס מקרקעין השונה מזה שנקבע בתוכנית החלה במקום או בהיתר הבנייה.", "שימוש בנכס לפי תוכנית בדבר בינוי או עיצוב אדריכליים החורג מקו הבניין.", "שינוי חלוקת שטחי הבנייה המותרים בתוכנית אחת, שהיא תוכנית שאישרה הוועדה המחוזית.", "הגדלת מספר יחידות הדיור ללא הגדלת סך השטחים למטרות עיקריות."]'::jsonb, 0, null, 'סעיף 1 לחוק התכנון והבנייה מגדיר "שימוש חורג" כשימוש בקרקע או בבניין למטרה שלא הותר להשתמש בהם לפי התוכנית החלה או לפי ההיתר. למשל, הפעלת משרד בדירה שייעודה מגורים. שימוש חורג מתוכנית טעון היתר של הוועדה המקומית ופרסום, ולרוב לתקופה מוגבלת. שלוש החלופות האחרות מתארות שינויים תכנוניים שמתבצעים בתוכנית או בהקלה (חריגה מקו בניין, ניוד שטחים, תוספת יחידות דיור), לא שינוי בשימוש.', 'סעיף 1 לחוק התכנון והבנייה, התשכ"ה-1965 (הגדרת "שימוש חורג")', 23, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q24', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 24', 'האם חוק הגנת הדייר חל על בניינים שהם חלק ממשק חקלאי?', '["כן; אין הגבלה על השכרה בדמי מפתח.", "לא; שכירות בדמי מפתח מותרת רק בתוך יישובים עירוניים.", "כן; שכירות בדמי מפתח מותרת רק למטרות מגורים ומסחר.", "לא; חוק הגנת הדייר לא חל על בניינים שהם חלק ממשק חקלאי."]'::jsonb, 3, null, 'חוק הגנת הדייר [נוסח משולב] מוציא במפורש מתחולתו בניין או חלק מבניין שהוא חלק ממשק חקלאי, לצד חריגים נוספים (כמו מגרש פנוי ובניינים שנבנו או הושכרו אחרי המועדים שבחוק). לכן התשובה היא "לא", אבל מהטעם שבחלופה ד: החוק אינו חל, ולא בגלל הבחנה בין יישוב עירוני לכפרי (ב), שאינה קיימת בחוק. חלופות א ו-ג מניחות שהחוק חל ומתארות את היקפו, ושתיהן שגויות.', 'חוק הגנת הדייר [נוסח משולב], התשל"ב-1972 - הוראת התחולה וסייגיה', 24, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
