  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2023-07-q25', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2023, שאלה 25', 'יחיעם הוא מתווך מוסמך. יחיעם לקח לטיפולו בהתנדבות תיווך לזוג עולים חדשים. יחיעם לא תרגם את החוזה לשפה שהעולים מבינים ולא גילה להם על חריגת בנייה בנכס שמצא להם. בנסיבות המתוארות, האם יחיעם הפר את חוק המתווכים?', '["כן; אלא אם הצדדים הסכימו מראש ובכתב שהקונה לא ייחשב לקוח.", "לא; מתווך לא יכול לתת שירותי תיווך בהתנדבות.", "לא; לקוח של מתווך ייחשב רק מי שמשלם עבור התיווך.", "כן; בני הזוג מהווים לקוחות לכל דבר ועניין, גם כשהתיווך נעשה ללא תמורה."]'::jsonb, 3, null, 'חובות הנאמנות, ההגינות ומסירת המידע המהותי שבסעיף 8 לחוק המתווכים חלות על כל מי שהמתווך נטל על עצמו לשרת, ואינן מותנות בתשלום דמי תיווך; חריגת בנייה היא מידע מהותי מובהק שהיה עליו לגלות. אין איסור על תיווך בהתנדבות (ב), והחוק אינו מגדיר לקוח לפי תשלום (ג). גם אי-הסברת העסקה בשפה שהלקוחות מבינים היא כשל בחובת ההגינות, אם כי תרגום החוזה עצמו אינו תפקידו של המתווך. תקנות האתיקה 2024 מחדדות: תקנה 6 מחייבת הסבר בשפה פשוטה ומובנת לפני חתימה, ותקנה 7 עם התוספת השנייה מחייבת לברר ולגלות חריגות בנייה.', 'סעיף 8 לחוק המתווכים במקרקעין, התשנ"ו-1996; תקנות 6 ו-7 לתקנות המתווכים (אתיקה וחובות מקצועיות), התשפ"ד-2024', 25, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2023-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'exam-2024-05', 'מבחן מאי 2024', 1, 'מועד אביב 2024 היה מבחן של חוק המקרקעין: שליש מהשאלות הגיעו ממנו, ועוד ארבע שאלות נשענו על פסקי דין שצוינו בשם בגוף השאלה. מי שלמד את הפסיקה המרכזית (רבינאי, סויסה, שמואלי, דוידסון) הרוויח כאן נקודות קלות.', '<p>25 שאלות, 4 נקודות לכל שאלה, ציון עובר 60. כך התחלקו השאלות לפי חוק (ספירה שלנו לפי הנושא המרכזי של כל שאלה):</p><ul><li><strong>חוק המקרקעין</strong> - 8 שאלות (הסכם שיתוף, חלקה תלת-ממדית, זכות קדימה בין בני זוג, זיקת הנאה, עסקאות סותרות, בית משותף פעמיים, והערת אזהרה על זיכרון דברים).</li><li><strong>חוק המתווכים במקרקעין ופסיקה עליו</strong> - 4 שאלות (הזמנה בדוא"ל, בלעדיות לפי שמואלי נ'' סמוכה, תיווך ללא רישיון לפי דוידסון, וחובת הגילוי לפי סויסה נ'' זאגה).</li><li><strong>חוק מיסוי מקרקעין</strong> - 3 שאלות (ניכוי דמי תיווך, מס רכישה על דירה על הנייר, ומקדמת מס שבח - שאלה שבוטלה וכל התשובות בה התקבלו).</li><li><strong>דיני חוזים</strong> (חוק החוזים, חוק התרופות וחוק החוזים האחידים) - 3 שאלות.</li><li><strong>חוק המכר (דירות) והבטחת השקעות</strong> - 2 שאלות (הערת אזהרה כבטוחה, תקופת הבדק).</li><li><strong>מקרקעי ישראל</strong> - 2 שאלות (דמי היוון, הסכם משבצת דו-צדדי).</li><li><strong>חוק הגנת הדייר</strong> - שאלה אחת (דייר ממשיך).</li><li><strong>חוק התכנון והבנייה</strong> - שאלה אחת (עבודות פטורות מהיתר).</li><li><strong>משכנתאות</strong> - שאלה אחת (גרירת משכנתה).</li></ul>', '["חוק המקרקעין הוא הנושא הכבד ביותר במועד הזה: 8 מתוך 25. בית משותף לבדו נתן שתי שאלות (דוד שמש על הגג, החלפת חברת ניהול).", "ארבע שאלות נקבו בשם פסק דין. הבחינה לא מצפה שתזכרו את המספר, אלא את ההלכה: רבינאי (זיכרון דברים מחייב), סויסה (חובת גילוי של מתווך), שמואלי נ'' סמוכה (דמי תיווך בבלעדיות), דוידסון (תיווך ללא רישיון הוא עבירה).", "מלכודת חוזרת: חלופה שמתארת כלל נכון מחוק אחר. בשאלה על ניכוי דמי תיווך, החריג של \"נסיבות מיוחדות\" קיים בחוק, אבל רק לדמי תיווך במכירה ולא ברכישה.", "מלכודת של מספרים: 5 חודשים מול 6 בחוק הגנת הדייר, 5 שנים בהסכם שיתוף, 3 שנים לחברת ניהול, 2% לניכוי דמי תיווך. הבחינה בודקת את המספר המדויק.", "שאלה 23 (מקדמת מס שבח) בוטלה על ידי הרשם וכל התשובות בה התקבלו. כשזה קורה, הנקודות ניתנות לכולם, ולכן אל תבזבזו זמן על שאלה שנראית לא פתירה."]'::jsonb, '[]'::jsonb, 'רשם המתווכים במקרקעין, מועד 09.05.2024, גרסה 1', null, false, true
  from public.course_chapters c where c.slug = 'past-exams'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q01', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 1', 'מתווך שלח הזמנה לביצוע פעולת תיווך ללקוח באמצעות דואר אלקטרוני, הכוללת את כל הפרטים הנדרשים ואת חתימתו. הלקוח לא חתם על ההזמנה, אולם שלח הודעת דואר אלקטרוני כי הוא מאשר את ההתקשרות.
האם נכרת הסכם תיווך מחייב בין המתווך והלקוח? מדוע?', '["לא; אם הלקוח לא חתם על ההזמנה במקום המיועד לכך, לא נכרת הסכם מחייב.", "כן; ההסכם מחייב רק בתנאי שבמסמך ההזמנה מצוין כי אישור באמצעות שליחת דואר אלקטרוני יהווה תחליף לחתימה.", "כן; נכרת הסכם מחייב, משום שהתמלאו כל התנאים לכריתת חוזה כדין.", "לא; ההסכם מחייב רק אם המתווך מאשר לאחר מכן באמצעות דואר אלקטרוני כי הוא מאשר את העיסקה."]'::jsonb, 2, null, 'סעיף 9(א) לחוק המתווכים דורש הזמנה בכתב שהלקוח חתם עליה, והתקנות קובעות אילו פרטים חייבים להופיע בה. כאן ההזמנה כללה את כל הפרטים, והלקוח אישר אותה בהודעת דוא"ל משלו. לפי עמדת הרשם, אישור כזה הוא גמירות דעת בכתב שמזוהה עם הלקוח, ולכן דרישת הכתב והחתימה מתקיימת ונכרת הסכם מחייב (יש לכך תמיכה גם בפסיקה שהכירה בתכתובת אלקטרונית כמסמך בכתב). חלופה א'' מחמירה מדי (אין דרישה לחתימה דווקא "במקום המיועד"), וחלופות ב'' ו-ד'' ממציאות תנאים שאינם בחוק.', 'סעיף 9(א) לחוק המתווכים במקרקעין, התשנ"ו-1996; תקנות המתווכים במקרקעין (פרטי הזמנה בכתב), התשנ"ז-1997; חוק חתימה אלקטרונית', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q02', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 2', 'אדם נדרש לשלם דמי היוון עבור שימוש בקרקע שבבעלות המדינה.
למי מהבאים עליו לשלם את דמי ההיוון?', '["רשות מקרקעי ישראל.", "מיסוי מקרקעין.", "מועצה מקומית.", "לשכת רישום המקרקעין."]'::jsonb, 0, null, 'מקרקעי ישראל (קרקעות המדינה, רשות הפיתוח וקק"ל) מנוהלים על ידי רשות מקרקעי ישראל, והיא זו שמחכירה אותם וגובה דמי חכירה. דמי היוון הם תשלום מראש של דמי החכירה השנתיים לכל תקופת החכירה, ולכן משולמים לרמ"י. מיסוי מקרקעין גובה מס שבח ומס רכישה, המועצה המקומית גובה ארנונה והיטלים, ולשכת רישום המקרקעין (הטאבו) רושמת זכויות וגובה אגרות רישום בלבד.', 'חוק יסוד: מקרקעי ישראל; חוק רשות מקרקעי ישראל, התש"ך-1960', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q03', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 3', 'שותפים רכשו ביחד קרקע מוסדרת (להלן: "המגרש"). בשנת 2015 חתמו השותפים על הסכם שיתוף בקשר למגרש. השותפים מעוניינים לברר כעת מה מעמדו של הסכם השיתוף. ההסכם קבע הוראה אחת ויחידה, לפיה שותף אינו רשאי לעשות בחלקו במגרש עיסקה אחרת ללא הסכמת השותפים האחרים.
בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["ההסכם לא תקף כלפי צדדים שלישיים.", "ההסכם תקף, בתנאי שנרשמה זכות קדימה על פי ההסכם.", "ההסכם תקף, בתנאי שנרשמה זכות קדימה בין יורשים.", "ההסכם בין הצדדים אינו תקף."]'::jsonb, 3, null, 'סעיף 34(א) לחוק המקרקעין קובע שכל שותף רשאי להעביר את חלקו או לעשות בו עסקה בלי הסכמת השותפים, וסעיף 34(ב) מוסיף שתניה בהסכם שיתוף השוללת או מגבילה זכות זו אין כוחה יפה לתקופה העולה על חמש שנים. ההסכם נחתם ב-2015, הבחינה נערכת ב-2024, וההסכם כולל הוראה אחת בלבד, שהיא בדיוק ההגבלה הזו. לכן ההסכם כולו פקע ואינו תקף. חלופה א'' עוסקת בתוקף כלפי צדדים שלישיים (שתלוי ברישום לפי סעיף 29), אך השאלה היא על מעמד ההסכם בין השותפים עצמם; זכות קדימה (חלופות ב'' ו-ג'') כלל לא נקבעה בהסכם.', 'סעיף 34(ב) לחוק המקרקעין, התשכ"ט-1969', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q04', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 4', 'האם ניתן לרשום דירה בבית משותף כחלקה תלת-מימדית?', '["לא; דירה בבית משותף יש לרשום בפנקס הבתים המשותפים, ואין תוקף לעיסקה בחלק מסוים במקרקעין.", "כן, ניתן לרשום דירה בבית משותף כחלקה תלת-מימדית.", "לא ניתן לרשום דירה בבית משותף כחלקה תלת-מימדית, אולם ניתן לרשום כחלקה תלת-מימדית את כל הבית המשותף.", "כן, משום שכל דירה היא תלת מימדית."]'::jsonb, 2, null, 'תיקון חוק המקרקעין משנת 2018 הוסיף את מושג החלקה התלת-ממדית: חלקה שגבולותיה מוגדרים גם לגובה ולעומק ולא רק על פני הקרקע, והיא נרשמת כיחידת רישום נפרדת (למשל מנהרה או קומת מסחר מתחת לכביש). דירה בבית משותף אינה חלקה אלא יחידה בתוך בית משותף, והיא נרשמת בפנקס הבתים המשותפים לפי צו הרישום של הבית; הבית המשותף כולו, לעומת זאת, יכול להירשם על חלקה תלת-ממדית. חלופה א'' מערבבת בין איסור העסקה בחלק מסוים (סעיף 13) לבין שאלת הרישום, וחלופה ד'' מבלבלת בין המציאות הפיזית לבין מושג רישומי.', 'חוק המקרקעין, התשכ"ט-1969 (חלקה תלת-ממדית, תיקון 2018; פרק הבתים המשותפים)', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q05', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 5', 'זוג נשוי הינו בעלים משותפים של נכס מקרקעין בו הם מנהלים במשותף עסק מסחרי. לאחרונה נקלעו יחסיהם למשבר, והבעל רוצה להעביר את חלקו בנכס, ללא תמורה, לחברו. האישה טוענת כי על הבעל להציע לה תחילה לרכוש את חלקו.
בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["האישה צודקת; יש לה זכות קדימה לגבי חלקו של הבעל בנכס.", "האישה צודקת; בן זוג לא יכול להעביר נכס המשמש לעסק משותף עם בן הזוג השני, אלא באישור בית המשפט.", "האישה טועה; אין לה זכות קדימה בעסק, אלא רק בדירת מגורים משותפת.", "האישה טועה, מכיוון שלא רשמה הערת אזהרה לגבי זכותה."]'::jsonb, 0, null, 'סעיף 101 לחוק המקרקעין קובע זכות קדימה מכוח החוק בין בני זוג: במקרקעין שבבעלות משותפת של בני זוג, שהם משק חקלאי, בית עסק המתנהל על ידי שניהם או דירת מגוריהם, בן זוג אינו רשאי להעביר את חלקו לאחר אלא אם הציע אותו תחילה לבן זוגו. זכות הקדימה הזו אינה טעונה רישום והיא חלה גם על העברה ללא תמורה. חלופה ג'' שגויה כי החוק מונה במפורש גם בית עסק משותף, לא רק דירת מגורים; חלופה ב'' ממציאה דרישת אישור בית משפט; וחלופה ד'' שגויה כי זכות הקדימה בסעיף 101 קיימת מכוח החוק עצמו.', 'סעיף 101 לחוק המקרקעין, התשכ"ט-1969', 5, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q06', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 6', 'דוד פנה ליזם אשר משווק פרוייקט חדש למגורים. דוד התקשר בהסכם מכר עם היזם לרכישת דירה "על הנייר" בפרוייקט. דוד החליט לשלם כבר עכשיו, ביום חתימת ההסכם, 100% ממחיר התמורה. הערובה בהסכם המכר הינה ערבות בנקאית של בנק מלווה לאחר תשלום מלוא התמורה. לפני הבנייה מבקש היזם לרשום הערת אזהרה לטובת דוד במקום ערבות של הבנק.
בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["בקשת היזם הינה בניגוד לחוק. הערת אזהרה אינה ערובה מותרת לפי החוק. היזם נדרש היה להמציא ערבות בנקאית או פוליסת ביטוח לטובת דוד.", "בקשת היזם הינה בניגוד לחוק. הערת אזהרה היא אמנם ערובה מותרת לפי החוק, אך במקרה כזה, יש להשלים את הבנייה כדין ולמסור חזקה בנכס תחילה.", "בקשת היזם הינה בהתאם לחוק. הערת אזהרה הינה ערובה מקובלת לפי החוק.", "בקשת היזם הינה בהתאם לחוק, אך במקרה שבו התמורה משולמת במלואה במעמד חתימת ההסכם, נדרש לקבל אישור מהממונה על חוק המכר."]'::jsonb, 1, null, 'סעיף 2 לחוק המכר (דירות) (הבטחת השקעות של רוכשי דירות) מונה חמש בטוחות שמוכר רשאי להבטיח בהן כספים מעבר ל-7% מהמחיר: ערבות בנקאית, פוליסת ביטוח, משכנתה ראשונה, הערת אזהרה ורישום הבעלות על שם הקונה. שלוש האחרונות, ובהן הערת אזהרה, מותרות לפי החוק רק לאחר שהושלמה בניית הדירה ונמסרה החזקה בה לקונה, כי לפני כן אין נכס מוחשי שההערה מגינה עליו. כאן הבנייה טרם החלה, ולכן הבקשה לרשום הערת אזהרה במקום ערבות מנוגדת לחוק. חלופה א'' שגויה כי הערת אזהרה כן מופיעה ברשימת הבטוחות; חלופה ד'' ממציאה הליך אישור שאינו קיים.', 'סעיף 2 לחוק המכר (דירות) (הבטחת השקעות של רוכשי דירות), התשל"ה-1974', 6, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q07', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 7', 'עידו רכש דירה בסיוע מתווך. בהתאם לסיכום בין עידו למתווך, שילם עידו דמי תיווך בשיעור של 3% מסכום העיסקה. עידו מבקש למכור היום את הדירה ומבקש לנכות את סכום דמי התיווך ששילם בעת הרכישה, וזאת על מנת להפחית את החבות במס שבח.
האם רשאי עידו לעשות כך?', '["עידו רשאי לנכות את דמי התיווך במלואם.", "עידו רשאי לנכות עד 2% מסכום התמורה של רכישת הדירה.", "עידו אינו רשאי לנכות דמי תיווך במקרה המתואר.", "עידו רשאי לנכות את דמי התיווך במלואם, בכפוף לכך שפקיד רשות המיסים שוכנע שנסיבות העיסקה המיוחדות שהוסברו לו, הצדיקו תשלום דמי תיווך גבוהים יותר."]'::jsonb, 1, null, 'סעיף 39 לחוק מיסוי מקרקעין מונה את ההוצאות המותרות בניכוי לחישוב השבח. דמי תיווך ששילם המוכר בקשר לרכישת הזכות מותרים בניכוי עד 2% מהתמורה ששילם ברכישה (סעיף 39(7)), בלי חריג. החריג של "נסיבות מיוחדות" שהמנהל שוכנע בהן קיים רק לדמי תיווך ששולמו בקשר למכירה (סעיף 39(8)), ולכן חלופה ד'' היא המלכודת: היא מצטטת כלל אמיתי אבל מהפסקה הלא נכונה. עידו ינכה 2% ולא 3%.', 'סעיפים 39(7) ו-39(8) לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963', 7, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q08', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 8', 'משה פנה ליוסי, מתווך מקרקעין מוסמך, וביקש ממנו לפעול למכירת דירתו. יוסי החתים את משה על הסכם להזמנת שירותי תיווך, במסגרתו נקבעה תקופת בלעדיות, וכן נקבע כי יוסי יהיה זכאי לקבלת דמי תיווך במהלך תקופה זו, בין אם הדירה נמכרה באמצעותו ובין אם לאו. הדירה נמכרה במהלך תקופת הבלעדיות שלא באמצעות יוסי. משה סירב לשלם את דמי התיווך, לאחר שיוסי ביצע פעולות שיווק כדין.
לפי פסק הדין: ברע (ת"א) 2285/05 אבנר שמואלי נ'' דורון סמוכה, האם יוסי זכאי לדמי תיווך?', '["קיים הסכם מחייב בין הצדדים - יוסי זכאי לקבלת דמי תיווך ללא סייג.", "קיים הסכם מחייב בין הצדדים - יוסי זכאי לדמי תיווך, מכיוון שביצע את פעולות השיווק לצורך קידום המכירה.", "ההסכם אינו חוקי - יוסי לא יכול היה לקבוע בהסכם, כי יקבל דמי תיווך בין אם הדירה תימכר באמצעותו ובין אם לאו.", "ההסכם אינו חוקי - יוסי יכול היה לקבוע בהסכם כי יקבל דמי תיווך גם אם הדירה תימכר שלא באמצעותו, אולם היה צריך לקבוע דמי תיווך מופחתים במקרה כזה."]'::jsonb, 1, null, 'סעיף 9(ב) לחוק המתווכים מתיר הסכם בלעדיות, וסעיף 14(ב) קובע שאם הנכס נמכר בתקופת הבלעדיות, חזקה שהמתווך היה הגורם היעיל לעסקה, ובלבד שביצע את פעולות השיווק שנקבעו בתקנות. בעניין שמואלי נ'' סמוכה נקבע ברוח זו שמתווך בבלעדיות שפעל לשיווק הנכס זכאי לדמי תיווך גם כשהמכירה לא נעשתה דרכו. הזכאות אינה "ללא סייג" (חלופה א''): היא מותנית בביצוע פעולות השיווק, ואם המתווך ישב בחוסר מעש, החזקה לא תעמוד לו. חלופות ג'' ו-ד'' שגויות כי תניה כזו היא בדיוק מהות הבלעדיות שהחוק מכיר בה.', 'סעיפים 9(ב) ו-14(ב) לחוק המתווכים במקרקעין, התשנ"ו-1996; תקנות המתווכים במקרקעין (פעולות שיווק), התשס"ה-2004; בר"ע (ת"א) 2285/05 שמואלי נ'' סמוכה', 8, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q09', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 9', 'דוד רכש דירה חדשה מיזם. לאחר שנה וחצי מיום קבלת החזקה בדירה, נתגלו בעיות וליקויים בדירה. דוד פנה אל היזם בדרישה לתיקון הליקויים.
האם היזם עדיין מחוייב לתיקון הליקויים בדירה?', '["תקופת הבדק היא שנה מיום מסירת הדירה, לכן אין חובה על היזם לתקן את הליקויים.", "תקופת הבדק היא עד שנתיים מיום מסירת הדירה, לכן קיימת חובה על היזם לתקן את הליקויים.", "תקופת הבדק משתנה בין ליקוי לליקוי ולכן יש לבחון את סוג הליקויים.", "תקופת הבדק היא עד שבע שנים מיום חתימת הסכם המכר. לכן, יש לבחון מתי נחתם הסכם המכר והאם חלפה תקופת הבדק."]'::jsonb, 2, null, 'סעיף 4 לחוק המכר (דירות) והתוספת לחוק קובעים תקופת בדק שמתחילה במסירת הדירה לקונה, ואורכה תלוי בסוג הליקוי: משנה אחת (למשל צנרת, חיפויים ונגרות) ועד שבע שנים (למשל קורוזיה בצנרת ורטיבות מסוימת), ולליקוי יסודות ושלד אין הגבלה. אחרי תקופת הבדק באה תקופת אחריות של שלוש שנים נוספות שבה נטל ההוכחה עובר לקונה. לכן אי אפשר לענות על "שנה וחצי" בלי לדעת מהו הליקוי. חלופות א'' ו-ב'' נוקבות בתקופה אחידה שאינה קיימת, וחלופה ד'' מונה מיום החוזה במקום מיום המסירה.', 'סעיף 4 והתוספת לחוק המכר (דירות), התשל"ג-1973', 9, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q10', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 10', 'יערית רכשה דירה בבית משותף. יערית מעוניינת לשפץ את הדירה באופן יסודי.
בגין אילו מהעבודות הבאות יערית לא נדרשת לקבל היתר בנייה?', '["הוספת מרפסת בצד המזרחי של הדירה, שאינו צד חזיתי בבניין.", "הרחבת פתחי החלונות בדירה בחזית הפונה לרחוב.", "שינוי בחלוקת החדרים בדירה, כך שבמקום דירת 4 חדרים הדירה תשמש כדירת 5 חדרים.", "פיצול הדירה ל- 2 דירות קטנות בנות כ- 45 מ\"ר כל אחת, עם דלת כניסה נפרדת לכל דירה מחדר המדרגות."]'::jsonb, 2, null, 'סעיף 145 לחוק התכנון והבנייה דורש היתר לכל בנייה, הוספה או שינוי חיצוני, ותקנות העבודות הפטורות מהיתר פוטרות עבודות פנימיות שאינן נוגעות בשלד, במעטפת הבניין או במספר יחידות הדיור. חלוקה פנימית מחדש של הדירה באמצעות קירות פנים קלים, בלי לשנות את השטח או את החזית, היא עבודה כזו. הוספת מרפסת (גם בצד שאינו חזיתי) ושינוי פתחי חלונות בחזית משנים את מעטפת הבניין וטעונים היתר, ופיצול דירה לשתיים מוסיף יחידת דיור, שינוי שתמיד טעון היתר (וגם נבחן לפי התוכנית החלה).', 'סעיף 145 לחוק התכנון והבנייה, התשכ"ה-1965; תקנות התכנון והבנייה (עבודות ומבנים הפטורים מהיתר), התשע"ד-2014', 10, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q11', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 11', 'דביר שוחח עם חברו נדב, וסיפר לו כי הוא מחפש לרכוש דירה בנתניה. נדב נזכר כי יש לו חבר אשר מעוניין למכור דירה בנתניה. נדב הציע לדביר ולחברו (בעלי הדירה בנתניה), כי יקשר ביניהם תמורת דמי תיווך בשיעור 1% מהעיסקה. לנדב אין רישיון לעסוק בתיווך.
לפי פסק הדין ת.פ. 1224/06 מ"י נ'' דוידסון דניאל, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["העיסוק בתיווך ללא רישיון הוא עבירה פלילית.", "כל אדם רשאי לעסוק בתיווך במקרקעין, אך אם אין לו רישיון תיווך עליו לעדכן את הצדדים.", "כל אדם רשאי לעסוק בתיווך במקרקעין, בתנאי שהוא בעל רישיון תיווך או שהוא עובד אצל מתווך בעל רישיון.", "כל אדם רשאי לעסוק בתיווך במקרקעין, אף ללא רישיון תיווך, אך לא יהיה זכאי לדמי תיווך במקרה המתואר."]'::jsonb, 0, null, 'סעיף 2 לחוק המתווכים קובע שלא יעסוק אדם בתיווך במקרקעין אלא אם כן הוא בעל רישיון, והחוק מטיל על העובר על האיסור עונש פלילי. בעניין דוידסון הורשע נאשם שתיווך בלי רישיון, ובכך הובהר שהאיסור אינו רק שלילת הזכות לדמי תיווך אלא עבירה של ממש. חלופה ד'' מתארת תוצאה אזרחית נכונה (אין זכאות לדמי תיווך בלי רישיון) אבל מתעלמת מהפן הפלילי, ולכן אינה "הנכונה ביותר". חלופות ב'' ו-ג'' שגויות: גילוי לצדדים אינו מרפא את החסר, ועובד אצל מתווך חייב רישיון משלו כדי לעסוק בתיווך.', 'סעיף 2 לחוק המתווכים במקרקעין, התשנ"ו-1996 (והוראת העונשין שבחוק); ת"פ 1224/06 מדינת ישראל נ'' דוידסון', 11, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q12', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 12', 'זוג קשישים הינם בעלי קרקע חקלאית מזה שנים רבות. לאחרונה פנה אל בני הזוג מתווך והציע לרכוש מהם את הקרקע. המתווך לא סיפר לבני הזוג כי באותו מועד פורסמה כתבה בעיתון המקומי, לפיה הופקדה תוכנית מיתאר בוועדה המחוזית, שמשמעותה קידום הליך של שינוי יעוד הקרקע מייעוד חקלאי לייעוד למגורים. יש לציין כי המידע על כך היה נגיש לכול. זוג הקשישים, שלא היו מודעים לכך, חתמו על הסכם המכר עם המתווך, אולם יום למחרת החתימה על ההסכם גילו את המידע, ובהתאם לכך דורשים לבטל את החוזה.
לפי פסק דין ע"א 2469/06 רונן סויסה ואח'' נגד חברת זאגה ואח'', מה הדין?', '["בני הזוג זכאים לבטל את החוזה בשל הטעיה.", "בני הזוג זכאים לבטל את החוזה, משום שכל פרט לא נכון שנמסר בעיסקה מקנה זכות לביטול החוזה.", "בני הזוג אינם זכאית לבטל את החוזה, כי לא הקונה היטעה אותם.", "בני הזוג אינם זכאים לבטל את החוזה עקב הטעיה; המידע היה גלוי לכול והם היו יכולים לבדוק בעצמם את המצב התכנוני טרם המכירה."]'::jsonb, 0, null, 'סעיף 15 לחוק החוזים (חלק כללי) מאפשר ביטול חוזה שנכרת עקב הטעיה, ו"הטעיה" כוללת גם אי-גילוי של עובדה שלפי דין, נוהג או הנסיבות היה על הצד השני לגלותה. סעיף 8 לחוק המתווכים מטיל על מתווך חובת הגינות ומסירת כל מידע מהותי שבידו, וכשהמתווך הוא גם הקונה, חובת הגילוי מתעצמת. בעניין סויסה נ'' זאגה נקבע שמתווך שהסתיר מידע תכנוני מהותי הפר את חובותיו, והעובדה שהמידע היה זמין לציבור אינה פוטרת אותו (ולכן חלופה ד'' שגויה). חלופה ב'' מרחיבה מדי: רק הטעיה בעניין מהותי שגרמה להתקשרות מקנה זכות ביטול, לא "כל פרט". חלופה ג'' שגויה עובדתית: המתווך הוא הקונה.', 'סעיף 15 לחוק החוזים (חלק כללי), התשל"ג-1973; סעיף 8 לחוק המתווכים במקרקעין, התשנ"ו-1996; ע"א 2469/06 סויסה נ'' זאגה', 12, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q13', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 13', 'בחוזה שכירות דירה שנכרת בין משה לבין גילה, השוכרת, נקבע כי איחור במסירת הדירה לשוכרת יזכה אותה בסך של 100 ש"ח לכל יום איחור. משה איחר למסור את הדירה לגילה במשך חודשיים ולגילה נגרמו בשל האיחור נזקים כספיים גדולים וכן עוגמת נפש רבה.
בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["גילה רשאית לוותר על הפיצוי המוסכם ולתבוע את נזקיה הממוניים הריאליים.", "גילה זכאית לקבל את הפיצוי המוסכם בלבד ולא מעבר לכך.", "גילה זכאית לקבל את הפיצוי המוסכם וגם לתבוע כל נזק נוסף.", "גילה לא זכאית לוותר על הפיצוי המוסכם ולתבוע את נזקיה הממוניים הריאליים."]'::jsonb, 0, null, 'סעיף 15(א) לחוק החוזים (תרופות) מאפשר לצדדים לקבוע פיצוי מוסכם מראש בלי צורך בהוכחת נזק, וסעיף 15(ב) קובע שהסכם על פיצויים מוסכמים אינו גורע מזכות הנפגע לתבוע במקומם פיצויים רגילים לפי סעיפים 10 עד 14. כלומר הנפגעת בוחרת: הפיצוי המוסכם (100 ש"ח ליום, בלי להוכיח נזק) או הנזק הממשי שתוכיח, אך לא שניהם במצטבר על אותו נזק. לכן חלופה ג'' שגויה (כפל פיצוי), וחלופות ב'' ו-ד'' שוללות את זכות הבחירה שהחוק נותן במפורש.', 'סעיף 15(ב) לחוק החוזים (תרופות בשל הפרת חוזה), התשל"א-1970', 13, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q14', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 14', 'יעקב מכר את דירת המגורים שלו ללאה, וזאת באמצעות זיכרון דברים מחייב, המהווה חוזה לכל דבר. הצדדים לא ציינו בזיכרון הדברים מה יהיה מועד מסירת הדירה. הצדדים פנו לבית המשפט בעניין הפרט החסר בזיכרון הדברים.
על פי מה ישלים בית המשפט את הפרט החסר של מועד מסירת הדירה?', '["בית משפט לא משלים פרטים חסרים בחוזים.", "בית משפט ישלים את הפרטים החסרים בהתאם לשיקול דעתו.", "בית משפט ישלים פרטים לפי הנוהג הקיים בין הצדדים, או לפי הנוהג המקובל בחוזים מאותו סוג.", "בית המשפט ייאלץ לבטל את החוזה, כי אין אפשרות להשלים פרט מהותי כזה שלא סוכם במפורש בחוזה מקרקעין."]'::jsonb, 2, null, 'סעיף 26 לחוק החוזים (חלק כללי) קובע שפרטים שלא נקבעו בחוזה או על פיו יהיו לפי הנוהג הקיים בין הצדדים, ובאין נוהג כזה, לפי הנוהג המקובל בחוזים מאותו סוג. זהו מנגנון השלמה שבחוק, ולא שיקול דעת חופשי של השופט (חלופה ב''). חוזה שחסר בו פרט שאינו מהותי להסכמה עצמה אינו בטל (חלופה ד''), ובוודאי שבית המשפט משלים פרטים (חלופה א''). בפסיקה על זיכרון דברים (למשל רבינאי) נאמר במפורש שפרטים כמו מועד מסירה ניתנים להשלמה מכוח סעיף 26, ולכן היעדרם אינו שולל את תוקף החוזה.', 'סעיף 26 לחוק החוזים (חלק כללי), התשל"ג-1973', 14, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q15', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 15', 'משה, המתווך, החתים את יגאל על הזמנה לביצוע פעולת תיווך, למכירת דירתו. בנוסח ההזמנה, שהוכן מראש על ידי המתווך, נקבע כי הסכם המכר עם הרוכשים ייערך אך ורק על ידי עורך דין לוי.
בהנחה שנוסח ההזמנה עונה להגדרת "חוזה אחיד", האם הסעיף שקבע כי עריכת הסכם המכר תיערך רק ע"י עו"ד לוי הוא סעיף תקף?', '["חזקה שמדובר בתנאי מקפח בחוזה אחיד ולכן יתכן שבית המשפט יבטל את הסעיף.", "מדובר בתנאי מקובל הנוגע לשיתוף פעולה בין מתווך לעורך דין ולכן הסעיף תקף.", "מדובר בתנאי מקפח רק אם המתווך מקבל עמלה מעורך הדין.", "מדובר בסעיף שיגאל היה מודע לקיומו ולכן הסעיף תקף."]'::jsonb, 0, null, 'סעיף 3 לחוק החוזים האחידים מאפשר לבית המשפט לבטל או לשנות תנאי מקפח בחוזה אחיד, וסעיף 4 מונה תנאים שחזקה עליהם שהם מקפחים, ובהם תנאי המחייב את הלקוח באופן בלתי סביר להיזקק לספק או לאדם אחר, או המגביל את חופש הלקוח להתקשר עם אדם אחר. תניה שכופה על המוכר עורך דין מסוים היא בדיוק כזו, ולכן קמה חזקת קיפוח, והנטל על המתווך לסתור אותה. קבלת עמלה (חלופה ג'') היא שיקול לחומרה אך אינה תנאי לקיפוח, ומודעות הלקוח (חלופה ד'') אינה מרפאת תנאי מקפח בחוזה אחיד. היום גם תקנה 12 לתקנות האתיקה (תשפ"ד-2024) אוסרת על מתווך להתנות שירותי תיווך ברכישת שירות אחר.', 'סעיפים 3 ו-4 לחוק החוזים האחידים, התשמ"ג-1982; תקנה 12 לתקנות המתווכים במקרקעין (אתיקה וחובות מקצועיות), התשפ"ד-2024', 15, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q16', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 16', 'בין כפיר, בעל מגרש, לבין אריאל, נכרת חוזה המעניק לאריאל זכות מעבר במגרש של כפיר (להלן: "הזכות"). אריאל מעוניין למכור את הזכות לשחר.
בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["בהיעדר הוראה אחרת בחוזה, על אריאל לקבל את הסכמתו של כפיר למכירה.", "אריאל רשאי למכור את הזכות לשחר, שכן הוא בעל הזכות.", "אריאל אינו רשאי למכור את הזכות, אלא אם השתמש בה בעצמו לפחות 30 שנה.", "אריאל רשאי למכור את הזכות רק באישור בית המשפט."]'::jsonb, 0, null, 'זכות מעבר במקרקעין של אחר היא זיקת הנאה (סעיף 92 לחוק המקרקעין): שעבוד של מקרקעין להנאה שאין עמה זכות להחזיק בהם. זיקת הנאה יכולה להיות לטובת מקרקעין (ואז היא עוברת יחד איתם) או לטובת אדם, כמו כאן, לטובת אריאל אישית. זיקת הנאה לטובת אדם אינה ניתנת להעברה אלא בהסכמת בעל המקרקעין הכפופים, אלא אם נקבע אחרת בתנאי הזיקה. לכן אריאל זקוק להסכמת כפיר. חלופה ג'' מבלבלת עם זיקת הנאה מכוח שנים (30 שנות שימוש יוצרות זיקה, אך אינן תנאי להעברתה), וחלופה ד'' ממציאה דרישת אישור בית משפט.', 'חוק המקרקעין, התשכ"ט-1969, פרק זיקת ההנאה (סעיף 92 ואילך)', 16, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q17', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 17', 'דני התחייב להשכיר לדינה את דירתו למשך שנה. דינה שילמה לו את שכר הדירה לשנה מראש. כעבור יום, ובטרם קיבלה דינה את החזקה בדירה, התחייב דני להשכיר את הדירה ליפית. יפית שילמה לדני שכר דירה לשנה מראש ואף קיבלה חזקה בדירה.
מה הדין?', '["אם יפית לא ידעה על ההתחייבות הקודמת לדינה, זכותה של יפית תגבר על זכותה של דינה.", "זכותה של דינה גוברת, שכן היא בעלת התחייבות קודמת לזו של יפית.", "זכותה של יפית גוברת, רק אם רשמה הערת אזהרה.", "זכותה של יפית גוברת, כי כבר שילמה מראש את מלוא דמי השכירות."]'::jsonb, 0, null, 'סעיף 9 לחוק המקרקעין מסדיר עסקאות סותרות: זכותו של בעל העסקה הראשונה עדיפה, אלא אם השני פעל בתום לב ובתמורה והעסקה לטובתו נרשמה בעודו בתום לב. שכירות לתקופה של עד חמש שנים אינה טעונה רישום (סעיף 79), ולכן העסקה בה "מושלמת" במסירת החזקה ולא ברישום. יפית שילמה תמורה וקיבלה חזקה, ואם לא ידעה על דינה היא גם בתום לב, ולכן זכותה גוברת. חלופה ב'' מתעלמת מהחריג שבסעיף 9; חלופה ג'' דורשת הערת אזהרה בשכירות קצרה שאינה טעונה רישום; וחלופה ד'' מזהה את ההכרעה בתשלום בלבד, בעוד שתום הלב והחזקה הם שמכריעים.', 'סעיפים 9 ו-79 לחוק המקרקעין, התשכ"ט-1969', 17, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q18', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 18', 'רוני מתגורר בבית משותף ומעוניין להתקין על גג הבית המשותף, המהווה רכוש משותף, דוד לחימום מים על ידי השמש. הגג לא משמש את הדיירים לשום מטרה. רוני קיבל היתר להתקנה לפי חוק התכנון והבנייה. גג הבניין קטן ורק מחצית מהדיירים יוכלו להתקין דודים בדומה לרוני.
בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["על רוני לקבל את הסכמת כל בעלי הדירות האחרים, טרם התקנת הדוד.", "על רוני לקבל את הסכמת רוב בעלי הדירות, טרם התקנת הדוד.", "רוני רשאי לבצע את ההתקנה ללא הסכמת כל בעלי הדירות, כי ממילא הגג לא שימש לכל מטרה אחרת ומכיוון שקיבל לכך היתר.", "רוני רשאי לבצע את ההתקנה בהסכמת נציגות הבית המשותף בלבד."]'::jsonb, 0, null, 'הגג הוא רכוש משותף, וכל בעלי הדירות שותפים בו. חוק המקרקעין מתיר לבעל דירה להתקין על הגג המשותף מיתקן לחימום מים בשמש בלי הסכמת השאר רק כשהגג מספיק כדי שכל בעלי הדירות יוכלו להתקין מיתקן כמוהו; כשהגג קטן ורק חלק מהדיירים יוכלו ליהנות ממנו, ההתקנה היא בפועל הקצאה של חלק מהרכוש המשותף לשימושו הבלעדי של אחד, ודבר כזה טעון הסכמת כל בעלי הדירות. היתר הבנייה (חלופה ג'') עוסק ביחסים מול רשויות התכנון ואינו מסדיר את היחסים בין השותפים ברכוש המשותף; נציגות הבית (חלופה ד'') מנהלת את הרכוש המשותף אך אינה מוסמכת להקצות ממנו.', 'חוק המקרקעין, התשכ"ט-1969, פרק הבתים המשותפים (הרכוש המשותף והתקנת מיתקן לחימום מים בשמש)', 18, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q19', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 19', 'בחוזה המכר בין קבלן לבין רוכשי הדירות בבית משותף נקבע כי הניהול וההחזקה של הרכוש המשותף יתבצעו למשך שש שנים מיום איכלוס הבניין על ידי חברת הניהול וההחזקה "דינדין" בע"מ.
בהתאם לתנאים הנ"ל, האם ניתן להחליף את חברת ההחזקה כעבור שנתיים מאכלוס הבניין?', '["לא ניתן להחליף את חברת ההחזקה עד שלוש שנים מיום תחילת הניהול וההחזקה.", "ניתן להחליף את חברת ההחזקה, מכיוון שמדובר בתנייה מקפחת בחוזה אחיד.", "ניתן להחליף את חברת ההחזקה בהחלטה של רוב בעלי דירות שיש להם 2/3 מהרכוש המשותף הצמוד לבתיהם.", "לא ניתן להחליף את חברת ההחזקה, כי החלפת החברה תהווה הפרת חוזה שתקף לשש שנים מול הקבלן."]'::jsonb, 0, null, 'חוק המקרקעין מגביל את כוחו של הקבלן לכבול את רוכשי הדירות לחברת ניהול שהוא בחר: התקשרות עם מתחזק שנקבעה בחוזה המכר מחייבת את בעלי הדירות לתקופה שאינה עולה על שלוש שנים מתחילת הניהול, ומעבר לה בעלי הדירות חופשיים להחליט על המתחזק באסיפה הכללית. לכן תניית שש השנים תקפה רק לשלוש שנים, ואחרי שנתיים עדיין אי אפשר להחליף. חלופה ד'' מתעלמת מהמגבלה שבחוק, חלופה ב'' מפנה לחוק החוזים האחידים כשיש הסדר ספציפי בחוק המקרקעין, וחלופה ג'' מערבבת רוב של 2/3 מהסדרים אחרים בבית משותף.', 'חוק המקרקעין, התשכ"ט-1969, פרק הבתים המשותפים (ניהול על ידי מתחזק שנקבע בחוזה המכר - הגבלה לשלוש שנים)', 19, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q20', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 20', 'מנחם, בעלים של דירה, חתם על זיכרון דברים למכירת דירתו לקונה. הקונה שילם למנחם באותו מעמד מקדמה על חשבון העיסקה.
בזיכרון הדברים הופיעו עיקרי העיסקה ונכתב בו כי "חוזה מפורט ייערך בעוד שבוע".
בהתאם לפסק דין ע"א 158/77 חוה רבינאי נ'' חברת מן השקד בע"מ (בפירוק), האם רשאי הקונה לבקש רישום הערת אזהרה על סמך זיכרון הדברים?', '["הקונה זכאי לכך, מכיוון שזיכרון הדברים עומד בדרישת הכתב שבסעיף 8 לחוק המקרקעין ומהווה התחייבות לעשות עיסקה.", "הקונה זכאי לרישום הערת אזהרה, מכיוון ששילם מקדמה על חשבון התמורה.", "הקונה אינו זכאי לרישום הערת אזהרה ללא הסכמת המוכר.", "הקונה אינו זכאי לרישום הערת אזהרה, שכן בין השניים נכרת זיכרון דברים בלבד ולא נכרת חוזה מחייב."]'::jsonb, 0, null, 'בעניין רבינאי נ'' מן השקד קבע בית המשפט העליון שזיכרון דברים הוא חוזה מחייב כשמתקיימים בו שני מבחנים: גמירות דעת של הצדדים להתקשר כבר עכשיו, והסכמה על הפרטים המהותיים (הנוסחה המקשרת: "חוזה מפורט ייערך" אינה שוללת גמירות דעת כשעיקרי העסקה סוכמו). זיכרון דברים כזה עומד בדרישת הכתב של סעיף 8 לחוק המקרקעין, ולכן הוא התחייבות לעשות עסקה במקרקעין, שעל פיה ניתן לרשום הערת אזהרה לפי סעיף 126. הקונה רשאי לבקש את הרישום על סמך המסמך עצמו, בלי הסכמה נוספת של המוכר (חלופה ג''). המקדמה (חלופה ב'') היא ראיה לגמירות דעת, אך אינה כשלעצמה הבסיס לרישום.', 'סעיפים 8 ו-126 לחוק המקרקעין, התשכ"ט-1969; ע"א 158/77 רבינאי נ'' מן השקד', 20, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q21', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 21', 'שלמה שכר דירת מגורים כדייר מוגן בדמי מפתח, ונפטר. לשלמה בת זוג, אשר התגוררה עימו במשך 5 חודשים בסמוך לפטירתו. בנוסף, הוא הותיר שלושה ילדים. דני, אחד מילדיו, התגורר עימו בדירה למשך שנה בסמוך לפטירתו. בת הזוג ושלושת הילדים מעוניינים להמשיך בשכירות המוגנת.
מי מהם זכאי להמשיך את הזכות לשכירות המוגנת?', '["עם פטירתו של שלמה אף אחד מהם לא זכאי לכך; הזכות לדייר מוגן בדמי מפתח היא אישית, ולכן פוקעת עם פטירתו.", "בת הזוג לא זכאית, משום שהיה עליה להיות בת זוגו ולהתגורר עימו לפחות 6 חודשים בסמוך לפטירתו על מנת שתהפוך לדיירת. שלושת הילדים זכאים לכך.", "בת הזוג זכאית ראשונה, ואם היא מוותרת על זכות הדיור, אזי שלושת הילדים יהיו לדיירים. במקרה כזה, לילדים תינתן זכות הבחירה האם להתגורר יחדיו או למכור את זכות השכירות.", "רק דני זכאי להמשיך את הזכות לשכירות המוגנת."]'::jsonb, 3, null, 'סעיף 20 לחוק הגנת הדייר קובע מי נעשה דייר בדירה עם פטירת הדייר המוגן: בן הזוג, בתנאי שהתגורר עמו לפחות שישה חודשים סמוך לפטירה; ובאין בן זוג כזה, ילדי המנוח, ובאין ילדים קרוביו האחרים, ובלבד שהתגוררו עמו בדירה לפחות שישה חודשים סמוך לפטירתו. בת הזוג גרה עמו חמישה חודשים בלבד ולכן אינה עומדת בתנאי; מבין הילדים רק דני התגורר עמו (שנה), ולכן רק הוא זכאי. חלופה ב'' מתעלמת מכך שגם הילדים חייבים לעמוד בתנאי המגורים, וחלופה א'' מתעלמת מסעיף 20 כולו.', 'סעיף 20 לחוק הגנת הדייר [נוסח משולב], התשל"ב-1972', 21, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q22', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 22', 'דניאלה רכשה דירה מקבלן "על הנייר". הדירה תיבנה בעוד מספר שנים ותימסר לדניאלה לאחר סיום הבנייה וקבלת טופס 4.
האם דניאלה נדרשת לשלם מס רכישה לפי רכישת זכות במקרקעין או לפי רכישת דירת מגורים?', '["דניאלה תשלם מס רכישה לפי ערך הקרקע, מכיוון שהדירה עדיין לא בנויה.", "דניאלה תשלם מס רכישה לפי דירת מגורים, משום שמדובר בדירה שבנייתה טרם נסתיימה, ויש עימה התחייבות מצד המוכר לסיים את הבנייה.", "דניאלה תשלם מס רכישה לפי ערך הקרקע; הגדרת דירת מגורים היא שהדירה משמשת למגורים בפועל כעת או שימשה בעבר במשך 18 חודשים לפחות. מאחר שהדירה עדיין לא נבנתה, היא לא עונה להגדרת דירת מגורים.", "דניאלה תשלם מס רכישה לפי דירת מגורים; תמיד מחשבים את ערך הקרקע כשהיא בנויה."]'::jsonb, 1, null, 'לעניין מס רכישה, סעיף 9(ג) לחוק מיסוי מקרקעין מגדיר "דירת מגורים" כדירה המשמשת או מיועדת לשמש למגורים, ובדירה שבנייתה טרם נסתיימה, בתנאי שיש עמה התחייבות מצד המוכר לסיים את הבנייה. רכישה מקבלן "על הנייר" כוללת התחייבות כזו, ולכן המס מחושב לפי מדרגות מס הרכישה לדירת מגורים, על מלוא התמורה. חלופה ג'' מצטטת את ההגדרה של דירת מגורים לעניין מס שבח (ולא לעניין מס רכישה) ומוסיפה דרישת שימוש שאינה קיימת בהגדרה הזו, וחלופות א'' ו-ד'' ממציאות שיטת חישוב.', 'סעיף 9(ג) לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963', 22, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q23', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 23', 'דניאל חתם על הסכם לרכישת דירה. למוכר הדירה יש חבות במס שבח בגין מכירת הדירה. בהסכם המכר נקבע כי דניאל ישלם סך של 35% מהתמורה במעמד חתימת ההסכם וסך של 65% הנותרים בתוך 3 חודשים, בעת קבלת החזקה בדירה. עוד נקבע, כי המוכר ישלם את מס השבח, בהתאם לשומה עצמית שדיווחו לרשות המיסים באותו רגע. דניאל שילם למוכר את מלוא התמורה.
האם היה על דניאל לשלם מקדמה על חשבון תשלום מס שבח?', '["לא; מכיוון שתשלום מס שבח חל תמיד על המוכר.", "כן; דניאל צריך היה לשלם תשלום מקדמת מס שבח על חשבון התמורה בתוך 30 ימים.", "לא; המוכר צריך היה לשלם תשלום מקדמת מס שבח על חשבון התמורה בתוך 60 ימים.", "כן; דניאל צריך היה לשלם תשלום מקדמת מס שבח מתוך התשלום השני."]'::jsonb, 3, null, 'שאלה זו בוטלה על ידי הרשם: במפתח התשובות הרשמי נכתב "כל התשובות מתקבלות", וכל נבחן קיבל עליה את הנקודות. לגופו של עניין, סעיף 15 לחוק מיסוי מקרקעין מטיל על הרוכש להעביר למנהל מקדמה על חשבון מס השבח של המוכר (7.5% או 15% מהתמורה, לפי מועד רכישת הנכס בידי המוכר), וזאת מתוך התשלומים שמעבר ל-40% מהתמורה, כלומר כאן מתוך התשלום השני. לכן חלופה ד'' היא הקרובה ביותר לדין. חלופה א'' שגויה כי החובה להעביר מקדמה מוטלת על הרוכש גם כשהמס עצמו חל על המוכר. ככל הנראה השאלה בוטלה משום שהעובדה שהמוכר הגיש שומה עצמית פותחת פתח לפטור מהמקדמה או להקטנתה, ולכן לא הייתה תשובה אחת חד-משמעית.', 'סעיף 15 לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963', 23, false
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q24', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 24', 'מהי גרירת משכנתה?', '["החלפת ההלוואה לנכס כנגד הלוואה מבנק אחר.", "החלפת זהות הלווה בנכס המשועבד ללווה אחר.", "החלפת ההלוואה לנכס כנגד הלוואה ממוסד חוץ בנקאי.", "החלפת הנכס המשועבד לבנק כבטוחה כנגד הלוואה, בנכס אחר."]'::jsonb, 3, null, 'גרירת משכנתה היא מצב שבו הלווה מוכר את הנכס המשועבד ורוכש נכס אחר, וההלוואה הקיימת נשארת באותם תנאים, אך הבטוחה "נגררת": השעבוד מוסר מהנכס הישן ונרשם על הנכס החדש. ההלוואה, הבנק והלווה נשארים אותם; רק הנכס המשועבד מתחלף. חלופות א'' ו-ג'' מתארות מחזור משכנתה (החלפת ההלוואה במלווה אחר), וחלופה ב'' מתארת העברת הלוואה ללווה אחר, שהיא הסבת חוב ולא גרירה.', 'חוק המשכון, התשכ"ז-1967 ופרק המשכנתה בחוק המקרקעין (מונח מתחום המשכנתאות הבנקאיות)', 24, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-05-q25', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2024, שאלה 25', 'מהו הסכם "משבצת דו צדדי"?', '["הסכם חכירה אשר נחתם בין רשות מקומית לאגודה שיתופית.", "הסכם חכירה אשר נחתם בין הסוכנות היהודית לאגודה שיתופית.", "הסכם חכירה אשר נחתם בין רשות מקרקעי ישראל לסוכנות היהודית.", "הסכם חכירה אשר נחתם בין רשות מקרקעי ישראל לאגודה שיתופית."]'::jsonb, 3, null, '"משבצת" היא שטח הקרקע החקלאית של יישוב שיתופי (מושב או קיבוץ), שרשות מקרקעי ישראל מחכירה לאגודה השיתופית של היישוב. הסכם משבצת דו-צדדי נחתם בין שני צדדים בלבד: רמ"י (בשם המדינה כבעלת הקרקע) והאגודה השיתופית. לעומתו, הסכם משבצת תלת-צדדי כולל גם את הסוכנות היהודית (או ההסתדרות הציונית) כגורם מיישב, ולכן חלופות ב'' ו-ג'' מתארות רק חלק מהצדדים להסכם התלת-צדדי. רשות מקומית (חלופה א'') אינה צד להסכמי חכירה של מקרקעי ישראל.', 'חוק יסוד: מקרקעי ישראל; חוק רשות מקרקעי ישראל, התש"ך-1960; החלטות מועצת מקרקעי ישראל בעניין הסכמי משבצת', 25, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'exam-2024-08', 'מבחן אוגוסט 2024', 2, 'מועד קיץ 2024 היה מבחן של פסיקה: שישה פסקי דין נשאלו בשמם ובמספרם, וחוק המקרקעין לבדו נתן שבע שאלות. מי שהכיר את גנז, רבינאי, דה כהן ושושני הרוויח כאן רבע מהציון בלי להתאמץ.', '<p>25 שאלות, 4 נקודות כל אחת, ציון עובר 60. החלוקה לפי חוקים (ספירה שלנו לפי הדין שמכריע את השאלה):</p><ul><li><strong>חוק המקרקעין</strong> - 7 שאלות (בעלות בעומק ובחלקה תלת-ממדית, שימוש של שותף במושע, הערת אזהרה, הצמדת מעלית בבית משותף, רישום שכירות עם אופציה, עסקאות נוגדות לפי הלכת גנז, הסכם שיתוף).</li><li><strong>חוק המתווכים במקרקעין ותקנותיו</strong> - 6 שאלות (תנאי הזכאות לדמי תיווך, גורם יעיל אחרי תום הבלעדיות, תיווך באמצעות תאגיד, דמי תיווך כשהחוזה בוטל, שיתוף פעולה בין מתווכים, מתווך שגבה הפרש מחיר בסתר).</li><li><strong>חוק מיסוי מקרקעין</strong> - 3 שאלות (דירת מגורים מזכה, מוכר אחד עם ילד קטין, חלוקת עיזבון).</li><li><strong>חוק החוזים (כללי ותרופות)</strong> - 3 שאלות (טעות סופר, הקטנת הנזק, זכרון דברים לפי הלכת רבינאי).</li><li><strong>חוק המכר (דירות) והבטחת השקעות</strong> - 2 שאלות (ערבות בנקאית ורכיב המע״מ, תקופת הבדק והאחריות).</li><li><strong>חוק הגנת הצרכן</strong> - שאלה אחת (חובת הגילוי של מתווכת).</li><li><strong>חוק הגנת הדייר</strong> - שאלה אחת (שותפות רשומה כדייר מוגן).</li><li><strong>חוק התכנון והבנייה</strong> - שאלה אחת (תוכנית בסמכות מחוזית שהוגשה לוועדה מקומית).</li><li><strong>ידע כללי בשמאות</strong> - שאלה אחת (מחירון דקל).</li></ul>', '["שישה פסקי דין נשאלו בשם ובמספר: נדב נ'' ינובסקי, דה כהן נ'' עמרם, רבינאי נ'' מן שקד, גנז נ'' בריטיש קולוניאל, שושני נ'' אברון, עוז נ'' עזרא. לכל אחד יש משפט אחד שצריך לזכור, והחלופות בנויות סביבו.", "הגורם היעיל חוזר פעמיים (שאלות 11 ו-20): הוא אחד משלושת תנאי סעיף 14 לחוק המתווכים, והוא גם מה שמזכה בדמי תיווך אחרי שהבלעדיות נגמרה. הבלעדיות לבדה אינה עילה.", "מלכודת החוזה שבוטל: דמי התיווך מגיעים ברגע שנכרת הסכם מחייב (והתנאי המתלה התקיים). הפרה וביטול אחר כך הם עניין שבין הצדדים לעסקה, לא בין הלקוח למתווך.", "חוק המקרקעין בפרטים הקטנים: אופציה נספרת לתקופת השכירות לצורך רישום, מעלית אינה ניתנת להצמדה, והערת אזהרה נרשמת גם לבקשת הקונה כשיש התחייבות בכתב.", "במיסוי מקרקעין, שלוש השאלות הוכרעו בהגדרות ולא בחישוב: מי הוא \"מוכר אחד\", מה הופך דירה ל\"מזכה\", ומתי חלוקת עיזבון אינה מכירה."]'::jsonb, '[]'::jsonb, 'רשם המתווכים במקרקעין, מועד 01.08.2024, גרסה 1', null, false, true
  from public.course_chapters c where c.slug = 'past-exams'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q01', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 1', 'יוסי פנה לחן, שהיא מתווכת במקרקעין, על מנת למצוא דירת מגורים. חן המתווכת הציגה ליוסי דירה, וציינה בפניו כי הדירה מתאימה לדרישותיו. חן ידעה כי בדירה קיימת רטיבות בחדר השינה, אך לא יידעה בכך את יוסי. יוסי רכש את הדירה. בדיעבד (לאחר רכישת הדירה), נודע ליוסי כי יש רטיבות בחדר השינה, וכי חן הייתה מודעת לליקוי. יוסי למד משיחות עם אנשי מקצוע בתחום, כי המדובר בליקוי שלא ניתן לתקן עקב שיפוע בגג, ומשיחה עם שמאי אף למד כי ליקוי שכזה מפחית באופן ניכר את שווי המכירה של הנכס.

לפי דיני הגנת הצרכן, האם חן הפרה את חובת הגילוי כלפי יוסי כצרכן?', '["כן, מכיוון שמדובר בפגם המפחית באופן משמעותי את ערך הנכס.", "לא, חוק הגנת הצרכן אינו חל על מתווך מקרקעין.", "לא, חובת הגילוי לפי חוק הגנת הצרכן חלה רק על מוצרים, ולא על מתן שירותים כגון שירותי תיווך.", "לא, מכיוון שחן מחויבת לחובת הגילוי ללקוח שבחוק המתווכים בלבד, ויוסי צריך לבדוק את הנכס בעצמו ולשקול בעצמו את כדאיות הרכישה בהתאם לכך."]'::jsonb, 0, null, 'חוק הגנת הצרכן חל על כל "עוסק", וההגדרה כוללת מי שנותן שירות, ולכן מתווכת היא עוסק והלקוח שלה הוא צרכן. סעיף 4 לחוק מטיל על העוסק חובה לגלות לצרכן כל פגם או תכונה שמפחיתים באופן משמעותי מערכו של הנכס או השירות, ורטיבות שאינה ניתנת לתיקון ומורידה את שווי הדירה היא בדיוק פגם כזה. חובת הגילוי שבחוק המתווכים (סעיף 8) אינה מחליפה את חוק הגנת הצרכן אלא מצטרפת אליו, ולכן חלופות ב, ג ו-ד שגויות.', 'סעיפים 1 ו-4 לחוק הגנת הצרכן, התשמ״א-1981; סעיף 8 לחוק המתווכים במקרקעין', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q02', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 2', 'לקוח פנה לעידו, מתווך במקרקעין, לקבלת שירותי תיווך. הצדדים סיכמו שאם עידו יאתר עבור הלקוח דירה מתאימה, ישלם הלקוח דמי תיווך בסך 2% מסכום התמורה. בעקבות האמור, חתם הלקוח על הסכם להזמנת שירותי תיווך במקרקעין מול עידו. בהסכם נפלה טעות סופר ונכתב כי ישולמו דמי תיווך בסך 20%, בתוספת מע״מ. הצדדים לא הבחינו בטעות שנרשמה בסכום. לאחר מאמץ משמעותי של עידו, הוא הצליח לאתר ללקוח דירה מתאימה, והלקוח חתם על הסכם לרכישת הדירה. כעת הגיע הזמן לשלם את דמי התיווך בהתאם להסכם, שמלבד הטעות האמורה לגבי הסכום, לא נפל בו פגם. הלקוח מצידו זועם על הטעות ומסרב לשלם דמי תיווך.

בנסיבות המתוארות, איזה מההיגדים הבאים הוא הנכון ביותר?', '["הלקוח צריך לשלם דמי תיווך בסך 20%, כפי שהועלה על הכתב ונחתם.", "על הלקוח לשלם 2% דמי תיווך. יש לתקן את החוזה לפי אומד דעת הצדדים, ובהתאם לכך הטעות לא מהווה עילה לביטול החוזה.", "הלקוח רשאי לבטל את החוזה כולו עקב הטעות שנפלה בכריתתו, מכיוון שהיא מהותית.", "הטעות מהווה סטייה משמעותית מדמי התיווך שסוכמו, ולכן לא ניתן לתקן את הטעות והחוזה בטל ומבוטל בהתאם."]'::jsonb, 1, null, 'סעיף 16 לחוק החוזים (חלק כללי) קובע שטעות סופר או טעות דומה בחוזה מתוקנת לפי אומד דעת הצדדים, ואינה עילה לביטול. הצדדים סיכמו 2%, ושניהם לא הבחינו שנכתב 20%, ולכן החוזה מתוקן ל-2% ועומד בתוקפו. חלופה א נתפסת לאות המתה של הכתוב, וחלופות ג ו-ד מבלבלות בין טעות סופר לבין טעות בכריתה לפי סעיף 14, שהיא טעות שמשפיעה על עצם ההסכמה.', 'סעיף 16 לחוק החוזים (חלק כללי), התשל״ג-1973', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q03', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 3', 'דניאל השכיר חנות שבבעלותו לחן. תקופת השכירות נקבעה על ידי הצדדים למשך ארבע שנים. בחוזה נכתב כי על חן השוכרת לשלם את דמי השכירות, בין אם היא משתמשת בנכס, ובין אם לאו. כעבור מספר חודשים מתחילת השכירות נקלעה חן לקשיים כלכליים, והפסיקה לשלם את דמי השכירות. חן פינתה את החנות, אך חיפשה ולא מצאה שוכר חלופי. דניאל מצידו נמנע מלהשכיר את החנות עד לתום תקופת השכירות, וזאת על אף שפנו אליו שוכרים רבים מתאימים, אשר רצו לשכור את החנות. אף אחד מהפונים לשכור את הנכס לא הסכים לשלם את אותם דמי שכירות ששילמה חן, או שהדרך שבה התלבשו לא מצאה חן בעיני דניאל. דניאל דורש מחן לשלם לו את דמי השכירות במלואם, לכל התקופה.

בנסיבות המתוארות, האם חן חייבת בתשלום דמי השכירות?', '["חן חייבת בתשלום דמי השכירות עד לתום תקופת השכירות. חן הייתה רשאית למצוא שוכר חלופי, שייכנס בנעליה ובמחדלה לא עשתה כן, כי לא מצאה שוכר מתאים.", "חן חייבת בתשלום דמי השכירות עד לתום מחצית מתקופת השכירות.", "חן לא חייבת בתשלום דמי השכירות שדורש דניאל, שכן דניאל יכול היה למנוע את הנזק או להקטינו באמצעים סבירים על ידי השכרת המקום לשוכר חלופי.", "חן לא חייבת בתשלום דמי שכירות מרגע שפינתה את החנות."]'::jsonb, 2, null, 'חן הפרה את החוזה, אבל הנפגע מהפרה חייב להקטין את נזקו: סעיף 14 לחוק החוזים (תרופות) קובע שהמפר אינו חייב בפיצויים בעד נזק שהנפגע יכול היה למנוע או להקטין באמצעים סבירים. דניאל דחה שוכרים מתאימים מטעמים שאינם סבירים (מחיר מעט נמוך יותר, לבוש), ולכן אינו יכול לגלגל על חן את דמי השכירות של כל התקופה. חלופה ד מרחיקה לכת לצד השני: הפינוי לבדו אינו פוטר שוכרת מחוזה שהפרה, וחלופה ב ממציאה כלל של מחצית שאינו קיים.', 'סעיף 14 לחוק החוזים (תרופות בשל הפרת חוזה), התשל״א-1970', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q04', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 4', 'דניאל הוא בעלים רשום כדין בטאבו של קרקע, שעליה התחיל בבנייה של וילה עבור משפחתו. כעת מדינת ישראל מעוניינת לקדם פרויקט ''מטרו'', שהוא פרויקט תחבורה תת קרקעי אשר יעבור מתחת לקרקע של דניאל.

האם דניאל הוא הבעלים של השטח שמתחת לחלקה שלו, והאם ניתן לפצל את הבעלות לקרקע ולשטח שמתחתיה?', '["הבעלות בשטח של קרקע מתפשטת בכל המימדים, לרבות העומק שמתחת לשטח הקרקע ובחלל הרום שמעליו, ואין לכך חריגים. לכן, לא ניתן לפצל את הבעלות מתחת לקרקע של דניאל ומעליה ברישום בטאבו.", "הבעלות בשטח של קרקע מתפשטת בחלל הרום שמעל הקרקע, אך לא בעומק שמתחת לשטח הקרקע. לכן מימד העומק שמתחת לשטח של קרקע אינו שייך לבעלים פרטיים ואינו רשום על שמם.", "העומק שמתחת לקרקע של דניאל שייך לו, אך ניתן להפרידו משאר החלקה ולרשום את החלק שמתחת לקרקעו של דניאל כחלקה תלת מימדית.", "אין כל אפשרות חוקית לקדם פרויקט ציבורי של המדינה בשטח הרשום כשטח פרטי."]'::jsonb, 2, null, 'סעיף 11 לחוק המקרקעין קובע שהבעלות בקרקע חלה גם על מה שמתחת לפני הקרקע ועל חלל הרום שמעליה, ולכן העומק שייך לדניאל וחלופה ב שגויה. אבל הכלל אינו בלי חריגים: תיקון לחוק המקרקעין בעניין מקרקעין תלת-ממדיים מאפשר להגדיר חלק מהחלקה לפי עומק או גובה ולרשום אותו כחלקה תלת-ממדית נפרדת, בדיוק לצורך פרויקטים תת-קרקעיים כמו המטרו. לכן חלופה א ("אין חריגים") שגויה, וחלופה ד מתעלמת גם מדיני ההפקעה.', 'סעיף 11 לחוק המקרקעין, התשכ״ט-1969; הוראות חוק המקרקעין בעניין מקרקעין תלת-ממדיים', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q05', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 5', 'שמעון ודניאל הינם בעלים בחלקים שווים ב"מושע" בקרקע פנויה. בין הצדדים אין הסכם שיתוף המסדיר את אופן השימוש של הצדדים בקרקע. שמעון לקח יוזמה, והפעיל לבדו במקום חניון, בהתאם לחוק, ברוב החלקה, והחניון הניב רווח נאה. דניאל לא התנגד ליוזמה. לאחר כשנה, דניאל דרש משמעון שישלם לו בעבור השימוש שעשה בקרקע.

האם שמעון צריך לשלם לדניאל תשלום כלשהו בגין השימוש שעשה בחלקה?', '["שמעון לא צריך לשלם כל תשלום, משום שעשה שימוש בשטח משותף והעסק הוא שלו בלבד.", "שמעון צריך לשלם דמי שימוש ראויים בהתאם לרווחים שהופקו מהשימוש בקרקע לחניון, וזאת בהתאם לחלקו היחסי של דניאל בקרקע.", "שמעון צריך לשלם אך ורק דמי שימוש ראויים בקרקע, ואין לדניאל זכות ברווחים של השכרת מקומות חניה, כי הוא עסק פרטי של שמעון.", "שמעון לא צריך לשלם כל תשלום שהוא; מכיוון שאין בין הצדדים הסכם שיתוף שמגדיר את חלקו של דניאל בקרקע, כל שותף יכול להשתמש בחלק בלתי מסוים בקרקע כרצונו."]'::jsonb, 1, null, 'סעיף 33 לחוק המקרקעין קובע ששותף שהשתמש במקרקעין המשותפים חייב ליתר השותפים, לפי חלקיהם, שכר ראוי בעד השימוש, וסעיף 35 מוסיף שכל שותף זכאי לחלק מפירות המקרקעין לפי חלקו. שמעון תפס לבדו את רוב החלקה והפיק ממנה רווח, ולכן דניאל זכאי לחלקו בהתאם לרווחים שהופקו. היעדר הסכם שיתוף (חלופה ד) אינו מבטל את זכויות השותף האחר אלא להפך, מחיל את ברירת המחדל שבחוק; וחלופה ג מנתקת שלא כדין בין השימוש לבין הפירות שהוא הניב.', 'סעיפים 33 ו-35 לחוק המקרקעין, התשכ״ט-1969', 5, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q06', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 6', 'פלוני חתם על הסכם מכר ללא עורכי דין, למכירת דירתו לאלמוני. הסכם המכר אינו קובע הוראות לעניין רישום הערת אזהרה על התחייבות לעשיית עיסקה. הדירה רשומה בפנקס הבתים המשותפים בלשכת רישום המקרקעין. אלמוני פנה לרשם המקרקעין בבקשה לרישום הערת אזהרה בגין הסכם המכר.

האם אלמוני יכול לרשום הערת אזהרה?', '["אין לאלמוני זכות לרשום הערת אזהרה. רק הבעלים הרשום יכול לרשום הערת אזהרה בגין מכירה, וזאת על מנת למנוע נוכלויות במקרקעין.", "אלמוני צריך להגיש לרשם המקרקעין את הסכמתו של פלוני לצורך רישום הערת האזהרה, שאז יוכל לרשום הערת אזהרה. ללא הסכמה שכזאת, לא תירשם הערת אזהרה.", "רשם המקרקעין ירשום הערת אזהרה לטובת אלמוני, בכפוף לכך שלהנחת דעתו הוכח שפלוני אכן התחייב בכתב לעשות עיסקה במקרקעין.", "הרשם אינו מוסמך לרשום הערת אזהרה לטובת אלמוני, ואפשר לרשום הערת אזהרה רק באמצעות בית משפט."]'::jsonb, 2, null, 'סעיף 126(א) לחוק המקרקעין קובע שכאשר בעל מקרקעין התחייב בכתב לעשות בהם עסקה, רשם המקרקעין ירשום הערת אזהרה על פי בקשת מי שהתחייב או על פי בקשת הזכאי לפי ההתחייבות, ובלבד שהוכח להנחת דעתו שההתחייבות נעשתה. כלומר הקונה עצמו רשאי לבקש את הרישום על סמך הסכם המכר החתום, בלי הסכמה נוספת של המוכר ובלי בית משפט. חלופות א, ב ו-ד מוסיפות דרישות שאינן בחוק.', 'סעיף 126(א) לחוק המקרקעין, התשכ״ט-1969', 6, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q07', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 7', 'שמעון רכש דירה חדשה מקבלן. הוראות הסכם המכר בין הצדדים קובעות כי הפרויקט יקבל ליווי בנקאי מטעם בנק גדול בישראל. שמעון שילם את התשלום הראשון באמצעות פנקס שוברים, וקיבל לידיו ערבות בנקאית. להפתעתו, הבחין שמעון שסכום הערבות שקיבל נמוך מהסכום ששילם על חשבון הדירה. שמעון פנה לבנק, ובבנק השיבו לו שסכום הערבות אינו אמור לכלול את רכיב המע״מ המשולם.

האם הבנק צודק? מדוע?', '["כן; הערבות הבנקאית לא אמורה לכלול את רכיב המע״מ בעיסקה.", "לא; הערבות הבנקאית אמורה לכלול את כל הסכום ששולם עפ״י פנקס השוברים.", "לא; הערבות הבנקאית אמורה לכלול את כל התשלום ששילם שמעון על דירתו ולהבטיח אותה.", "כן, אך רק בכפוף לכך שהקבלן הנפיק ערבות אישית לידי שמעון בגובה סכום המע״מ."]'::jsonb, 0, null, 'חוק המכר (דירות) (הבטחת השקעות של רוכשי דירות) מחייב את המוכר להבטיח את כספי הקונה באחת הבטוחות שבסעיף 2, והערבות הבנקאית היא הנפוצה שבהן. מאז תיקון החוק, הערבות הבנקאית מבטיחה את הכספים ששולמו למעט רכיב המע״מ, ורכיב המע״מ מובטח בנפרד על ידי המדינה, ולכן הבנק צודק וסכום הערבות נמוך מהסכום ששולם בשובר. חלופה ד ממציאה דרישה לערבות אישית של הקבלן שאינה בחוק.', 'סעיף 2 לחוק המכר (דירות) (הבטחת השקעות של רוכשי דירות), התשל״ה-1974', 7, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q08', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 8', '"מוגנים ונהנים" היא שותפות רשומה, אשר שוכרת בית עסק כדייר מוגן מאז שנות ה- 50 של המאה הקודמת. במהלך שנת 2023 עזב אחד השותפים את השותפות, ולשותפות הצטרף שותף חדש. בעל הנכס גילה זאת והודיע לשותפות כי מדובר בהפרה של כללי הדיירות המוגנת בישראל, ולכן על השותפות לפנות את הנכס.

האם בעל הנכס צודק? מדוע?', '["לא; דייר מוגן בעסק אינו יכול להחליף דייר מוגן אחר, אלא אם בעל העסק ביקש לרכוש את חלקו תחילה. מכיוון שבעל העסק לא עשה זאת, הוא טועה.", "כן; עזיבה של אחד השותפים בשותפות פוגעת בזכויות הדיירות המוגנת. יחד עם זאת, הצטרפות של שותף חדש לשותפות, מבלי לקבל את אישור בעל הנכס, שוללת את זכות הדיירות המוגנת.", "לא; עזיבה או הצטרפות של שותף לשותפות רשומה אינה פוגעת בזכויות הדיירות המוגנת.", "כן; פעילות השותפות הינה פעילות עסקית בנכס, ולכן היא שוללת את זכות הדיירות המוגנת. דיירות מוגנת נועדה למגורים בלבד."]'::jsonb, 2, null, 'הדייר המוגן כאן הוא השותפות הרשומה עצמה, שהיא אישיות משפטית נפרדת מהשותפים שבה. חילופי שותפים משנים את הרכב השותפות אך לא את זהות הדייר, ולכן אין כאן העברה של זכות הדיירות לאחר ואין עילת פינוי. חלופה ד שגויה מיסודה: חוק הגנת הדייר חל במפורש גם על בתי עסק, וחלופה א ממציאה זכות סירוב ראשונה שאינה קיימת בחוק.', 'חוק הגנת הדייר [נוסח משולב], התשל״ב-1972 - דייר מוגן שהוא תאגיד', 8, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
