insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q09', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 9', 'עידו ביקש למכור קרקע שבבעלותו. לצורך כך, התקשר עידו עם יוסי, מתווך במקרקעין, וביקש מיוסי לאתר קונה לקרקע. השניים חתמו על הסכם להזמנת שירותי תיווך. לאחר כשבוע התקשר יוסי לעידו והודיע לו, כי קיים קונה שהציע לרכוש את הזכויות בקרקע בתמורה לסך של 2,000,000 ש״ח. עידו הסכים, ובהתאם לכך נחתם הסכם מכר מקרקעין. עידו ביקש שלא להיות מעורב כלל בנושא, ולבוא רק לחתימה על הסכם המכר. בדיעבד גילה עידו שהקונה שילם בפועל עבור רכישת הזכויות סך כולל של 2,500,000 ש״ח, שמתוכם 500,000 ש״ח הגיעו אל המתווך יוסי ללא ידיעת עידו. עידו תבע את המתווך ודרש לקבל את ההפרש ששילם הקונה עבור הקרקע.

בהתאם לפסק הדין בעניין ע״א 3597/09 יואל נדב נ'' עו״ד דוד ינובסקי ואח'', מה דין הסכום הנוסף ששילם הרוכש בעבור הקרקע?', '["עידו הסכים למכור את זכויות בתמורה לסך של 2 מיליון ש״ח, ולכן אינו זכאי לקבלת תמורה נוספת.", "המתווך נדרש להשיב לעידו את ההפרש בסך 500,000 ש״ח.", "מדובר בדמי תיווך שהם עניין שבין המתווך לרוכש בלבד ולכן לא יקבל עידו סכום נוסף מהמתווך.", "בהתאם לפסיקת בית המשפט, אם ההפרש בין הסכום ששילם הרוכש לבין הסכום ששולם למתווך אינו עולה על 25% מסכום התמורה המקורי, המוכר אינו זכאי לקבלת סכום כלשהו."]'::jsonb, 1, null, 'מתווך חב ללקוחו חובת נאמנות, הגינות וגילוי (סעיף 8 לחוק המתווכים), ומתווך שמסתיר מהמוכר את המחיר האמיתי שהקונה מוכן לשלם ושולח את ההפרש לכיסו מפר אותה באופן בוטה. בעניין נדב נ'' ינובסקי נפסק שהכסף שהקונה שילם עבור הקרקע שייך למוכר, והמתווך חייב להשיב לו את ההפרש שגבה בסתר. חלופה ד ממציאה סף של 25% שאינו קיים, וחלופה ג מתעלמת מכך שהסכום שולם כתמורה לקרקע ולא כדמי תיווך מוסכמים.', 'סעיף 8 לחוק המתווכים במקרקעין, התשנ״ו-1996; ע״א 3597/09 נדב נ'' ינובסקי', 9, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q10', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 10', 'לוועדה המקומית לתכנון ובנייה תל אביב הוגשה תוכנית שבסמכות ועדה מחוזית לתכנון ובנייה.

כיצד צריכה הוועדה המקומית לפעול?', '["הוועדה המקומית צריכה להעביר את התוכנית לוועדה המחוזית.", "הוועדה המקומית צריכה לדון בתוכנית ולהעביר את המלצותיה לוועדה המחוזית, בתוך 30 ימים מיום שהוגשה לה התוכנית.", "הוועדה המקומית צריכה להחזיר את הבקשה למגישים ולהפנות את המגישים לוועדה הנכונה.", "הוועדה המקומית צריכה לדחות את הבקשה מחוסר סמכות."]'::jsonb, 1, null, 'לפי חוק התכנון והבנייה, תוכנית שבסמכות הוועדה המחוזית מוגשת דרך הוועדה המקומית, והוועדה המקומית אינה רק צינור: היא דנה בתוכנית ומעבירה את המלצותיה לוועדה המחוזית בתוך המועד שקבוע בחוק, ולפי מפתח הבחינה 30 ימים מיום ההגשה. אם לא דנה במועד, התוכנית עוברת לוועדה המחוזית גם בלי המלצה. הוועדה המקומית אינה רשאית לדחות או להחזיר תוכנית רק משום שאינה בסמכותה (חלופות ג ו-ד), וחלופה א מחסירה את חובת הדיון וההמלצה.', 'סעיף 62 לחוק התכנון והבנייה, התשכ״ה-1965', 10, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
