  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q11', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 11', 'מהם התנאים המינימליים לפי הדין, לצורך זכאות לדמי תיווך על ידי מתווך?', '["הסכם בלעדיות במסמך נפרד, היותו של המתווך הגורם היעיל בהתקשרות בין הצדדים, הזמנת תיווך בכתב חתומה כדין, רישיון תיווך בתוקף במועד ביצוע העסקה.", "הזמנת תיווך בכתב חתומה כדין, ורישיון תיווך בתוקף במועד ביצוע העסקה.", "בלעדיות בתוקף, והיותו של המתווך הגורם היעיל להתקשרות בין הצדדים.", "היותו של המתווך הגורם היעיל בהתקשרות היעיל של הצדדים, הזמנת תיווך בכתב חתומה כדין, ורישיון תיווך בתוקף במועד ביצוע העסקה."]'::jsonb, 3, null, 'סעיף 14(א) לחוק המתווכים מונה שלושה תנאים מצטברים לזכאות לדמי תיווך: המתווך היה בעל רישיון בתוקף בעת שעסק בתיווך, הלקוח חתם על הזמנה בכתב לביצוע פעולת תיווך לפי סעיף 9, והמתווך היה הגורם היעיל שהביא להתקשרות הצדדים בהסכם מחייב. בלעדיות אינה תנאי לזכאות אלא הסדר נוסף שמקים חזקת גורם יעיל (סעיף 14(ב)), ולכן חלופות א ו-ג שגויות, וחלופה ב מחסירה את תנאי הגורם היעיל.', 'סעיף 14(א) לחוק המתווכים במקרקעין, התשנ״ו-1996', 11, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
