insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q12', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 12', 'דינה רכשה דירת מגורים לפני 17 שנה והתגוררה בה במשך שנתיים. כעבור שנתיים עברה דינה לגור בדירה שכורה, תוך שהשתמשה בדירה שבבעלותה לצורך עסק לבניית ציפורניים. כעת מבקשת דינה למכור את דירתה כדירת מגורים מזכה לצורכי מס שבח.

האם דינה רשאית לעשות כן? מדוע?', '["כן, משום שמדובר בדירת מגורים.", "כן, משום שהדירה שימשה למגורים במשך השנתיים האחרונות לפני מכירתה.", "לא, משום שהדירה לא שימשה בעיקרה למגורים במרבית תקופת השבח של הדירה, ולא בארבע השנים האחרונות.", "לא, משום שהופעל בדירה עסק, ולכן היא אינה עונה להגדרת דירת מגורים לצורכי מס שבח."]'::jsonb, 2, null, 'סעיף 49(א) לחוק מיסוי מקרקעין מגדיר "דירת מגורים מזכה" כדירה ששימשה בעיקרה למגורים באחת משתי תקופות: ארבע חמישיות מהתקופה שבשלה מחושב השבח, או ארבע השנים שקדמו למכירה. דינה גרה בדירה שנתיים בלבד מתוך 17, ובשנים האחרונות הדירה שימשה עסק, ולכן אף אחד משני המבחנים לא מתקיים. חלופה ד מחמירה מדי: עסק בדירה אינו שולל את ההגדרה כשלעצמו אלא רק אם פגע במבחן השימוש למגורים, וחלופות א ו-ב מתעלמות מהמבחן בכלל.', 'סעיף 49(א) לחוק מיסוי מקרקעין (שבח ורכישה), התשכ״ג-1963 - הגדרת "דירת מגורים מזכה"', 12, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q13', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 13', 'בהתייחס לפסק הדין בעניין ע״א 3455/06 דה כהן נ'' עמרם, איזה מההיגדים הבאים הוא הנכון ביותר?', '["לפי פסק הדין, אין מניעה שתאגיד יספק שירותי תיווך לציבור, אם הבעלים הרשום של התאגיד הוא מתווך בעל רישיון תיווך.", "לפי פסק הדין, החוק לא מאפשר מתן שירותי תיווך באמצעות תאגיד, אלא באמצעות מתווכים בלבד.", "לפי פסק הדין, תאגיד אינו יכול לתת שירותי תיווך, משום ששם המתווך ופרטיו חייבים להיות כלולים בהזמנת התיווך.", "לפי פסק הדין, תאגיד יכול לתת שירותי תיווך לציבור, כל עוד פעולות התיווך נעשות על ידי מתווך בעל רישיון."]'::jsonb, 3, null, 'בעניין דה כהן נ'' עמרם נקבע שחוק המתווכים אינו אוסר על תאגיד לעסוק בתיווך, אך הרישיון הוא אישי: הדרישה שבסעיף 13 לחוק היא שפעולות התיווך עצמן ייעשו בידי אדם בעל רישיון, ולכן חברת תיווך יכולה לספק שירותים לציבור כל עוד המתווכים הפועלים מטעמה מורשים. חלופה א מסתפקת ברישיון של הבעלים בלבד, וזה לא מספיק אם מי שמתווך בפועל אינו מורשה; חלופות ב ו-ג הופכות את ההלכה.', 'סעיף 13 לחוק המתווכים במקרקעין, התשנ״ו-1996; ע״א 3455/06 דה כהן נ'' עמרם', 13, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
