insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q14', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 14', 'שירה ביקשה למכור את דירתה. המתווך זריזי מצא לשירה קונה. זריזי ניהל את המשא ומתן והצדדים ניסחו בעזרתו זכרון דברים מפורט, שבו הופיעה ההצעה שהציע הקונה ושירה קיבלה, ותנאי העיסקה הבסיסיים: כתובת, מחיר, מועדי תשלום ומועד מסירת החזקה. הצדדים לחצו ידיים ופתחו בקבוק שמפניה, אך סיכמו לערוך תיקון הגהה במועד התשלום האחרון, כך שמועד התשלום האחרון יוקדם בשבוע מהמועד שכתוב בזכרון הדברים. שירה חתמה על זכרון הדברים, אך הקונה לא הספיק לחתום על זכרון הדברים - אלא רק אישר את זכרון הדברים והתיקון בכתב במשפט "מאשר את ההסכם" שנכתב בדואר אלקטרוני, לפני שנסע בדחיפות לחו״ל לתקופה קצרה. כעת שירה מבקשת למכור את דירתה לקונה אחר, שמציע לה סכום גבוה יותר, ומבקשת לדעת האם זכרון הדברים מחייב אותה, מכיוון שהקונה טרם חתם עליו.

לפי פסק הדין בעניין ע״א 158/77 רבינאי נ'' מן שקד בע״מ, האם בנסיבות המתוארות זכרון הדברים הוא חוזה מחייב?', '["לפי פסק הדין, עריכת זכרון דברים היא פעולה משפטית לפי חוק המתווכים במקרקעין, התשנ״ו-1996. מכיוון שלמתווך אסור לסייע בעריכת זכרון דברים, אזי לזכרון הדברים אין תוקף.", "לפי פסק הדין, זכרון דברים שכזה עומד בקריטריונים לכריתת חוזה לפי חוק החוזים, החתימה של הרוכש אינה חיונית ובין הצדדים נכרת חוזה בתוקף בהתאם לסעיף 2 לחוק החוזים (חלק כללי), התשל״ג-1973.", "לפי פסק הדין, זכרון דברים אינו מחייב, משום שחסרה בו גמירת דעת לפי סעיף 2 לחוק החוזים (חלק כללי), התשל״ג-1973, כל עוד לא נחתם.", "לפי פסק הדין זכרון הדברים אינו מחייב משום שעיסקה במקרקעין חייבת להיות בכתב לפי סעיף 6 לחוק המקרקעין, התשכ״ט-1969, ודרישה זו כוללת חתימה."]'::jsonb, 1, null, 'הלכת רבינאי קובעת שזכרון דברים הוא חוזה מחייב כאשר מתקיימים שני יסודות: גמירת דעת של הצדדים להתקשר, ומסוימות, כלומר הפרטים המהותיים של העסקה (נכס, מחיר, מועדי תשלום ומסירה) מופיעים בו. כאן שני היסודות קיימים, וחתימה אינה תנאי לכריתה: דרישת הכתב שבסעיף 8 לחוק המקרקעין מתמלאת במסמך הכתוב, והאישור במייל מעיד על גמירת הדעת. חלופה א שגויה גם בעובדות (איסור עריכת מסמכים משפטיים אינו מבטל את תוקף המסמך) וחלופה ד מפנה לסעיף 6, שעוסק בהגדרת עסקה ולא בדרישת הכתב.', 'סעיפים 2 ו-5 לחוק החוזים (חלק כללי), התשל״ג-1973; סעיף 8 לחוק המקרקעין; ע״א 158/77 רבינאי נ'' מן שקד', 14, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
