insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q15', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 15', 'גלית רכשה דירה בבניין הרשום כבית משותף. בבניין קיימות שלוש מעליות: מעלית ימנית, מעלית אמצעית, ומעלית שמאלית. לאחר שגלית נכנסה להתגורר בדירה, היא קיבלה הודעה מוועד הבית, האוסרת על הדיירים להשתמש במעלית הימנית, משום שהיא הוצמדה לדירת הפנטהאוז אשר בקומה 4. עוד נכתב בהודעה, כי השימוש במעלית השמאלית והאמצעית מותר לכל דיירי הבניין.

האם ניתן להצמיד מעלית לדירה מסוימת בבניין?', '["כן; בעלי הדירות רשאים לקבוע בתקנון כי חלק מסוים של הרכוש המשותף יהיה צמוד לדירה פלונית - ובלבד שאם יש עוד מעליות בבניין, ייוותרו רוב המעליות לשימוש כלל הדיירים.", "לא, בעלי הדירות רשאים לקבוע בתקנון כי חלק מסוים של הרכוש המשותף יהיה צמוד לדירה פלונית - ובלבד שלא קבעו זאת ביחס לחדרי מדרגות, מעליות, מקלטים ומתקנים המיועדים לשמש את כל בעלי הדירות.", "לא, בעלי הדירות לא רשאים לקבוע בתקנון כי חלק מסוים של הרכוש המשותף יהיה צמוד לדירה פלונית.", "כן, כל עוד ומי שמשתמש במעלית הוא דייר בבניין."]'::jsonb, 1, null, 'סעיף 55(ג) לחוק המקרקעין מתיר לבעלי הדירות לקבוע בתקנון שחלק מסוים של הרכוש המשותף יהיה צמוד לדירה פלונית, אך מסייג במפורש: לא חדרי מדרגות, לא מעליות, לא מקלטים ולא מתקנים שנועדו לשמש את כל בעלי הדירות. מעלית נמצאת ברשימה השחורה הזו, ולכן ההצמדה פסולה גם אם נשארו מעליות אחרות (חלופה א ממציאה מבחן של רוב). חלופה ג שגויה כי הצמדה של חלקים אחרים, כמו חניה או גג, בהחלט מותרת.', 'סעיף 55(ג) לחוק המקרקעין, התשכ״ט-1969', 15, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q16', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 16', 'יוחנן וליאור התקשרו ביניהם בחוזה שכירות למשך 4 שנים עם אופציה (ברירה) להארכת השכירות לתקופה נוספת בת 20 שנים. בהסכם נקבע כי הארכת השכירות תבוצע בהתאם להודעה שתימסר בין הצדדים 90 יום לפני תום תקופת השכירות הראשונה.

האם במקרה שכזה נדרש רישום השכירות בפנקסי המקרקעין? מדוע?', '["לא, משום שההסכם נחתם ל- 4 שנים. תקופת האופציה טרם התממשה, ולכן היא לא נחשבת כחייבת ברישום בפנקסי המקרקעין.", "לא, משום שאין חובה לרשום שכירות שתוקפה פחות מ- 25 שנה.", "כן, משום שישנה חובה לרשום כל שכירות בפנקסי המקרקעין.", "כן, משום שתקופת האופציה (הברירה) נספרת בחישוב של תקופת השכירות לצורכי רישום השכירות בפנקסי המקרקעין."]'::jsonb, 3, null, 'סעיף 79(א) לחוק המקרקעין פוטר מרישום שכירות לתקופה שאינה עולה על חמש שנים, וסעיף 79(ב) קובע שהפטור לא יחול כאשר יש עם השכירות ברירה להאריך אותה לתקופה כוללת שעולה על חמש שנים. כאן 4 שנים ועוד אופציה ל-20 מצטברים ל-24 שנה, ולכן השכירות טעונה רישום כבר עכשיו, בלי קשר לשאלה אם האופציה מומשה. חלופה ב מבלבלת עם סף 25 השנה של "חכירה לדורות", וחלופה ג מתעלמת מהפטור לשכירות קצרה.', 'סעיף 79 לחוק המקרקעין, התשכ״ט-1969', 16, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q17', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 17', 'דויד מכר את דירתו ליונתן, תושב חוץ שהחליט לעלות לישראל. מסיבות שונות טרם עלה יונתן לישראל. המכירה נעשתה כנגד תמורה מלאה, אך מסיבות שונות לא נסתיימה ברישום הבעלות של יונתן בפנקסי המקרקעין, ואף לא ברישום הערת אזהרה לטובת יונתן.
לאחר שנים רבות, דויד החליט למכור את הדירה לרחל. רחל שילמה את מלוא התמורה שביקש ורשמה הערת אזהרה לטובתה, אך לא הספיקה להשלים את רישום הבעלות בדירה על שמה בפנקסי המקרקעין. דויד לקח את התמורה ונעלם. כעבור זמן עלה יונתן לישראל וגילה לתדהמתו כי רחל נמצאת בדירה שרכש. יצוין כי רחל לא היתה מודעת לעיסקה שביצע דויד עם יונתן.

לפי פסק הדין בע״א 2643/97 שלמה גנז נ'' בריטיש קולוניאל בע״מ, איזה מההיגדים הבאים הוא הנכון ביותר?', '["יונתן לא זכאי לאכיפת ההסכם משום שהוא לא רשם הערת אזהרה לטובתו, אך נשמרת לו הזכות להגיש תביעת פיצויים כנגד דויד.", "יונתן זכאי לאכיפת ההסכם, משום שהוא הראשון בזמן, ורחל לא השלימה את רישום הבעלות על שמה.", "יונתן פעל בחוסר תום לב כשלא רשם הערת אזהרה על שמו, ולכן רחל זוכה בנכס.", "דויד המוכר פעל בחוסר תום לב ובמרמה, לכן רחל תזכה בנכס."]'::jsonb, 0, null, 'סעיף 9 לחוק המקרקעין נותן עדיפות לראשון בזמן, אלא אם השני פעל בתום לב, בתמורה והשלים רישום. בעניין גנז נקבע חריג מכוח עקרון תום הלב: קונה ראשון שנמנע במשך שנים מלרשום הערת אזהרה, ובכך אפשר את התאונה המשפטית עם קונה שני תם לב, אינו זכאי לאכיפה גם אם השני טרם נרשם כבעלים, וזכותו מצטמצמת לפיצויים מהמוכר. לכן חלופה ב, שהיא הכלל הרגיל של סעיף 9, שגויה כאן; וחלופה ג מנסחת את ההלכה באופן מוטעה: המחדל אינו "חוסר תום לב" בפני עצמו, ובעיקר היא מחסירה את זכות הפיצויים שנשמרת ליונתן.', 'סעיף 9 לחוק המקרקעין, התשכ״ט-1969; ע״א 2643/97 גנז נ'' בריטיש קולוניאל', 17, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q18', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 18', 'מאיה מכרה את דירתה לשירה באמצעות מתווך, וחתמה על טופס הזמנת שירותי תיווך כדין. המתווך היה הגורם היעיל בעיסקה, ובעל רישיון תיווך כדין. ההסכם בין מאיה לרוכשת כלל תנאי מתלה, הקובע כי תוקפו של ההסכם כפוף לאישור בית משפט. עוד קבע ההסכם כי עד לאישור בית משפט, יופקד הכסף בנאמנות אצל עורכי דין. בית המשפט אישר את ההסכם (התנאי המתלה התקיים), אך שירה הפרה את ההסכם, וגרמה לביטולו.

לפי פסק הדין רע״א אנג''ל שושני ואח'' נ'' אברון בע״מ, איזה מההיגדים הבאים הוא הנכון ביותר?', '["מאיה לא חייבת לשלם את דמי התיווך, מאחר שההסכם הופר ובוטל.", "אין חובה לשלם דמי תיווך במקרה שכזה, מכיוון שמדובר בהסכם שכפוף לתנאי מתלה.", "על מאיה החובה לשלם למתווך את דמי התיווך, משום שהתנאי המתלה התקיים.", "על מאיה החובה לשלם למתווך מרגע שנחתם הסכם מחייב בין הצדדים."]'::jsonb, 2, null, 'סעיף 14(א) לחוק המתווכים מזכה בדמי תיווך כשהמתווך הביא את הצדדים ל"הסכם מחייב". בעניין שושני נ'' אברון נקבע שהזכאות מתגבשת עם ההסכם, והפרה וביטול מאוחרים אינם מאיינים אותה, כי המתווך עשה את שלו ואינו ערב להתנהגות הצדדים אחר כך. בחוזה עם תנאי מתלה, ההסכם הופך מחייב באופן מלא כשהתנאי מתקיים, וכאן בית המשפט אישר אותו, ולכן חלופה ג מדויקת יותר מחלופה ד, שמתעלמת מהתנאי המתלה ומועד התגבשותו.', 'סעיף 14(א) לחוק המתווכים במקרקעין, התשנ״ו-1996; סעיף 27 לחוק החוזים (חלק כללי); רע״א שושני נ'' אברון', 18, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q19', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 19', 'שני היא מתווכת במקרקעין. לשני לקוחה אשר מעוניינת למכור דירה. שני פנתה ללימור, שהינה מתווכת במקרקעין, והציעה לה לשתף פעולה בתיווך העיסקה, כך ששני ולימור יחלקו בדמי התיווך. שני החתימה את הלקוחה על הזמנת תיווך כדין והוסיפה את לימור להסכם להזמנת שירותי התיווך מהלקוחה, ביצעה פעולות שיווק בנכס, והעבירה את הרוכשים הפוטנציאליים להמשך טיפול אצל לימור. לאחר מספר חודשים גילתה שני לתדהמתה כי לימור תיווכה את אותה עיסקה, קיבלה דמי תיווך, אך לא העבירה לשני כל תשלום. לימור טוענת שלא נעשה הסכם ביניהן, משום שיש לערוך הסכם תיווך בכתב.

לפי פסק הדין בעניין תא 35922/07 מרדכי עוז נ'' משה עזרא, איזה מההיגדים הבאים הוא הנכון ביותר?', '["הסכם שיתוף פעולה בין מתווכים במקרקעין חייב להיערך בכתב. לפיכך, משלא נערך הסכם בכתב ונחתם ע״י הצדדים, שני אינה זכאית לדמי תיווך.", "הוראות חוק המתווכים במקרקעין אינן מתייחסות להסכמי שיתוף פעולה בין מתווכים, ולכן לא נדרש הסכם בכתב כדי שלימור תהיה חייבת בתשלום לשני.", "כאשר יש שני מתווכים באותה עיסקה, רק המתווך שהיה הגורם היעיל בעיסקה ואיתר את הרוכש יהיה זכאי לדמי תיווך. לפיכך שני אינה זכאית לדמי תיווך.", "לפי פסק הדין, שתי המתווכות זכאיות לדמי תיווך, וזאת בתנאי ששני החזיקה בהסכם בלעדיות בתוקף ולימור הייתה הגורם היעיל בביצוע העיסקה."]'::jsonb, 1, null, 'דרישת הכתב שבסעיף 9 לחוק המתווכים חלה על ההזמנה שבין המתווך ללקוח, והיא נועדה להגן על הלקוח. היא אינה חלה על ההסכמות שבין שני מתווכים לחלוקת דמי התיווך, וכך נפסק בעניין עוז נ'' עזרא: הסכם שיתוף פעולה בין מתווכים הוא חוזה רגיל לפי חוק החוזים, שיכול להיכרת בעל פה ובהתנהגות, ומתווכת שהפרה אותו חייבת בחלקה של השותפה. חלופה ד מוסיפה תנאי בלעדיות שאינו נדרש, וחלופה ג מערבבת את מבחן הגורם היעיל, שעניינו היחס ללקוח, עם היחסים הפנימיים בין המתווכות.', 'סעיף 9 לחוק המתווכים במקרקעין, התשנ״ו-1996; חוק החוזים (חלק כללי); ת״א 35922/07 עוז נ'' עזרא', 19, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
