  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q20', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 20', 'דוד הינו מתווך בעל רישיון בתוקף. דוד החתים את ליבנת על הזמנת שירותי תיווך כדין וכן על הסכם בלעדיות לתקופה של חצי שנה, אשר הוארך לתקופה של שנה. בנוסף, ביצע דוד שתי פעולות שיווק כדין.
כעבור שנתיים מכרה ליבנת את דירתה לקונה שדוד מצא (קונה אשר שינה דעתו מספר פעמים לאורך התקופה).

איזו מהסיבות הבאות יכולה להוות סיבה שבגינה עשוי דוד להיות זכאי לדמי תיווך?', '["היותו הגורם היעיל בביצוע העיסקה.", "קיומו של הסכם הבלעדיות בנכס.", "ההסכם להזמנת שירותי תיווך שנחתם בין הצדדים, שבו הוארכה תקופת הבלעדיות.", "דוד אינו יכול להיות זכאי לדמי תיווך במצב שכזה, משום שהבלעדיות שלו בנכס הסתיימה לפי חוק."]'::jsonb, 0, null, 'הבלעדיות בדירת מגורים מוגבלת לפי סעיף 9(ב1) לחוק המתווכים לשישה חודשים לכל היותר, ולכן ההארכה לשנה אינה תקפה, והעסקה אחרי שנתיים בוודאי מחוץ לתקופת הבלעדיות וחזקת הגורם היעיל שהיא מקימה. אבל הבלעדיות היא רק קיצור דרך: הזכאות הבסיסית לפי סעיף 14(א) עומדת למתווך שהיה בפועל הגורם היעיל, וכאן הקונה הוא זה שדוד מצא, גם אם התלבט בדרך. לכן חלופה ד שגויה, וחלופות ב ו-ג נשענות על בלעדיות שפקעה.', 'סעיפים 9(ב1) ו-14(א) לחוק המתווכים במקרקעין, התשנ״ו-1996', 20, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
