insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q21', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 21', 'לדנית דירה בבעלותה. כשנולד בנה, רכשה דנית עבורו דירה ורשמה את הבעלות בדירה זו על שמו של הבן. כעת דנית מעוניינת למכור את הדירה שבבעלותה.

בנסיבות המתוארות, האם זכאית דנית לפטור ממס שבח בגין "דירת מגורים יחידה"? מדוע?', '["כן; לפי החוק, על שמה של דנית רשומה דירת מגורים אחת, והיא מוכרת אותה.", "כן, אך הפטור יהיה חלקי. רואים בדירת מגורים הרשומה על שם ילד שטרם מלאו לו 18 כחצי דירה, ולכן דנית תהיה פטורה מתשלום מחצית ממס השבח.", "לא; אין פטור ממס שבח בגין ''דירת מגורים יחידה'', הפטור של דירת מגורים יחידה הוא פטור ממס רכישה בלבד, ומס שבח מחושב לפי מדרגות בלבד.", "לא; דנית נחשבת לפי חוק כמי שבבעלותה שתי דירות מגורים. זאת משום שילדים שטרם מלאו להם 18 והוריהם, נחשבים כ\"מוכר אחד\" לעניין מס שבח."]'::jsonb, 3, null, 'סעיף 49(ב) לחוק מיסוי מקרקעין קובע שלעניין הפטור לדירת מגורים רואים את המוכר, את בן זוגו ואת ילדיהם שטרם מלאו להם 18 שנים כמוכר אחד, מה שנקרא "התא המשפחתי". דירה הרשומה על שם הבן הקטין נספרת אפוא כדירה של דנית, ולכן היא אינה בעלת דירה יחידה ואינה זכאית לפטור לפי סעיף 49ב(2). חלופה ג שגויה כי הפטור לדירת מגורים מזכה יחידה קיים במס שבח, וחלופה ב ממציאה חישוב של חצי דירה.', 'סעיפים 49(ב) ו-49ב(2) לחוק מיסוי מקרקעין (שבח ורכישה), התשכ״ג-1963', 21, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
