  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q22', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 22', 'איזה מההיגדים הבאים הוא הנכון ביותר לגבי זמני "תקופת הבדק", ו"תקופת האחריות" ברכישת דירה חדשה מקבלן לפי חוק?', '["תקופת הבדק נמשכת שנה מרגע מסירת הדירה לקונה, ותקופת האחריות אורכת שלוש שנים מרגע מסירת הדירה.", "תקופת הבדק מתחילה ברגע העמדת הדירה לרשות הקונה, ותקופת האחריות היא לתקופה של שלוש שנים, שתחילתה בסיום תקופת הבדק.", "תקופת הבדק נמשכת שנה ממועד מסירת הדירה לקונה, ותקופת האחריות נמשכת שנה נוספת אחריה.", "תקופת הבדק נמשכת שבע שנים ממועד מסירת הדירה לקונה, ותקופת האחריות נקבעת בהתאם לזמני האחריות לפי סוג הדירה."]'::jsonb, 1, null, 'סעיף 4(ג) לחוק המכר (דירות) מגדיר את שתי התקופות: תקופת הבדק היא התקופה הקבועה בתוספת לחוק לכל סוג של אי-התאמה (משנה ועד שבע שנים, לפי הרכיב), ותחילתה בעת העמדת הדירה לרשות הקונה; תקופת האחריות היא שלוש שנים שתחילתן בתום תקופת הבדק. ההבדל המעשי: בתקופת הבדק הנטל על הקבלן להוכיח שהליקוי אינו באחריותו, ובתקופת האחריות הנטל על הקונה. חלופות א, ג ו-ד נוקבות באורך אחיד לבדק שאינו קיים, ומתחילות את האחריות במועד הלא נכון.', 'סעיף 4(ג) והתוספת לחוק המכר (דירות), התשל״ג-1973', 22, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
