select 'exam-2024-08-q23', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 23', 'מהו "הסכם שיתוף במקרקעין"?', '["הסכם בין דיירים בבית משותף, המתייחס לכלל הנכסים המשותפים, כגון מעליות, מדרגות, קומת הכניסה ועוד.", "הסכם בין בני זוג או יורשים במקרקעין.", "הסכם שנעשה בין בעלים משותפים באותה חלקה או גוש, לרוב כאשר אין פרצלציה במקרקעין.", "הסכם שיתוף ברווחי שכירות במקרקעין בין בעלים שונים בנכס."]'::jsonb, 2, null, 'סעיף 29 לחוק המקרקעין מגדיר הסכם שיתוף: הסכם בין השותפים במקרקעין בדבר ניהול המקרקעין המשותפים והשימוש בהם ובדבר זכויותיהם וחובותיהם בכל הנוגע למקרקעין, והוא ניתן לרישום בפנקסים כך שיחייב גם מי שרוכש חלק מהשותפים אחר כך. הוא נפוץ במיוחד בקרקע במושע, כשאין פרצלציה והבעלים רוצים לקבוע מי מחזיק באיזה חלק. חלופה א מתארת תקנון בית משותף (סעיפים 61 ואילך), וחלופות ב ו-ד מצמצמות את המושג לזהות הצדדים או לרווחים בלבד.', 'סעיף 29 לחוק המקרקעין, התשכ״ט-1969', 23, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
