insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q24', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 24', 'מוטי נפטר והשאיר לילדיו, אור ואיריס, עיזבון שכלל דירה בתל אביב ודירה בירושלים. ע״פ צו הירושה יורשים אור ואיריס את העיזבון בחלקים שווים. אור ואיריס מעוניינים לערוך ביניהם הסכם חלוקת עיזבון, לפיו איריס תקבל לבעלותה את הדירה בירושלים וכן מחצית מהדירה בתל אביב, ואילו אור יקבל לבעלותו את מחצית הדירה הנותרת בתל אביב. יודגש כי ההסכם נעשה ללא שניתנה ע״י מי מהיורשים תמורה בכסף או בשווה כסף שהגיע מחוץ לנכסי העיזבון.

האם מדובר בעסקה החייבת במס? מדוע?', '["לא; מכיוון שמדובר בחלוקה ראשונה של נכסי העיזבון.", "לא; התמורה שהצדדים מעבירים ביניהם בהסכם הירושה פטורה ממס.", "כן; האחים מעבירים ביניהם נכסים ולכן חייבים במס גם אם הם קרובי משפחה.", "כן; מדובר במתנה בין קרובים המחויבת בשליש מס רכישה."]'::jsonb, 0, null, 'סעיף 5(ג)(4) לחוק מיסוי מקרקעין קובע שחלוקה ראשונה של נכסי עיזבון בין היורשים אינה "מכירה" לעניין החוק, ובלבד שלא ניתנה במסגרתה תמורה בכסף או בשווה כסף שאינו נכס מהעיזבון. כאן החלוקה אינה שווה, אבל כל מה שעבר בין האחים הוא נכסי העיזבון עצמם, ולכן אין אירוע מס כלל: לא מס שבח ולא מס רכישה. חלופה ב מגיעה לתוצאה דומה אך בנימוק שגוי ("פטור" ולא היעדר מכירה), וחלופה ד הייתה נכונה רק אם האחים היו מעבירים נכס במתנה אחרי שהחלוקה הראשונה כבר הושלמה.', 'סעיף 5(ג)(4) לחוק מיסוי מקרקעין (שבח ורכישה), התשכ״ג-1963', 24, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
