insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-08-q25', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, אוגוסט 2024, שאלה 25', 'בועז החליט לשפץ את ביתו ולהוסיף שטחי בנייה נוספים (ממ״ד ומרפסת). לצורך כך מבקש בועז לדעת מה אומדן העלויות הנדרשות לצורך תמחור עבודות הבנייה.

באיזה מחירון מקובל להשתמש ככלי עזר בנסיבות אלה?', '["מחירון מדד תשומות הבנייה.", "מחירון דקל.", "מחירון יד 2 לחישוב שווי נכס.", "מחירון משרד הבינוי והשיכון."]'::jsonb, 1, null, 'מחירון דקל הוא המחירון המקובל בענף הבנייה בישראל לתמחור עבודות בנייה ושיפוץ לפי סעיפי עבודה וכמויות, והוא כלי העזר של שמאים, מפקחים וקבלנים לאומדן עלויות. מדד תשומות הבנייה (חלופה א) אינו מחירון אלא מדד של הלשכה המרכזית לסטטיסטיקה שמשמש להצמדת תשלומים בחוזי רכישה מקבלן, ואילו מחירון יד2 (חלופה ג) עוסק בשווי שוק של נכסים ולא בעלות בנייה. משרד הבינוי והשיכון אינו מפרסם מחירון כזה.', 'ידע מקצועי בשמאות ותמחור בנייה (מחירון דקל)', 25, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-08'
