  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'exam-2024-11', 'מבחן נובמבר 2024', 3, 'מבחן נובמבר 2024 הוא מבחן של מיסוי ובנייה: רק חמש שאלות נוגעות ישירות בחוק המתווכים, ושבע עוסקות במס שבח, בהיטל השבחה ובחוק המכר (דירות). שתי שאלות מפנות לפסקי דין בשמם, ובשתי שאלות הרשם עצמו קיבל שתי תשובות כנכונות.', '<p>25 שאלות, ופיזור רחב במיוחד בין החוקים. חוק המתווכים ותקנותיו הם רק חמישית מהמבחן, והשאר מגיע מדיני המיסוי, הבנייה והחוזים:</p><ul><li><strong>חוק המתווכים, תקנותיו והפסיקה</strong> - 5 שאלות (8, 10, 14, 15, 24): תקופת בלעדיות שלא נקבעה, פעולות שיווק ואובדן הבלעדיות, פרטי ההזמנה בכתב (גופר נ'' קאופמן), היקף פעולת התיווך (כהן נ'' גולן) וחובת הגילוי של מידע מהותי.</li><li><strong>חוק מיסוי מקרקעין</strong> - 4 שאלות (2, 13, 20, 25): ניכוי היטל השבחה מהשבח, דירת מגורים מזכה, מקדמת מס שבח (15% מול 7.5%) ופטור שאינו חל על חנות.</li><li><strong>חוק המכר (דירות) והבטחת השקעות</strong> - 3 שאלות (4, 11, 19): הבטוחות המותרות, דירה בלי מפרט ותקופת האחריות שאחרי הבדק.</li><li><strong>חוק התכנון והבנייה</strong> - 3 שאלות (9, 12, 22): עבודות הפטורות מהיתר, מועד תשלום היטל השבחה והסכם לקרקע חלופית בהפקעה.</li><li><strong>חוק החוזים (תרופות)</strong> - 2 שאלות (1, 3): ביטול חלקי של חוזה ואכיפה של שירות אישי.</li><li><strong>שמאות מקרקעין</strong> - 2 שאלות (7, 23): דו"ח אפס וייחוד העיסוק בשומה.</li><li><strong>מקרקעי ישראל ומשק חקלאי</strong> - 2 שאלות (16, 17): דמי הסכמה בחכירה לא מהוונת והורשת נחלה.</li><li><strong>אחת מכל אחד</strong>: חוק המקרקעין - בית משותף (21), חוק הגנת הדייר (5), חוק ההוצאה לפועל - כונס נכסים (6), וחברה משכנת ורישום משכון (18).</li></ul>', '["מיסוי מקרקעין הוא הנושא הכבד במבחן הזה: ארבע שאלות ישירות ועוד שתיים על היטל השבחה. צריך לדעת בעל פה את הגדרת \"דירת מגורים מזכה\" (4 שנים או 80% מתקופת השבח), את שיעורי המקדמה (15% לרכישה לפני 7.11.2001, 7.5% אחריה) ושהפטור חל רק על דירות.", "בשאלות הבלעדיות הרשם בודק את המספרים: 6 חודשים לדירה, 9 לנכס אחר, ובלעדיות שנופלת אחרי שליש מהתקופה כשאין פעולות שיווק. חלופה שמציעה \"3 חודשים\" או \"שנה\" היא מלכודת.", "שתי שאלות מפנות לפסק דין בשמו (גופר נ'' קאופמן, כהן נ'' גולן). בשתיהן ההלכה היא גישה מהותית: פגם טכני בטופס אינו שולל עמלה, אבל דירה שהלקוח מצא לבד אינה בתחום התיווך.", "חוק המכר (דירות) חוזר שלוש פעמים ובכל פעם עם מספר: 7% לבטוחה, איכות גבוהה כשאין מפרט, ושלוש שנות אחריות אחרי הבדק. הקבלן אינו נפטר בתום הבדק, הנטל רק עובר לקונה.", "כשחלופה נשמעת סבירה אבל מוסיפה תנאי שאינו בחוק (\"אישור רמ\"י\", \"פרויקט יוקרה\", \"רק אם מייצג צד אחד\"), התנאי הוא הסימן שהיא שגויה. במבחן הזה זה הדפוס בלפחות שש שאלות."]'::jsonb, '[]'::jsonb, 'רשם המתווכים במקרקעין, מועד 24.11.2024, גרסה 1', null, false, true
  from public.course_chapters c where c.slug = 'past-exams'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q01', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 1', 'יסמין ויפעת חתמו על הסכם למכירת דירתה של יסמין ליפעת. אחד הנספחים בהסכם עוסק ב-"מיזוג מרכזי". לאחר שנמסרה הדירה, התברר שהמזגן המרכזי נהרס ולא ניתן לתקנו. יסמין, המוכרת, הודיעה כי היא עומדת על קיום החוזה, אך מוכנה לבטל בחוזה את ההוראות הנוגעות למחיר המזגן שסוכם, ולהפחית מהמחיר הכולל את עלות ההחלפה, הרכישה וההתקנה של מזגן מרכזי חדש - מזגן שיהיה מאותו סוג בדיוק. יפעת הקונה, מצידה, דורשת לבטל את ההסכם כולו, בטענה שהיא לא מסוגלת לגור בחום של ישראל בדירה ללא מזגן אפילו רגע אחד.

בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["יפעת רשאית לבטל את החלק הנוגע למזגן בלבד, אך היא תוכל לבטל את ההסכם כולו אך ורק אם תוכיח כי היא לא הייתה חותמת על ההסכם אילו ידעה שהמזגן לא תקין ודורש החלפה.", "יפעת לא רשאית לבטל את ההסכם, כי המזגן הוא חלק מנספח לחוזה ולא חלק מהחוזה עצמו. זאת ללא קשר לשאלה האם הייתה קונה דירה ללא מזגן תקין.", "יפעת לא רשאית לבטל את ההסכם, כי המוכרת מוכנה להחליף את המזגן ולא ניתן להפריד הסכם לחלקים ולקיים רק את חלקו.", "יפעת רשאית לבטל את ההסכם, אך עליה לבטל את ההסכם כולו, מכיוון שלא ניתן להפריד הסכם לחלקים, אלא ניתן לבטל את כולו, או לקיים את כולו."]'::jsonb, 0, null, 'סעיף 7(ג) לחוק החוזים (תרופות) קובע שכאשר החוזה ניתן להפרדה לחלקים והופר אחד מחלקיו, הנפגע רשאי לבטל רק את החלק שהופר; את החוזה כולו הוא רשאי לבטל רק אם ההפרה היא גם הפרה יסודית של כל החוזה. הפרה יסודית לפי סעיף 6 היא הפרה שאדם סביר לא היה מתקשר בחוזה אילו ראה אותה מראש, וזה בדיוק מה שיפעת תצטרך להוכיח כדי לבטל את כל העסקה. חלופות ג ו-ד טועות כי חוזה בהחלט ניתן להפרדה לחלקים, וחלופה ב טועה כי נספח לחוזה הוא חלק ממנו.', 'סעיפים 6 ו-7(ג) לחוק החוזים (תרופות בשל הפרת חוזה), התשל"א-1970', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q02', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 2', 'יהונתן מכר להילה דירת מגורים שבה בנה תוספת של חדר נוסף כדין. מדובר בדירתו השנייה של יהונתן, והדירה נמכרה ברווח גדול. לאחר שיהונתן הצהיר על העיסקה לרשות המיסים, הוא חויב בשומת מס שבח בסך 500,000 ש"ח. הוועדה המקומית שבשטחה מצוי הנכס דרשה ממנו לשלם לה היטל השבחה (שהוא תשלום חובה המכונה גם ''מס השבחה''), בסך של 200,000 ש"ח.

בנסיבות המתוארות, האם יהונתן יכול לנכות את היטל ההשבחה ממס שבח מקרקעין?', '["לא; יש לשלם מס שבח מקרקעין והיטל השבחה, כי שניהם מחושבים לפי עליית הערך של המקרקעין.", "כן; היטל השבחה הוא הוצאה מוכרת לצורך חישוב מס שבח מקרקעין.", "לא; היטל השבחה הוא לא הוצאה מוכרת לצורך חישוב מס שבח מקרקעין, כי מדובר במיסים נפרדים.", "כן, ובלבד ששיעור הניכוי לא יעלה על 15% מעליית הערך."]'::jsonb, 1, null, 'סעיף 39 לחוק מיסוי מקרקעין מונה את ההוצאות המותרות בניכוי לצורך חישוב השבח, והיטל השבחה ששולם לוועדה המקומית הוא אחת מהן. ההיטל מנוכה מהשבח (הרווח שעליו מחושב המס) ולא מסכום המס עצמו, ואין לניכוי תקרה של 15% כפי שמציעה חלופה ד. שני התשלומים אמנם נגזרים מעליית ערך, אבל זו בדיוק הסיבה שהחוק מכיר בהיטל כהוצאה: אחרת היה יהונתן משלם פעמיים על אותה עליית ערך.', 'סעיף 39 לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q03', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 3', 'יעקב מתחתן בשעה טובה והוריו רוכשים לו דירה. מאחר שמשפחתו של יעקב עשירה, הוריו החליטו לרכוש את שירותיו של מעצב הדירות הנודע תומר עדש, אשר ידוע בכך שהוא מתאים באופן אישי את העיצוב של הנכס באופן מרגש ועל בסיס היכרות עם בני הזוג. סוכם בין הצדדים מועד לעיצוב הנכס והתאריך שוריין. שבועיים לפני החתונה התקשר המנהל של המעצב ואמר: "אני מצטער, אבל איש עסקים ידוע מחתן את בתו בדיוק ביום החתונה שלך ומבקש את העיצוב שלו בדירה של בני הזוג, והוא הציע לתומר סכום כפול ממה שסיכמנו איתך. לכן תומר לא מעוניין לבצע את העיצוב אצלך. אבל נשמח לשלוח לך מעצב אחר".

בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["הוריו של יעקב לא יכולים לאכוף על המעצב המצליח תומר את החוזה כי לא מדובר בהפרת חוזה, שכן החוזה לא נערך בכתב.", "הוריו של יעקב לא יכולים לאכוף על המעצב המצליח תומר את החוזה ולחייב אותו להופיע באופן אישי, אך הם יכולים לתבוע מתומר המעצב פיצויים.", "הוריו של יעקב יכולים לתבוע מתומר אכיפה של החוזה, וגם פיצויים.", "הוריו של יעקב יכולים לאכוף על המעצב המצליח תומר את החוזה, אבל הם יצטרכו לבחור האם לתבוע אכיפה של החוזה שהופר או פיצוי."]'::jsonb, 1, null, 'סעיף 3(2) לחוק החוזים (תרופות) שולל את תרופת האכיפה כאשר אכיפת החוזה היא כפייה לעשות או לקבל עבודה אישית או שירות אישי, וכאן כל מהות ההתקשרות היא העיצוב האישי של תומר. חוזה בעל פה הוא חוזה תקף (רק עסקה במקרקעין טעונה כתב, והזמנת שירותי עיצוב אינה כזו), ולכן יש הפרה, והוריו של יעקב זכאים לפיצויים לפי סעיף 10 לחוק. חלופות ג ו-ד נופלות כי אכיפה אינה אפשרית כלל, וחלופה א נופלת כי היעדר כתב אינו שולל את קיום החוזה.', 'סעיפים 3(2) ו-10 לחוק החוזים (תרופות בשל הפרת חוזה), התשל"א-1970', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q04', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 4', 'ברכישת דירה חדשה מקבלן, כאשר מקבל הקבלן מרוכש הדירה סכום העולה על 7% מהמחיר, איזו מהחלופות הבאות אינה קבילה כערובה לטובת הקונים?', '["ערבות בנקאית.", "פוליסת ביטוח.", "צ''ק לפקודת הקונה.", "הערת אזהרה."]'::jsonb, 2, null, 'סעיף 2 לחוק המכר (דירות) (הבטחת השקעות של רוכשי דירות) אוסר על מוכר לקבל מהקונה יותר מ-7% ממחיר הדירה בלי להבטיח את כספו באחת הדרכים שהחוק מונה: ערבות בנקאית, פוליסת ביטוח, משכנתה ראשונה, הערת אזהרה, או רישום הבעלות או החכירה על שם הקונה. צ''ק של הקבלן לפקודת הקונה אינו ברשימה: הוא רק התחייבות נוספת של אותו קבלן, ואם הקבלן יקרוס הצ''ק יהיה חסר ערך בדיוק כמו החוזה. זו הנקודה של החוק: הבטוחה חייבת לבוא מגורם חיצוני או מזכות קניינית בנכס.', 'סעיף 2 לחוק המכר (דירות) (הבטחת השקעות של רוכשי דירות), התשל"ה-1974', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q05', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 5', 'גיא הוא מתווך במקרקעין. אביתר מבקש מגיא למצוא לו בית להשכרה בדמי מפתח, והוא מבקש ליהנות מזכויות של דייר מוגן במבנה, הנמצא בתוך משק חקלאי באחד המושבים שבאזור מגוריו כיום.

בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["אין מניעה לשכור בדמי מפתח במקרה זה, מדובר בשכירות משנה מול רשות מקרקעי ישראל (מינהל מקרקעי ישראל).", "יש מניעה לשכור בדמי מפתח במקרה זה, משום שאביתר הוא לא קרוב משפחה של בעלי החלקה.", "אין מניעה לשכור בדמי מפתח במקרה זה, משום ששכירות בדמי מפתח מותרת למטרות מגורים ומסחר.", "יש מניעה להחלת חוק הגנת הדייר במקרה זה, שכן חוק הגנת הדייר לא חל על מבנים שהם חלק ממשק חקלאי."]'::jsonb, 3, null, 'חוק הגנת הדייר [נוסח משולב] מחריג במפורש מתחולתו מבנים שהם חלק ממשק חקלאי, ולכן אי אפשר ליצור במבנה כזה דיירות מוגנת ולשכור אותו בדמי מפתח. קרבת משפחה לבעלי החלקה (חלופה ב) אינה תנאי בחוק, ושכירות משנה מול רמ"י (חלופה א) אינה מנגנון שקיים. חלופה ג נכונה כעיקרון כללי (החוק חל על דירות ועל בתי עסק) אבל מתעלמת מהחריג שהוא לב השאלה.', 'חוק הגנת הדייר [נוסח משולב], התשל"ב-1972 (הוראות התחולה: החרגת מבנים שהם חלק ממשק חקלאי)', 5, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q06', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 6', 'עורך דין יצחקי מונה ע"י רשם ההוצאה לפועל ככונס נכסים על דירתו של החייב אמנון, במסגרת תיק הוצאה לפועל שנפתח כנגד אמנון. אחרי שהדירה נמכרה, התברר, למרבה הצער, כי עורך דין יצחקי התרשל במילוי תפקידו וגרם נזקים לדירה טרם מסירתה לרוכש.

בנסיבות המתוארות, מה יכול אמנון לעשות על מנת לקבל פיצוי מכונס הנכסים?', '["להגיש תביעה בבית משפט נגד כונס הנכסים, מכיוון שבהוצאה לפועל לא ניתן לחייב כונס נכסים בפיצוי. חילוט הכספים ייעשה לאחר מכן בהוצאה לפועל.", "להגיש בקשה לרשם ההוצאה לפועל לחיוב כונס הנכסים בפיצוי, וחילוט הערובה שהפקיד.", "להגיש בבית המשפט השלום בקשה לביטול הליכי הכינוס ולביטול מכירת הדירה ע\"י הכונס.", "להגיש בקשה להתמנות ככונס נכסים על המשרד של כונס הנכסים בהוצאה לפועל."]'::jsonb, 1, null, 'כונס נכסים בהוצאה לפועל הוא זרועו הארוכה של רשם ההוצאה לפועל, ולכן גם האחריות על מילוי תפקידו נדונה שם: סעיף 58 לחוק ההוצאה לפועל קובע שכונס שלא מילא חובה מחובותיו, הרשם רשאי לחייבו בפיצוי הנזק שגרם ולחלט את הערובה שהפקיד עם מינויו. אין צורך בתביעה נפרדת בבית משפט (חלופה א), ביטול המכירה (חלופה ג) אינו הסעד לנזק שכבר נגרם לדירה, וחלופה ד אינה הליך שקיים.', 'סעיף 58 לחוק ההוצאה לפועל, התשכ"ז-1967', 6, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q07', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 7', 'יזם פנה לבנק בבקשה לליווי בנקאי לפרויקט בנייה חדש. הבנק פנה לשמאי מקרקעין בבקשה לערוך דו"ח כללי המפרט את העלויות המשוערות בפרויקט הבנייה ואת פוטנציאל הרווח שלו.

בנסיבות המתוארות, כיצד נקרא הדו"ח אותו ביקש הבנק מהשמאי?', '["דו\"ח פוטנציאל.", "דו\"ח בנק מלווה ליזם.", "דו\"ח רווח פרויקט משוער.", "דו\"ח אפס."]'::jsonb, 3, null, '"דו"ח אפס" הוא המונח המקצועי המקובל לדוח השמאי שנערך לבנק המלווה לפני תחילת הפרויקט ("נקודת האפס"): הוא מפרט את עלויות הבנייה הצפויות, את תחזית ההכנסות ממכירת הדירות ואת הרווח היזמי, וממנו הבנק גוזר את תנאי הליווי. יתר השמות בחלופות הם תיאורים שהומצאו לשאלה ואינם מונחים בשימוש. זו שאלת מונחים ולא שאלת דין, ולכן לא ניתן להפנות לסעיף חוק.', 'מונח מקצועי בליווי בנקאי לפרויקטים (שמאות מקרקעין); אין סעיף חוק', 7, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q08', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 8', 'איתי, ספרן שעובד בספרייה העירונית, חתם על הזמנה בכתב לביצוע פעולת תיווך ועל הסכם בלעדיות למתווך המוסמך חן. במסגרת ההסכם בין השניים, התחייב חן לקבל לטיפולו עסקת מכירה של חנות שירש איתי מסבו. השניים הסכימו כי חן יקבל בלעדיות על העסקה ולא קבעו את משך תקופת הבלעדיות.

בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["תקופת הבלעדיות תסתיים בתום 9 חודשים מיום ההזמנה.", "תקופת הבלעדיות תסתיים בתום שנה מיום ההזמנה.", "תקופת הבלעדיות תסתיים בתום 6 חודשים מיום ההזמנה.", "בהיעדר קביעה בנוגע למשך הבלעדיות, לא תהיה לחן בלעדיות על המכירה."]'::jsonb, 0, null, 'סעיף 9 לחוק המתווכים מבחין בין דירת מגורים לנכס אחר: בנכס שאינו דירה, כמו החנות שירש איתי, תקופת הבלעדיות המרבית היא תשעה חודשים, וכשלא נקבעה תקופה הבלעדיות מסתיימת בתום תשעה חודשים מיום ההזמנה. המלכודת היא חלופה ג: שישה חודשים הם התקרה לדירה, לא לחנות (ובדירה שלא נקבעה בה תקופה, הבלעדיות קצרה בהרבה: 30 ימים). היעדר קביעת תקופה אינו מבטל את הבלעדיות (חלופה ד), החוק פשוט משלים אותה.', 'סעיף 9 לחוק המתווכים במקרקעין, התשנ"ו-1996 (תקופת הבלעדיות)', 8, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q09', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 9', 'יערית רכשה דירת יד שנייה בת 90 מטר בקומה השלישית בבית משותף. יערית מתכוונת לשפץ את הדירה באופן יסודי לצורך השכרתה.

בנסיבות המתוארות, ביחס לאיזו מהעבודות הבאות יערית לא נדרשת לקבל היתר בנייה?', '["הוספת מרפסת שמש בצד המזרחי של הדירה, שאינו צד חזיתי בבניין.", "הרחבת פתחי החלונות בדירה בחזית הפונה לרחוב.", "שינוי בחלוקת החדרים בדירה, כך שבמקום דירת 4 חדרים הדירה תשמש כדירת 3 חדרים.", "פיצול הדירה ל- 2 דירות קטנות בנות כ- 45 מטרים כל אחת, עם דלת כניסה נפרדת לכל דירה מחדר המדרגות."]'::jsonb, 2, null, 'סעיף 145 לחוק התכנון והבנייה מחייב היתר לכל בנייה, לשינוי חיצוני בבניין ולשינוי בחלוקת דירה ליחידות נוספות. שינוי פנימי בלבד, כמו הזזת קירות פנים שאינם נושאים כדי להפוך ארבעה חדרים לשלושה, אינו משנה את החזית, את השטח או את מספר יחידות הדיור, ולכן פטור מהיתר (תקנות עבודות ומבנים הפטורים מהיתר). מרפסת חדשה והרחבת פתחים בחזית הן שינוי חיצוני, ופיצול לשתי דירות יוצר יחידת דיור נוספת, ושלושתם טעונים היתר.', 'סעיף 145 לחוק התכנון והבנייה, התשכ"ה-1965; תקנות התכנון והבנייה (עבודות ומבנים הפטורים מהיתר), התשע"ד-2014', 9, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q10', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 10', 'עדן מעוניין למכור את ביתו ולצורך כך חתם על הסכם להזמנת שירותי תיווך ועל הסכם בלעדיות עם אורי המתווך. אורי פרסם את הבית למכירה ומצא רוכשים פוטנציאליים. לאחר כשבוע אכן נחתם הסכם מכר אצל עורכי הדין. כעת עדן מסרב לשלם את דמי התיווך, בטענה שהופרו תקנות המתווכים הנוגעות להזמנת התיווך. הטענה להפרה הייתה בכך שמספרי תעודות הזהות של עדן ואורי לא היו כתובות על הזמנת שירותי התיווך והסכם הבלעדיות.

בהתאם לפסק הדין עא 08/4582 אהרון גופר נ'' יהודית קאופמן ובנסיבות המתוארות, איזה מהמשפטים הבאים נכון?', '["אורי לא זכאי לדמי תיווך, מאחר שהפר את התקנות המחייבות בהזמנת התיווך, בכך שמספרי תעודות הזהות של הרוכש והמתווך לא היו כתובות בהסכם התיווך.", "אורי זכאי לדמי התיווך, על אף אי מילוי הדרישה לכתיבת מספרי הזיהוי, מאחר שאין ספק ביחס לזהותם של המתווך והלקוח.", "אורי לא זכאי לדמי תיווך, מאחר שלא נחתם זיכרון דברים במעמד המשא ומתן.", "אורי זכאי לדמי תיווך, אך מאחר שלא מילא באופן מדויק אחרי הוראות החוק, הוא יהיה זכאי רק למחצית מדמי התיווך הכתובים בהסכם."]'::jsonb, 1, null, 'תקנות המתווכים במקרקעין (פרטי הזמנה בכתב) דורשות שההזמנה תכלול, בין השאר, את מספרי הזהות של הלקוח ושל המתווך. אבל הפסיקה (גופר נ'' קאופמן) אימצה גישה מהותית ולא טכנית: תכלית הדרישה היא ודאות לגבי זהות הצדדים, וכשאין כל ספק מי הלקוח ומי המתווך, חסרון מספר תעודת הזהות אינו שולל את הזכאות לדמי תיווך. זכרון דברים אינו תנאי לדמי תיווך (חלופה ג), ואין בחוק מנגנון של "חצי עמלה" על פגם טכני (חלופה ד).', 'סעיף 9(א) לחוק המתווכים במקרקעין; תקנות המתווכים במקרקעין (פרטי הזמנה בכתב), התשנ"ז-1997; ע"א גופר נ'' קאופמן', 10, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q11', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 11', 'חברת הבנייה "דירה נאה" בנתה דירה חדשה והדירה נמכרה לדנה. לחוזה המכר לא צורף מפרט. חודשיים אחרי איכלוס הדירה החדשה גילתה דנה כי המרצפות בדירה הן ברמת איכות בינונית ומטה. דנה חוששת שהמרצפות ייסדקו לאחר זמן קצר ומבקשת מהחברה להחליף אותן במרצפות באיכות גבוהה יותר.

בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["החברה לא מחויבת לעשות דבר בנוגע למרצפות, כי החברה לא מחויבת לצרף מפרט לחוזה.", "החוזה בטל; מאחר שהמפרט חייב להיות חלק בלתי נפרד מן החוזה, דנה יכולה לבקש שיחזירו לה את כל הכסף ששילמה עבור רכישת הדירה.", "החברה רשאית למסור לדנה מפרט גם לאחר מסירת החזקה בדירה ובלבד שכל דבר שהיה צריך לפרט במפרט יהיה לפי התקן או תקנות הבנייה.", "החברה מחויבת למסור את הדירה לדנה כשכל פרט שהיה צריך לפרט במפרט הוא באיכות גבוהה."]'::jsonb, 3, null, 'חוק המכר (דירות) מחייב את המוכר לצרף לחוזה מפרט (סעיף 2), ולמקרה שלא נמסר מפרט או שהוא חסר, סעיף 5 קובע את הסנקציה: רואים את המוכר כמי שהתחייב שכל פרט שהיה צריך להופיע במפרט יהיה באיכות גבוהה. כלומר החוק אינו מבטל את החוזה (חלופה ב) ואינו פוטר את המוכר (חלופה א), אלא הופך את החסר לחובה מוגברת של המוכר, וזו בדיוק הדרישה של דנה. מפרט שנמסר אחרי המסירה אינו מרפא את ההפרה (חלופה ג).', 'סעיפים 2 ו-5 לחוק המכר (דירות), התשל"ג-1973', 11, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
