  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q12', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 12', 'למוטי נודע כי לאחרונה אושרה תוכנית בניין עיר מיטיבה, החלה גם לגבי הנכס שלו. התוכנית תעניק תוספת זכויות המאפשרת למוטי לבנות קומה נוספת לגג הבית בשטח של 200 מ"ר. מוטי לא מעוניין כרגע לנצל את זכויות הבנייה הנוספות ולהוסיף עוד קומה לנכס שלו, אלא למכור את הנכס.

בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["מוטי יצטרך לשלם היטל השבחה בגובה 50% מערך הנכס אך ורק אם הוא בונה בפועל לפי התוכנית, וכך גם לגבי מי שיקנה ממנו.", "מוטי יחויב בהיטל השבחה מלא בגובה של עד 50% מערך ההשבחה שנקבע, אותו יחויב לשלם באופן מיידי במועד בו נודע לו על אישור התוכנית, גם אם הוא לא מעוניין לנצל את הזכויות הנוספות.", "מוטי יחויב בהיטל השבחה לפי התוכנית אך ורק אם הוא מנצל אישית את זכויות הבנייה.", "מוטי יחויב בהיטל השבחה בגובה 50% מערך ההשבחה, אך רק כאשר ימכור את זכויותיו בנכס, או כאשר יחליט לבנות לפי זכויות הבנייה הנוספות."]'::jsonb, 3, null, 'לפי התוספת השלישית לחוק התכנון והבנייה, החבות בהיטל נוצרת עם אישור התוכנית המשביחה, ושיעורו מחצית מההשבחה (לא מערך הנכס, כמו בחלופה א). אבל מועד התשלום נדחה עד "מימוש הזכויות", שמוגדר כקבלת היתר בנייה, התחלת שימוש בפועל, או העברת הזכויות בנכס (מכירה). לכן מוטי אינו משלם ביום שנודע לו על התוכנית (חלופה ב), וגם לא נפטר מההיטל כשהוא מוכר בלי לבנות (חלופה ג): המכירה עצמה היא מימוש, וההיטל ישולם אז.', 'התוספת השלישית לחוק התכנון והבנייה, התשכ"ה-1965: סעיף 1 (הגדרת "מימוש זכויות"), סעיף 3 (שיעור ההיטל) וסעיף 7 (מועד התשלום)', 12, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
