  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q13', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 13', 'בחודש ינואר 2018 רכשה ריקי דירה למגוריה והתגוררה בה במשך שנתיים. בחודש ינואר 2020 החליטה ריקי לגור בשכירות במקום אחר, ולהפעיל בדירה שרכשה מכון ספא יוקרתי. בחודש דצמבר 2023 החליטה ריקי לסגור את הספא ולמכור את הדירה.

בנסיבות העניין, האם תוכל ריקי למכור את הדירה כדירת מגורים מזכה לצורך קבלת פטור ממס שבח? מדוע?', '["כן; כל עוד הדירה שימשה למגוריה בחלק מהתקופה, ניתן למכור אותה כדירת מגורים מזכה.", "כן; הדירה בבעלות פרטית ולכן אין מניעה שתיחשב כדירת מגורים מזכה, גם אם הופעל בה עסק.", "לא; משום שהדירה לא שימשה למגורים ב- 4 שנים שלפני המכירה, וגם לא שימשה למגורים במרבית תקופת השבח.", "לא; אם חלפו יותר מ- 4 שנים מאז מועד הרכישה, לא ניתן למכור דירה כדירת מגורים מזכה לצורך קבלת פטור ממס שבח."]'::jsonb, 2, null, '"דירת מגורים מזכה" מוגדרת בסעיף 1 לחוק מיסוי מקרקעין כדירת מגורים ששימשה בעיקרה למגורים באחת משתי תקופות: ארבע השנים שקדמו למכירה, או 80% מתקופת השבח (התקופה שבין הרכישה למכירה). ריקי גרה בדירה שנתיים מתוך כמעט שש (כשליש מתקופת השבח), ובארבע השנים שלפני המכירה פעל בה ספא, ולכן היא נכשלת בשני המבחנים ואינה זכאית לפטור. חלופה ד ממציאה כלל של "ארבע שנים מהרכישה" שאינו קיים, וחלופות א ו-ב מתעלמות ממבחן השימוש.', 'סעיף 1 לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963 (הגדרת "דירת מגורים מזכה"); פרק חמישי 1 לחוק', 13, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
