insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q14', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 14', 'מאיר חתם על הזמנה בכתב לביצוע פעולת תיווך במקרקעין "בעניין שכירת דירה במגדל ברח'' ההסתדרות 8 בפתח-תקווה", שבו מאיר מעוניין לגור. מיד לאחר החתימה הוצגו בפניו מספר דירות במגדל המבוקש. הפרטים של אותן הדירות לא צוינו במפורש בטופס ההזמנה, למעט כתובת המגדל. עוד באותו היום, הודיע מאיר למתווך שהוא לא מעוניין בדירות שהוצגו בפניו, ודרכיהם של השניים נפרדו. מאיר מעוניין להיפגש עם בעליה של דירה אחרת בבניין המשותף, וחושש שמא יהיה חייב לשלם את עמלת התיווך עליה התחייב בהזמנה.

בנסיבות המתוארות ובהתייחס לפסק הדין בעניין ת"ק 41268-09-12 כהן נ'' גולן, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["פירוט הנכסים לא מהווה חלק מדרישות התקנות בכל הקשור לטופס ההזמנה, ולכן מאיר לא יהיה חייב בדמי תיווך במקרה זה.", "פעולת התיווך לא מתייחסת לדירה הנוספת שמאיר מצא בעצמו באותו בניין, ולכן מאיר לא יהיה חייב בדמי תיווך.", "המתווך זכאי לדמי תיווך גם בגין עיסקה המתייחסת לדירה באותו בניין, וזאת מכוח עיקרון תום הלב.", "המתווך זכאי לדמי תיווך במקרה זה בכל נכס שימצא מאיר באותו הבניין, כי זה בדיוק מה שכתוב בטופס הזמנת שירותי התיווך."]'::jsonb, 1, null, 'הזכאות לדמי תיווך לפי סעיף 14 לחוק המתווכים דורשת שהמתווך היה הגורם היעיל שהביא להתקשרות, וההזמנה בכתב מתייחסת לנכסים שהמתווך הציג בפועל. בפסק הדין כהן נ'' גולן נקבע שדירה אחרת באותו בניין, שהלקוח מצא בכוחות עצמו ובלי שהמתווך הציג אותה, אינה בגדר פעולת התיווך, ולכן אין דמי תיווך. תיאור הנכס הוא דווקא פרט נדרש בטופס ההזמנה (ולכן חלופה א שגויה בנימוקה), וכתובת של בניין שלם אינה הופכת כל דירה בו לנכס שהמתווך תיווך (חלופות ג ו-ד).', 'סעיפים 9(א) ו-14(א) לחוק המתווכים במקרקעין, התשנ"ו-1996; תקנות המתווכים במקרקעין (פרטי הזמנה בכתב), התשנ"ז-1997; ת"ק 41268-09-12 כהן נ'' גולן', 14, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q15', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 15', 'דנה וליאור פנו למתווך חגי בבקשה למציאת רוכש לביתם.
המתווך החתים את בני הזוג על הסכם הזמנת שירותי תיווך והסכם בלעדיות למשך שישה חודשים, אך לא ביצע פעולות לשיווק הנכס. לאחר ארבעה חודשים בני הזוג מכרו את ביתם ללא התערבותו של חגי.

בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["לחגי יש בלעדיות על מכירת הנכס עד 6 חודשים, וכל עוד הדירה נמכרת בזמן הבלעדיות, הוא ייחשב כ''גורם יעיל'' ובכל מקרה דנה וליאור חייבים לשלם לו דמי תיווך.", "חגי לא ביצע פעולות שיווק ולכן תקופת הבלעדיות הסתיימה לאחר 1/3 מהתקופה המנויה בהסכם התיווך, כלומר לאחר חודשיים, וחגי אינו נחשב עוד כ''גורם יעיל''. דנה וליאור לא צריכים להוכיח כי חגי לא היה גורם יעיל.", "בתקופת הבלעדיות מתווך זכאי לדמי תיווך ואין צורך להזדקק לשאלה אם הוא ''גורם יעיל''.", "תקופת הבלעדיות ביחס לדירה היא שלושה חודשים לכל היותר. גם אם הצדדים כתבו בהסכם תקופה העולה על 3 חודשים."]'::jsonb, 1, null, 'בלעדיות לפי סעיף 9 לחוק המתווכים מותנית בכך שהמתווך מבצע את פעולות השיווק שבתוספת לחוק; מתווך שלא ביצע אותן עד תום שליש מתקופת הבלעדיות מאבד אותה בתום השליש, כלומר כאן אחרי חודשיים. חזקת "הגורם היעיל" שבסעיף 14(ב), שלפיה עסקה שנעשתה בתקופת הבלעדיות נחשבת כפרי עבודת המתווך, חלה רק כל עוד הבלעדיות בתוקף, ולכן כשהבית נמכר בחודש הרביעי הנטל אינו על דנה וליאור. חלופה ד ממציאה תקרה של שלושה חודשים (התקרה לדירה היא שישה), וחלופות א ו-ג מתעלמות מתנאי פעולות השיווק.', 'סעיף 9 לחוק המתווכים במקרקעין, התשנ"ו-1996 (בלעדיות ופעולות שיווק) וסעיף 14(ב) (חזקת הגורם היעיל)', 15, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
