insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q16', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 16', 'מיכאל מבקש למכור את הזכויות בבית המגורים שלו, אך לדבריו "צריך לשלם דמי הסכמה למינהל" (רשות מקרקעי ישראל).

בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["הנכס הוא נכס מהוון ולכן יש לשלם דמי הסכמה לרשות מקרקעי ישראל.", "מינהל ההנדסה של הוועדה המקומית דורש תשלום בגין הסכמתו למכירת הנכס.", "הנכס לא מהוון ולכן יש לשלם דמי הסכמה לרשות מקרקעי ישראל.", "תשלום דמי הסכמה למיכאל הוא תנאי הכרחי להעברת זכויות החכירה בנכס לצד ג''."]'::jsonb, 2, null, 'דמי הסכמה הם התשלום שרשות מקרקעי ישראל גובה מחוכר כתנאי להסכמתה להעברת זכויות חכירה שאינן מהוונות, כחלקה בעליית ערך הקרקע. בחכירה מהוונת דמי החכירה לכל התקופה שולמו מראש, ולכן העברת הזכויות פטורה מדמי הסכמה, וחלופה א הפוכה. דמי ההסכמה משולמים לרמ"י ולא למוכר (חלופה ד), ולוועדה המקומית אין כל חלק בעסקה (חלופה ב). העובדה שמיכאל נדרש לשלם מלמדת שהנכס אינו מהוון.', 'חוק רשות מקרקעי ישראל, התש"ך-1960, והחלטות מועצת מקרקעי ישראל בדבר דמי הסכמה בהעברת זכויות חכירה לא מהוונת', 16, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
