insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q17', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 17', 'ראובן הוא בעלים של הזכויות במשק חקלאי במושב יוקרתי. את המשק ראובן מעבד במסגרת האגודה השיתופית של המושב. בצוואה שלו ביקש ראובן להוריש את הנחלה לילדיו בחלקים שווים.

בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["ראובן יכול להוריש את הנחלה לילדיו בחלקים שווים, כי הוא מוגדר כ-\"בר רשות\" בהסכם המשבצת החל על הקרקע.", "ראובן יכול להוריש את הנחלה לילדיו בחלקים שווים, אבל עליו להפקיד את הצוואה אצל הרשם לענייני ירושה ו/או אצל האפוטרופוס הכללי.", "קביעת הבן הממשיך נעשית מראש ומחייבת אישור של האגודה השיתופית ושל רמ\"י.", "לא ניתן להוריש את הנחלה, מכיוון שלחקלאים באגודה שיתופית אין זכות קניינית בקרקע."]'::jsonb, 2, array[2,3]::smallint[], 'במפתח הרשמי של הבחינה התקבלו כנכונות שתי חלופות, ג ו-ד. הנחלה במושב היא מקרקעי ישראל: הקרקע מוחכרת לאגודה (הסכם המשבצת), וראובן מחזיק בה כבר רשות ולא כבעלים, ולכן אין לו זכות קניינית שניתן לחלק בין יורשים (זו הנקודה של חלופה ד). סעיף 114 לחוק הירושה קובע שמשק חקלאי אינו ניתן לחלוקה ועובר ליורש אחד שמוכן ומסוגל לקיימו, ובמושבים הדרך המקובלת היא מינוי "בן ממשיך" מראש, באישור האגודה ורמ"י (חלופה ג). חלוקה שווה בין כל הילדים (חלופות א ו-ב) אינה אפשרית.', 'סעיף 114 לחוק הירושה, התשכ"ה-1965; מוסד "הבן הממשיך" לפי הסכם המשבצת (רמ"י - האגודה השיתופית)', 17, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q18', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 18', 'צחי ודלית רכשו דירה חדשה מקבלן. לצורך רכישת הדירה הם לקחו הלוואה לדיור מהבנק. כאשר ביקשו לרשום את שיעבוד ההלוואה, הקבלן הודיע להם שהרישום אודות השיעבוד בגין לקיחת ההלוואה מהבנק ייעשה ברשם המשכונות וכן במינהל מקרקעי ישראל, וגם בחברה המשכנת.
בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["חברה משכנת פועלת מטעם הבנק לרישום המשכנתא, שכן לזוג אין זכויות בעלות על הדירה, אלא הבעלות על הדירה היא של הבנק עד לסילוק המשכנתא.", "חברה משכנת בונה את הבניין, משכנת בו את הדיירים ומנהלת את רישום הבעלויות בו. החברה המשכנת תרשום ברישומיה את השיעבוד לבנק בגין ההלוואה ואת צחי ודלית כבעלים של הנכס.", "חברה משכנת מנהלת את הרישום בפנקסי המקרקעין (טאבו).", "חברה משכנת בונה את הבניין ומשכנת בו את הדיירים."]'::jsonb, 1, array[1,3]::smallint[], 'במפתח הרשמי של הבחינה התקבלו כנכונות שתי חלופות, ב ו-ד. "חברה משכנת" היא הקבלן או החברה שמנהלת את רישום הזכויות בפרויקט כל עוד הבניין לא נרשם כבית משותף בטאבו; בשלב הזה הזכויות של הרוכשים הן חוזיות, והמשכון לטובת הבנק נרשם אצל רשם המשכונות ומדווח גם לחברה המשכנת (ובקרקע של רמ"י, גם לרמ"י), וזה בדיוק מה שהקבלן תיאר. החברה המשכנת אינה מנהלת את פנקסי המקרקעין (חלופה ג), והבנק אינו הבעלים של הדירה (חלופה א): הוא נושה מובטח בלבד.', 'סעיף 6 לחוק המכר (דירות), התשל"ג-1973 (חובת המוכר לרשום את הזכויות); חוק המשכון, התשכ"ז-1967 (רישום משכון אצל רשם המשכונות)', 18, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q19', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 19', 'ליאור רכש דירה מקבלן בקומה השלישית בפרויקט יוקרה. למרבה הצער, לאחר שהתגורר בדירה כ- 3.5 שנים בלבד, הריצוף בדירה החל לשקוע והתגלו ליקויים נוספים בריצוף, שמקורם בתכנון לקוי. הקבלן סירב לתקן את הליקויים מאחר שלטענתו, בתום תקופת הבדק בגין ליקויים אלו אין לו כל אחריות לביצוע תיקונים בדירה.

בנסיבות המתוארות, האם על הקבלן קיימת חובה לבצע תיקונים לליקויים שבנכס זה? מדוע?', '["לא; לפי הדין תקופת הבדק בגין ליקויים אלו היא שנתיים בלבד, ולכן לאחר תקופה זו אין לקבלן אחריות לביצוע תיקונים.", "כן; מאחר שמדובר בפרויקט ששווק לציבור כפרויקט יוקרה, חובה על הקבלן לדאוג לתיקון ליקויים שהתגלו בדירה בתוך תקופה של 20 שנה מתום תקופת הבדק.", "כן; על הקבלן לתקן את הליקויים, מאחר שחלה כאן תקופת האחריות שבתום תקופת הבדק.", "לא; אם הליקויים לא צוינו בפרוטוקול מסירת הדירה ולא התגלו גם ב- 3 חודשים שלאחר המסירה, הקבלן אינו נושא באחריות בגינם."]'::jsonb, 2, null, 'סעיף 4 לחוק המכר (דירות) מבחין בין שתי תקופות: תקופת הבדק, שנקבעת לכל סוג ליקוי בתוספת לחוק (לריצוף היא קצרה, ובחלופה א היא אכן שנתיים), שבה הקבלן אחראי לכל אי-התאמה אלא אם הוכיח שהקונה גרם לה; ואחריה תקופת אחריות של שלוש שנים נוספות, שבה הקבלן עדיין אחראי, אבל הנטל עובר לקונה להוכיח שמקור הליקוי בתכנון, בעבודה או בחומרים. ליקוי שהתגלה אחרי 3.5 שנים ושמקורו בתכנון לקוי נופל בתוך תקופת האחריות, ולכן הקבלן חייב לתקן. "פרויקט יוקרה" אינו קטגוריה בחוק (חלופה ב), ופרוטוקול המסירה אינו חוסם ליקויים שהתגלו מאוחר (חלופה ד).', 'סעיף 4 לחוק המכר (דירות), התשל"ג-1973, והתוספת לחוק (תקופות הבדק)', 19, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
