  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q20', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 20', 'ביום 15.6.2024 מכרה ורד לשמואל דירת מגורים בסכום של 2 מיליון ש"ח (להלן - הדירה הנמכרת). ורד רכשה את הדירה הנמכרת בשנת 1995. במועד המכירה לשמואל היו בבעלות ורד דירות נוספות, אותן רכשה בשנים קודמות. סוכם בין ורד לשמואל כי במעמד חתימת ההסכם ישלם שמואל לורד 40% מהתמורה, ואת היתרה בתוך 6 חודשים.

האם שמואל וורד חייבים בתשלום מקדמת מס שבח?', '["שמואל וורד לא חייבים בתשלום מקדמת מס שבח, כי ורד רכשה את הדירה בשנת 1995.", "שמואל וורד חייבים בתשלום מקדמת מס שבח; ורד תהיה חייבת בתשלום מקדמת מס שבח בשיעור 7.5% מהתמורה.", "שמואל וורד לא חייבים בתשלום מקדמת מס שבח, כי מס שבח חל על הקונה.", "שמואל וורד חייבים בתשלום מקדמת מס שבח בשיעור 15% מהתמורה."]'::jsonb, 3, null, 'סעיף 15 לחוק מיסוי מקרקעין מטיל על הקונה להעביר למנהל, מתוך התמורה ולאחר ששילם 40% ממנה, מקדמה על חשבון מס השבח של המוכר: 15% מהתמורה כשיום הרכישה של המוכר קודם ל-7.11.2001, ו-7.5% כשיום הרכישה מאוחר יותר. ורד רכשה ב-1995, ולכן המקדמה היא 15%, וחלופה ב שגויה בשיעור. למכירה אין פטור, כי לוורד דירות נוספות ואין זו דירתה היחידה. חלופה ג הפוכה: מס שבח חל על המוכרת, והקונה רק מעביר את המקדמה מתוך הכסף שהיה משלם לה ממילא.', 'סעיף 15 לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963 (מקדמה על חשבון מס השבח)', 20, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q21', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 21', 'יוסף גר בדירת גג בבית משותף ברח'' ז''בוטינסקי בבני ברק. הבית רשום בפנקס הבתים המשותפים וחל עליו התקנון המצוי. כל דייר בבית המשותף משלם עבור הוצאות אחזקת הבית דמי ועד בית בסך 100 ש"ח לחודש. יו"ר ועד הבית דרש מיוסף לשלם דמי ועד בית בסך 200 ש"ח לחודש, הואיל ודירתו של יוסף גדולה פי שתיים מכל שאר הדירות בבניין. יוסף סירב, בטענה שאסור לחייב אותו לשלם יותר מדיירים אחרים בבניין.

בנסיבות המתוארות, האם יוסף צודק בטענתו? מדוע?', '["כן; כל דייר בבית משותף משלם ועד בית בסכום שווה.", "לא; בעל דירה חייב להשתתף בהוצאות הדרושות להחזקתו התקינה ולניהולו של הרכוש המשותף לפי יחס שטח רצפת דירתו אל שטח הרצפה של כל הדירות בבית המשותף.", "לא; בעל דירה חייב לשלם לוועד הבית לפי החלטת ועד הבית ואין התייחסות בחוק לנושא.", "כן; אלא אם יוסף מקבל שירות נוסף מהוועד בגין התשלום הנוסף, ששאר הדיירים אינם מקבלים."]'::jsonb, 1, null, 'סעיף 58(א) לחוק המקרקעין קובע שבעל דירה חייב להשתתף בהוצאות ההחזקה והניהול של הרכוש המשותף לפי יחס שטח רצפת דירתו לשטח הרצפה של כל הדירות, אלא אם נקבע בתקנון שיעור אחר. בבית שחל עליו התקנון המצוי אין הוראה אחרת, ולכן דירה כפולה בשטחה משלמת פי שניים, והדרישה של ועד הבית היא בדיוק לשון החוק. חלוקה שווה (חלופות א ו-ד) היא הכלל רק כשהתקנון קבע כך, והחוק בהחלט מתייחס לנושא (חלופה ג).', 'סעיף 58(א) לחוק המקרקעין, התשכ"ט-1969', 21, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
