insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q22', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 22', 'בית מגורים צמוד קרקע מוצע למכירה. יעל המתווכת מצאה כי קיימת הערת אזהרה לטובת הוועדה המקומית לתכנון ובנייה בדבר תוכנית להפקעת שטח המיועד לדרך המתוכננת לעבור בחלקה עליה בנוי הבית. בתגובה, בעל הנכס עדכן את יעל כי הוועדה המקומית הציעה קרקע חלופית הממוקמת בצידו האחר של המגרש.

בנסיבות המתוארות, האם אכן הוועדה המקומית רשאית לכרות הסכם עם בעלי מקרקעין פרטיים לצורך הפקעה?', '["הוועדה המקומית רשאית לבוא לידי הסכם עם בעל מקרקעין שהופקעו על ידיה, כי במקום תשלום יועברו לו מקרקעין אחרים רק אם התקבל אישור מאת רשות מקרקעי ישראל להסכם.", "בהתאם לחוק, הוועדה המקומית רשאית לשלם פיצויים כספיים בלבד לטובת שטח ההפקעה ולא לתת שטח חלופי.", "הוועדה המקומית לא רשאית לכרות הסכמים עם בעל קרקע פרטי; אם מתקיימת הפקעה, נקבע תשלום זהה ואחיד לכל בעלי הקרקעות בגין ההפקעה.", "הוועדה המקומית רשאית, בתנאים מסוימים, לבוא לידי הסכם עם בעל מקרקעין שהופקעו על ידיה, כי במקום תשלום יועברו לו מקרקעין אחרים."]'::jsonb, 3, null, 'פרק ההפקעות בחוק התכנון והבנייה מאפשר לוועדה המקומית לבוא לידי הסכם עם בעל מקרקעין שהופקעו, שלפיו במקום פיצוי כספי יועברו לו מקרקעין אחרים, וההסכם טעון אישור של מוסד התכנון (הוועדה המחוזית) ולא של רשות מקרקעי ישראל, שאינה צד להפקעה של קרקע פרטית; לכן חלופה א שגויה בתנאי שהיא מציבה. הפיצוי אינו מוגבל לכסף (חלופה ב), ואין "תעריף אחיד" לכל הבעלים (חלופה ג): הפיצוי נקבע לפי שווי המקרקעין שהופקעו.', 'חוק התכנון והבנייה, התשכ"ה-1965, פרק ח'' (הפקעות): הסכם להעברת מקרקעין אחרים במקום פיצויים', 22, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
