insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q23', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 23', 'יואל הוא בעל תואר שני במשפטים ועוסק בתחום הנדל"ן מזה שנים רבות. יואל פעיל במיוחד בעיר הרצליה, בה הוא מתגורר. בעברו היה יואל יזם מקרקעין ובנה מספר בניינים בהרצליה. בנוסף לכך אף עסק בשיווק פרויקטים. כיום יואל מלווה משקיעים ואנשים אשר מעוניינים לייצר הכנסה פאסיבית ולהגיע לחופש כלכלי.
לאחרונה התבקש יואל לבצע הערכת שווי תמורת תשלום לדירת מגורים בבניין בו שיווק מספר דירות בעבר.

בנסיבות המתוארות, איזה מהמשפטים הבאים הוא הנכון ביותר?', '["יואל יכול לבצע הערכת שווי בתנאי שקיבל היתר לכך מלשכת שמאי המקרקעין.", "יואל לא יכול לבצע הערכת שווי בתשלום, אלא אם הוא בעל רישיון שמאי מקרקעין.", "כמשפטן וכיזם נדל\"ן יואל יכול לבצע הערכת שווי בתשלום באזור בו הוא מתמחה.", "יואל יכול לבצע הערכת שווי בתשלום במקרה זה אם הוא בעל רישיון לתיווך במקרקעין."]'::jsonb, 1, null, 'חוק שמאי מקרקעין מייחד את העיסוק בשומת מקרקעין בתמורה למי שרשום בפנקס שמאי המקרקעין, ושום ניסיון, תואר או רישיון אחר אינו תחליף לכך. גם רישיון תיווך אינו מתיר שומה: תקנה 24 לתקנות האתיקה אוסרת על מתווך שאינו שמאי לעסוק בשומת מקרקעין (הערכת מחיר שיווקית לצורך התיווך היא עניין אחר, ואינה "שומה" בתשלום). לשכת השמאים היא גוף מקצועי ואינה מנפיקה "היתרים" (חלופה א), והתמחות באזור (חלופה ג) אינה שיקול בחוק.', 'חוק שמאי מקרקעין, התשס"א-2001 (ייחוד העיסוק); תקנה 24 לתקנות המתווכים במקרקעין (אתיקה וחובות מקצועיות), התשפ"ד-2024', 23, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
