  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q24', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 24', 'נמרוד הוא מתווך מקרקעין מזה 15 שנים. בינואר 2023 החתים נמרוד את משה על טופס הזמנת שירותי תיווך בנוגע לרכישת דירה בקומה חמישית ואחרונה בבניין בפתח תקווה ששווייה הועמד על סך 2 מיליון ש"ח. משה התחייב לשלם דמי תיווך בשיעור 2% משווי העיסקה, אולם היתנה את רכישת הדירה בכך שניתן יהיה לבנות תוספת של 2 חדרים מעל הדירה.
נמרוד הבטיח למשה שאכן יש היתר לבנות את התוספת מעל הדירה, אך ידע, ולא טרח לציין בפניו כי ההיתר בתוקף רק עד חודש מרץ 2023. בחודש מרץ 2023 נחתם הסכם מכר, ומשה שילם לנמרוד את דמי התיווך במלואם. בבדיקה שערך משה מול העירייה התברר לו כי נמרוד לא אמר לו שההיתר הוגבל בזמן, וכעת ההיתר לא רלוונטי. משה טוען כי נמרוד הפר את חובותיו המקצועיות כלפיו.

בנסיבות המתוארות, האם משה צודק? מדוע?', '["לא; היה על משה לבצע את כל הבדיקות הרלוונטיות בקשר לדירה ולא לסמוך על נמרוד בעניין.", "לא; נמרוד לא מוסמך לייעץ בנושאים של תכנון ובנייה בנכס שהוא מתווך.", "כן; ההגבלה בזמן היא פרט מהותי שהיה ידוע לנמרוד והיה עליו לגלותו למשה במסגרת חובת הנאמנות והגילוי שלו כלקוח כמתווך.", "כן; אבל רק אם נמרוד מייצג את משה בלבד ולא גם את הצד השני."]'::jsonb, 2, null, 'סעיף 8(א) לחוק המתווכים מחייב מתווך לפעול בנאמנות, בהגינות ובדרך מקובלת, ולמסור ללקוחו כל מידע מהותי שיש בידו על הנכס. תוקף ההיתר הוא מידע מהותי במיוחד כאן, כי משה התנה את הרכישה כולה באפשרות הבנייה, ונמרוד ידע ושתק. תקנות האתיקה מחזקות זאת: תקנה 4 אוסרת הטעיה גם במחדל, ותקנה 7(ג) דורשת שמידע תכנוני יימסר עם ציון המקור הרשמי שעליו הוא נשען. חובת הבדיקה של הלקוח (חלופה א) אינה מבטלת את חובת הגילוי של המתווך, וחובת הגילוי אינה תלויה בשאלה אם המתווך מייצג גם את הצד השני (חלופה ד).', 'סעיף 8(א) לחוק המתווכים במקרקעין, התשנ"ו-1996; תקנות 4 ו-7 לתקנות המתווכים במקרקעין (אתיקה וחובות מקצועיות), התשפ"ד-2024', 24, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2024-11-q25', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, נובמבר 2024, שאלה 25', 'ניב מעוניין למכור חנות ברחוב דיזנגוף בתל אביב בסכום של 4 מיליון ש"ח. החנות היא הנכס היחיד שבבעלות ניב, לא היה בבעלותו כל נכס אחר ב- 4 השנים האחרונות, והוא לא מכר כל נכס בפטור ממס שבח בארבע השנים האחרונות.

בנסיבות המתוארות, האם ניב זכאי לפטור ממס שבח?', '["כן; החנות היא הנכס היחיד של ניב ולכן הוא זכאי לפטור מלא ממס שבח.", "כן; ניב מעולם לא השתמש בפטור ממס שבח ולכן הוא זכאי לפטור מלא.", "לא; מכירת נכס במחיר של 4 מיליון ש\"ח אינה מזכה בפטור ממס שבח.", "לא; חנות לא פטורה ממס שבח במכירתה."]'::jsonb, 3, null, 'הפטור ממס שבח שבפרק חמישי 1 לחוק מיסוי מקרקעין (סעיף 49ב) ניתן רק במכירת "דירת מגורים מזכה". חנות אינה דירת מגורים, ולכן כל הנתונים בשאלה - נכס יחיד, היעדר פטור קודם, ארבע שנים - אינם רלוונטיים: הם תנאים של פטור שחל רק על דירות. חלופה ג טועה בנימוק: תקרת השווי (כ-4.5 מיליון ש"ח, מתעדכנת) נוגעת לדירת מגורים מזכה ולא לנכס עסקי, והסכום לבדו אינו השאלה.', 'סעיף 49ב לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963 (פטור לדירת מגורים מזכה)', 25, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2024-11'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'exam-2025-02', 'מבחן פברואר 2025', 4, 'מבחן פברואר 2025 הוא מבחן של פסיקה: שלוש שאלות נוקבות בשם פסק דין ודורשות לדעת מה נפסק בו, ושאלה אחת (9) בוטלה וכל תשובה בה התקבלה. ברוב השאלות התשובה פותחת ב"כן" או "לא" ואחריו נימוק - ושתי החלופות שפותחות באותה מילה נבדלות רק בנימוק, שם נופלים.', '<p>25 שאלות, ארבע חלופות לכל אחת, ציון עובר 60. לפי הספירה שלנו, השאלות הגיעו מהחוקים האלה:</p><ul><li><strong>חוק המתווכים במקרקעין, תקנותיו ופסיקת דמי התיווך</strong> - 7 שאלות (2, 3, 13, 14, 18, 19, 24): רישיון והזמנה בכתב, מע"מ בהזמנה, הגורם היעיל בבלעדיות, גילוי מידע מהותי, פרסום בלי רישיון, ופעולות השיווק.</li><li><strong>דיני חוזים</strong> - 4 שאלות (4, 20, 23, 25): כריתה בלי חתימה (רבינאי נ'' מן שקד), הצעה בלתי חוזרת, סייגי האכיפה, ותנאי מקפח בחוזה אחיד.</li><li><strong>חוק המכר (דירות) והמפרט</strong> - 3 שאלות (1, 11, 16): איחור במסירה, סטיית שטח, ותקופת הבדק בתמ"א 38.</li><li><strong>חוק המקרקעין</strong> - 3 שאלות (5, 17, 21): הצמדה בבית משותף, זיקת הנאה מכוח שנים, והערות אזהרה.</li><li><strong>חוק מיסוי מקרקעין</strong> - 3 שאלות (6, 15, 22): הורשה, "מוכר אחד", והעברה אגב גירושין.</li><li><strong>חוק התכנון והבנייה</strong> - 3 שאלות (9, 10, 12): איחוד וחלוקה, שימוש חורג, וערר על ועדה מקומית.</li><li><strong>חוק הגנת הדייר</strong> - שאלה אחת (8), ו<strong>חוזה פיתוח של רשות מקרקעי ישראל</strong> - שאלה אחת (7).</li></ul><p>שאלה 9 בוטלה על ידי הרשם: במפתח התשובות הרשמי כל ארבע החלופות התקבלו. כאן היא מוצגת עם התשובה הנכונה מבחינת הדין, כדי שתדעו מה זו תוכנית איחוד וחלוקה.</p>', '["שלוש שאלות נוקבות בשם פסק דין (רבינאי נ'' מן שקד, זיוה וזאב מאיר נ'' טלי שושן, עודד סיטי נ'' טל פרי). לומדים לא רק את הכלל אלא מה נפסק בכל אחד מהם.", "ברוב השאלות שתי חלופות פותחות ב\"כן\" ושתיים ב\"לא\". לקבוע את הכיוון זה חצי עבודה - הנימוק הוא מה שמפריד בין הנכונה לבין המסיחה.", "דמי תיווך הם שלושה תנאים מצטברים (סעיף 14 לחוק): רישיון בתוקף, הזמנה בכתב, גורם יעיל. חסר אחד - אין דמי תיווך, גם אם הלקוח יזם את הפנייה.", "שאלות המספרים נפתרות בחישוב: 13.5 מ\"ר מתוך 750 הם 1.8%, מתחת לסטייה של 2% שהמפרט מתיר. חשבו לפני שמנחשים.", "שימו לב למילים בשאלה מול המילים בחלופות: שאלה 17 שואלת על \"הערת אזהרה\" אבל כל החלופות עוסקות בזיקת הנאה, ושאלה 15 נשענת על חריג אחד בהגדרת \"מוכר אחד\" - בן זוג הגר דרך קבע בנפרד."]'::jsonb, '[]'::jsonb, 'רשם המתווכים במקרקעין, מועד 02.02.2025, גרסה 1', null, false, true
  from public.course_chapters c where c.slug = 'past-exams'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q01', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 1', 'ביום 1.1.2020 רכשה גילה דירת מגורים חדשה מקבלן. הקבלן התחייב בהסכם המכר להעמיד לרשות גילה את הדירה בתוך שנה מיום הרכישה. הבנייה התעכבה עקב מחלוקת פנימית בין הקבלן לבין עובדיו, וכתוצאה מכך הקבלן העמיד את הדירה לרשות גילה באיחור של 7 חודשים מהמועד שנקבע בהסכם. בהסכם לא נקבע מנגנון לפיצוי במקרה כזה.
האם זכאית גילה לפיצוי מהקבלן בגין העיכוב במסירת הדירה? מדוע?', '["לא; שבעה חודשים זו תקופת איחור סבירה, ולא תקופה שבגינה מגיע פיצוי בגין איחור במסירה לפי החוק.", "כן; בכל מקרה מגיע לגילה פיצוי, מכיוון שמדובר בהפרת החוזה. זאת, גם אם העיכוב הוא רק של יום.", "כן; גילה זכאית לפיצוי, אך זאת רק לאחר שחלפו שישים יום מתום המועד הקבוע לכך בחוזה המכר.", "לא; אלא אם גילה תצליח להוכיח את נזקיה."]'::jsonb, 2, null, 'סעיף 5א לחוק המכר (דירות) קובע פיצוי סטטוטורי, בלא הוכחת נזק, לקונה שדירתו לא נמסרה במועד החוזי - ולכן אין צורך בסעיף פיצוי בהסכם ואין צורך להוכיח נזק (חלופה ד נופלת). בנוסח הסעיף שחל על חוזה משנת 2020, הפיצוי מגיע כאשר האיחור עולה על שישים ימים מהמועד שנקבע בחוזה, ולכן איחור של יום (חלופה ב) אינו מזכה, ושבעה חודשים ודאי אינם "סבירים" (חלופה א). הסייג היחיד בסעיף הוא איחור שנגרם מנסיבות שאינן בשליטת המוכר, ומחלוקת פנימית עם עובדיו היא בשליטתו.', 'סעיף 5א לחוק המכר (דירות), התשל"ג-1973', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q02', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 2', 'יוסי עסק בתיווך מקרקעין ב- 5 השנים האחרונות לסירוגין. יוסי פגש את גילה במקרה בבית קפה בקניון לב המפרץ, והיא ספרה לו שהיא מעוניינת למכור את הדירה המדהימה שלה בקרית מוצקין בסכום של 2 מיליון שקל. יוסי ענה, שאמנם רישיון התיווך שלו, כפי שהיה באותה עת, אינו בתוקף, אולם הוא יהיה מוכן לסייע בכל זאת עם התיווך במקרה זה. יוסי איתר עבור גילה קונה, אשר רכש מגילה את הדירה במהירות, לפני שיוסי הספיק לחדש את רישיון התיווך שלו, ולפני שהספיק לשלוח לגילה טופס הזמנת תיווך לחתימתה. לאחר כחודש שלח יוסי לגילה דרישת תשלום דמי תיווך בשיעור 2% משווי העיסקה. גילה סירבה לשלם ליוסי דמי תיווך, בטענה כי יוסי אינו זכאי לדמי תיווך, הואיל ואינו עומד בתנאי החוק.
בנסיבות אלה, האם לפי החוק גילה חייבת בתשלום דמי התיווך?', '["כן; יוסי היה הגורם היעיל בעיסקה, ולכן עמד בתנאים לזכאות לתשלום דמי תיווך.", "לא; זאת משום שיוסי לא היה הגורם היעיל בעיסקה.", "לא; משום שיוסי לא מחזיק בהזמנת תיווך בכתב כדין, ולא היה בעל רישיון תיווך בתוקף במועד העיסקה.", "כן; מכיוון שלפי החוק אם הלקוח יזם את הפניה למתווך הוא חייב לשלם דמי תיווך אזי הוא חייב לשלם דמי תיווך בכל מקרה."]'::jsonb, 2, null, 'סעיף 14(א) לחוק המתווכים קובע שלושה תנאים מצטברים לדמי תיווך: המתווך היה בעל רישיון בתוקף בעת שעסק בתיווך, הלקוח חתם על הזמנה בכתב לפי סעיף 9, והמתווך היה הגורם היעיל. יוסי אמנם היה הגורם היעיל (ולכן חלופה ב שגויה), אבל שני התנאים האחרים חסרים - אין רישיון בתוקף ואין הזמנה בכתב - ודי בכל אחד מהם כדי לשלול את הזכאות. העובדה שגילה פנתה אליו מיוזמתה אינה תנאי בחוק (חלופה ד), ועיסוק בתיווך בלי רישיון הוא גם עבירה לפי סעיף 2.', 'סעיפים 2, 9 ו-14(א) לחוק המתווכים במקרקעין, התשנ"ו-1996', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q03', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 3', 'מתווך החתים לקוח על טופס הזמנת שירותי תיווך. בהזמנה נכתב כי ״דמי התיווך יעמדו על 2% ממחיר העיסקה״. הלקוח הבין כי מחיר זה כולל מע״מ ואמר זאת, והמתווך מצידו לא תיקן את הלקוח. העיסקה בוצעה כדין, והמתווך כעת זכאי לדמי תיווך. אלא שאז התגלעה מחלוקת בין הצדדים לגבי שאלת המע״מ: המתווך שביצע את העיסקה דורש מהלקוח לשלם דמי תיווך של 2% בתוספת מע״מ. הלקוח טוען כי המע״מ לא צוין בהזמנת התיווך ולכן אין להוסיפו.
בנסיבות אלה, האם יש חובה לכתוב במפורש את תוספת המע״מ בהזמנת התיווך?', '["אין חובה שחלה על המתווך להתייחס למע״מ בהזמנת תיווך.", "קיימת חובה על המתווך להתייחס לשאלה האם דמי התיווך כוללים מע״מ.", "רק כאשר הקונה הינו עוסק מורשה, על המתווך להתייחס למע״מ.", "אין חובה שחלה על המתווך להתייחס למע״מ בהסכם הזמנת תיווך כיוון שהמע״מ נגבה לפי שיעור המע״מ בעת החתימה על ההסכם."]'::jsonb, 1, null, 'תקנות המתווכים במקרקעין (פרטי הזמנה בכתב) מונות את הפרטים שחובה לכלול בהזמנה לפי סעיף 9(א) לחוק, וביניהם הסכום המוסכם של דמי התיווך או שיעורם, והאם הוא כולל מס ערך מוסף. החובה חלה על המתווך בכל הזמנה, בלי קשר לשאלה אם הלקוח עוסק מורשה (חלופה ג) ובלי קשר לשיעור המע"מ ביום החתימה (חלופה ד). מתווך שלא ציין זאת, ועוד שתק כשהלקוח אמר שהוא מבין שהמחיר כולל מע"מ, יתקשה לדרוש את התוספת.', 'תקנות המתווכים במקרקעין (פרטי הזמנה בכתב), התשנ"ז-1997; סעיף 9(א) לחוק המתווכים', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q04', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 4', 'מוכר מקרקעין שלח הצעה להסכם מכר בדואר אלקטרוני, הכוללת את כל הפרטים הנדרשים לצורך ההצעה, ואת חתימתו. הקונה לא חתם על ההזמנה אך שלח הודעה בדוא״ל כי גמר אומר בדעתו לאשר את ההסכם.
לפי פסק הדין ע״א 158/77 רבינאי נגד מן שקד, האם בנסיבות אלה נכרת הסכם מכר מחייב בין המוכר והקונה?', '["אם הרוכש אינו חותם על החוזה במקום המיועד לכך, אז לא נכרת מצד הרוכש חוזה מחייב.", "נכרת חוזה מחייב בין הצדדים, אך ורק בתנאי שבחוזה מצוין כי אישור באמצעות שליחת דואר אלקטרוני יהווה תחליף לחתימה של הרוכש על המסמך.", "בין הצדדים נכרת חוזה מחייב ללא חתימת הרוכש.", "נכרת חוזה מחייב בין הצדדים אך ורק אם מוכר מאשר לאחר חתימת הרוכש באמצעות דואר אלקטרוני כי הוא מאשר סופית את העיסקה."]'::jsonb, 2, null, 'בע"א 158/77 רבינאי נ'' מן שקד נקבע כי חוזה נכרת כשיש גמירות דעת ומסוימות (סעיפים 1, 2 ו-5 לחוק החוזים), וכי חתימה היא ראיה לגמירות דעת ולא תנאי לקיומה. דרישת הכתב בסעיף 8 לחוק המקרקעין מתקיימת כאן, כי ההצעה המפורטת נשלחה בכתב, וגמירות דעתו של הקונה הוכחה בהודעת הדוא"ל שבה גמר אומר לאשר. שאר החלופות ממציאות תנאים שאינם בדין - תניה בחוזה על אישור בדוא"ל או אישור סופי נוסף של המוכר.', 'ע"א 158/77 רבינאי נ'' מן שקד; סעיפים 1, 2 ו-5 לחוק החוזים (חלק כללי), התשל"ג-1973; סעיף 8 לחוק המקרקעין', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q05', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 5', 'הדיירים בבית משותף ברחוב אלנבי בתל אביב מבקשים לחזק את הבניין מפני רעידות אדמה, ולהוסיף ארבע דירות חדשות. במסגרת הפרויקט מבקשים הדיירים להוציא חלק מהרכוש המשותף ולהצמיד לכל דירה חדשה חניה. זאת מתוך הרכוש המשותף בבית המשותף.
במקרה זה, מהו הרוב הדרוש לשם אישור הצמדת החניות לדירות ספציפיות?', '["2/3 של בעלי הדירות ש- 3/4 מהרכוש המשותף צמודים לדירותיהם.", "רוב רגיל של בעלי הדירות.", "ניתן לאשר הצמדה של רכוש משותף לרכוש פרטי אך ורק על פי תביעה למפקח על הבתים המשותפים.", "כל בעלי הדירות."]'::jsonb, 3, null, 'הכלל בחוק המקרקעין הוא שהוצאת חלק מהרכוש המשותף והצמדתו לדירה מסוימת היא שינוי תקנון שפוגע בזכויות הקניין של כל בעלי הדירות, ולכן היא טעונה הסכמת כולם (סעיף 62(א)), ולא רוב רגיל ולא תביעה אצל המפקח. הרובות המיוחדים של חוק חיזוק בתים משותפים מפני רעידות אדמה (תמ"א 38) מקלים על ההחלטה על החיזוק ועל הבנייה עצמה, אך השאלה מתמקדת באישור ההצמדה של החניות לדירות ספציפיות, ועל כך הרשם קבע שנדרשת הסכמת כל בעלי הדירות. חלופה א משלבת מספרים שאינם קיימים יחד בשום סעיף (2/3 עם 3/4).', 'סעיף 62(א) לחוק המקרקעין, התשכ"ט-1969; חוק המקרקעין (חיזוק בתים משותפים מפני רעידות אדמה), התשס"ח-2008', 5, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q06', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 6', 'אדם ירש מקרקעין מסחריים מכוח צוואה של אביו, וכעת מבקש לרשום את המקרקעין המסחריים על שמו.
האם הירושה מהווה מכירה מהוריו אליו לצורכי מיסוי מקרקעין?', '["לצורכי מיסוי מקרקעין הורשה אינה נחשבת כמכירה, אך היא נחשבת כרכישה מקרוב משפחה.", "לצורכי מיסוי מקרקעין הורשה אינה נחשבת כרכישה, אלא אם מדובר בנכס מסחרי, אז הירושה מחויבת בשליש מס רכישה.", "הורשה נחשבת כמכירה לצורך מיסוי מקרקעין, והיא מחויבת בשליש מס שבח.", "הורשה אינה נחשבת כמכירה לצורכי מיסוי מקרקעין, גם אם מדובר בנכס מסחרי."]'::jsonb, 3, null, 'סעיף 4 לחוק מיסוי מקרקעין קובע במילים פשוטות: "הורשה איננה מכירה" לעניין החוק. לכן אין מס שבח ואין מס רכישה בהעברת הנכס מהמוריש ליורש, ואין בחוק הבחנה בין דירת מגורים לנכס מסחרי. "שליש מס רכישה" (חלופה ב) הוא השיעור המוקטן שחל על מתנה לקרוב בחיים, לא על ירושה, ו"רכישה מקרוב משפחה" (חלופה א) אינה מושג שחל על הורשה. המס יחול רק כשהיורש ימכור בעתיד, ואז ייכנס בנעלי המוריש לעניין יום הרכישה ושוויה.', 'סעיף 4 לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963', 6, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q07', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 7', 'מהו ׳חוזה פיתוח׳ שנכרת עם רשות מקרקעי ישראל (מינהל מקרקעי ישראל)?', '["חוזה שמקנה לרוכש הזכויות בקרקע מסוימת זכויות חכירה בנכס מקרקעין בלבד.", "חוזה שבו רשות מקרקעי ישראל מזמינה שירותי בנייה מקבלן.", "חוזה שלפיו רוכש זכויות בקרקע מתחייב לבנות בפרק זמן נתון נכס, ואחרי הבנייה יתקשר עם הרשות בהסכם חכירה.", "חוזה שלפיו הרשות מפתחת עבור רוכש זכויות בקרקע מסוימת את הקרקע או הנכס."]'::jsonb, 2, null, 'חוזה פיתוח הוא השלב הראשון בהקצאת קרקע של המדינה: רשות מקרקעי ישראל מעניקה ליזם זכות להחזיק בקרקע ולבנות עליה בתוך תקופה קצובה (בדרך כלל שלוש שנים), ורק לאחר שעמד בתנאי הפיתוח והשלים את הבנייה נחתם עמו חוזה חכירה לתקופה ארוכה. הרשות אינה מזמינה בנייה ואינה מפתחת עבור היזם (חלופות ב ו-ד), והחוזה אינו מקנה חכירה מיידית (חלופה א) - החכירה היא התוצאה של עמידה בחוזה הפיתוח.', 'נוהלי רשות מקרקעי ישראל - חוזה פיתוח וחוזה חכירה', 7, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
