insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q08', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 8', 'האם דייר מוגן לפי חוק הגנת הדייר רשאי למכור את זכויות הדיירות המוגנת ולהציע דייר אחר במקומו? אם כן, כיצד?', '["רשאי לעשות כן מבלי לקבל את הסכמת הבעלים של הנכס.", "אינו רשאי למכור את זכות הדיירות המוגנת.", "רשאי לעשות כן רק אם הנכס הינו דירת מגורים ולא נכס מסחרי.", "רשאי לעשות כן באמצעות פנייה תחילה לבעלים בצירוף תצהירים."]'::jsonb, 3, null, 'חוק הגנת הדייר מסדיר בפרק "דייר יוצא ודייר מוצע" מנגנון שבו דייר מוגן המבקש לצאת מהמושכר מציע דייר אחר במקומו: הוא פונה לבעל הבית ומצרף תצהירים של הדייר היוצא ושל הדייר המוצע עם פרטי העסקה, ולבעל הבית תקופה קצובה להשיב - לקבל את הדייר המוצע, או לרכוש בעצמו את הזכות ולשלם לדייר את חלקו בדמי המפתח. לכן הזכות קיימת (חלופה ב שגויה), היא אינה מותנית בסוג הנכס (חלופה ג), אך גם אינה חופשית מכל פנייה לבעלים (חלופה א).', 'סעיף 85 ואילך לחוק הגנת הדייר [נוסח משולב], התשל"ב-1972 (דייר יוצא ודייר מוצע)', 8, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q09', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 9', 'בדרומה של העיר תל אביב קיים בניין בן 4 קומות, ובו משרדים מעל קומת מסחר. הבניין נבנה בהיתר לפני 50 שנה. יוסי הינו בעל הזכויות במשרד בבניין, בשטח של כ- 50 מ"ר. לאחרונה גילה יוסי כי קיימת תוכנית בניין עיר חדשה למתחם שבו ממוקם הבניין. התוכנית הינה ״תוכנית איחוד וחלוקה ללא הסכמת דיירים״, ומטרתה לקדם התחדשות עירונית במתחם, אשר סובל מהזנחה מתמשכת.
בנסיבות אלה, מה המשמעות של תוכנית איחוד וחלוקה (רה-פרצלציה)?', '["תוכנית איחוד וחלוקה מאפשרת במסגרת התחדשות עירונית לנצל זכויות בנייה בלבד.", "תוכנית שניתן לקדם במגרשים פנויים בלבד, לרבות בשטח משותף, לשינוי יעוד קרקע בלבד.", "תוכנית לאיחוד וחלוקה של מגרשים שאינם סמוכים, וחלוקתם מחדש, כדי לאפשר פיתוח השטח וניצולו המקסימלי.", "תוכנית שבה נקבעות בעלויות וקווי גבול ובסופה הקרקע הופכת להיות מוסדרת."]'::jsonb, 2, null, 'שאלה זו בוטלה: במפתח התשובות הרשמי של הרשם כל ארבע החלופות התקבלו כנכונות, כנראה בגלל הניסוח בחלופה ג ("מגרשים שאינם סמוכים"). מבחינת הדין, תוכנית איחוד וחלוקה (רה-פרצלציה) לפי סימן ז'' לפרק ג'' של חוק התכנון והבנייה היא תוכנית שמאחדת מגרשים קיימים למקשה אחת ומחלקת אותם מחדש, בהסכמת הבעלים או בלעדיה, כדי לאפשר פיתוח יעיל של השטח, ובעל זכויות במגרש הישן מקבל זכויות במגרש חדש לפי שוויו היחסי. היא אינה מוגבלת לניצול זכויות בנייה (חלופה א), אינה למגרשים פנויים בלבד (חלופה ב), ואינה הליך הסדר קרקעות (חלופה ד).', 'סעיף 121 לחוק התכנון והבנייה, התשכ"ה-1965 (איחוד וחלוקה)', 9, false
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q10', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 10', 'עמי ותמי שותפים בעסק למכירת ממתקים. לאחרונה הקימו מפעל חדש בצפון הארץ, והחליטו לרכוש מכספי החברה בית מגורים בבעלות פרטית בקרית שמונה. בית אשר יותאם כך שישמש כחנות למכירת הממתקים שלהם, וזאת באמצעות התקנת מדפים ותשתית מיחשוב. הניחו כי בית המגורים נבנה בהיתר כדין.
בנסיבות אלה, איזה מההיגדים הבאים הוא הנכון ביותר?', '["עמי ותמי אינם יכולים להשתמש בבית המגורים לשימוש מסחרי.", "עמי ותמי יכולים להשתמש בבית המגורים לשימוש מסחרי, שכן אין איסור בישראל להשתמש בבית מגורים לצורך מסחרי, גם אם לא גרים בו.", "עמי ותמי צריכים להגיש בקשה לוועדה לתכנון ובניה לשינוי יעוד של הבית והסבתו מבית מגורים למסחר.", "עמי ותמי צריכים להגיש בקשה לשינוי יעוד לרשות מקרקעי ישראל ולקבל את הסכמתה לשינוי."]'::jsonb, 2, null, 'שימוש במבנה למטרה שונה מזו שנקבעה לו בהיתר או בתוכנית הוא "שימוש חורג" לפי חוק התכנון והבנייה, והוא אסור בלי היתר (סעיף 145). הדרך החוקית היא לפנות לוועדה המקומית לתכנון ובנייה בבקשה להיתר לשימוש חורג או לשינוי ייעוד (סעיף 146), ולכן חלופה ב שגויה - יש איסור, וחלופה א מוחלטת מדי - יש דרך לקבל היתר. רשות מקרקעי ישראל (חלופה ד) היא בעלת קרקע ולא מוסד תכנון, ובקרקע בבעלות פרטית אין לה מעמד.', 'סעיפים 145-146 לחוק התכנון והבנייה, התשכ"ה-1965 (שימוש חורג)', 10, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q11', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 11', 'דניאל רכש דירת יוקרה ענקית בגודל 750 מ״ר מחברת נדל"ן, שמשווקת פרויקט מגורים בתל אביב. נאמר לדניאל על ידי נציגי הקבלן שעשויים להיות שינויים של עד 13.5 מ"ר בשטח הבנוי שדניאל יקבל בפועל, בהשוואה לתשריט שנחתם בין הצדדים. דניאל חושש שיאבד חדר שלם בדירת היוקרה שלו וייגרעו מדירתו 13.5 מ"ר.
בנסיבות האמורות, האם לדניאל יש זכות לקבלת המטרים המלאים כפי שהיו בתשריט?', '["סטייה בשטח בשיעור העולה על 2% היא סטייה מהותית (לא סטייה קבילה), לכן דניאל זכאי לקבל את המטרים המדויקים אחד לאחד אל מול התשריט.", "סטייה בשטח בשיעור העולה על 5% היא סטייה מהותית (לא סטייה קבילה), לכן דניאל זכאי לקבל את המטרים המלאים מהתשריט.", "סטייה של עד 2% אינה מהותית ומהווה סטייה קבילה אל מול התשריט ולכן דניאל אינו זכאי לקבל את המטרים המדוברים בנסיבות אלה.", "סטייה בשיעור העולה על 5% היא סטייה לא מהותית (כלומר סטייה קבילה), אך דניאל יהיה זכאי לפיצוי בגין המטרים המופחתים."]'::jsonb, 2, null, 'המפרט שהמוכר חייב לצרף לחוזה לפי חוק המכר (דירות), בנוסח שנקבע בצו מכר דירות (טופס של מפרט), קובע שסטייה של עד 2% בשטח הדירה אינה נחשבת סטייה מהמפרט. כאן החישוב מכריע: 13.5 מ"ר מתוך 750 מ"ר הם 1.8%, כלומר בתוך גבול הסטייה המותרת, ולכן דניאל אינו זכאי למטרים המלאים ולא לפיצוי. חלופות ב ו-ד נוקבות בסף של 5% שאינו קיים, וחלופה א מציגה את הכלל הנכון אך מיישמת אותו הפוך - הסטייה כאן קטנה מ-2%.', 'סעיף 2 לחוק המכר (דירות), התשל"ג-1973; צו מכר דירות (טופס של מפרט), התשל"ד-1974', 11, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q12', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 12', 'יוסי, בעל זכויות במקרקעין שלגביהם קיימת הצעה של תוכנית בניין עיר מפורטת, הגיש התנגדות לתוכנית האמורה בפני ועדה מקומית עצמאית לתכנון ובנייה הוד השרון. הוועדה דחתה את התנגדותו.
בנסיבות המתוארות, איזה מההיגדים הבאים הוא הנכון ביותר?', '["יוסי רשאי לפנות להליך של ערר בוועדת ערר לתכנון ובנייה.", "אין אפשרות להתערב בהחלטה של ועדה לתכנון ובנייה.", "יוסי יכול להגיש ערר לוועדת ערר לתכנון ובנייה, אך רק אם לא קיבל רשות לבנות כפי שביקש.", "יוסי יכול להגיש ערר לבית משפט בלבד."]'::jsonb, 0, null, 'חוק התכנון והבנייה מקים ועדת ערר מחוזית, ומי שהתנגדותו לתוכנית שבסמכות ועדה מקומית נדחתה רשאי לערור עליה לוועדת הערר. זו הדרך הראשונה והטבעית לתקוף את ההחלטה, ורק אחריה, אם יש צורך, פונים לבית המשפט לעניינים מינהליים - ולכן "בית משפט בלבד" (חלופה ד) שגוי, וכך גם "אין אפשרות להתערב" (חלופה ב). זכות הערר על דחיית התנגדות אינה מותנית בבקשת היתר בנייה (חלופה ג) - היא נוגעת לתוכנית, לא להיתר.', 'חוק התכנון והבנייה, התשכ"ה-1965 - התנגדות לתוכנית (סעיף 100) וערר לוועדת הערר המחוזית על החלטת ועדה מקומית', 12, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q13', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 13', 'המתווך יצחק מייצג את סימה ודוד, שמבקשים לרכוש דירה לעצמם, בהתאם לטופס הזמנת שירותי תיווך, שנחתם כדין ביניהם לבין יצחק. יצחק מצא דירה שמתאימה לרצונותיהם של סימה ודוד, שבה משה ופזית אשתו מתגוררים. סימה ודוד ביקרו בנכס ובאותו מועד חתמו עם משה על חוזה לרכישת הדירה. בהמשך הסתבר שמשה הוא בעלים רק של מחצית הדירה, כפי שהיה ידוע למתווך יצחק. מחצית הדירה השנייה שייכת לאשתו, אשר סירבה לחתום על הזמנת התיווך ומתנגדת למכירת הדירה. עקב התנגדותה של פזית, החוזה בוטל על ידי סימה ודוד.
לפי פסק הדין בבר״ע 209/01 זיוה וזאב מאיר נ׳ טלי שושן, האם המתווך יצחק זכאי לדמי תיווך מהזוג סימה ודוד בנסיבות אלה?', '["כן; לפי פסק הדין מתווך זכאי לדמי תיווך מרגע שנחתם הסכם ואין לכך סייגים.", "כן; משום שהחוזה בוטל לאחר כריתתו והצדדים כרתו ביניהם את החוזה.", "לפי פסק הדין, המתווך יהיה זכאי למחצית דמי התיווך במצב שכזה.", "לא; המתווך יצחק היה צריך לגלות לרוכשים הפוטנציאליים כי פזית היא בעלים נוסף בנכס, ולכן הוא אינו זכאי לדמי תיווך."]'::jsonb, 3, null, 'בבר"ע 209/01 זיוה וזאב מאיר נ'' טלי שושן נפסק שמתווך שידע כי המוכר אינו הבעלים היחיד של הנכס והסתיר זאת מהקונים הפר את חובת ההגינות והזהירות שבסעיף 8 לחוק המתווכים ואת חובת גילוי המידע המהותי, ולכן אינו זכאי לדמי תיווך כשהעסקה קרסה בגלל אותו מידע. חתימת החוזה אינה סוף פסוק (חלופות א ו-ב): המתווך חייב להביא לעסקה תקפה, וחוזה עם מי שאינו בעל כל הזכויות אינו כזה. "מחצית דמי תיווך" (חלופה ג) אינה קונסטרוקציה שהדין מכיר.', 'בר"ע 209/01 זיוה וזאב מאיר נ'' טלי שושן; סעיפים 8 ו-14 לחוק המתווכים במקרקעין', 13, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
