  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q14', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 14', 'המתווך עודד התבקש על ידי דפנה לייצג אותה במכירת דירת המגורים שלה. דפנה חתמה לעודד על הזמנת תיווך כדין והסכם בלעדיות. עודד ביצע שתי פעולות תיווך בנכס כדין, שאחת מהן הייתה לתלות שלט בדירה הנמכרת. דפנה עצמה פירסמה את הדירה בקבוצת וואטסאפ, שבה חבר שלמה הרוכש. שלמה הגיע למקום, הרים טלפון למתווך עודד, ולאור השיחה עם המתווך עודד, שבה עודד נתן לשלמה את כל פרטי הדירה ואת המידע המהותי בקשר לנכס, החליט שלמה לרכוש את הדירה. דפנה טוענת כי היא אינה חייבת בדמי תיווך לעודד, משום שהיא זו שפירסמה את המודעה ומצאה את הקונה.
לפי פסק הדין ת״א 945-12-11 עודד סיטי נ׳ טל פרי, האם בנסיבות אלה דפנה חייבת בדמי תיווך לעודד? מדוע?', '["כן; גם במקרה שבו בעל הבית מוצא את הרוכש בעצמו, הבלעדיות מזכה את המתווך בדמי תיווך כ״גורם יעיל״.", "לא; מדובר במקרה שבו חזקת הגורם היעיל שבבלעדיות נסתרת על ידי פעולות שמבצע בעל הנכס שמצא את הרוכש בעצמו.", "כן; משום שהרכישה של הדירה נעשתה בעקבות השיחה עם המתווך עודד שהיה הגורם היעיל שהביא לחתימה על חוזה המכר.", "לא; המתווך לא היה הגורם היעיל, שכן דפנה פירסמה את ההודעה בקבוצה ומצאה את הרוכש בעצמה."]'::jsonb, 2, null, 'סעיף 14(ב) לחוק המתווכים קובע שמתווך בבלעדיות שביצע את פעולות השיווק הנדרשות - חזקה שהיה הגורם היעיל בעסקה שנכרתה בתקופת הבלעדיות. בת"א 945-12-11 עודד סיטי נ'' טל פרי נפסק שהחזקה לא נסתרה: הקונה אמנם ראה את המודעה של הבעלים, אבל הגיע לנכס בעקבות השלט, פנה למתווך, וההחלטה לרכוש התקבלה אחרי שהמתווך מסר לו את כל הפרטים והמידע המהותי - כלומר המתווך היה הגורם היעיל בפועל. חלופה א שגויה כי הבלעדיות אינה מזכה "בכל מקרה" - החזקה ניתנת לסתירה; חלופות ב ו-ד מתעלמות מהשיחה שהכריעה.', 'ת"א 945-12-11 עודד סיטי נ'' טל פרי; סעיף 14(א)(3) ו-14(ב) לחוק המתווכים במקרקעין', 14, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q15', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 15', 'איתן ובת זוגו נמצאים בזוגיות שנייה, וגרים בנפרד דרך קבע עקב שיקולים הקשורים לעבודתה של בת זוגו. יחד עם זאת, הם בעלים במשותף של דירת מגורים המשמשת למגורים בארבע השנים האחרונות.
האם ייחשבו איתן ובת זוגו, לצורכי הגדרת ׳דירה מזכה׳ למס שבח, כ״מוכר אחד״?', '["לא; על בני הזוג להתגורר יחדיו בדירת המגורים המזכה כדי להיחשב כ׳מוכר אחד׳ לצורך חישוב ׳דירת מגורים מזכה׳ לשניהם.", "לא; אלא אם דירת המגורים המזכה שימשה למגורים לא רק בארבע השנים האחרונות, אלא גם בארבע חמישיות מהתקופה שבשלה מחושב השבח בדירה עבור שניהם.", "כן; הדירה שימשה למגורים בארבע השנים האחרונות ולכן בני הזוג זכאים לפטור ׳דירת מגורים מזכה׳ ללא כל סייג.", "כן; מסתכלים רק על איתן לצורך בדיקת חישוב ׳דירת מגורים מזכה׳ ואין משמעות לבת זוגו. הזכות להיחשב כ׳דירת מגורים מזכה׳ היא עבור שני בני הזוג."]'::jsonb, 0, null, 'סעיף 49(ב) לחוק מיסוי מקרקעין קובע שלעניין הפטור לדירת מגורים מזכה רואים מוכר ובן זוגו וילדיהם הקטינים כמוכר אחד - "למעט בן זוג הגר דרך קבע בנפרד". איתן ובת זוגו גרים בנפרד דרך קבע, ולכן החריג חל והם אינם "מוכר אחד" - כל אחד מהם נבחן בנפרד. תנאי ארבע השנים או ארבע החמישיות (חלופה ב) נוגע להגדרת "דירת מגורים מזכה" עצמה ולא לשאלת התא המשפחתי, וחלופות ג ו-ד מתעלמות מהחריג שעליו כל השאלה בנויה.', 'סעיף 49(ב) לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963', 15, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
