  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q16', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 16', 'יערה רכשה דירה מקבלן בפרויקט של ״תמ״א 38(3)״ שבו כלל הדירות נהרסו, ויערה קיבלה לידיה דירה חדשה. יערה ביקשה במהלך תקופת הבדק כי ייערכו מספר תיקונים בדירתה, אך הקבלן הפתיע אותה וטען כי אין לה כל זכאות לכך, משום שמדובר בפרויקט תמ״א 38(3), וכי עליה לשלם עבור ההתאמות והתיקונים בהתאם להצעת מחיר שהעביר לה.
האם בנסיבות אלה הקבלן צודק בטענתו, ודירה חדשה בפרוייקט תמ״א 38(3) אינה מזכה בתיקונים בתקופת הבדק לפי חוק המכר (דירות), התשל״ג-1974?', '["כן; לא מדובר בדירה חדשה, אלא בדירה בפרויקט של תמ״א 38(3) ולכן חוק המכר (דירות) אינו חל במקרה זה.", "כן; לרוכשים אין כל זכאות לתיקונים שיבצע הקבלן בדירה בפרויקט תמ״א 38(3), אלא אם הם יממנו את התיקונים.", "לא; אלא אם לא מדובר בדירת מגורים, אלא בדירה שתשמש כמלאי עסקי, שאז לא יחול עליה חוק המכר (דירות).", "לא; חוק המכר (דירות) חל על דירות חדשות, ואין סייג לתחולתו על דירות שנבנו במסגרת פרויקט תמ״א 38(3)."]'::jsonb, 3, null, 'חוק המכר (דירות) חל על כל "מוכר" כהגדרתו בסעיף 1 - מי שבונה או גורם לבנות דירה על מנת למכרה - ועל כל "דירה", בלי קשר למסלול התכנוני שבו נבנתה. דירה חדשה שנבנתה בהריסה ובנייה מחדש לפי תמ"א 38(3) היא דירה חדשה לכל דבר, והקבלן חב בתיקון אי-ההתאמות בתקופת הבדק ובתקופת האחריות לפי סעיף 4 לחוק, על חשבונו. אין בחוק סייג לפרויקטי תמ"א 38 (חלופות א ו-ב), ואין סייג ל"מלאי עסקי" (חלופה ג) - החוק חל על הדירה, לא על השימוש שהקונה יעשה בה.', 'סעיפים 1 ו-4 לחוק המכר (דירות), התשל"ג-1973', 16, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q17', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 17', 'מנחם מחנה את רכבו מזה 30 שנה וחודש, בשביל שבכניסה לבית של שכנו יוסף, עימו היה בקשר טוב כל השנים. יוסף מעולם לא ביקש ממנחם שלא להחנות את הרכב במקום זה, והוא אף כתב לו בפתק לפני 30 שנה שהוא מסכים שיחנה במקום, כי אין לו רישיון נהיגה בעצמו.
לפני כחודש נפטר יוסף, וכעת מנחם חושש כי בנו ויורשו של יוסף ידרוש ממנו להפסיק להחנות את רכבו באותו מקום.
האם מנחם רשאי לרשום הערת אזהרה בגין השימוש בחניה?', '["כן; אך נדרשת לשם כך הסכמת בעל המקרקעין שבהם נרשמת זיקת ההנאה ברגע הרישום.", "כן; הואיל ומנחם עשה שימוש בשביל הבית של יוסף יותר מ- 30 שנה, אזי הוא בעל זכות זיקת הנאה הניתנת לרישום.", "לא; לא ניתן לרשום זיקת הנאה על חניה.", "לא; לא ניתן לרשום זיקת הנאה בחלק ממקרקעין בלבד, כגון רק בשביל שמוביל אל הנכס."]'::jsonb, 1, null, 'סעיף 94 לחוק המקרקעין קובע שמי שהשתמש בזכות הראויה להוות זיקת הנאה במשך שלושים שנים רצופות רכש את הזיקה, והוא זכאי לדרוש את רישומה - וזה בדיוק מצבו של מנחם, שחונה בשביל 30 שנה וחודש ברציפות ובגלוי. מכיוון שהזיקה נרכשה מכוח החוק, הרישום אינו תלוי בהסכמת הבעלים הנוכחי (חלופה א), והיורש נכנס לנעלי יוסף. זיקת הנאה יכולה להיות לשימוש מסוים כמו מעבר או חניה, ויכולה לחול על חלק מהמקרקעין (חלופות ג ו-ד שגויות). שימו לב שהשאלה מדברת על "הערת אזהרה", אבל הזכות הנכונה כאן היא זיקת הנאה, ועליה בנויות כל החלופות.', 'סעיפים 92-94 לחוק המקרקעין, התשכ"ט-1969 (זיקת הנאה מכוח שנים)', 17, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
