  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q18', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 18', 'למתווך שמחפש נכס לרכישה עבור לקוחו נודע כי בדירה מסוימת, שהוא מבקש להציע ללקוחו, ניתן היתר לשימוש חורג במרתף הדירה לצורך מגורים לעשר השנים הבאות.
האם המתווך חייב לגלות מידע זה ללקוחו?', '["המתווך אינו חייב לגלות ללקוח מידע זה, שכן חובת הגילוי חלה על המוכר.", "המתווך חייב לגלות מידע זה ללקוחו, שכן קיימת חובת גילוי של מידע מהותי לגבי הנכס, ומדובר במידע מהותי, שכן ההיתר לחריגה עשוי לפוג.", "המתווך חייב לגלות מידע זה ללקוחו רק אם הבעלים של הנכס מתיר זאת, שכן המתווך חייב כלפי הבעלים בחובת סודיות.", "המתווך אינו חייב לגלות מידע זה, שכן ההיתר לחריגה צפוי להתחדש."]'::jsonb, 1, null, 'סעיף 8 לחוק המתווכים מחייב את המתווך לנהוג בהגינות ובזהירות ולמסור ללקוחו כל מידע שיש בידו בעניין מהותי הנוגע לנכס, ותקנה 7 לתקנות האתיקה מפרטת את המידע המהותי שחובה למסור לקונה. היתר לשימוש חורג הוא זמני מטבעו: הוא ניתן לעשר שנים ועשוי שלא להתחדש, ואז המרתף יחזור להיות אסור למגורים - זה בדיוק מידע מהותי שמשפיע על ערך הנכס ועל ההחלטה לרכוש. חובת הגילוי של המתווך עומדת בפני עצמה ואינה נגרעת מחובות המוכר (חלופה א) ואינה כפופה לרשות הבעלים (חלופה ג); הציפייה שההיתר יתחדש (חלופה ד) אינה ודאות, ולכן אינה פוטרת מגילוי.', 'סעיף 8 לחוק המתווכים במקרקעין; תקנה 7 לתקנות המתווכים במקרקעין (אתיקה וחובות מקצועיות), התשפ"ד-2024', 18, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
