insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q19', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 19', 'חברת ״אמות״ עוסקת בבנייה ובשיווק מקרקעין.
האם מותר לעובד החברה, שאינו בעל רישיון תיווך, להציג בה נכסים ולפרסם מידע ופרטים לגבי זכויות במקרקעין כדי לעניין רוכשים?', '["כל אדם רשאי לפרסם פרסומים כאמור ובתנאי שהוא התקשר בהסכם בלעדיות עם מתווך בעל רישיון המפקח עליו.", "חל איסור מוחלט על פרסומים כאמור ללא רישיון תיווך.", "מותר לפרסם פרסומים כאמור, ובלבד שהמפרסם אינו מציג עצמו כמתווך במקרקעין.", "מותר לפרסם פרסומים כאמור כל עוד והמשווק לא מציג מידע מהותי לגבי הנכס."]'::jsonb, 2, null, 'סעיף 2 לחוק המתווכים אוסר שני דברים: לעסוק בתיווך במקרקעין בלי רישיון, ולפרסם ברבים הודעה שאדם הוא מתווך במקרקעין בלי רישיון. "תיווך במקרקעין" לפי סעיף 1 הוא הפגשה בתמורה בין שני צדדים לעסקה - ועובד של חברה יזמית שמשווק את הנכסים של החברה עצמה אינו מפגיש בין צדדים זרים אלא פועל בשם צד לעסקה, ולכן אינו עוסק בתיווך. מה שאסור לו הוא להציג את עצמו כמתווך. אין בחוק דרישה לפיקוח של מתווך מורשה (חלופה א), ואין היגיון בהסתרת מידע מהותי (חלופה ד) - ההפך, גילויו הוא חובה.', 'סעיפים 1 ו-2 לחוק המתווכים במקרקעין, התשנ"ו-1996', 19, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
