select 'exam-2025-02-q20', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 20', 'ביום 1.1.24 יוסף הציע בכתב לאבנר את דירתו בלוד למכירה בניסוח הבא: ״אני מציע לך לרכוש את דירתי במחיר של 1.9 מיליון ש"ח. ההצעה תעמוד בתוקפה למשך שבעה ימים״. ביום 5.1.24 הודיע יוסף לאבנר בעל פה, כי מכיוון שלא הודיע על רצונו לרכוש את הדירה עד אותו זמן, הוא מעלה את המחיר המבוקש על ידו ל- 2.1 מיליון ש"ח.
האם יוסף רשאי היה לנהוג כפי שנהג? מדוע?', '["כן; כל עוד אבנר לא קיבל את הצעתו של יוסף, יוסף רשאי לחזור בו מן ההצעה ולשנותה.", "לא; מכיוון שהודיע כי הוא חוזר בו מההצעה בעל פה - יוסף היה צריך לשנות את המחיר בכתב לא בעל פה.", "לא; מאחר שהצעתו של יוסף היא הצעה בלתי חוזרת, אסור היה לו לחזור בו מן ההצעה בטרם חלף המועד שנקבע על ידו, במחיר שנקבע לתקופה זאת.", "כן; הצעה בלתי חוזרת היא תמיד לרכישת הנכס בלבד, והמוכר רשאי תמיד להעלות את המחיר במהלך תקופת ההצעה הבלתי חוזרת."]'::jsonb, 2, null, 'סעיף 3 לחוק החוזים (חלק כללי) מבחין בין הצעה רגילה, שהמציע רשאי לחזור בו ממנה כל עוד לא נמסרה הודעת קיבול (זה הכלל שחלופה א מתארת), לבין הצעה שנקבע בה מועד לקיבולה או שנאמר בה שהיא ללא חזרה - הצעה בלתי חוזרת, שממנה אין המציע רשאי לחזור בו לאחר שנמסרה לניצע. יוסף קבע בעצמו שההצעה תעמוד שבעה ימים, ולכן ב-5.1.24, בתוך התקופה, לא היה רשאי לבטלה או לשנות את מחירה. הצורה (בכתב או בעל פה, חלופה ב) אינה העניין, והטענה שהמחיר תמיד פתוח לשינוי (חלופה ד) סותרת את מהות ההצעה הבלתי חוזרת.', 'סעיף 3 לחוק החוזים (חלק כללי), התשל"ג-1973 (הצעה בלתי חוזרת)', 20, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
