select 'exam-2025-02-q21', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 21', 'מה מהבאים לא ניתן לרשום במרשם המקרקעין (טאבו)?', '["הערת אזהרה בגין התחייבות בכתב לעשות עיסקת מקרקעין.", "הערת אזהרה בגין התחייבות בכתב לשאילת נכס מקרקעין.", "הערת אזהרה בגין התחייבות בכתב לזכות קדימה במקרקעין.", "עסקה הסותרת הערת אזהרה קיימת."]'::jsonb, 3, null, 'סעיף 126 לחוק המקרקעין מאפשר לרשום הערת אזהרה על כל התחייבות בכתב לעשות עסקה במקרקעין או להימנע מעסקה - ושאילה, שכירות וזכות קדימה הן כולן זכויות במקרקעין שהתחייבות לגביהן ניתנת להערה (חלופות א-ג). לעומת זאת, סעיף 127(א) קובע שמשנרשמה הערת אזהרה, לא תירשם עסקה הסותרת את תוכן ההערה כל עוד לא נמחקה, אלא בהסכמת הזכאי לפי ההערה או לפי צו בית משפט. זו בדיוק התכלית של ההערה: להגן על הזכאי מפני עסקה נוגדת.', 'סעיפים 126-127 לחוק המקרקעין, התשכ"ט-1969', 21, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
