insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q22', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 22', 'נאווה ויוסי החליטו להתגרש. בבעלות בני הזוג דירת מגורים ברחובות, הרשומה על שם שניהם בחלקים שווים. בני הזוג הגיעו להסכמה להתגרש, שבמסגרתה יוסי יעביר על שם נאווה את חלקו בדירה המשותפת, אגב הגירושין. חלקו של יוסי בדירה המשותפת שווה מיליון ש״ח.
בבעלות נאווה דירה נוספת בראשון לציון, שרכשה לפני שנישאה.
כמה מס רכישה תשלם נאווה בגין קבלת חלקו של יוסי בדירה ברחובות?', '["הואיל ובבעלות נאווה דירה נוספת על דירת בני הזוג, היא תשלם מס רכישה בשיעור 8% משווי הדירה עבור מחצית הדירה שהיא מקבלת מיוסי.", "נאווה לא תשלם מס רכישה, משום שהיא אינה מגיעה למדרגות המס המחייבות תשלום.", "נאווה לא תשלם מס רכישה כלל, הואיל והעברה אגב גירושין אינה מכירה.", "נאווה תשלם מס רכישה לפי דירה ראשונה, הואיל וההעברה בין בני הזוג אינה נספרת לצורכי מיסוי מקרקעין."]'::jsonb, 2, null, 'סעיף 4א לחוק מיסוי מקרקעין קובע שהעברת זכויות במקרקעין בין בני זוג אגב גירושין, על פי פסק דין לגירושין, אינה "מכירה" לעניין החוק. כשאין מכירה אין אירוע מס - לא מס שבח ליוסי ולא מס רכישה לנאווה - ולכן הדירה הנוספת שלה בראשון לציון (חלופה א) אינה רלוונטית, וגם מדרגות המס (חלופה ב) ושיעור "דירה ראשונה" (חלופה ד) אינם נכנסים לחישוב. המס נדחה למועד שבו נאווה תמכור את הדירה לצד שלישי, ואז תיכנס לנעלי יוסי לגבי החלק שקיבלה.', 'סעיף 4א לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963', 22, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
