insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q23', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 23', 'באיזה מהמקרים הבאים אדם שנפגע מהפרת חוזה אינו זכאי לאכיפת החוזה שהופר?', '["אם החוזה בר ביצוע.", "אם הופר חיוב מחיובי החוזה במשתמע.", "אם הוא זכאי לפיצויים בשל הפרת החוזה.", "אם אכיפת החוזה אינה צודקת בנסיבות העניין."]'::jsonb, 3, null, 'סעיף 3 לחוק החוזים (תרופות) מעניק לנפגע זכות לאכיפת החוזה, ומונה ארבעה סייגים: החוזה אינו בר ביצוע, אכיפה היא כפייה לעשות או לקבל עבודה אישית, האכיפה דורשת פיקוח בלתי סביר מטעם בית המשפט, או שהאכיפה אינה צודקת בנסיבות העניין. חלופה ד היא הסייג הרביעי כלשונו. חלופה א הפוכה - חוזה בר ביצוע הוא דווקא תנאי לאכיפה; הפרה של חיוב משתמע (חלופה ב) היא הפרה לכל דבר; והזכות לפיצויים (חלופה ג) מצטברת לאכיפה ואינה שוללת אותה (סעיף 2 לחוק).', 'סעיפים 2 ו-3(4) לחוק החוזים (תרופות בשל הפרת חוזה), התשל"א-1970', 23, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
