insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q24', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 24', 'לצורך קבלת בלעדיות בתיווך, האם יש לפרט את כל פעולות השיווק שהדין מתייחס אליהן? אם כן, היכן?', '["כן; יש לפרט את כל פעולות השיווק שהדין מתייחס אליהן, וכן פעולות נוספות שסוכמו בין הצדדים, ככל שסוכמו, במסמך נפרד מטופס הזמנת שירותי התיווך.", "כן; יש יש לפרט את כל פעולות השיווק שהדין מתייחס אליהן, וכן פעולות נוספות שסוכמו בין הצדדים, ככל שסוכמו, בטופס הזמנת שירותי התיווך.", "לא; יש לפרט את הפעולות שסוכמו בין הצדדים בלבד לצורך הבלעדיות, בטופס נפרד מטופס הזמנת שירותי התיווך.", "כן; יש לפרט את כלל פעולות השיווק שהדין מתייחס אליהן, בטופס הזמנת שירותי התיווך."]'::jsonb, 0, null, 'סעיף 9(ב) לחוק המתווכים קובע שבלעדיות נקבעת במסמך נפרד מההזמנה בכתב, ושלמתווך בבלעדיות חובה לבצע פעולות שיווק שנקבעו בתקנות. תקנות המתווכים במקרקעין (פעולות שיווק) מפרטות את הפעולות, ודורשות שמסמך הבלעדיות יפרט את פעולות השיווק שהמתווך התחייב לבצע - אלה שבתקנות, וכל פעולה נוספת שסוכמה. לכן התשובה היא "כן", ו"במסמך נפרד" - שתי החלופות שמכניסות את הפירוט לטופס ההזמנה עצמו (ב ו-ד) נופלות על המיקום, וחלופה ג נופלת על "בלבד": הפעולות שבדין הן חובה ולא רק מה שסוכם. שימו לב שהמילה "יש" כפולה בחלופה ב במקור.', 'סעיף 9(ב) לחוק המתווכים במקרקעין; תקנות המתווכים במקרקעין (פעולות שיווק), התשס"ה-2004', 24, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
