insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-02-q25', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, פברואר 2025, שאלה 25', 'בחוזה התיווך המיועד לכלל לקוחות סוכנות התיווך ״נוף נאה עוסק מורשה״, נכתב הסעיף הבא: ״עמלת התיווך ללקוחות המחפשים נכסים דרך הסוכנות תעמוד על 1% ממחיר הנכס. יחד עם זאת, אם מנהל הסוכנות יקבע כי הסוכנות החליטה להוציא מספר לא סביר של שעות עבודה על חיפוש הנכס עבור הלקוח, תועמד העמלה על 2% ממחיר העיסקה".
משה, לקוח של הסוכנות, טוען שמדובר בתנאי שמקפח אותו.
האם משה צודק לפי הדין? מדוע?', '["לא; לא מדובר בחוזה אחיד אלא בחוזה עם לקוח מסוים.", "לא; דמי התיווך עולים מכיוון שההשקעה בלקוח משמעותית במיוחד.", "כן; מדובר בתנאי מקפח, מכיוון שלא מדובר בחוזה אחיד, אלא בחוזה עם לקוח מסוים.", "כן; חזקה שהתנאי המקנה זכות לשינוי מחיר בדיעבד בחוזה הנו מקפח."]'::jsonb, 3, null, 'חוזה שנוסח מראש כדי לשמש את כל לקוחות הסוכנות הוא "חוזה אחיד" לפי סעיף 2 לחוק החוזים האחידים, ולכן חלופות א ו-ג, שטוענות שאין כאן חוזה אחיד, שגויות (וחלופה ג גם סותרת את עצמה). סעיף 4 לחוק מונה תנאים שחזקה עליהם שהם מקפחים, וביניהם תנאי המקנה לספק זכות לקבוע או לשנות על דעתו בלבד מחיר או חיובים מהותיים אחרים לאחר כריתת החוזה. סעיף שמאפשר למנהל הסוכנות להכפיל את העמלה לפי שיקול דעתו הבלעדי הוא בדיוק כזה, ועל הסוכנות הנטל להוכיח שאינו מקפח - ההשקעה בלקוח (חלופה ב) אינה מסירה את החזקה.', 'סעיפים 2, 3 ו-4(4) לחוק החוזים האחידים, התשמ"ג-1982', 25, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-02'
