insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'exam-2025-05', 'מבחן מאי 2025', 5, 'מועד מאי 2025 היה מבחן של דיני מקרקעין יותר מאשר של חוק המתווכים: שבע שאלות בלבד על המתווך עצמו, ומולן שבע על חוק המקרקעין וארבע על מיסוי. מי שלמד רק את החוק "שלנו" יצא מהאולם עם 11 שאלות שלא ידע מאיפה להתחיל.', '<p>25 השאלות של מועד מאי 2025 התפלגו כך (ספירה לפי החוק שמכריע את השאלה):</p><ul><li><strong>חוק המתווכים במקרקעין ותקנות האתיקה</strong> - 7 שאלות (1, 3, 5, 6, 14, 15, 18), שלוש מהן דרך פסקי דין על הגורם היעיל וחובת הנאמנות.</li><li><strong>חוק המקרקעין</strong> - 7 שאלות (7, 8, 10, 11, 17, 22, 24): בתים משותפים, עסקאות נוגדות, הצמדות, וחוק החיזוק.</li><li><strong>חוק מיסוי מקרקעין</strong> - 4 שאלות (2, 4, 12, 13): דירה יחידה, דירה חלופית, ומס שבח מול היטל השבחה.</li><li><strong>חוק המשכון ומשכנתאות</strong> - 2 שאלות (9, 21).</li><li><strong>חוק הגנת הדייר</strong>, <strong>חוק מקרקעי ישראל</strong>, <strong>חוק החוזים האחידים</strong>, <strong>חוק המכר (דירות)</strong> ו<strong>חוק הירושה</strong> - שאלה אחת כל אחד (16, 19, 20, 23, 25).</li></ul><p>שתי הערות על המפתח הרשמי: בשאלה 2 התקבלו שתי תשובות (18 ו-24 חודשים, בגלל הוראת שעה שחלה במועד הבחינה), ושאלה 24 בוטלה וכל תשובה בה התקבלה.</p>', '["שלוש שאלות על דמי תיווך הגיעו דרך פסיקה (מאיר נ'' שושן, ב.פ. הנשיא נ'' בקרמן, יצחקוב): הכלל המשותף הוא שמתווך שהפר חובה כלפי הלקוח אינו זכאי לשכר, ושיותר ממתווך אחד יכול להיות הגורם היעיל.", "בתים משותפים חזרו ארבע פעמים (מעלית, הסגת גבול ברכוש משותף, הצמדה, חדר מדרגות): סעיפים 55(ג), 59ו ו-72 לחוק המקרקעין הם חובה.", "מלכודת המספרים במיסוי: 18 חודשים לדירה חלופית, שליש מדירה שלא נספר כדירה נוספת, ומס שבח (מדינה, על הרווח) מול היטל השבחה (ועדה מקומית, על תוכנית).", "ארבע שאלות על \"האם המתווך פעל תקין\" נפתרות בשני סעיפים: 8 (נאמנות ומידע מהותי) ו-10 (עניין אישי), ובתקנות 12 ו-14 (התניית שירות, העברת הצעות).", "שאלות על מה לא ניתן לעשות כלל (הצמדת חדר מדרגות, תנאי שחוסם תביעה בחוזה אחיד, מכירת מקרקעין על ידי מנהל עיזבון בלי בית משפט) הן נקודות קלות למי שזוכר את הרשימות הסגורות."]'::jsonb, '[]'::jsonb, 'רשם המתווכים במקרקעין, מועד 04.05.2025, גרסה 1', null, false, true
  from public.course_chapters c where c.slug = 'past-exams'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q01', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 1', 'חיים המתווך ראה מודעה שפורסמה על ידי יהודה - בעלים של דירה, לפיה מוכר יהודה את דירתו בסכום של 1,000,000 ש"ח. במודעה נכתבו המילים הבאות: "פרטי, לא למתווכים". חיים יצר קשר עם רחל, אשר התעניינה בעבר בדירה דומה. חיים ציין בפני רחל כי יש לו להציע לה דירה במחיר 1,050,000 ש"ח, והחתים אותה על טופס הזמנת שירותי תיווך, לפיו חויבה ב- 2% דמי תיווך מתוך 1,050,000 ש"ח. שבוע לאחר מכן נפגשו יהודה ורחל אצל עו"ד עציוני כדי לחתום על הסכם מכר, או אז התברר לרחל, לתדהמתה, שמחיר הדירה היה ונותר 1,000,000 ש"ח בלבד, ולא 1,050,000 ש"ח, כפי שטען בפניה חיים. חיים מצידו טען כי היא משלמת לו דמי תיווך מוגדלים והדבר מוכר למיסוי מקרקעין.
האם חיים פעל באופן תקין בנסיבות המתוארות? מדוע?', '["כן; על הצדדים לדווח את המחיר המלא שהם משלמים בעד עיסקת מקרקעין.", "כן, הואיל וחיים היה הגורם היעיל בעיסקה ודמי התיווך פורטו בהזמנת שירותי התיווך.", "לא, משום שחיים לא החתים את יהודה על הסכם להזמנת שירותי תיווך כלקוח שממומן את שכר טרחתו.", "לא; חיים הפר את חובת הנאמנות שלו כלפי רחל בכך שלא נקב במחיר של עיסקת המקרקעין בפניה בשקיפות."]'::jsonb, 3, null, 'סעיף 8 לחוק המתווכים מחייב מתווך לפעול בנאמנות, בהגינות ובדרך מקובלת ולמסור ללקוחו כל מידע מהותי, ותקנה 4 לתקנות האתיקה אוסרת הטעיה בעניין מהותי לעסקה. המחיר המבוקש הוא מידע מהותי (הוא אף מנוי בתוספת הראשונה לתקנות), וחיים הציג לרחל מחיר כוזב כדי להשאיר את ההפרש בכיסו. חלופה ב'' מתעלמת מכך שדמי תיווך נגבים רק לפי סעיף 14 ולא דרך ניפוח מחיר, וחלופה ג'' אינה הפגם: מתווך רשאי לייצג רק את הקונה.', 'סעיף 8 לחוק המתווכים במקרקעין; תקנות 4 ו-7 לתקנות המתווכים (אתיקה וחובות מקצועיות)', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q02', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 2', 'שמשון הוא בעל דירה יחידה. שמשון מעוניין לרכוש מאדם פרטי אחר דירה, שתהווה תחליף לדירה הראשונה שלו.
האם שמשון יכול להיות זכאי לשלם מס רכישה במדרגת מס לפי דירה יחידה, בגין הדירה השנייה שהוא רוכש בנסיבות אלה?', '["לא, אלא אם שמשון ימכור את הדירה הראשונה שלו בתוך 24 חודשים.", "כן, אם שמשון ימכור את אחת מדירותיו בתוך 12 חודשים.", "לא, שמשון לא זכאי למדרגות מס הרכישה של דירה יחידה, מכיוון שברגע שהוא רוכש את הדירה השנייה הוא רוכש דירה נוספת.", "כן, אם ימכור את דירתו האחרת, שהיתה דירתו היחידה, בתוך 18 חודשים."]'::jsonb, 3, array[0,3]::smallint[], 'רוכש "דירה חלופית" נחשב רוכש דירה יחידה אם ימכור את הדירה הקודמת בתוך התקופה הקבועה בסעיף 9(ג1ג)(2)(ב) לחוק מיסוי מקרקעין: 18 חודשים מיום הרכישה (או שנה ממסירת הדירה כשנרכשה מקבלן). שימו לב: במפתח הרשמי התקבלו שתי תשובות, א'' (24 חודשים) ו-ד'' (18 חודשים), כי במועד הבחינה חלה הוראת שעה שהאריכה את התקופה ל-24 חודשים. חלופה ב'' שגויה (12 חודשים), וחלופה ג'' מתעלמת מהסדר הדירה החלופית.', 'סעיף 9(ג1ג)(2)(ב) לחוק מיסוי מקרקעין (שבח ורכישה)', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q03', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 3', 'לפני ארבע שנים עבר יחזקאל בהצלחה את הבחינה בדיני תיווך מקרקעין של משרד המשפטים, אולם טרם שילם את אגרת רישיון התיווך. יחזקאל איתר לקוח שמעוניין בשירותיו כמתווך, ובהתאם לכך החתים אותו על טופס תקין להזמנת שירותי תיווך, איתר עבורו דירה, ופעל במסירות וביעילות. כתוצאה מפעולותיו של יחזקאל הלקוח חתם על הסכם לרכישת הדירה האמורה. יומיים לאחר חתימת העיסקה, יחזקאל פנה למשרד המשפטים, שילם את האגרה והפעיל את רישיון התיווך שלו.
האם יחזקאל זכאי לדמי תיווך בנסיבות המתוארות?', '["כן - כל עוד יחזקאל פועל בהגינות, מוסר את כל המידע הרלוונטי ללקוח ומחתים אותו על טופס הזמנת שירותי תיווך.", "כן - יחזקאל רשאי להפעיל את רישיונו מייד לאחר ביצוע העיסקה.", "לא - אסור למתווך לפעול לאיתור לקוח, אלא על הלקוח לפנות למתווך.", "לא - משום שליחזקאל לא היה רישיון תיווך בתוקף בזמן שעסק בתיווך העיסקה."]'::jsonb, 3, null, 'סעיף 14(א)(1) לחוק המתווכים קובע כתנאי ראשון לזכאות לדמי תיווך שהמתווך "היה בעל רישיון בתוקף בעת שעסק בתיווך". מעבר הבחינה אינו רישיון; הרישיון ניתן לפי סעיף 5 רק לאחר תשלום האגרה, ותשלום בדיעבד אינו מרפא את התקופה שבה פעל ללא רישיון (ולפי סעיף 2 העיסוק עצמו אסור). טופס הזמנה תקין והגינות (חלופה א'') אינם מספיקים כשחסר התנאי הראשון, וחלופה ג'' ממציאה איסור שאינו קיים.', 'סעיפים 2, 5 ו-14(א)(1) לחוק המתווכים במקרקעין', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q04', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 4', 'ביום 1.1.24 נפטרה סבתה של גילה, והורישה לה את דירת המגורים היחידה שלה. העיזבון של הסבתא טרם חולק בין היורשים. שבועיים לאחר מכן התגרשה גילה מבעלה, כאשר הסכם גירושין שנחתם בין בני הזוג (ואושר ע"י בית המשפט בפסק דין) קבע, כי היא תקבל מבעלה אגב הגירושין וללא תמורה את זכויותיו בדירה המשותפת של בני הזוג.
האם גילה חייבת בתשלום מס רכישה? אם כן - בעבור איזו מהדירות?', '["מאחר שהזכויות בדירה המשותפת שקיבלה גילה מבעלה נחשבות לדירתה השנייה (אחרי הדירה שירשה מסבתה), גילה חייבת בתשלום מס רכישה בגין הדירה השנייה על פי המדרגות הקבועות בחוק לדירה שאיננה דירה יחידה.", "מכיוון שבבעלות התא המשפחתי (גילה ובעלה דאז) היתה כבר דירה, גילה היתה חייבת בתשלום מס רכישה בגין הדירה שקיבלה מסבתה על פי המדרגות הקבועות בחוק לדירה שאינה דירה יחידה.", "גילה לא חייבת במס רכישה בגין אף אחת מהעיסקאות האמורות, מכיוון שהירושה וגם ההעברה ללא תמורה מבן זוג אגב גירושין, אינן נחשבות למכירה על פי חוק.", "גילה חייבת בתשלום מס רכישה לפי מדרגות המס, בהתאם לשווי הנכסים באופן מדורג."]'::jsonb, 2, null, 'מס רכישה מוטל רק על "מכירת זכות במקרקעין", ושני האירועים כאן אינם מכירה: סעיף 4 לחוק מיסוי מקרקעין קובע שהורשה אינה מכירה, וסעיף 4א קובע שהעברת זכויות בין בני זוג אגב גירושין על פי פסק דין אינה מכירה (ואינה רכישה). לכן אין אירוע מס באף אחת מהדירות, ושאלת "דירה יחידה" שבחלופות א'', ב'' ו-ד'' כלל אינה מתעוררת.', 'סעיפים 4 ו-4א לחוק מיסוי מקרקעין (שבח ורכישה)', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q05', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 5', 'חננאל המתווך יצר קשר עם יואב, שהיה מעוניין למכור את דירתו. חננאל הציג בפני יואב רישיון תיווך בתוקף, וציין כי הוא מתווך מנוסה. יואב התרשם מאוד מחננאל, וקבע פגישה עם חננאל. בעת הפגישה ציין המתווך כי יש לו קונה המעוניין בדירה, אולם הודיע ליואב כי יהיה מוכן לקשר בין הצדדים רק אם יואב יסכים לרכוש את שירותיו כמתווך, כשירכוש דירה במקום הדירה אותה הוא מוכר. יואב הרגיש שעליו להסכים להצעת המתווך, ובהתאם לכך החתים חננאל את יואב על טופס הזמנת שירותי תיווך לשתי הדירות.
האם יש פסול בהתנהלותו של חננאל? מדוע?', '["לא; חננאל הציג בפני יואב רישיון תיווך כדין והחתים אותו על טופס הזמנת שירותי תיווך.", "לא; אין כל פסול בכך שמתווך ירצה לייצג את המוכר גם בעיסקת הרכישה הבאה, ואין מגבלה שחלה על ההתקשרות של יואב עימו בעיסקה הבאה, אלא אם ידרוש בלעדיות.", "כן; אסור למתווך להתנות שירות בדירה אחת במתן שירות בדירה אחרת.", "כן; אלא אם המתווך החתים את יואב על שני טפסי הזמנת שירותי תיווך שונים."]'::jsonb, 2, null, 'חוק המתווכים ותקנות האתיקה אוסרים התניית שירות בשירות: תקנה 12 קובעת שמתווך לא יתנה מתן שירותי תיווך בקניית שירות אחר, והחוק אוסר להתנות תיווך בעסקה אחת בתיווך בעסקה אחרת. חננאל התנה את הפגשת הקונה עם יואב בכך שיואב יזמין ממנו גם את תיווך הרכישה הבאה, וזו בדיוק ההתניה האסורה. רישיון בתוקף וטופס הזמנה (חלופה א'') אינם מכשירים אותה, ופיצול לשני טפסים (חלופה ד'') אינו משנה את מהות ההתניה.', 'חוק המתווכים במקרקעין (איסור התניית שירות); תקנה 12 לתקנות המתווכים (אתיקה וחובות מקצועיות)', 5, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q06', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 6', 'גרשון, מתווך בעל רישיון, ואשתו גילה, הינם הבעלים של בית מגורים (להלן: "הבית"). גרשון פרסם את הבית למכירה בסכום של 5 מיליון ש"ח. עופרה התעניינה בבית ופנתה לגרשון. גרשון הציג בפני עופרה רישיון תיווך, ולאחר שעופרה חתמה על טופס הזמנת שירותי תיווך, לפיו התחייבה לשלם לגרשון דמי תיווך בשיעור 2% משווי העיסקה, הציג גרשון את הבית לעופרה. עופרה התרשמה מהבית וביקשה לקבוע פגישה אצל עו"ד לחתימה על הסכם המכר.
האם גרשון פעל באופן תקין? מדוע?', '["כן; גרשון פרסם את הבית, הציג בפני עופרה רישיון תיווך במקרקעין, והחתים אותה על טופס הזמנת שירותי תיווך כדין בהיותו הגורם היעיל בעיסקה.", "כן; אך רק אם גרשון מגלה בכתב כי הוא בן זוגה של גילה.", "לא; גרשון הוא בעל עניין אישי בעיסקה כבן זוגה של גילה.", "לא; גרשון היה חייב לגלות לעופרה שיש לו עניין אישי בעיסקה, והוא מוגבל בייצוג הנכס, מכיוון שהוא הבעלים."]'::jsonb, 3, null, 'סעיף 10 לחוק המתווכים אוסר על מתווך לתווך בעסקה שיש לו בה עניין אישי, אלא אם גילה ללקוח את עניינו האישי וקיבל את הסכמתו בכתב. גרשון הוא בעלים של הבית, ולא רק "בן זוג" (חלופות ב'' ו-ג'' מצמצמות את העניין האישי לקשר הנישואין), ולכן היה חייב בגילוי מלא. ומעבר לכך, תקנה 25 לתקנות האתיקה אוסרת לגבות דמי תיווך בעסקה שבה למתווך עצמו זכות במקרקעין: מי שמוכר את ביתו אינו מתווך בו.', 'סעיף 10 לחוק המתווכים במקרקעין; תקנה 25 לתקנות המתווכים (אתיקה וחובות מקצועיות)', 6, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q07', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 7', 'הרצל גר בקומת קרקע בבית משותף שבו 16 דירות. כל בעלי הדירות בבית המשותף, למעט הרצל, הסכימו על התקנת מעלית בבניין. לאחר התקנת המעלית, פנתה נציגות הבית המשותף להרצל בדרישה כי ישלם את חלקו בעלות הקמת המעלית, וכי ישלם את חלקו בהוצאות החזקתה והפעלתה של המעלית.
בנסיבות המתוארות, איזה מההיגדים הבאים הוא הנכון ביותר?', '["הרצל לא משתמש במעלית, ולכן הוא לא צריך לשלם עבור התקנת המעלית, וגם לא עבור החזקתה והפעלתה.", "הרצל חייב לשלם עבור התקנתה, החזקתה והפעלתה של המעלית, מכיוון שהיא משותפת לכל הבניין.", "הרצל חייב לשלם עבור חלקו בהתקנת המעלית, אולם הוא פטור מתשלום החזקתה והפעלתה של המעלית, מכיוון שהוא לא משתמש בה בפועל.", "מאחר שהרצל גר בקומת הקרקע, הוא פטור מתשלום עבור התקנת המעלית, אולם הוא חייב להשתתף בהוצאות החזקתה והפעלתה של המעלית."]'::jsonb, 3, null, 'סעיף 59ו לחוק המקרקעין מסדיר התקנת מעלית בבית משותף: ההחלטה מתקבלת ברוב של שני שלישים מבעלי הדירות, בעלי דירות בקומת הקרקע אינם חייבים להשתתף בהוצאות ההתקנה, אך לאחר שהותקנה המעלית היא רכוש משותף וכל בעלי הדירות, כולל קומת הקרקע, נושאים בהוצאות החזקתה והפעלתה. "אני לא משתמש" (חלופות א'' ו-ג'') אינו פוטר מהוצאות רכוש משותף.', 'סעיף 59ו לחוק המקרקעין', 7, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q08', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 8', 'אלכס הוא בעלים של דירה בבית משותף. אלכס גילה להפתעתו כי משה - בעל דירה בקומת הקרקע, הרחיב את דירתו ובנה מחסן בשטח הרכוש המשותף. אלכס פנה למשה ודרש ממנו לפנות את המחסן. משה סירב.
האם אלכס יכול להגיש תביעה נגד משה? אם כן, בפני איזו ערכאה?', '["כן; אלכס יכול להגיש תביעה לסילוק יד לבית המשפט המחוזי שבתחום שיפוטו נמצא הבניין.", "לא; על אלכס לפתוח הליך בפני הוועדה המקומית לתכנון ובנייה בלבד.", "לא; אלכס אינו רשאי להגיש תביעה, אלא רק הנציגות של הבית המשותף מוסמכת להגיש תביעה לסילוק יד נגד משה מהשטח המשותף.", "כן; אלכס יכול להגיש תביעה לסילוק יד לבית המשפט המוסמך או למפקח על רישום המקרקעין, במחוז שבו נמצא הבית המשותף."]'::jsonb, 3, null, 'סעיף 72(ב) לחוק המקרקעין קובע שסכסוך בין בעלי דירות בבית משותף בדבר הסגת גבול מצד בעל דירה לגבי דירה אחרת או לגבי הרכוש המשותף, רשאי התובע להביא, לפי בחירתו, לפני בית משפט מוסמך או לפני המפקח. כל בעל דירה הוא שותף ברכוש המשותף ורשאי לתבוע בעצמו (חלופה ג'' שגויה), הוועדה המקומית עוסקת בהיתרי בנייה ולא בסכסוך קנייני (חלופה ב''), והערכאה אינה דווקא המחוזי (חלופה א'').', 'סעיף 72(ב) לחוק המקרקעין', 8, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q09', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 9', 'חזי ירש מאביו דירה. עו"ד נמרודי טיפל ברישום הדירה על שם חזי. כשהוציא עו"ד נמרודי נסח טאבו התברר כי רשומה משכנתא על זכויות אביו בדירה, עוד משנת 1958 לטובת ג''ורג'' סמיט - בעל דרכון אנגלי, בסכום של 150 ל"י (לירות ישראליות). חזי ניסה לברר אודות אותו ג''ורג'' סמיט ואף שכר את שירותיהם של חוקרים פרטיים בישראל ובאנגליה, אולם ללא הצלחה. מאחר שהורשה איננה מכירה על פי חוק, הועברו הזכויות על שם חזי, אולם חזי אינו יכול למכור את הדירה לצד שלישי מבלי למחוק את המשכנתא.
בנסיבות המתוארות, איזה מההיגדים הבאים הוא הנכון ביותר?', '["חזי חייב לאתר את ג''ורג'' סמיט ולשלם לו את כספי המשכנתא, אחרת לא ניתן לבטל את רישום המשכנתא.", "חזי יכול לפנות לבית המשפט המוסמך בבקשה לסעד הצהרתי לפיו מאחר שהוא לא הצליח לאתר את ג''ורג'' סמיט יש למחוק את המשכנתא מהטאבו, כך שיוכל למכור את הדירה.", "חזי רשאי להפקיד את כספי המשכנתא המגיעים מאביו לג''ורג'' סמיט בידי רשם המקרקעין ולבקש שהרשם יפקיע את המשכנתא במידה שנפדתה, וכך תימחק המשכנתא מהטאבו.", "חזי יכול לפנות למפקח על רישום המקרקעין בבקשה שימחק את המשכנתא הואיל והתיישנה."]'::jsonb, 2, null, 'משכנתא היא משכון של מקרקעין, וחוק המשכון (סעיף 13) מקנה לחייב ולכל מי שזכותו עלולה להיפגע את הזכות לפדות את המשכון בקיום החיוב. כשבעל המשכנתא אינו ניתן לאיתור, הדין מאפשר להפקיד את סכום הפדיון בידי רשם המקרקעין ולבקש את מחיקת המשכנתא על יסוד הפדיון. אין צורך בתביעה לסעד הצהרתי (חלופה ב''), משכנתא רשומה אינה "מתיישנת" (חלופה ד''), ואי-איתור הנושה אינו מנציח את השעבוד (חלופה א'').', 'חוק המשכון, סעיף 13 (פדיון המשכון); פרק המשכנתאות בחוק המקרקעין', 9, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q10', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 10', 'ניצה ראתה דירה שפרסמה מוכרת, והחליטה כי היא מעוניינת בדירה. בהתאם לכך ביקשה ניצה מהמוכרת שתמתין עד שהיא תגייס את מלוא המימון לרכישת הדירה. במקביל חתמה ניצה עם המוכרת על זיכרון דברים ושילמה לה מקדמה ע"ס 200,000 ש"ח על חשבון רכישת הדירה. כל זאת ללא שנעזרו בעורכי דין, וללא שנרשמה לטובת ניצה הערת אזהרה בלשכת רישום המקרקעין (הטאבו).
בינתיים ראתה קונה אחרת את הדירה, תוך שלא היתה מודעת לניצה ולמה שהתרחש מולה, ולאחר משא ומתן עם המוכרת חתמה עימה על הסכם מכר בקשר לדירה, שילמה למוכרת את מלוא התמורה והשלימה את רישום הדירה בטאבו על שמה.
האם ניצה זכאית לרישום הדירה על שמה? מדוע?', '["כן; ניצה היא הראשונה שנחתם עימה הסכם, ושולמה מקדמה כדין.", "כן, משום שהקונה השנייה בזמן צריכה הייתה לדעת על זכותה של ניצה.", "לא; משום שלא נחתם חוזה העונה לדרישת המסוימות בחוק החוזים.", "לא; משום שהקונה השנייה שילמה את מלוא התמורה, פעלה בתום לב והשלימה את העיסקה ברישום בטאבו."]'::jsonb, 3, null, 'זו "עסקאות נוגדות" לפי סעיף 9 לחוק המקרקעין: ככלל זכות בעל העסקה הראשונה עדיפה, אלא אם השני רכש בתמורה ובתום לב והעסקה לטובתו נרשמה בעודו בתום לב. הקונה השנייה עמדה בכל שלושת התנאים, ולכן זכותה גוברת. ניצה יכלה להגן על עצמה ברישום הערת אזהרה (סעיף 126), ומשלא עשתה כן אי אפשר לייחס לקונה השנייה ידיעה (חלופה ב''). חלופה ג'' עוסקת בתוקף זיכרון הדברים, וזו אינה הסיבה שניצה מפסידה.', 'סעיפים 9 ו-126 לחוק המקרקעין', 10, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q11', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 11', 'גידי, חבר בנציגות הבית המשותף בבניין, שוחח עם משה, בעל דירה בבניין, ושאל לעמדתו של משה בקשר לביצוע פרוייקט התחדשות עירונית, לפי חוק המקרקעין (חיזוק בתים משותפים מפני רעידות אדמה) (להלן - "חוק החיזוק"). משה השיב שבאופן עקרוני הוא בעד הפרוייקט. לאחר מספר חודשים ראה משה מודעה על לוח המודעות של הבניין, שבה הוא רשום כמי שנתן הסכמתו לפרוייקט התחדשות עירונית.
האם משה אכן נחשב כמי שנתן את הסכמתו לפרוייקט? מדוע?', '["כן; משה אמר לגידי במפורש שהוא לא מתנגד לפרוייקט, וגידי רשם את הדברים בספרי הבית המשותף.", "כן; משום שניתנה הסכמה לפרוייקט ההתחדשות העירונית בעל פה על ידי משה.", "לא; הסכמות בפרוייקט כזה לא יכולות להינתן בעל פה בלבד. גידי היה חייב להחתים את משה על הצהרה מסודרת, ורק אז ההסכמה היא על פי דין.", "לא; הסכמתו של משה חייבת היתה להינתן בכתב, ואף להיות מאומתת ע\"י עורך דין בדרך שמאמתים שטר עיסקה."]'::jsonb, 3, null, 'הסכמה לפרויקט חיזוק לפי חוק החיזוק היא הסכמה לעסקה בזכויות במקרקעין (הצמדת רכוש משותף ליזם, מכירת זכויות בנייה), ולכן היא חייבת להינתן בכתב ולהיות מאומתת בדרך שבה מאמתים שטר עסקה, ורק הסכמה כזו נספרת במניין הרוב הנדרש לפי החוק. אמירה עקרונית בעל פה (חלופות א'' ו-ב'') או רישום של חבר הנציגות אינם הסכמה. חלופה ג'' נכונה ברעיון אך חסרה את דרישת האימות, ולכן ד'' היא "הנכונה ביותר".', 'חוק המקרקעין (חיזוק בתים משותפים מפני רעידות אדמה), התשס"ח-2008 (דרך מתן ההסכמה)', 11, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q12', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 12', 'לדנה דירת מגורים בבעלותה המלאה. דנה החליטה לרכוש דירת מגורים נוספת, ביחד עם אחיה, וכל אחד שילם מחצית מעלות הדירה. דנה ואחיה חילקו את הדירה ביניהם לשימושם.
האם דנה זכאית לשלם מס רכישה בגין רכישת הדירה לפי מדרגות דירת מגורים יחידה? מדוע?', '["כן; חלק מדירת מגורים אינו נחשב דירת מגורים נוספת.", "לא; מאחר שגם חלק מדירה נחשב לדירת מגורים, דנה אינה זכאית למס רכישה לפי מדרגות דירת מגורים יחידה.", "כן; מאחר שחלקה של דנה נחשב מלאי עיסקי.", "לא; מאחר שבאותה עיסקת מכר לא ניתן לתת פטור לשני רוכשים."]'::jsonb, 1, null, 'הגדרת "דירה יחידה" בסעיף 9(ג1ג)(4) לחוק מיסוי מקרקעין מתעלמת רק מדירה נוספת שחלקו של הרוכש בה אינו עולה על שליש. דנה כבר מחזיקה דירה שלמה, ועכשיו רוכשת מחצית מדירה, כלומר חלק העולה על שליש, ולכן הרכישה היא של "דירה נוספת" במדרגות המלאות. חלופה א'' הופכת את הכלל, חלופה ג'' ממציאה סיווג של מלאי עסקי, וחלופה ד'' אינה הדין: כל רוכש נבחן בנפרד.', 'סעיף 9(ג1ג)(4) לחוק מיסוי מקרקעין (שבח ורכישה), הגדרת "דירה יחידה"', 12, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q13', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 13', 'מהו מס שבח ובאילו נסיבות הוא מוטל?', '["המס אשר מוטל על ידי רשות מיסוי מקרקעין על מוכר זכות במקרקעין בעבור תוכניות בניין עיר שאושרו באזור. המס יוטל במכירת הזכות במקרקעין או עם אישור תוכנית בניין עיר המעלה את ערך הנכס על ידי הרשות המקומית שבה נמצאים המקרקעין.", "המס אשר מוטל על על ידי רשות מיסוי מקרקעין על מוכר זכות במקרקעין בעבור ההפרש שבו עולה שווי המכירה על יתרת שווי הרכישה. מס זה מוטל על ידי רשויות מיסוי מקרקעין בעת מכירת זכות במקרקעין.", "המס אשר מוטל על ידי הרשות המקומית על רוכש זכות במקרקעין בעבור תוכניות בניין עיר שאושרו באזור. המס ישולם במכירת זכות במקרקעין או במימוש תוכנית הבנייה.", "המס אשר מוטל על ידי הרשות המקומית על מוכר זכות במקרקעין בעבור ההפרש מסכום הרכישה לסכום המכירה. מס זה יוטל בעת מכירת זכות במקרקעין."]'::jsonb, 1, null, 'סעיף 6 לחוק מיסוי מקרקעין: מס שבח מוטל על השבח במכירת זכות במקרקעין, והשבח הוא הסכום שבו עולה שווי המכירה על יתרת שווי הרכישה. גובה אותו מנהל מיסוי מקרקעין (המדינה), והחייב הוא המוכר. המלכודת בשאלה היא הבלבול עם היטל השבחה: אותו גובה הוועדה המקומית לפי התוספת השלישית לחוק התכנון והבנייה בגין עליית ערך מאישור תוכנית (חלופות א'' ו-ג''), ואילו חלופה ד'' מייחסת את מס השבח לרשות המקומית.', 'סעיף 6 לחוק מיסוי מקרקעין (שבח ורכישה); להבדיל מהיטל השבחה לפי התוספת השלישית לחוק התכנון והבנייה', 13, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q14', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 14', 'שרית ויניב (להלן: "בני הזוג") מעוניינים ברכישת דירה. בני הזוג פנו למתווך והדגישו בפניו כי הם מעוניינים שיאתר עבורם דירה "ללא חריגות וללא הפתעות". המתווך מצא לבני הזוג דירה, ונחתם הסכם מכר. אלא שלאחר החתימה על ההסכם, גילו בני הזוג כי חלק מהדירה נבנה ללא היתר. בהמשך לכך ביטלו בני הזוג את הסכם המכר.
על פי פסק דין בר"ע 209/01 זיוה וזאב מאיר נ'' טלי שושן ואח'', האם המתווך זכאי לדמי תיווך במקרה כזה? מדוע?', '["לא; משום שהסכם המכר בוטל בדיעבד.", "כן; המתווך זכאי לשכר טרחתו מרגע שנחתם הסכם מחייב ואין לכך חריגים.", "לא; למתווך ישנה חובה לברר פרטים מהותיים מסוג זה.", "כן; משום שלא הוכח כי המתווך ידע על חריגות הבנייה והיה על בני הזוג להסתייע באיש מקצוע בנושא זה."]'::jsonb, 2, null, 'בפרשת מאיר נ'' שושן נקבע שחובת הנאמנות והזהירות של המתווך לפי סעיף 8 לחוק המתווכים כוללת חובה לברר פרטים מהותיים על הנכס, ובוודאי כשהלקוח ביקש זאת במפורש. מתווך שלא בירר קיומן של חריגות בנייה הפר את חובתו, ומי שהפר את חובותיו אינו זכאי לדמי תיווך. הביטול עצמו (חלופה א'') אינו הנימוק, חלופה ב'' מתעלמת מתנאי הזכאות שבסעיף 14, וחלופה ד'' מגלגלת את החובה על הלקוח.', 'סעיף 8 לחוק המתווכים במקרקעין; בר"ע 209/01 מאיר נ'' שושן', 14, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q15', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 15', 'דנית התקשרה עם מתווכת בהסכם תיווך. המתווכת הציגה לדנית דירה, וזו ביקשה להגיש למוכרים הצעה בסך של מיליון ש"ח, הצעה נמוכה ב- 200,000 ש"ח מהמחיר המבוקש. המתווכת סירבה להעביר למוכרים את ההצעה, כי לדעתה אין סיכוי שיסכימו להצעה כה נמוכה.
לאחר מספר ימים פנה לדנית מתווך אחר והציע לה את אותה הדירה, דנית שכרה את שירותיו של המתווך, אשר ניהל משא ומתן עם המוכרים ולבסוף רכשה דנית את הדירה בסך של מיליון ש"ח בזכות המשא ומתן. דנית שילמה למתווך דמי תיווך. יחד עם זאת, למתווכת שהכירה לה את הנכס, דנית לא מעוניינת לשלם דמי תיווך.
המתווכת טוענת כי על דנית לשלם לה דמי תיווך. לאף אחד מהמתווכים לא היתה בלעדיות על הנכס בעיסקה.
על פי תא"מ 10272-02-11 ב.פ. הנשיא סוכנויות נדל"ן בע"מ נ'' בקרמן ואח'', האם המתווכת זכאית לדמי תיווך במקרה כזה?', '["לא; משום שהמתווכת הפרה את חובתה כלפי דנית ולכן אינה זכאית לדמי תיווך.", "כן; משום שמהמתווך אשר מראה את הדירה לראשונה לרוכש, והרוכש רכש את הדירה במועד קרוב (עד חצי שנה), חזקה שהוא הגורם היעיל בעיסקה. אלא אם למתווך אחר קיימת בלעדיות.", "כן, אך מאחר שהמתווכת רק הראתה את הדירה ולא ניהלה מו\"מ, יש לשלם לה מחצית מדמי התיווך לפי פסק הדין.", "כן; משום שלפי פסק הדין, מתווך אשר מראה את הדירה אינו מחויב להעביר הצעה מופרכת לדעתו, וזה חלק משיקול דעתו המקצועי."]'::jsonb, 0, null, 'מתווך חייב להעביר ללקוחו כל הצעה ולפעול לפי הוראותיו (חובת הנאמנות בסעיף 8 לחוק, והיום במפורש תקנה 14 לתקנות האתיקה); ההחלטה אם ההצעה "מופרכת" היא של הלקוח, לא של המתווך (חלופה ד''). המתווכת סירבה להעביר את ההצעה, הפרה את חובתה, ולא היא שהביאה לעסקה: המתווך השני ניהל את המשא ומתן והיה הגורם היעיל לפי סעיף 14(א)(3). חלופה ב'' הופכת את "מי שהראה ראשון" לחזקה שאינה קיימת בדין, וחלוקה למחצית (חלופה ג'') אינה נקבעת בפסק הדין.', 'סעיפים 8 ו-14(א)(3) לחוק המתווכים במקרקעין; תקנה 14 לתקנות האתיקה; תא"מ 10272-02-11 ב.פ. הנשיא נ'' בקרמן', 15, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q16', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 16', 'בבעלותו של משה היה בית עסק בדמי מפתח. משה נפטר ללא בת זוג. דני, בנו, מבקש להמשיך את השכירות בדמי המפתח.
האם הבן זכאי לעשות כן?', '["כן, ובתנאי שדני ימשיך לנהל בעצמו או על ידי אחרים, את העסק שאביו ניהל, ולא ישכירו.", "כן, ובתנאי שדני עבד עם אביו בעסק לפחות 6 חודשים לפני מותו.", "לא, מכיוון שלא ניתן להמשיך שכירות בדמי מפתח בנכס מסחרי, אלא בדירת מגורים בלבד.", "לא; במקרה שכזה הנכס יחזור לבעל הנכס ללא סייג."]'::jsonb, 0, null, 'חוק הגנת הדייר מסדיר גם בתי עסק (חלופה ג'' שגויה) ומכיר בדיירות נמשכת של בן זוג, ובהיעדרו של ילדי הדייר, בבית עסק (סעיף 23). התנאי שהחוק מציב להמשך הדיירות של הילד בבית עסק הוא שימשיך לנהל בו, בעצמו או על ידי אחרים, את העסק שניהל המנוח ולא ישכירו לאחר; זו החלופה שהמפתח הרשמי קבע כנכונה. חלופה ד'' מתעלמת מהדיירות הנמשכת כליל.', 'חוק הגנת הדייר [נוסח משולב], התשל"ב-1972, סעיף 23 והוראות הדיירות הנמשכת בבית עסק', 16, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q17', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 17', 'מהי "הצמדה" ברכוש משותף במקרקעין?', '["חיבור (הצמדה) בין שני בתים או יותר זה לזה בחלקה אחת, כגון בבית דו משפחתי.", "הצמדת השטח לרשות מקומית מסוימת. כל שטח במדינת ישראל מוצמד לרשות מקומית, כך שעל השטח חלות תוכניות בניין של הרשות המקומית.", "שיוך של רכוש ליחידה או לבעלים מסוים של מקרקעין בבית משותף.", "הצמדת כל נכס לבעלים שלו בנסח הטאבו."]'::jsonb, 2, null, 'סעיף 55(ג) לחוק המקרקעין מאפשר לקבוע בתקנון הבית המשותף שחלק מסוים של הרכוש המשותף (חניה, מחסן, גג, גינה) יהיה צמוד לדירה פלונית; מאותו רגע הוא חלק מהדירה לכל דבר ועניין. זו ההצמדה. שאר החלופות משתמשות במילה בהקשרים שאינם מונח משפטי: צירוף בתים (א''), שיוך לרשות מקומית (ב''), או רישום בעלות בנסח (ד'').', 'סעיף 55(ג) לחוק המקרקעין', 17, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
