  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q18', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 18', 'ברוך מעוניין למכור נכס. המתווך ששכר ברוך מצא קונה לנכס. הקונה ביקש מהמתווך להעביר בשמו הצעת רכישה בסכום של מיליון ש"ח. המתווך נפגש עם הקונה והמוכר, אך הצדדים לא הגיעו להסכמות ונפרדו, תוך שהמתווך התבקש להפסיק לעבוד על הנכס של ברוך, וברוך והרוכש התחמקו מהמתווך החל מרגע זה.
לאחר מספר שבועות, הקונה שוחח עם מתווך נוסף, וסיפר לו על הנכס. המתווך הנוסף הציע את שירותיו כמתווך, ליווה את הקונה לפגישה עם המוכר, ניהל את המשא ומתן, והביא את הצדדים למחיר שהיה מקובל על שני הצדדים. ההסכם נחתם ויצא לפועל.
לפי עא 7274/97 כוכבה יצחקוב נ'' מרדכי אביב מפעל בניה בע"מ, מי זכאי לדמי תיווך ומדוע?', '["שני המתווכים עשויים להיות זכאים לדמי תיווך; המתווך הראשון הפגיש בין הצדדים, והמתווך השני סייע לצדדים להגיע להסכמה.", "המתווך הראשון זכאי לדמי התיווך במלואם. הוא הפגיש בין הצדדים, ולכן הוא הגורם היעיל בעיסקה, כאשר בלעדיו לא הייתה נחתמת עיסקה.", "המתווך השני זכאי לדמי התיווך במלואם. אם לא היה מסייע לצדדים להגיע להסכמה לגבי המחיר, לא הייתה מתקיימת העיסקה, ולכן הוא הגורם היעיל.", "אף אחד מהמתווכים לא זכאי לדמי תיווך. לא ניתן לקבוע לגבי אף אחד מהם שהוא היה הגורם היעיל בעיסקה שבלעדיו לא הייתה נחתמת עיסקה."]'::jsonb, 0, null, 'בפרשת יצחקוב קבע בית המשפט העליון את מבחני "הגורם היעיל" (סעיף 14(א)(3) לחוק המתווכים), ובהם: מידת הדמיון בין ההצעה המקורית לעסקה שנחתמה, הזמן שחלף, האם הצדדים הכירו דרך המתווך, ומי ניהל את המשא ומתן. בית המשפט הכיר גם באפשרות שיותר ממתווך אחד תרם לעסקה ושניהם זכאים לשכר. כאן הראשון יצר את ההיכרות והשני הביא להסכמה, ולכן שניהם עשויים להיות זכאים; החלופות ב'' ו-ג'' מייחסות את כל השכר לאחד מהם בלבד, וחלופה ד'' שוללת את שניהם.', 'סעיף 14(א)(3) לחוק המתווכים במקרקעין; ע"א 7274/97 יצחקוב נ'' מרדכי אביב מפעל בניה', 18, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q19', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 19', 'על איזה מבין סוגי המקרקעין הבאים לא חלה הגבלה בהעברה לגורמים פרטיים לפי דין?', '["כל מקרקעי ישראל השייכים למדינה.", "מקרקעי ישראל שיש בהם כדי להשלים לגורם פרטי את נחלתו, להיקף שמעל מאה דונם.", "מקרקעי ישראל שיש בהם כדי להשלים לגורם פרטי את נחלתו, בהיקף של פחות ממאה דונם.", "מקרקעי ישראל השייכים לנפקדים וצאצאיהם אשר אינם אזרחי או תושבי ישראל."]'::jsonb, 2, null, 'חוק יסוד: מקרקעי ישראל קובע בסעיף 1 שהבעלות במקרקעי ישראל (המדינה, רשות הפיתוח וקק"ל) לא תועבר במכר או בדרך אחרת. סעיף 2 לחוק מקרקעי ישראל, התש"ך-1960, מונה חריגים לאיסור, ובהם העברת מקרקעין להשלמת נחלה או לחלוקה חדשה בשטח קטן (עד מאה דונם), ולכן רק חלופה ג'' נופלת בגדר ההיתר. שטח מעל מאה דונם (ב'') חוזר לאיסור, "כל מקרקעי המדינה" (א'') הוא היפוך הכלל, ונכסי נפקדים (ד'') מנוהלים לפי חוק נכסי נפקדים ואינם חריג להעברה.', 'סעיף 1 לחוק יסוד: מקרקעי ישראל; סעיף 2 לחוק מקרקעי ישראל, התש"ך-1960', 19, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q20', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 20', 'ליאור המתווך חושש מתביעות של לקוחותיו, ולכן בטפסי ההזמנה שלו כלל את המשפט הבא: "הלקוחות לא יהיו רשאים לתבוע את המתווך. מי שיתבע את המתווך יחויב לשלם לו פיצוי בסך 50,000 ש"ח, תהיינה תוצאות התביעה אשר תהיינה".
בנסיבות המתוארות, איזה מההיגדים הבאים הוא הנכון ביותר?', '["הלקוח יכול אך ורק לפנות לבית הדין לחוזים אחידים כדי שיבטל את התנאי הזה, ורק לאחר מכן יוכל להגיש תביעה כנגד המתווך.", "הלקוח יכול אך ורק לפנות בתלונה לוועדת המשמעת במשרד המשפטים כדי שתעמיד את המתווך לדין משמעתי, ורק לאחר שיורשע בדין יוכל להגיש תביעה נגדו.", "הלקוח יכול להפקיד בחשבון הבנק של המתווך 50,000 ש\"ח, שכן הסכים לתנאי בחוזה.", "הלקוח רשאי להגיש תביעה ללא חשש. טופס ההזמנה מהווה חוזה אחיד, ותנאי השולל או מגביל את זכות הלקוח לפנות לערכאות משפטיות בחוזה אחיד - בטל."]'::jsonb, 3, null, 'טופס הזמנה שהמתווך מנסח מראש לכלל לקוחותיו הוא חוזה אחיד. סעיף 5 לחוק החוזים האחידים קובע שתנאי בחוזה אחיד השולל או המגביל את זכות הלקוח לפנות לערכאות משפטיות בטל, מעיקרו ובלי צורך בהליך ביטול. לכן הלקוח פשוט תובע, ובית המשפט מתעלם מהתנאי. אין צורך בהליך מקדים בבית הדין לחוזים אחידים (א'') או בדין משמעתי (ב''), והפיצוי הקנסי (ג'') נופל יחד עם התנאי.', 'סעיף 5 לחוק החוזים האחידים, התשמ"ג-1982', 20, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
