  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q21', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 21', 'אופיר רכש דירה מקבלן בפרוייקט בנייה חדש, הרשום על שם החברה הקבלנית שבונה את הפרוייקט. אופיר ביקש לקחת הלוואה לצורך מימון הרכישה מקרן "מימון לישראל חזקה בע"מ". הקרן מבקשת לוודא שאין משכנתא או עיקול על אופיר או על היחידה שרכש וטרם נרשמה בטאבו.
היכן ייערך רישום השיעבודים?', '["רישום השיעבודים יתנהל תמיד ברשם המשכונות בלבד.", "רישום השיעבודים יתנהל תמיד בעירייה.", "רישום השיעבודים יתנהל בחברה המשכנת ורשם המשכונות.", "רישום השיעבודים יתנהל תמיד בטאבו באמצעות הערות אזהרה."]'::jsonb, 2, null, 'כל עוד הדירה לא נרשמה כיחידה בטאבו, לאופיר אין זכות קניינית רשומה אלא זכות חוזית כלפי הקבלן. שעבוד של זכות כזו נעשה כמשכון: הוא נרשם אצל רשם המשכונות לפי חוק המשכון (וכך הוא תקף כלפי נושים אחרים), ובמקביל נרשם בספרי החברה המשכנת, שמנהלת את מרשם הזכויות בפרויקט עד לרישום בטאבו. רק אחרי רישום הבית המשותף יהפוך השעבוד למשכנתא בטאבו (חלופה ד''), והעירייה (ב'') כלל אינה מרשם שעבודים.', 'חוק המשכון, התשכ"ז-1967 (רישום משכון אצל רשם המשכונות); רישום בחברה המשכנת עד לרישום בטאבו', 21, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
