insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q22', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 22', 'דוד מתגורר בבית משותף. דוד מעוניין להצמיד לדירתו חלק מחדר המדרגות, הנמצא בקומה של דירתו, וזאת לצורך הרחבת דירתו.
מהו הרוב הדרוש לדוד מתוך כלל דיירי הבניין לשם ביצוע האמור?', '["רוב רגיל מדיירי הבניין.", "דוד כלל לא יכול לבצע הצמדה כאמור לדירתו, אפילו אם יקבל את הסכמת כל הדיירים.", "רוב של 75% מבעלי הדירות, שלהם צמודים 2/3 מהרכוש המשותף.", "הסכמה של כלל בעלי הדירות."]'::jsonb, 1, null, 'סעיף 55(ג) לחוק המקרקעין מתיר להצמיד חלקים מהרכוש המשותף לדירה, "ובלבד שלא יהיו אלה חדרי מדרגות, מעליות, מקלטים ומתקנים המיועדים לשמש את כל בעלי הדירות". חדר המדרגות הוא ברשימה הסגורה של מה שאינו ניתן להצמדה כלל, ולכן שאלת הרוב (א'', ג'', ד'') אינה מתעוררת: גם הסכמה פה אחד אינה מכשירה את ההצמדה. המלכודת היא שהחלופות המספריות נשמעות מוכרות מהסעיפים על הרחבת דירה.', 'סעיף 55(ג) לחוק המקרקעין', 22, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
