insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q23', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 23', 'דני רכש דירה חדשה מקבלן.
מהי תקופת האחריות של הקבלן על הדירה ומתי היא מתחילה?', '["תקופה של שנה - מרגע שהתקבל טופס 4.", "תקופה של שלוש שנים - שתחילתה בתום תקופת הבדק.", "תקופה של שנה - שתחילתה בתום תקופת הבדק.", "החוק אינו קובע תקופת אחריות, והיא נקבעת לפי הוראות הסכם המכר שנחתם בין הצדדים."]'::jsonb, 1, null, 'סעיף 4 לחוק המכר (דירות) מבחין בין שתי תקופות: תקופת הבדק, שאורכה נקבע בתוספת לפי סוג הליקוי ומתחילה במסירת הדירה, ותקופת האחריות, שהיא שלוש שנים שתחילתן בתום תקופת הבדק. בתקופת הבדק הקבלן אחראי לכל ליקוי אלא אם יוכיח שנגרם באשמת הקונה, ובתקופת האחריות הנטל עובר לקונה להוכיח שהליקוי נובע מהבנייה. התקופות קבועות בחוק ואינן ניתנות להתניה לרעת הקונה (חלופה ד'').', 'סעיף 4 לחוק המכר (דירות), התשל"ג-1973', 23, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
