insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q24', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 24', 'אברהם ויצחק הם שכנים בעלי גדר משותפת. אברהם חפר והתקין צנרת מתחת לאדמה שבביתו של יצחק, על מנת להעביר במקום כבלים לתקשורת, אינטרנט וטלפון. יצחק כעס על כך שהדבר נעשה ללא הסכמה וללא תשלום כלשהו מצד אברהם, ודרש מאברהם להוציא את הכבלים מתחת לשטחו.
האם אברהם חייב להיענות לדרישתו של יצחק? מדוע?', '["לא; אברהם יכול להעביר צנרת ללא בקשת הסכמה מתחת לביתו של שכנו, כל עוד הצנרת אינה מזיקה או מפריעה באופן בלתי סביר להנאתו של השכן מהמקרקעין שלו.", "לא; אולם על אברהם לשלם ליצחק בגין זיקת הנאה למעבר מתחת לחלקה שלו.", "כן; אברהם חייב לפרק את הצנרת באופן מיידי, שכן החפירה וההנחה של הצנרת נעשו ללא הסכמת שכנו.", "כן; משום שהבעלות של יצחק על המקרקעין שלו מתפשטת לעומק הקרקע ואין לכך חריגים."]'::jsonb, 3, null, 'שימו לב: במפתח הרשמי של הבחינה שאלה זו סומנה "כל התשובות מתקבלות", כלומר הרשם ביטל אותה בפועל וכל נבחן קיבל עליה ניקוד. ברקע: סעיף 11 לחוק המקרקעין קובע שהבעלות בקרקע חלה גם על מה שמתחת לשטחה (בכפוף לדינים על מים, נפט ומחצבים), ולכן חפירה והנחת צנרת ללא הסכמה היא הסגת גבול; מנגד סעיף 14 קובע שבעלות אינה מצדיקה גרימת נזק לאחר, וחוק המקרקעין מכיר בזיקת הנאה בהסכמה או מכוח שנים. אף חלופה אינה מנוסחת בדיוק ("אין לכך חריגים" בחלופה ד'' אינו מדויק), ומכאן הביטול.', 'סעיפים 11 ו-14 לחוק המקרקעין (השאלה בוטלה במפתח הרשמי)', 24, false
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-05-q25', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, מאי 2025, שאלה 25', 'רמי מונה על ידי רשם הירושה כמנהל עזבונו של אפרים ז"ל. לאחר המינוי, גילה רמי שלמנוח נותר חוב של 500,000 ש"ח לבנק. הדרך היחידה לפרוע את החוב, הייתה למכור דירה שאפרים ז"ל רכש בחייו. שלמה, אחד הילדים של המנוח, מתנגד למכירה. אך לנוכח החובות, רמי הודיע לשלמה שאין ברירה, ומתוקף תפקידו כמנהל עיזבון הוא ימכור את הדירה לצד שלישי שאינו אחד מהיורשים. רמי מצא קונה, מכר את הדירה, וחילק את יתרת הכסף שנותר מהמכירה ליורשים.
האם רמי פעל כדין? מדוע?', '["כן; ידו של מנהל עיזבון כיד המוריש והוא רשאי לסלק את חובות העיזבון.", "כן; אך רק אם הציע לכל היורשים לקנות את הנכס תחילה במחיר שאינו נופל ממחיר השוק.", "לא; רמי לא יכול למכור את הדירה ללא הסכמת כל היורשים.", "לא; רמי צריך היה לקבל אישור בית משפט לפני מכירת דירת העיזבון."]'::jsonb, 3, null, 'סעיף 97 לחוק הירושה קובע שמנהל עיזבון לא יעשה, בלי אישור בית המשפט, העברה או שעבוד של מקרקעין (וכן פעולות מהותיות נוספות). סילוק חובות העיזבון הוא אמנם מתפקידיו, אך הדרך למכור דירה לשם כך עוברת באישור בית המשפט, לא בהסכמת היורשים (חלופה ג'') ולא בזכות קדימה ליורשים (חלופה ב''). חלופה א'' מתארת סמכות רחבה שאין למנהל עיזבון.', 'סעיף 97 לחוק הירושה, התשכ"ה-1965', 25, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-05'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'exam-2025-07', 'מבחן יולי 2025', 6, 'מבחן יולי 2025 נשען בכבדות על תקנות האתיקה החדשות: כמעט חצי מהשאלות שואלות "האם המתווך פעל כדין", ורובן נפתרות בתקנה אחת. ומי שלא קרא את חוק המקרקעין ואת פרק ההגדרות של מיסוי מקרקעין איבד כאן שבע שאלות בלי לשים לב.', '<p>25 שאלות, 4 נקודות לכל שאלה, ציון עובר 60. שאלה 21 בוטלה במפתח הרשמי וכל תשובה בה התקבלה. כך התחלקו השאלות לפי חוק:</p><ul><li><strong>חוק המתווכים ותקנות האתיקה: 11 שאלות</strong> (1, 2, 14, 15, 18, 19, 20, 21, 22, 23, 24). הנושאים: חוזה למראית עין, הטעיה והסתרת זהות רוכש, הסרת פרסום של נכס שנמכר, דמי רצינות, שירות נוסף במחיר אחד, דמי תיווך על חידוש שכירות, זיכרון דברים (אופז), הזמנה בכתב בוואטסאפ, פעולה בניגוד להוראת הלקוח, דייר מוגן כמידע מהותי, ובלעדיות במסמך נפרד (בראון נ'' סידרון).</li><li><strong>חוק המקרקעין: 4 שאלות</strong> (3, 8, 10, 11): הצמדת מקלט, מכירת חלק ממקרקעין, דרישת הכתב, ופירוק שיתוף למרות הסכם.</li><li><strong>חוק מיסוי מקרקעין: 3 שאלות</strong> (5, 6, 9): דירה יחידה לחנות, האישורים לרישום בטאבו, והגדרת דירת מגורים.</li><li><strong>רשות מקרקעי ישראל: 2 שאלות</strong> (12, 25): הסכם משבצת ודמי הסכמה.</li><li><strong>שאלה אחת מכל אחד מאלה:</strong> חוק המכר (דירות) (4, מפרט חסר), חוק החוזים (תרופות) (7, הפרה לא יסודית), חוק העונשין (13, התחזות), חוק הירושה (16, תאגיד כמנהל עיזבון), חוק התכנון והבנייה (17, הקלה מול שימוש חורג).</li></ul>', '["תקנות האתיקה הן המקור לרוב שאלות \"האם פעל כדין\": תקנה 13 (שירות נוסף בנפרד ובכתב), תקנה 19(ג) (הסרת פרסום בהקדם האפשרי), תקנה 26 (לא דמי רצינות ולא תשלום על חידוש חוזה). שלוש תקנות, שלוש שאלות.", "שתי שאלות פסיקה חוזרות: אופז (זיכרון דברים הוא עבירה פלילית ושולל דמי תיווך) ובראון נ'' סידרון (בלעדיות חייבת מסמך נפרד, ואי אפשר להתנות על כך).", "מלכודת הנוסח \"בתוך 3 ימים\": בשאלות 7 ו-14 החלופה עם מועד קצוב היא הפיתוי. החוק אומר \"זמן סביר\" ו\"בהקדם האפשרי\", בלי מספר.", "חוק המקרקעין נשאל דרך סעיפים ספציפיים שכדאי לזכור במספר: 8 (דרישת הכתב), 13 (אין עסקה בחלק ממקרקעין), 37(ב) (פירוק שיתוף אחרי 3 שנים), 55(ג) (מקלט ומדרגות אינם ניתנים להצמדה).", "מיסוי מקרקעין נשאל על הגדרות ולא על חישובים: \"דירת מגורים\" היא רק דירה שבנייתה נסתיימה, ומדרגות דירה יחידה לא חלות על חנות."]'::jsonb, '[]'::jsonb, 'רשם המתווכים במקרקעין, מועד 31.07.2025, גרסה 1', null, false, true
  from public.course_chapters c where c.slug = 'past-exams'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q01', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 1', 'שוש היא מתווכת במקרקעין. נמרוד פנה לשוש, וביקש ממנה שתמצא קונה לדירתו. נמרוד היתנה את חתימתו על טופס הזמנת שירותי תיווך בכך, שבהסכם המכר יירשם סכום נמוך באופן משמעותי מסכום המכירה בפועל, וזאת במטרה לחסוך במס שבח, דבר שהינו בניגוד לחוק. שוש הסכימה לכך, ונמרוד חתם על טופס הזמנת שירותי תיווך בהתאם. שוש פנתה לקונה וסיכמה עימו שמחיר הנכס יעמוד על 1,300,000 ש"ח, אך הצדדים ירשמו בחוזה שהמחיר הוא 1,000,000 ש"ח בלבד. בנסיבות אלה, האם המתווכת שוש פעלה כדין? מדוע?', '["כן; שוש פעלה בנאמנות ובמסירות עבור הלקוח, ותוכן הסכם המכר אינו בסמכותו של המתווך.", "כן; משום שטופס הזמנת שירותי התיווך כולל מחיר משוער של נכסים בלבד.", "לא; אסור היה לשוש כמתווכת לקבוע מחיר עם הצד השני לעיסקה.", "לא; אסור היה לשוש כמתווכת לשתף פעולה עם הסכם למראית עין בלבד."]'::jsonb, 3, null, 'חוזה שבו המחיר הרשום שונה מהמחיר האמיתי כדי להונות את רשויות המס הוא חוזה למראית עין, שלפי סעיף 13 לחוק החוזים (חלק כללי) בטל, ומסירת הצהרה כוזבת לרשויות מיסוי מקרקעין היא עבירה. מתווך/ת חייב/ת לפעול בנאמנות, בהגינות ובדרך מקובלת (סעיף 8(א) לחוק המתווכים) וביושר ותום לב (תקנה 2 לתקנות האתיקה), ונאמנות ללקוח אינה מתירה שיתוף פעולה בעבירה, ולכן חלופה א'' נדחית. חלופה ג'' שגויה כי אין איסור על מתווך/ת לנהל משא ומתן על המחיר, והפסול הוא בהסכם הכוזב, לא במשא ומתן.', 'סעיף 13 לחוק החוזים (חלק כללי); סעיף 8 לחוק המתווכים; תקנה 2 לתקנות האתיקה', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q02', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 2', 'ראובן פנה לגילה, מתווכת במקרקעין, בבקשה שתסייע לו למצוא רוכש לנכס מסחרי שבבעלותו. בהתאם לכך, חתם ראובן על טופס הזמנת שירותי תיווך, ללא בלעדיות, לפיו התחייב לשלם דמי תיווך בשיעור 1% משווי העיסקה. שבועיים לאחר מכן פגש ראובן רוכש פוטנציאלי בשם יוסף, ומסר לו את כל פרטי הנכס, כולל את גובה דמי השכירות המשולמים לו עבור הנכס. יוסף דחה את ההצעה משום שלדעתו דמי השכירות היו נמוכים מידי. לאחר כשבועיים פנה יוסף לגילה והתעניין ברכישת נכס מסחרי. גילה הציגה בפני יוסף את הנכס שבבעלות ראובן. יוסף הודיע לגילה מיד, כי הוא מכיר את הנכס וכי קיבל כבר הצעה מראובן, אלא שלאור דמי השכירות הנמוכים, דחה אותה. גילה הבטיחה ליוסף, כי יש לה שוכרים אחרים שמוכנים לשלם דמי שכירות גבוהים יותר, ואף הציגה לו אותם. יוסף התרצה, וחתם על טופס הזמנת שירותי תיווך. גילה הודיעה לראובן, כי יש לה רוכש חדש, אותו ראובן אינו מכיר, ודרשה מראובן לחתום על טופס הזמנת שירותי תיווך חדש, לפיו נדרש ראובן לשלם דמי תיווך בשיעור 2% משווי העיסקה. כשבועיים לאחר מכן, במעמד חתימת הסכם המכר, הופתע ראובן לגלות כי הרוכש "החדש" הוא לא אחר מאשר יוסף, אותו הכיר. ראובן הודיע לגילה על ביטול ההסכם השני, וסירב לשלם לה דמי התיווך בשיעור 2%, בטענה כי גילה הטעתה אותו. האם ראובן צודק? מדוע?', '["לא; מאחר שראובן חתם על טופס הזמנת שירותי תיווך וגילה הייתה הגורם היעיל בעיסקה, הוא חייב לקיימו.", "כן; גילה לא הייתה הגורם היעיל לעיסקה.", "כן; גילה הטעתה את ראובן, הן לעניין זהות הרוכש והן בכך שלא גילתה לראובן עובדות מהותיות בקשר לאותו רוכש.", "לא; גילה אינה חייבת לגלות לראובן כל מידע בקשר לרוכש לפני חתימתו על הסכם להזמנת שירותי תיווך."]'::jsonb, 2, null, 'סעיף 8 לחוק המתווכים מחייב מתווך/ת לנהוג בהגינות ולמסור ללקוח כל מידע מהותי, ותקנה 4 לתקנות האתיקה אוסרת הטעיה בעניין מהותי, גם במחדל. זהות הרוכש, שראובן כבר פגש ודחה, היא עובדה מהותית שהסתרתה גרמה לראובן לחתום על הסכם יקר יותר, ולכן ההסכם השני ניתן לביטול בשל הטעיה (סעיף 15 לחוק החוזים). חלופה א'' נופלת כי הסכם שהושג בהטעיה אינו מחייב גם אם המתווכת תרמה לעסקה; חלופה ב'' נדחית כי השאלה אינה הגורם היעיל אלא ההטעיה; וחלופה ד'' סותרת את חובת הגילוי.', 'סעיף 8 לחוק המתווכים; תקנה 4 לתקנות האתיקה; סעיף 15 לחוק החוזים (חלק כללי)', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q03', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 3', 'דיירים בבית משותף ברחוב הציונות 19 בעפולה, קיימו אסיפת דיירים. באסיפה עלתה הצעה להצמיד מקלט לאחת הדירות בלבד, בתמורה לתשלום כספי לקופת הבית המשותף המדולדלת. בהצבעה תמכו בהצעה מאה אחוז מהדיירים. האם ניתן להצמיד את המקלט לאחת הדירות בבית המשותף? אם כן, באיזה רוב של דיירי הבית המשותף ניתן לעשות כן?', '["ניתן לבצע הצמדה כאמור והרוב הדרוש לכך הוא של 2/3 מבעלי הדירות בבית המשותף.", "ניתן לבצע הצמדה כאמור, אך נדרש לכך רוב של 100 אחוז מבעלי הדירות בבית המשותף.", "ניתן לבצע הצמדה כאמור, אך נדרש לשם כך רוב רגיל של בעלי הדירות בבית המשותף.", "לא ניתן להצמיד מקלט לדירה מסוימת בבית משותף, גם לא בהסכמה של כל בעלי הדירות בבית המשותף."]'::jsonb, 3, null, 'סעיף 55(ג) לחוק המקרקעין מתיר לבעלי הדירות לקבוע בתקנון שחלק מסוים מהרכוש המשותף יוצמד לדירה פלונית, אך מוציא מכלל זה במפורש חדרי מדרגות, מעליות, מקלטים ומיתקנים המיועדים לשמש את כל בעלי הדירות. מקלט הוא אחד החלקים שאינם ניתנים להצמדה כלל, ולכן גם הסכמה של מאה אחוז מהדיירים אינה מועילה. שלוש החלופות הראשונות עוסקות בגודל הרוב, אך כאן אין רוב שיכול להכשיר את ההצמדה.', 'סעיף 55(ג) לחוק המקרקעין', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q04', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 4', 'יוסף רכש דירה חדשה מקבלן. הקבלן לא צירף לחוזה המכר את המפרט של הדירה, ובין הצדדים התגלע סכסוך בנושא איכות הגימור שעל הקבלן לספק ליוסף בדירה החדשה. בנסיבות המתוארות, איזה מההיגדים הבאים הוא הנכון ביותר?', '["על הקבלן למסור את הדירה כשכל פרט שהיה אמור להיכלל במפרט הוא באיכות גבוהה.", "על הקבלן למסור את הדירה כשכל פרט שהיה אמור להיכלל במפרט הוא באיכות סבירה.", "הקבלן רשאי למסור גימור בכל איכות שהיא, אלא אם החוזה בין הצדדים מחייב אותו במפורש אחרת.", "מדובר בעניין שבין הצדדים לחוזה, הדין אינו מתייחס כלל לאיכות הגימור של דירה חדשה."]'::jsonb, 0, null, 'חוק המכר (דירות) מחייב את המוכר לצרף לחוזה מפרט (סעיף 2), וסעיף 5(א) קובע את הסנקציה: מוכר שלא מסר מפרט, או שהמפרט אינו כולל פרט שחובה לכלול בו, רואים אותו כאילו התחייב שאותו פרט יהיה בטיב ובאיכות גבוהים. כלומר החסר פועל לרעת הקבלן ולא לרעת הקונה. חלופה ב'' (איכות סבירה) היא הסטנדרט של חוק המכר הכללי, אך חוק המכר (דירות) מחמיר יותר; חלופות ג'' ו-ד'' מתעלמות מהחוק, שהוא קוגנטי ואינו ניתן להתניה לרעת הקונה (סעיף 7א).', 'סעיפים 2 ו-5(א) לחוק המכר (דירות)', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q05', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 5', 'שלומי חיפש חנות לקנייה, ופנה למתווכת מירי שתסייע לו בעניין. שבועיים לאחר מכן התקשרה מירי לשלומי ועידכנה אותו כי מצאה חנות עבורו, במחיר של 1.2 מיליון ש"ח. אין בבעלותו של שלומי כל דירת מגורים. האם שלומי יהיה זכאי לסיווג של "דירה יחידה" לצורכי מס רכישה בגין רכישת החנות? מדוע?', '["כן; הואיל ואין בבעלות שלומי כל דירת מגורים, הוא פטור לחלוטין ממס רכישה.", "כן; הואיל ושווי החנות הוא מתחת לתקרת דירה יחידה, שלומי יהיה פטור ממס רכישה.", "לא; שלומי לא יהיה פטור ממס רכישה, אולם הוא יהיה פטור ממס שבח בעת מכירת החנות.", "לא; מדרגות מס רכישה ל\"דירה יחידה\" אינן תקפות לגבי מקרקעין שאינם דירת מגורים."]'::jsonb, 3, null, 'מדרגות מס הרכישה המוטבות ל"דירה יחידה" שבסעיף 9 לחוק מיסוי מקרקעין חלות רק על דירת מגורים כהגדרתה בחוק. חנות היא נכס מסחרי, ולכן היא ממוסה בשיעור האחיד החל על מקרקעין שאינם דירת מגורים, בלי קשר לשאלה אם לרוכש יש דירה. חלופות א'' ו-ב'' מערבבות בין הטבה לדירת מגורים לבין נכס עסקי, וחלופה ג'' טועה פעמיים: אין פטור ממס רכישה, ופטור ממס שבח במכירה ניתן לדירת מגורים מזכה ולא לחנות.', 'סעיף 9 לחוק מיסוי מקרקעין (שבח ורכישה)', 5, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q06', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 6', 'אילו אישורים דורש רשם המקרקעין (טאבו) מצדדים לעיסקה, כתנאי לרשום את זכויותיו של רוכש דירת מגורים שבבעלות המוכר?', '["אישור מס רכישה, אישור מס שבח, אישור מס הכנסה ואישור מהרשות המקומית.", "אישור מס רכישה, אישור מס שבח, אישור מהרשות המקומית על היעדר חובות, אישור אדריכל על היעדר חריגות בנייה.", "אישור מס רכישה, אישור מס שבח, אישור הרשות המקומית על היעדר חובות.", "אישור מס רכישה, אישור מס שבח, אישור הרשות המקומית על היעדר חובות ואישור רשות מקרקעי ישראל."]'::jsonb, 2, null, 'סעיף 16 לחוק מיסוי מקרקעין קובע שמכירת זכות במקרקעין לא תירשם בפנקסי המקרקעין אלא אם ניתנו אישורי המנהל על תשלום מס השבח ומס הרכישה (או על פטור מהם), וסעיף 324 לפקודת העיריות דורש תעודה מהרשות המקומית על סילוק החובות בגין הנכס (ארנונה והיטל השבחה). הנכס בבעלות פרטית של המוכר, ולכן אין צורך בהסכמת רשות מקרקעי ישראל (חלופה ד''), ואין דרישה לאישור מס הכנסה (חלופה א'') או לאישור אדריכל (חלופה ב'').', 'סעיף 16 לחוק מיסוי מקרקעין; סעיף 324 לפקודת העיריות', 6, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
