  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q07', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 7', 'אורלי ואורן כרתו ביניהם חוזה מכר של דירה; אורלי המוכרת ואורן הוא הרוכש. אורן הפר את אחד מסעיפי החוזה, הפרה לא יסודית. בנסיבות המתוארות, איזה מההיגדים הבאים הוא הנכון ביותר?', '["אורלי זכאית לבטל את החוזה באופן מיידי.", "אורלי אינה זכאית לבטל את החוזה במקרה של הפרה לא יסודית.", "אורלי זכאית לבטל את החוזה רק לאחר שנתנה לאורן אורכה לקיום החוזה והחוזה לא קוים בתוך זמן סביר לאחר מתן האורכה.", "אורלי אינה זכאית לביטול החוזה, אלא אם נתנה לאורן 3 ימי עסקים לתיקון ההפרה."]'::jsonb, 2, null, 'חוק החוזים (תרופות בשל הפרת חוזה) מבחין בין הפרה יסודית, שמקנה זכות ביטול מיידית (סעיף 7(א)), לבין הפרה לא יסודית, שבה הנפגע רשאי לבטל רק אחרי שנתן למפר ארכה לקיום החוזה והחוזה לא קוים בתוך זמן סביר לאחריה (סעיף 7(ב)). חלופה א'' מתאימה להפרה יסודית בלבד, חלופה ב'' שגויה כי ביטול אפשרי אחרי ארכה, וחלופה ד'' ממציאה תקופה קבועה של 3 ימי עסקים שאינה בחוק, שמדבר על זמן סביר.', 'סעיף 7 לחוק החוזים (תרופות בשל הפרת חוזה)', 7, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
