  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q08', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 8', 'נעמי ירשה מהוריה בית פרטי בנהריה, אשר מבחינה תכנונית אינו ניתן לחלוקה. הבית הוא בשטח של 250 מ"ר ומחולק לשתי קומות. נעמי מעוניינת לפצל את הנכס לשתי דירות, אחת בכל קומה, ולמכור אחת מהן. בנסיבות המתוארות, האם נעמי תוכל למכור רק את אחת הקומות בבית שירשה? מדוע?', '["כן; החוק אינו עוסק בפיצול של נכס לשתי יחידות.", "כן; אולם רק אם אף אחת מהדירות אינה עולה בשוויה על מיליון ש\"ח.", "לא; משום שלא ניתן למכור רק חלק ממקרקעין.", "לא; משום שלא שולם היטל השבחה בגין הפיצול."]'::jsonb, 2, null, 'סעיף 13 לחוק המקרקעין קובע שעסקה במקרקעין חלה על הקרקע יחד עם הבנוי והנטוע עליה, ואין תוקף לעסקה בחלק מסוים במקרקעין. קומה בבית פרטי אינה יחידה רישומית נפרדת, ואפשר למכור אותה בנפרד רק אחרי חלוקה תכנונית ורישום הבית כבית משותף, וכאן נאמר שהנכס אינו ניתן לחלוקה. חלופה ב'' ממציאה תקרת שווי שאינה קיימת, וחלופה ד'' מערבבת היטל השבחה, שנגבה על השבחה תכנונית, עם השאלה אם העסקה אפשרית בכלל.', 'סעיף 13 לחוק המקרקעין', 8, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
