  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q09', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 9', 'מה מבין הבאים לא יכול להיות מוכר כ"דירת מגורים יחידה" לצורכי מס שבח?', '["דירה המיועדת למגורים שבנייתה נסתיימה.", "דירה המיועדת למגורים שבנייתה טרם נסתיימה.", "חלק מדירת מגורים.", "דירה בבעלותו של יחיד."]'::jsonb, 1, null, 'סעיף 1 לחוק מיסוי מקרקעין מגדיר "דירת מגורים" כדירה או חלק מדירה, שבנייתה נסתיימה, שהיא בבעלותו או בחכירתו של יחיד, ומשמשת למגורים או מיועדת למגורים לפי טיבה. דירה שבנייתה טרם נסתיימה אינה עומדת בהגדרה ולכן אינה יכולה ליהנות מפטור של דירת מגורים מזכה. חלק מדירה (חלופה ג'') ודירה בבעלות יחיד (חלופה ד'') נכללים במפורש בהגדרה.', 'סעיף 1 לחוק מיסוי מקרקעין (הגדרת "דירת מגורים")', 9, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
