insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q10', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 10', 'רועי מעוניין למכור את דירתו למרדכי. רועי ומרדכי הגיעו ביחד לרשם המקרקעין והודיעו לו שהם סיכמו ביניהם בעל פה על עיסקת מכר בנוגע לדירה. האם רשם המקרקעין יבצע רישום בטאבו של העיסקה בין הצדדים כאמור? מדוע?', '["כן; אם מתקיימים היסודות הנדרשים בחוק החוזים לחוזה.", "כן; אם הונחה דעתו של הרשם שמדובר בעיסקה שאינה פיקטיבית.", "לא; מכיוון שעיסקת מקרקעין טעונה מסמך בכתב.", "לא; מכיוון שרשם המקרקעין אינו הסמכות לרישום עיסקת מקרקעין."]'::jsonb, 2, null, 'סעיף 8 לחוק המקרקעין קובע שהתחייבות לעשות עסקה במקרקעין טעונה מסמך בכתב, וזו דרישה מהותית ולא ראייתית: בלי מסמך אין התחייבות תקפה. הרישום עצמו נעשה לפי שטר עסקה חתום ומאומת, ועסקה במקרקעין נגמרת ברישום (סעיף 7). סיכום בעל פה, גם אם שני הצדדים מודים בו, אינו מספיק. חלופה ד'' שגויה כי רשם המקרקעין הוא בדיוק הגורם שרושם עסקאות.', 'סעיפים 7 ו-8 לחוק המקרקעין', 10, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
