  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q11', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 11', 'נוי ועמית רכשו חלקת קרקע. נוי ועמית חתמו על הסכם שיתוף המסדיר את היחסים המשפטיים ביניהן בקשר לקרקע. אחד מהסעיפים בהסכם השיתוף קובע כי נוי ועמית אינן רשאיות לפרק את השיתוף ביניהן. תוקפו של הסעיף ל- 10 שנים מיום חתימת ההסכם. לאחר 5 שנים ממועד חתימת ההסכם, נוי ועמית הסתכסכו, ועמית מעוניינת לפרק את השיתוף. בנסיבות המתוארות, איזה מההיגדים הבאים הוא הנכון ביותר?', '["עמית אינה רשאית לדרוש את פירוק השיתוף כל עוד לא עברו 10 שנים מיום חתימת ההסכם.", "עמית רשאית לדרוש את פירוק השיתוף רק אם נוי תסכים לכך.", "בית משפט רשאי לפרק את השיתוף אם נראה לו הדבר צודק בנסיבות העניין.", "עמית יכולה לפנות לרשם המקרקעין (טאבו) ולפרק את השיתוף."]'::jsonb, 2, null, 'סעיף 37(א) לחוק המקרקעין קובע שכל שותף זכאי בכל עת לדרוש פירוק שיתוף, וסעיף 37(ב) מגביל את כוחו של הסכם שיתוף לשלול זכות זו: אם ההסכם שולל או מגביל את הזכות לתקופה העולה על שלוש שנים, בית המשפט רשאי, כעבור שלוש שנים, לצוות על פירוק השיתוף אם נראה לו הדבר צודק בנסיבות העניין. כאן עברו חמש שנים, ולכן עמית יכולה לפנות לבית המשפט. חלופה א'' מתעלמת מתקרת שלוש השנים, וחלופה ד'' שגויה כי פירוק בניגוד להסכם הוא עניין לבית המשפט ולא לרשם.', 'סעיף 37 לחוק המקרקעין', 11, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q12', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 12', 'מהו "הסכם משבצת" במושב חקלאי?', '["הסכם שכירות של עד 10 שנים בין אגודה שיתופית לרשות מקרקעי ישראל.", "הסכם מכר בין אגודה שיתופית לסוכנות היהודית.", "הסכם חכירה בין אגודה שיתופית לרשות מקרקעי ישראל.", "הסכם מכר בין אגודה שיתופית לרשות מקרקעי ישראל."]'::jsonb, 2, null, 'הסכם משבצת הוא חוזה החכירה שבין רשות מקרקעי ישראל לבין האגודה השיתופית של המושב, שמכוחו האגודה מחזיקה בשטח המשבצת של היישוב וחברי המושב מחזיקים בנחלות שלהם. מקרקעי ישראל אינם נמכרים (חוק יסוד: מקרקעי ישראל), ולכן כל חלופה שמדברת על הסכם מכר נפסלת, והסוכנות היהודית, גם כשהיא צד ל"חוזה משולש", אינה הבעלים ואינה מוכרת. חלופה א'' מגדירה את ההסכם כשכירות קצרה עם תקרת שנים שאינה מאפיינת אותו.', 'חוק יסוד: מקרקעי ישראל; החלטות מועצת מקרקעי ישראל בעניין הסכמי משבצת', 12, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
