  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q13', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 13', 'כפיר הוא בעלים של דירה. לכפיר יש אח תאום בשם אופיר. אופיר הצליח להשיג את תעודת הזהות של כפיר, פרסם למכירה את הדירה של כפיר, ומכר אותה, תוך שהוא מתחזה לכפיר, הבעלים האמיתי של הנכס. מה העונש הצפוי לאופיר על התחזות זו?', '["עבודות שירות של עד 24 חודשים.", "מאסר על תנאי של עד 12 חודשים.", "מאסר של עד 3 שנים.", "מאסר בית של עד 6 חודשים."]'::jsonb, 2, null, 'סעיף 441 לחוק העונשין קובע שהמתחזה כאדם אחר, חי או מת, בכוונה להונות, דינו מאסר שלוש שנים. זו העבירה שמתאימה בדיוק למעשה של אופיר, שהשתמש בתעודת הזהות של אחיו כדי להציג את עצמו כבעלים. שאר החלופות נוקבות בעונשים (עבודות שירות, מאסר על תנאי, מאסר בית) שהם דרכי ריצוי או ענישה שבית המשפט רשאי לקבוע בתוך העונש המרבי, ולא העונש הקבוע בחוק לעבירה.', 'סעיף 441 לחוק העונשין', 13, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
