  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q14', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 14', 'שאול עבר בהצלחה את המבחן האחרון שהתקיים להסמכת מתווכים וקיבל את רישיון התיווך. שאול התחיל לעבוד כמתווך והגיע להסכמה עם ציפורה, בעלת דירה, כי יפרסם את דירתה למכירה, אך לא קיבל בלעדיות. לאחר כשלושה שבועות ציפורה הודיעה לשאול כי מכרה את הדירה בעצמה. שאול השאיר את המודעה שפירסם בקשר לדירתה, למשך חצי שנה נוספת, וענה לשלושה מתעניינים בפרק הזמן הזה. האם שאול פעל כדין בנסיבות אלה? מדוע?', '["כן; מותר לפרסם מודעות באזור הפעילות של מתווך ובכלל זה נכס לדוגמא שכבר נמכר.", "כן; אין למתווך כל מניעה להמשיך ולפרסם נכס שכבר נמכר.", "לא; על שאול חלה החובה להסיר פרסום של נכס שנמכר בתוך 3 ימי עסקים ממועד ההודעה על כך.", "לא; על שאול חלה החובה להסיר בהקדם האפשרי פרסום של נכס שנמכר."]'::jsonb, 3, null, 'תקנה 19(ג) לתקנות האתיקה מחייבת מתווך/ת להסיר או לעדכן בהקדם האפשרי פרסום של נכס שאינו עוד למכירה או להשכרה. אין בתקנה מועד קצוב של ימי עסקים, ולכן חלופה ג'' שגויה אף שהיא מגיעה למסקנה הנכונה. השארת המודעה חצי שנה ומענה למתעניינים היא גם הטעיה לפי תקנה 4 (הצגת נכס שאינו מיועד למכירה) וגם שיווק ללא הסכמת בעלת הזכות לפי תקנה 18, ולכן חלופות א'' ו-ב'' נדחות.', 'תקנה 19(ג) לתקנות האתיקה; תקנות 4 ו-18', 14, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q15', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 15', 'תומר הוא מתווך מקרקעין. תומר מתמחה בליווי משקיעים לרכישת דירות להשקעה. לקוחותיו של תומר משלמים לו דמי רצינות כמקדמה על סך 5,000 ש"ח וסכום זה מקוזז מדמי התיווך כאשר נחתמת עיסקה. האם תומר פועל כדין? מדוע?', '["כן; כל עוד תומר מצהיר לרשויות המס על הכנסתו מדמי התיווך.", "לא; על תומר חל איסור מוחלט לגבות דמי רצינות בגין עיסקת תיווך.", "כן; כל עוד דמי התיווך ייגבו בנוסף ובנפרד מדמי הרצינות.", "לא; אלא אם הלקוח אישר זאת בכתב מראש ולא בדיעבד."]'::jsonb, 1, null, 'תקנה 26 לתקנות האתיקה אוסרת על מתווך/ת לגבות תשלום בעד תיווך שלא לפי סעיף 14 לחוק, ובפרט דמי קדימה או דמי רצינות, ואף אוסרת להתנות את השירות בתשלום כזה. סעיף 14 לחוק מקנה זכות לדמי תיווך רק אחרי שנכרת הסכם מחייב בין הצדדים לעסקה, ולכן גבייה מראש, גם כמקדמה שתקוזז, אסורה. הסכמת הלקוח בכתב (חלופה ד'') או דיווח למס (חלופה א'') אינם מכשירים את האיסור.', 'תקנה 26 לתקנות האתיקה; סעיף 14 לחוק המתווכים', 15, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
