  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q16', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 16', 'יוסף נפטר, והותיר מספר בתים בעזבונו. בצוואתו ציווה יוסף שחברת "ארטיקים לכל כיס" תהיה מנהלת העיזבון, ואם לא יתאפשר, אזי ימונה בנו הבגיר למנהל העיזבון. בנסיבות המתוארות, איזה מההיגדים הבאים הוא הנכון ביותר?', '["לא ניתן למנות חברה כמנהלת עיזבון, אלא רק אדם מעל גיל 18 יכול להיות מנהל עיזבון.", "ניתן למנות חברה כמנהלת עזבון אך ורק אם לא יתאפשר לבנו של הנפטר להיות מנהל עיזבון, כגון עקב מחלה.", "ניתן למנות חברה כמנהלת עיזבון.", "בית המשפט לא רשאי להתערב בבקשתו של נפטר בקשר למינוי מנהל עיזבון, וימנה רק את מי שהנפטר ציין בצוואתו כמנהל עיזבון."]'::jsonb, 2, null, 'סעיף 79 לחוק הירושה קובע שמנהל עיזבון יכול להיות יחיד, תאגיד או האפוטרופוס הכללי, ולכן חברה כשרה לשמש מנהלת עיזבון. חלופות א'' ו-ב'' מגבילות את הכשרות הזו בלי בסיס בחוק. חלופה ד'' שגויה כי המינוי נעשה על ידי בית המשפט (או הרשם לענייני ירושה), ואף שהוא נוהג לכבד את מי שהמצווה קבע בצוואתו, שיקול הדעת נשאר בידו ואין הוא כבול למינוי שצוין בצוואה.', 'סעיף 79 לחוק הירושה', 16, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
