insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q17', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 17', 'מה ההבדל בין "שימוש חורג" ל"הקלה"?', '["הקלה היא מתן רשות לעשות שימוש חורג בנכס, שימוש חורג הוא שימוש בנכס בניגוד לרישיון העסק.", "הקלה היא שימוש השונה מזה שנקבע בתוכנית החלה על הנכס או בהיתר הבנייה, שימוש חורג הוא בנייה בשינוי קל מהוראות התוכנית החלה על הנכס.", "הקלה היא בנייה בשינוי קל מהוראות התוכנית החלה על הנכס, שימוש חורג הוא שימוש השונה מזה שנקבע בתוכנית החלה על הנכס או בהיתר הבנייה.", "הקלה היא בנייה בשינוי קל מהוראות התוכנית החלה על הנכס, שימוש חורג הוא בנייה בשינוי גדול מהוראות התוכנית החלה על הנכס."]'::jsonb, 2, null, 'סעיף 1 לחוק התכנון והבנייה מגדיר "הקלה" כהרשאה לבצע עבודה שהיא טעונה היתר בסטייה מהוראות תכנית, כלומר שינוי קל בבנייה (קווי בניין, גובה וכדומה), ו"שימוש חורג" כשימוש בקרקע או בבניין למטרה שלא הותר להשתמש בה לפי התכנית או ההיתר. הקלה עוסקת בבנייה, שימוש חורג עוסק בייעוד. חלופה ב'' מחליפה בין השניים, חלופה א'' קושרת את המונח לרישיון עסק שאינו קשור, וחלופה ד'' הופכת את שימוש חורג לעניין של בנייה בלבד.', 'סעיף 1 לחוק התכנון והבנייה; סעיפים 146-147 לחוק', 17, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
