insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q18', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 18', 'יובל הוא מתווך רשום, וגם מעצב פנים. יובל החתים רוכש פוטנציאלי על הסכם להזמנת שירותי תיווך בסך 2% מסכום העיסקה והציג בפניו בית לרכישה. הרוכש מעוניין ברכישת הבית, אך מבקש להפחית את דמי התיווך ל- 1% מסכום העיסקה. יובל מספר לו שהוא עוסק גם כמעצב פנים. הם מגיעים לידי הסכמה שהרוכש ישלם 2% דמי תיווך, כפי שכתוב בהסכם, אך יובל גם יעצב את הבית מחדש בעבור אותו תשלום. האם יובל פעל כדין? מדוע?', '["כן; כל עוד דמי התיווך אינם גבוהים מ- 2% אין מניעה להוסיף שירות במסגרת אותו התשלום.", "לא; על המתווך להבחין במפורש ובכתב בין סכום דמי התיווך לבין סכום נוסף בעבור כל שירות נוסף.", "כן; מאחר שעיצוב הבית הוא עיסוק שמסייע למתווכים למכור את הבית, מתווכים רשאים להציע את שירותיהם כמעצבים במסגרת התשלום על התיווך.", "לא; בכל מקרה על המתווך נאסר לעסוק עם לקוחו בכל עיסוק אחר שאינו תיווך."]'::jsonb, 1, null, 'תקנה 13 לתקנות האתיקה מתירה למתווך/ת לתת ללקוח גם שירותים שאינם תיווך, אך מחייבת להבחין במפורש ובכתב בין דמי התיווך לבין התמורה בעד כל שירות נוסף. תשלום אחד שמערבב תיווך ועיצוב פנים הוא בדיוק מה שהתקנה אוסרת, וגם מטשטש את הבסיס לדמי התיווך לפי סעיף 14 לחוק. חלופה ד'' מרחיקה לכת: אין איסור על עיסוק נוסף, רק חובת הפרדה; וחלופות א'' ו-ג'' מתעלמות מחובת ההפרדה בכתב.', 'תקנה 13 לתקנות האתיקה', 18, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
