  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q19', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 19', 'גלית שכרה דירה באמצעות מתווך. השכירות עומדת להסתיים, וגלית שכחה להודיע לבעל הבית על רצונה להמשיך את השכירות. כחודש לפני תום השכירות, בעל הנכס חתם על בלעדיות לאותו המתווך, אשר יצר קשר עם גלית והסביר לה כי הוא מבקש לקבוע עם שוכרים פוטנציאליים. המתווך סיפר לגלית שהוא פרסם את הנכס, ועבד שעות רבות על מנת להביא שוכרים לנכס. גלית המופתעת מבקשת להישאר בדירה, אך המתווך מבהיר לה כי במידה שהיא מעוניינת להישאר בדירה, המדובר בחוזה חדש, ולכן עליה לשלם לו דמי תיווך בסך דמי השכירות החודשיים, וזאת על מנת לפצות אותו על דמי התיווך שהוא היה מקבל לו היה מוצא שוכר חדש. בנסיבות המתוארות, האם המתווך רשאי לגבות דמי תיווך מגלית? מדוע?', '["כן; למתווך יש בלעדיות, הוא ביצע פעולות שיווק והשקיע מאמצים בשיווק, ולכן חזקה שהוא צריך לקבל דמי תיווך בגין חידוש החוזה.", "לא; למתווך אסור לגבות דמי תיווך בגין חידוש השכירות.", "כן; המתווך פעל כדין, מכיוון שקיבל את רשותו של בעל הנכס לאתר שוכר חדש.", "כן; אך המתווך רשאי לגבות מגלית דמי חידוש רק בסך מחצית מסכום השכירות החודשי."]'::jsonb, 1, null, 'תקנה 26(א) לתקנות האתיקה אוסרת במפורש לגבות תשלום בשל חידוש חוזה או מימוש אופציה, וסעיף 14 לחוק מקנה דמי תיווך רק למי שהיה הגורם היעיל להתקשרות, ומכוח הזמנה בכתב מהלקוח. גלית לא הזמינה מהמתווך שירות, והוא לא הביא אותה לדירה הפעם: היא כבר גרה בה. הבלעדיות מול בעל הנכס (חלופות א'' ו-ג'') יוצרת יחסים בין המתווך לבעלים, לא חיוב של השוכרת, וחלופה ד'' ממציאה תעריף שאינו קיים.', 'תקנה 26(א) לתקנות האתיקה; סעיפים 9 ו-14 לחוק המתווכים', 19, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
