insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q20', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 20', 'לפי פסק הדין בעניין מדינת ישראל נגד אופז, האם מותר למתווך לערוך זיכרון דברים עבור צדדים לעיסקה שלגביה מחזיק המתווך הזמנת תיווך חתומה כדין? האם המתווך זכאי במקרה כזה לדמי תיווך?', '["לא; מדובר באיסור פלילי והמתווך לא זכאי לדמי תיווך.", "לא; מדובר בהפרת כללי אתיקה בלבד, אך המתווך זכאי לדמי תיווך אם היה בעל רישיון בתוקף והיווה גורם יעיל בעיסקה.", "כן; מותר למתווך לכתוב זיכרון דברים לבקשת הלקוחות, והמסמך יועבר לעורך דין להמשך טיפול.", "כן; מכיוון שזה תפקידו של המתווך להעלות על הכתב את הפרטים המהותיים שהוסכמו בין הצדדים לעיסקה."]'::jsonb, 0, null, 'סעיף 12 לחוק המתווכים אוסר על מתווך/ת לערוך או לסייע לערוך מסמכים בעלי אופי משפטי הנוגעים לעסקה במקרקעין, וסעיף 15 לחוק הופך את ההפרה לעבירה פלילית. זיכרון דברים הוא הסכם מחייב לכל דבר, ותקנה 23 לתקנות האתיקה חוזרת ואוסרת לערוך או למסור אותו. בעניין מדינת ישראל נגד אופז נקבע שמתווך שערך זיכרון דברים ביצע עבירה, ושפעולה בניגוד לאיסור שוללת ממנו את הזכאות לדמי תיווך. חלופה ב'' טועה בסיווג (זו עבירה, לא רק אתיקה), וחלופות ג'' ו-ד'' מתירות את האסור.', 'סעיפים 12 ו-15 לחוק המתווכים; תקנה 23 לתקנות האתיקה', 20, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q21', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 21', 'דן רוצה לשכור חנות ולכן התקשר למתווך וביקש שיאתר עבורו חנות מתאימה. עם סיום השיחה שלח המתווך לדן הודעת וואטסאפ, כדלקמן: "בהמשך לשיחתנו, תשלום דמי תיווך למציאת חנות להשכרה יהיה בסך חודש אחד של דמי שכירות". לאחר בדיקה של מספר חנויות שאת פרטיהן דן לא עידכן בהסכם הזמנת התיווך, המתווך מצא חנות שהתאימה לדן ודן אכן שכר את החנות. לפי פסק הדין בעניין תא 6577/98 טרנס גלובל נגד נתנאל, האם זכאי המתווך לדמי תיווך מהשוכר בנסיבות אלה? מדוע?', '["כן; לפי פסק הדין הודעת הוואטסאפ של דן המתווך מחליפה טופס הזמנת שירותי תיווך כנדרש עפ\"י החוק ודן היה הגורם היעיל בעיסקה.", "לא; הודעת הוואטסאפ אינה כוללת את הפרטים הנדרשים בהזמנת תיווך, ולכן דן המתווך לא זכאי לדמי תיווך.", "כן; משום שדן המתווך היה הגורם היעיל בעיסקה.", "דן המתווך אינו זכאי לדמי תיווך, כי לא היה הגורם היעיל בעיסקה."]'::jsonb, 1, null, 'שאלה זו בוטלה במפתח הרשמי: כל ארבע התשובות התקבלו, ככל הנראה משום שהנוסח מערבב בין "דן" הלקוח ל"דן המתווך" בחלופות. לגופו של עניין, סעיף 9(א) לחוק המתווכים ותקנות המתווכים (פרטי הזמנה בכתב) דורשים שההזמנה בכתב תכלול, בין היתר, את פרטי הצדדים, תיאור הנכס, סוג העסקה והמחיר המשוער, ובלעדיהם אין זכאות לדמי תיווך לפי סעיף 14(א). הודעת וואטסאפ שמציינת רק את גובה התשלום אינה עומדת בדרישות אלה, ולכן חלופה ב'' היא ההסבר המשפטי המדויק ביותר, אך בסימולציה כל תשובה נחשבת נכונה.', 'סעיפים 9(א) ו-14 לחוק המתווכים; תקנות המתווכים במקרקעין (פרטי הזמנה בכתב)', 21, false
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
