  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q22', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 22', 'חווה ויוסי מבקשים למכור את דירתם. הם פנו לאביגיל המתווכת על מנת שאביגיל תשווק עבורם את הדירה. חווה ויוסי ביצעו בדיקות באופן עצמאי והגיעו למסקנה כי שווי דירתם הינו 2.5 מיליון ש"ח. בהתאם לכך הינחו את אביגיל לפרסם את הדירה במחיר זה. בשיחתם עם אביגיל ציינו חווה ויוסי כי מצבם הכלכלי אינו טוב וכי הם מעוניינים למכור את הדירה כמה שיותר מהר. אביגיל פרסמה את הדירה בסכום של 2 מיליון ש"ח, ובתוך שבוע יצר עימה קשר קונה וחתם עימה על טופס הזמנת שירותי תיווך. אביגיל המתינה כשבועיים ואז עדכנה את חווה ויוסי כי יש לה קונה שמוכן לשלם רק 2 מיליון ש"ח. בלית ברירה הסכימו חווה ויוסי למחיר, אלא שבמועד החתימה על הסכם המכר התברר לחווה ויוסי כי הקונה כלל לא ידע שהם דרשו 2.5 מיליון ש"ח. האם נפל פגם בפעולותיה של אביגיל? מדוע?', '["לא; אביגיל היוותה גורם יעיל בעיסקה והפעילה שיקול דעת לגבי מחיר הדירה.", "לא; מכיוון שאביגיל מייצגת את שני הצדדים היא רשאית להציע לצדדים מחיר מתאים לנכס.", "כן; אסור היה לאביגיל לפעול בניגוד להוראה שקיבלה מחווה ויוסי, והיה עליה לפעול בשקיפות לגבי המחיר שהיא מפרסמת עבורם.", "כן; אסור היה לאביגיל לייצג את שני הצדדים."]'::jsonb, 2, null, 'סעיף 8 לחוק המתווכים מחייב מתווך/ת לפעול בנאמנות, בהגינות ובדרך מקובלת כלפי הלקוח ולמסור לו כל מידע מהותי. אביגיל פרסמה מחיר שונה מזה שהבעלים הורו עליו, הסתירה זאת מהם, ואף הסתירה מהקונה את המחיר המבוקש: זו הפרה של חובת הנאמנות ושל איסור ההטעיה (תקנה 4), ושל תקנה 14 המחייבת לפעול לפי הוראות הלקוח. חלופה ד'' שגויה כי תקנה 17 מתירה ייצוג של שני הצדדים בכפוף ליידוע בכתב ותיעוד ההצעות; הפגם אינו בייצוג הכפול אלא בהסתרה.', 'סעיף 8 לחוק המתווכים; תקנות 4, 14 ו-17 לתקנות האתיקה', 22, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
