  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q23', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 23', 'משה טייל ברחוב וראה על אחד הבתים שלט "דירה למכירה" עם מספר הטלפון של המתווך חזי. משה התקשר לחזי, וחזי עדכן אותו שהדירה נמכרת במחיר מציאה של 1.2 מיליון ש"ח מכיוון שיש בדירה שוכר. משה התלהב, ניגש מיד למשרדו של חזי וחתם על טופס הזמנת שירותי תיווך. לאחר כשבוע נפגשו המוכר ומשה במשרדו של עו"ד לחתימה על הסכם מכר. לתדהמת משה התברר לו, כי הדירה מושכרת כדין לדייר מוגן בשכירות מוגנת. משה ביטל מיד את הסכם התיווך, וסירב לחתום על הסכם המכר. חזי כעס ודרש ממשה את דמי התיווך, כפי שהתחייב בטופס הזמנת שירותי התיווך. האם חזי פעל כדין? מדוע?', '["כן; משה חתם על טופס הזמנת שירותי תיווך והתחייב לשלם לחזי דמי תיווך.", "כן; חזי גילה למשה כי הדירה מושכרת, ובכך יצא ידי חובתו.", "לא; חזי היה חייב למסור למשה כל מידע מהותי בקשר לדירה, והעובדה שהדירה מושכרת לדייר מוגן היא מידע מהותי, משום שדייר מוגן זוכה להגנות ששוכר רגיל אינו זכאי להן.", "לא; לפי הדין בישראל כל דייר שמתגורר בדירה בשכירות נחשב כדייר מוגן בה ולכן לא מדובר במידע מהותי מבחינת הלקוח."]'::jsonb, 2, null, 'סעיף 8(א) לחוק המתווכים מחייב למסור ללקוח כל מידע מהותי הנוגע לנכס, ותקנה 7 לתקנות האתיקה והתוספת הראשונה מונות במפורש את קיומו של מחזיק שאינו הבעלים ומועד פינויו. דייר מוגן לפי חוק הגנת הדייר אינו ניתן לפינוי בתום תקופת השכירות ומשלם דמי שכירות מופחתים, ולכן "יש שוכר" אינו גילוי מספק (חלופה ב''). חלופה ד'' שגויה עובדתית: רוב השכירויות כיום אינן מוגנות. ובלי הסכם מכר שנחתם, אין בכלל זכאות לדמי תיווך לפי סעיף 14 (חלופה א'').', 'סעיף 8(א) לחוק המתווכים; תקנה 7 לתקנות האתיקה והתוספת הראשונה; חוק הגנת הדייר; סעיף 14 לחוק המתווכים', 23, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q24', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 24', 'משה הוא מתווך מקרקעין. משה החתים את יעל, המעוניינת למכור את דירתה, על טופס הזמנת שירותי תיווך, אך שכח להביא עימו את טופס הבלעדיות הרגיל שלו, ולכן הוסיף בכתב יד כי יזכה לבלעדיות למשך שישה חודשים במכירת דירת המגורים של יעל. בסופו של דבר הדירה נמכרה על ידי מתווך אחר בתוך תקופת הבלעדיות. לפי פסק הדין בתא 2461/07 בראון נ'' סידרון, האם העובדה שהבלעדיות לא נחתמה במסמך נפרד, פוסלת את הבלעדיות של משה? מדוע?', '["כן; הוראת החוק דורשת החתמה על בלעדיות במסמך נפרד מטופס הזמנת שירותי התיווך, ולא ניתן להתנות ולהסכים אחרת בין הצדדים.", "כן; מכיוון שהדירה נמכרה על ידי מתווך אחר.", "לא; ובלבד שיש הסכמה של הלקוחה לכך שהדבר לא ייעשה במסמך נפרד.", "לא; מדובר בדרישה טכנית של החוק והלקוחה חתמה על בלעדיות כדין."]'::jsonb, 0, null, 'סעיף 9(ב) לחוק המתווכים קובע שהסכם בלעדיות ייערך במסמך נפרד מההזמנה בכתב, ותקנה 1 לתקנות האתיקה מגדירה "הסכם בלעדיות" כמסמך שנחתם לפי אותו סעיף. בעניין בראון נ'' סידרון נקבע שהדרישה מהותית ולא טכנית, שכן היא נועדה להבטיח שהלקוח יבין שהוא מוותר על זכותו לפנות למתווכים אחרים, ולכן בלעדיות שנכתבה בתוך טופס ההזמנה אינה תקפה, והצדדים אינם יכולים להתנות על כך. חלופה ב'' מצביעה על תוצאה ולא על עילה, וחלופות ג'' ו-ד'' מתירות התניה על הוראה מגינה.', 'סעיף 9(ב) לחוק המתווכים; תקנה 1 לתקנות האתיקה', 24, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2025-07-q25', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2025, שאלה 25', 'גבריאל רכש בית צמוד קרקע עם חלקה חקלאית צמודה, הרשום ברשות מקרקעי ישראל (מנהל מקרקעי ישראל) (להלן: "רמ"י"). בנסיבות אלה, מהם דמי הסכמה בהקשר זה, והאם גבריאל חייב בתשלום דמי הסכמה לרמ"י?', '["דמי הסכמה משולמים לרמ\"י על מנת לקבל את הסכמת רמ\"י לתוספות בנייה, ויש לשלמם במקרה של בקשה לתוספות בנייה בלבד.", "דמי הסכמה הם תשלום לרמ\"י המשולם כתנאי להעברת זכויות חכירה. יש לשלמם במקרה שהחכירה על הנכס אינה מהוונת.", "דמי הסכמה הם תשלום לרמ\"י שיש לשלם בכל מקרה של העברת זכויות ברמ\"י.", "דמי הסכמה הם תשלום לרמ\"י עבור הסכמת רמ\"י לתוכנית בנייה בנכס ויש לשלמם עם אישור תוכנית בנייה על ידי רמ\"י בבעלות המדינה."]'::jsonb, 1, null, 'דמי הסכמה הם התשלום שרשות מקרקעי ישראל גובה כתנאי להסכמתה להעברת זכויות חכירה, והם מחושבים כחלק מעליית ערך הקרקע. הם נגבים רק כשהחכירה אינה מהוונת: חוכר ששילם דמי חכירה מהוונים (או דמי היתר להיוון) מעביר את זכויותיו בלי דמי הסכמה, ולכן חלופה ג'' ("בכל מקרה") שגויה. חלופות א'' ו-ד'' מערבבות דמי הסכמה עם דמי היתר, שהם התשלום בעד תוספת בנייה או שינוי ייעוד.', 'החלטות מועצת מקרקעי ישראל בעניין דמי הסכמה והיוון', 25, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2025-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_lessons (chapter_id, slug, title, position, intro, body_html, key_points, steps, source_ref, video_url, is_free, published)
select c.id, 'exam-2026-07', 'מבחן יולי 2026', 7, 'המועד האחרון שפורסם. שימו לב כמה שאלות כאן בכלל לא על חוק המתווכים: מקרקעין, חוזים, מכר דירות, הגנת הדייר. ככה נראית הבחינה האמיתית.', '<p>25 שאלות, ומפתח התשובות הרשמי. החלוקה לפי חוקים:</p><ul><li><strong>חוק המתווכים ותקנות האתיקה:</strong> 7 שאלות (1, 2, 3, 10, 12, 14, 23).</li><li><strong>חוק המקרקעין:</strong> 8 שאלות (6, 7, 9, 11, 20, 22, 25, ושאלה 4 על שכירות בעל פה).</li><li><strong>דיני חוזים:</strong> 2 שאלות (5, 24).</li><li><strong>חוק המכר (דירות) והבטחת השקעות:</strong> 2 שאלות (16, 17).</li><li><strong>הגנת הדייר:</strong> 2 שאלות (18, 19).</li><li><strong>משכנתה, מיסוי מקרקעין, תכנון ובנייה, דמי תיווך בפסיקה:</strong> שאלה אחת כל אחד (8, 15, 13, 21).</li></ul><p>המועד הזה מדגים את הכלל: מי שלומד/ת רק את חוק המתווכים מגיע/ה ל-7 שאלות מתוך 25, הרבה מתחת לציון העובר.</p>', '["רק 7 מתוך 25 שאלות על חוק המתווכים והתקנות. בלי דיני מקרקעין וחוזים אי אפשר לעבור.", "שלוש שאלות על התקנות החדשות (גילוי עמלה מצד שלישי, הצגה כמתווך בפנייה ראשונה, העברת כל הצעה).", "שאלת הבלעדיות (14) בודקת פרט טכני: בלעדיות היא מסמך נפרד.", "שאלות החוזים (5, 24) דורשות לדעת כללים מספריים: סדר זקיפת תשלומים, ושלוש התרופות על הפרה."]'::jsonb, '[]'::jsonb, 'רשם המתווכים במקרקעין, מועד 16.7.2026, גרסה 1', null, false, true
  from public.course_chapters c where c.slug = 'past-exams'
on conflict (chapter_id, slug) do update set title = excluded.title, position = excluded.position,
  intro = excluded.intro, body_html = excluded.body_html, key_points = excluded.key_points,
  steps = excluded.steps,
  source_ref = excluded.source_ref, video_url = coalesce(excluded.video_url, public.course_lessons.video_url),
  is_free = excluded.is_free, published = true, updated_at = now();

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q01', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 1', 'חברה יזמית, הבונה בנייני מגורים, מממנת את פעילותה באמצעות משקיעים פרטיים. משקיעים אלו שכרו מתווך כדי שיבצע פעולות תיווך בפרויקט שבונה החברה. המתווך התקשר בעסקאות תיווך עם רוכשים פוטנציאליים אך לא גילה להם כי הוא מקבל שכר גם מהמשקיעים. האם, בנסיבות העניין, המתווך פעל כדין?', '["המתווך פעל כדין. זאת משום שהוא לא מקבל שכר בקשר לעסקת המקרקעין הפרטנית של כל דייר ודייר.", "המתווך לא פעל כדין. במקרה המתואר הוא חייב לגלות לרוכשים כי הוא מקבל שכר מהמשקיעים.", "המתווך לא פעל כדין. חוץ מהעובדה שהוא מקבל שכר מהמשקיעים, היה עליו לשתף את רוכשי הדירות גם במידע עסקי שנמסר לו מהמשקיעים.", "המתווך פעל כדין. הוא מחויב לסודיות כלפי המשקיעים, ולכן כל שהוא מחויב לעשות הוא לגלות למשקיעים כי הוא מקבל עמלה גם מהרוכשים."]'::jsonb, 1, null, 'סעיף 10 לחוק המתווכים ותקנה 9 לתקנות האתיקה מחייבים לגלות בכתב ללקוח כל תשלום או טובת הנאה שהמתווך מקבל או עשוי לקבל מגורם שאינו צד לעסקה. המשקיעים אינם צד לעסקת המכר בין הרוכש לחברה, ולכן הגילוי חובה. חלופה ג מרחיקה לכת: אין חובה לחשוף מידע עסקי סודי של המשקיעים, רק את עצם קבלת השכר.', 'סעיף 10 לחוק המתווכים, תקנה 9', 1, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q02', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 2', 'רפאל הוא מתווך במקרקעין מוסמך. רפאל נוהג לטייל ברחובות עירו, וכשהוא נתקל במודעה "למכירה" שמפרסם בעל דירה, הוא פונה לבעל הדירה מבלי לספר שהוא מתווך במקרקעין, ומתעניין בפרטי הנכס ובמחיר המבוקש. לאחר מכן, רפאל מציע את הנכסים ללקוחותיו. האם רפאל פועל כדין בנסיבות אלה?', '["רפאל לא פועל כדין, אך ורק אם בעל הדירה מיוצג על ידי מתווך אחר.", "רפאל פועל כדין משום שהוא לא רשאי לגלות שום מידע הנוגע ללקוחותיו.", "רפאל פועל כדין שכן הוא מחויב להציג עצמו כמתווך אך ורק ללקוחות שלו.", "רפאל לא פועל כדין, שכן הוא צריך להציג את עצמו כמתווך במקרקעין גם למי שלא לקוח שלו."]'::jsonb, 3, null, 'תקנה 5(א) לתקנות האתיקה: בפנייה ראשונה של מתווך לאדם בנוגע לנכס מסוים יציין המתווך את שמו ואת עובדת היותו מתווך. התקנה אומרת "לאדם", ולא "ללקוח". בנוסף, תקנה 18 אוסרת לבצע פעולות שיווק בנכס בלי הסכמת הבעלים.', 'תקנה 5(א), תקנה 18', 2, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q03', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 3', 'ליאורה הציעה את דירתה למכירה באמצעות מתווך, וחתמה עימו על הסכם להזמנת שירותי תיווך במקרקעין. המתווך הראה את הדירה ליוכבד, מבלי שעדכן את ליאורה על הביקור של יוכבד בדירה. בעת הביקור בדירה, הודיעה יוכבד למתווך, כי תסכים לרכוש את הדירה במחיר הנמוך ב-150,000 ₪ מהמחיר המבוקש. יוכבד מבקשת מהמתווך להעביר לליאורה את הצעת המחיר שלה יחד עם ההסבר כי לדעתה המחיר מופרז מכיוון שהדירה זקוקה לשיפוץ משמעותי. המתווך הודיע ליוכבד שאין בכוונתו להעביר לליאורה הצעות נמוכות מהמחיר המבוקש, וכך עשה. המתווך לחץ על יוכבד להעלות את הצעתה למחיר המבוקש, ובסופו של דבר יוכבד נענתה לדרישתו ורכשה את הדירה במחיר המבוקש. בנסיבות המתוארות האם המתווך פעל כדין?', '["המתווך פעל כדין, לא היה עליו להעביר את ההצעה לליאורה כיוון שההצעה פחותה מהמחיר המבוקש.", "המתווך לא פעל כדין, הוא לא צריך להיות מעורב במשא ומתן בין הצדדים.", "המתווך לא פעל כדין, משום שהיה עליו להעביר ללקוחה כל הצעה שקיבל.", "המתווך פעל כדין, מכיוון שהשיג עבור ליאורה את המחיר המבוקש."]'::jsonb, 2, null, 'תקנה 14 לתקנות האתיקה: מתווך יעביר ללקוחו בתוך זמן סביר כל הצעה שקיבל, ויפעל לפי הוראות הלקוח. ההחלטה אם לקבל הצעה נמוכה היא של ליאורה. התוצאה (המחיר המבוקש הושג) אינה מרפאה את ההפרה, וחלופה ב שגויה כי מתווך בהחלט רשאי להיות מעורב במשא ומתן.', 'תקנה 14', 3, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
