  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q04', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 4', 'יצחק פרסם את דירתו להשכרה לתקופה של שנתיים. ראובן, ביקר בדירה, ניהל עם יצחק משא ומתן, וסיכם עם יצחק, בעל פה, על שכירת הדירה לשנתיים במחיר של 2,500 ש״ח לחודש. ראובן קיבל מיצחק את מפתחות הדירה והעביר חלק מחפציו לדירה באותו יום. למחרת, התקשר ראובן ליצחק במטרה לתאם עימו את מסירת השיקים עבור תשלום דמי השכירות אלא שיצחק מסר לראובן כי הוא מצטער אבל שרה ביקרה בדירה לפני שעה, הותירה עליו רושם טוב, והציעה לשכור את הדירה ב-2,800 ש״ח לחודש. בנסיבות העניין, האם יצחק רשאי להשכיר את הנכס לשרה?', '["כן, זאת משום שלא נחתם חוזה שכירות עם ראובן, וכל חוזה במקרקעין חייב להיעשות בכתב.", "כן, משום ששרה לא ידעה על ראובן, ולכן יצחק רשאי לקבל את הצעתה.", "לא, מכיוון שהחזקה בדירה נמסרה לראובן והוא כבר הכניס את חפציו לדירה.", "לא, מכיוון שההפרש בין דמי השכירות שסוכמו עם ראובן לאלו שסוכמו עם שרה, לא מהותי."]'::jsonb, 2, null, 'דרישת הכתב של סעיף 8 לחוק המקרקעין אינה חלה על שכירות קצרה: סעיף 79 לחוק המקרקעין פוטר שכירות לתקופה שאינה עולה על חמש שנים מדרישת הכתב ומהרישום. לכן נכרת חוזה שכירות תקף בעל פה בין יצחק לראובן, והוא אף קוים בחלקו במסירת המפתחות והחזקה. חלופה א שגויה בעובדה המשפטית (לא כל חוזה במקרקעין חייב כתב), וחלופה ד מנמקת בטעם שאינו רלוונטי.', 'סעיפים 8 ו-79 לחוק המקרקעין', 4, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
