  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q05', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 5', 'במסגרת חוזה לרכישת דירה שנכרת ביניהם, דוד היה חייב ליהונתן תשלום אחרון בסך של 200,000 ₪. יתרת החוב העדכנית של דוד ליהונתן עומדת כיום על 250,000 ₪, ומורכבת מקרן בסך 200,000 ₪, ריבית בסך 40,000 ₪ והוצאות שיהונתן התחייב בהן במסגרת החוזה במקרה של חוב, בסך 10,000 ₪. יהונתן הצליח לגבות מדוד רק 100,000 ₪ על חשבון החוב, ואת יתרת החוב, נותר דוד חייב ליהונתן. בנסיבות העניין, ובהיעדר הסכמה אחרת בין הצדדים, מהו סדר זקיפת התשלומים של החוב של דוד כלפי יהונתן?', '["תחילה יש לזקוף את התשלום לחשבון הקרן. לאחר מכן ניתן לזקוף לחשבון הריבית, ורק לאחר מכן לחשבון ההוצאות שיהונתן התחייב בהן בשל אותו חוב.", "יש לזקוף את התשלום לחשבון הריבית בסך 40,000 ₪ תחילה, ואז את היתרה להקטין מקרן החוב. ההוצאות שיהונתן הוציא לא רלוונטיות באכיפה של חוזה. הן נושא לתביעה נפרדת ותו לא.", "יש לזקוף את התשלום לחשבון ההוצאות שהוציא יהונתן תחילה בסך 10,000 ₪, ואת היתרה לזקוף לחשבון קרן החוב. הריבית לא רלוונטית באכיפה של חוזה. היא נושא לתביעה נפרדת ותו לא.", "יש לזקוף תחילה את התשלום להוצאות בסך 10,000 ₪, את היתרה מכך לזקוף לריבית בסך 40,000 ₪, ואת היתרה על חשבון קרן החוב."]'::jsonb, 3, null, 'בדיני החוזים, בהיעדר הסכמה אחרת, תשלום על חשבון חוב שמורכב מקרן, ריבית והוצאות נזקף קודם להוצאות, אחר כך לריבית, ורק בסוף לקרן. ההיגיון: הקרן ממשיכה לשאת ריבית, ולכן הדין שומר על זכות הנושה. כאן: 10,000 להוצאות, 40,000 לריבית, ו-50,000 הנותרים לקרן.', 'חוק החוזים (חלק כללי), זקיפת תשלומים', 5, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q06', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 6', 'ארבעה שותפים הם בעלים בחלקים שווים בבניין ישן בן ארבע דירות שלא רשום כבית משותף בפנקס הבתים המשותפים. אחד השותפים מגיש תביעה לפירוק השיתוף בבניין, דורש למכור את הבניין כולו לצד שלישי, ולחלק את התמורה הכספית בין השותפים. שלושת השותפים האחרים מתנגדים למכירה, ודורשים לפרק את השיתוף כך שכל אחת מהדירות תירשם על שם אחד מהשותפים. בנסיבות אלה, האם ישנה אפשרות עבור השותפים במקרקעין להימנע ממכירת הבניין?', '["לא. זאת משום שרישום בית משותף לא מהווה דרך חוקית לפירוק שיתוף לפי חוק המקרקעין, והדרך היחידה לפירוק שותפות בבניין היא מכירתו.", "כן. אפשר לבצע פירוק שיתוף בדרך של רישום הנכס כבית משותף והקצאת בעלות לכל אחד מהבעלים על דירה משלו.", "לא. רישום בית משותף כדרך לפירוק שיתוף אפשרי אך ורק אם כל השותפים מסכימים לכך פה אחד. בהיעדר הסכמה של אחד השותפים, בית המשפט מחויב להורות על מכירת הנכס.", "כן. ניתן למנוע משותף במקרקעין מלפרק את השותפות במקרקעין."]'::jsonb, 1, null, 'סעיף 42 לחוק המקרקעין: היה עיקר המקרקעין המשותפים בית הראוי להירשם כבית משותף, רשאי בית המשפט לצוות על פירוק השיתוף בדרך של רישום בבית משותף והקצאת דירות לשותפים לפי חלקיהם. זו דרך פירוק שאינה דורשת הסכמה פה אחד, וקודמת למכירה. חלופה ד שגויה כי לפי סעיף 37 כל שותף זכאי לדרוש פירוק בכל עת.', 'סעיפים 37 ו-42 לחוק המקרקעין', 6, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
