  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q07', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 7', 'שמשון מכר את דירתו לשני אנשים שונים. הוא חתם על חוזה עם הרוכש הראשון וקיבל ממנו תשלום עבור הדירה, ולאחר מכן חתם על חוזה עם הרוכש השני וקיבל גם ממנו תשלום, ואף רשם לטובת הקונה השני הערת אזהרה. שמשון נעלם, וכעת כל אחד מהרוכשים טוען כי זכותו בדירה גוברת. זכותו של מי מהקונים עדיפה?', '["מכיוון ששני הקונים פעלו בתום לב ושילמו את התמורה, זכאותם לדירה זהה ולכן יחלקו ביניהם את הדירה שווה בשווה.", "זכותו של הקונה הראשון גוברת.", "הקונה הראשון גובר, אלא אם הקונה השני פעל בתום לב, שילם את התמורה והשלים את הרישום על שמו.", "אף אחד מהצדדים לא יכול לזכות בדירה בנסיבות אלה, מכיוון שרישום הערת אזהרה ע\"י הקונה השני לא נחשב כהשלמת עסקה מצדו."]'::jsonb, 2, null, 'סעיף 9 לחוק המקרקעין (עסקאות נוגדות): זכותו של בעל העסקה הראשונה עדיפה, אלא אם השני פעל בתום לב ובתמורה והעסקה לטובתו נרשמה בעודו בתום לב. הערת אזהרה אינה רישום העסקה, ולכן לבדה אינה מקנה עדיפות לשני; רק רישום הבעלות משלים את התנאי. חלופה ב חסרה את החריג, ולכן אינה "הנכונה ביותר".', 'סעיף 9 לחוק המקרקעין', 7, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
