  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q08', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 8', 'לאחרונה רכש רועי דירת מגורים. לצורך רכישת הדירה נטל רועי הלוואה מהבנק. בתמורה להלוואה נרשמה לטובת הבנק משכנתה על הדירה. כעת מבקש רועי למכור את דירתו לפנינה, אולם הבנק מסרב לכך, שכן, לטענת הבנק על רועי לעמוד בתנאי ההלוואה עד לסיומה ולא רשאי להביא לפרעונה טרם המועד. רועי מבקש לשלם את יתרת ההלוואה במלואה. מה הדין בנסיבות האמורות?', '["הבנק צודק, שכן, רועי לא רשאי למכור את הדירה אלא לאחר שההלוואה תשולם במלואה, במועדה המקורי, ולכן עליו להמתין עד שיגיע מועד ההלוואה לסיומו.", "הבנק טועה. הבנק לא רשאי למנוע מרועי לפרוע את יתרת ההלוואה בטרם הגיע מועד סילוקה, ולכן רועי רשאי להפקיד את התשלום אצל רשם המקרקעין ולבקש שיפקיע את המשכנתה שנפדתה.", "הבנק טועה. רועי רשאי בכל עת לפרוע את ההלוואה, אך אם הבנק מסרב לכך, יכולה פנינה לגרור את המשכנתה אליה.", "הבנק צודק. המשכנתה מקומה לבנק זכות בלעדית בדירה, ולבנק הזכות למנוע בכל מקרה את מכירת הדירה לפנינה."]'::jsonb, 1, null, 'חוק המקרקעין מחיל על משכנתה את דיני המשכון (סעיף 91), וחוק המשכון מאפשר לחייב לפדות את המשכון לפני המועד. אם הנושה מסרב לקבל את הפירעון, החייב רשאי להפקיד את הסכום ולבקש את ביטול רישום המשכנתה (ראו סעיף 88 לחוק המקרקעין לעניין פקיעה בהפקדה). "גרירת משכנתה" לקונה אינה זכות של הקונה אלא הסדר שתלוי בהסכמת הבנק, ולכן חלופה ג שגויה.', 'סעיפים 88 ו-91 לחוק המקרקעין, חוק המשכון', 8, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
