  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q09', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 9', 'רועי מתגורר בדירת הגג בבית משותף הרשום בפנקס הבתים המשותפים. בבית המשותף קיימות שתי מעליות המיועדות לשרת את כל בעלי הדירות. רועי מעוניין להצמיד לדירתו בלבד את אחת המעליות תוך תשלום הולם לשאר בעלי הדירות. מה הרוב של בעלי הדירות הדרוש לרועי לשם קביעת הוראה בתקנון אודות ההצמדה בה הוא מעוניין?', '["רוב רגיל מבעלי הדירות בבית המשותף.", "הסכמה של כל בעלי הדירות בבית המשותף.", "רוב של 75% מבעלי הדירות בבית המשותף.", "לא ניתן להצמיד את המעלית לדירה."]'::jsonb, 3, null, 'סעיף 55(ג) לחוק המקרקעין מונה חלקים ברכוש המשותף שאינם ניתנים להצמדה לדירה: חדרי מדרגות, מעליות, מקלטים ומיתקנים המיועדים לשמש את כל בעלי הדירות. לכן השאלה על גודל הרוב היא מלכודת: אין רוב שמאפשר זאת.', 'סעיף 55(ג) לחוק המקרקעין', 9, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q10', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 10', 'אליהו מתווך במקרקעין משנת 2010 ושילם את כל האגרות במועדן. בשנת 2026 הוגשה תלונה במשטרה כנגד אליהו שהובילה לפתיחת חקירה פלילית כנגדו בחשד לביצוע עבירות מין. אליהו מבקש לשלם את האגרה לחידוש רישיון התיווך לשנת 2027. מה רשם המתווכים מוסמך לעשות בנסיבות אלו?', '["רשם המתווכים יכול להתלות זמנית את רישיון התיווך של אליהו לאחר שנועץ בוועדה המייעצת.", "רשם המתווכים לא יכול למנוע את חידוש הרישיון במקרה זה, אלא רק לאחר ההרשעה.", "רשם המתווכים יכול לזמן את המתלוננת למסירת עדות, ואם התרשם שהיא אמינה יכול לבטל את הרישיון של אליהו.", "רשם המתווכים יכול לנקוט באמצעים משמעתיים כנגד אליהו: התראה, נזיפה, קנס, התליה או ביטול רישיון."]'::jsonb, 0, null, 'חוק המתווכים מסמיך את הרשם, בהתייעצות עם הוועדה המייעצת, להתלות רישיון באופן זמני כשהוגש כתב אישום או מתנהלת חקירה בעבירה שמפאת מהותה או חומרתה אין המתווך ראוי לשמש מתווך, עד לסיום ההליך. אמצעי המשמעת שבחלופה ד הם סמכות ועדת המשמעת, לא הרשם, ושמיעת עדות (חלופה ג) אינה הליך של הרשם.', 'חוק המתווכים, התליה זמנית של רישיון', 10, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q11', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 11', 'אילן הוא בעלים של דירת מגורים הרשומה בפנקס הבתים המשותפים. לדירה צמודה חניה. אילן מבקש למכור לסיגל את דירתו, אולם את החניה הצמודה לה הוא מבקש למכור לראובן, שהוא בעלים של משרד בבניין סמוך. האם אילן רשאי לעשות כן?', '["כן, וזאת בתנאי שהתקנון בין בעלי הדירות בבית המשותף מאפשר את הפרדת ההצמדה מהדירה.", "כן, אילן יכול למכור את החניה שלו בנפרד מדירתו לכל מי שיבחר.", "לא. לא ניתן למכור הצמדה במקרקעין למי שאינו בעל נכס בבניין.", "לא. אין אפשרות חוקית להפריד הצמדה מדירת מגורים ולמכור אותה בנפרד."]'::jsonb, 2, null, 'לפי חוק המקרקעין, חלק מהרכוש המשותף שהוצמד לדירה הוא חלק בלתי נפרד מהדירה, ואי אפשר להעביר אותו לאדם שאינו בעל דירה בבית המשותף. אפשר, בתנאים ובתיקון התקנון, להעביר הצמדה מדירה אחת לדירה אחרת באותו בית, ולכן חלופה ד רחבה מדי, וחלופה ג היא המדויקת: ראובן אינו בעל נכס בבניין.', 'סעיפים 55 ו-62 לחוק המקרקעין', 11, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q12', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 12', 'יורם הוא מתווך במקרקעין אשר החליט לפרוש מהמקצוע, ובהתאם לכך הודיע לרשם המתווכים כי הוא מבקש להתלות מרצון את רישיונו. לאחר שהותלה רישיונו מרצון, הוגשה כנגדו תלונה בגין עבירות משמעת, לפי חוק המתווכים במקרקעין התשנ"ו-1996, שלכאורה ביצע בתקופה שקדמה להתליית הרישיון. האם ועדת המשמעת מוסמכת לדון בקובלנה בגין המעשים?', '["לא. ועדת המשמעת לא מוסמכת לדון בעניין בנסיבות הללו. אלא אם מדובר בתלונה הנוגעת לחוק הגנת הצרכן, התשמ\"א-1981 או בעבירה לפי חוק העונשין, התשל\"ז-1977.", "לא. ועדת המשמעת לא מוסמכת לדון בעניין. אלא אם כן רישיונו של יורם לא היה בתוקף בזמן ביצוע המעשים.", "כן. ועדת המשמעת מוסמכת לדון בעניין גם לאחר שיורם פרש מהמקצוע ובהתאם לכך תחליט את העניין.", "כן. ועדת המשמעת מוסמכת לדון בעניין. אבל אם במועד הדיון פרט שרישיונו של יורם לא בתוקף, הוועדה לא רשאית להטיל עונש של התליה או ביטול רישיון."]'::jsonb, 2, null, 'חוק המתווכים קובע שהליכי משמעת אפשריים גם נגד מי שרישיונו פקע או הותלה, בשל מעשים שנעשו בתקופה שבה היה מתווך. אחרת כל מתווך היה נמלט מדין משמעתי על ידי התליית רישיונו. הוועדה מוסמכת להטיל את כל אמצעי המשמעת, ולכן הסייג שבחלופה ד אינו בחוק.', 'חוק המתווכים, שיפוט משמעתי', 12, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q13', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 13', 'רופא שיניים מפעיל מרפאה בבניין משרדים. לאחרונה נדרש לבצע שיפוץ יסודי במרפאה, ולכן מעוניין להעביר את מרפאתו באופן זמני למרתף של ביתו הפרטי. היתר הבניה לביתו קבע שימוש למגורים. האם רופא השיניים רשאי להעביר את מרפאתו למרתף ביתו באופן זמני?', '["לא. זאת משום שלא ניתן לסטות מהוראות היתר הבניה.", "כן, אך רק בתנאי שרופא השיניים פנה לוועדה המחוזית לתכנון ובניה לצורך שינוי ייעוד, ושינוי הייעוד אושר באופן קבוע.", "כן, בתנאי שהגיש בקשה לשימוש חורג והבקשה אושרה.", "לא, מכיוון שלא ניתן להגיש בקשה להקלה זמנית להפעלת העסק במרתף ביתו."]'::jsonb, 2, null, 'חוק התכנון והבנייה מאפשר "שימוש חורג": שימוש בנכס למטרה שאינה המטרה שבהיתר או בתוכנית, באישור הוועדה המקומית ולתקופה מוגבלת. זה בדיוק הכלי לשימוש זמני. שינוי ייעוד (חלופה ב) הוא הליך של תוכנית, קבוע ומיותר לצורך זמני, ו"הקלה" (חלופה ד) נוגעת לסטייה מהוראות בנייה ולא לשימוש.', 'חוק התכנון והבנייה, שימוש חורג', 13, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q14', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 14', 'מתווך במקרקעין החתים את לקוחו על הסכם להזמנת שירותי תיווך לצורך שיווק דירתו של הלקוח. באותו הסכם נכתב כי תינתן למתווך בלעדיות למכירת הדירה למשך חצי שנה מיום חתימת החוזה, וכי המתווך מתחייב להציב שלט בדירה, ולפרסם את הדירה בעיתון יומי נפוץ על חשבונו של המתווך. שבועיים לאחר חתימת החוזה, הלקוח מכר את דירתו בעצמו ללא סיועו של המתווך. כעת טוען הלקוח כי המתווך לא זכאי לדמי תיווך משום שמכר את דירתו בעצמו ללא כלשהו של המתווך. המתווך מצידו, טוען כי הוא ביצע את פעולות השיווק שפורטו בהסכם להזמנת שירותי התיווך, בתוך שבוע מיום חתימת החוזה, ולכן זכאי לדמי התיווך. האם המתווך זכאי לדמי תיווך בנסיבות אלה?', '["המתווך זכאי לדמי תיווך בנסיבות אלה, מכוח חזקת \"הגורם היעיל\" שבבלעדיות.", "המתווך לא זכאי לדמי תיווך, שכן הוא לא יכול להיחשב כ\"גורם היעיל\" בעסקה אם הוא לא איתר בעצמו את הרוכש.", "המתווך זכאי לדמי תיווך, משום שהלקוח אישר את ההסכם להזמנת שירותי תיווך והדירה נמכרה בתוך תקופת הבלעדיות.", "המתווך לא זכאי לדמי תיווך, שכן לא נחתם הסכם בלעדיות נפרד."]'::jsonb, 3, null, 'סעיף 9(ב) לחוק המתווכים: בלעדיות ניתנת רק ב"מסמך נפרד" מההזמנה בכתב, ורק אז, בביצוע פעולות השיווק, קמה החזקה שהמתווך היה הגורם היעיל (סעיף 14(ב)). כאן הבלעדיות נכתבה בתוך הסכם ההזמנה עצמו, ולכן אין בלעדיות תקפה ואין חזקה. בלי החזקה, המתווך שלא איתר את הרוכש אינו הגורם היעיל.', 'סעיפים 9(ב) ו-14(ב) לחוק המתווכים', 14, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q15', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 15', 'בני זוג חתמו על הסכם גירושין אשר אושר בבית משפט לענייני משפחה. בהסכם נקבע כי הבעל ישלם לאשה מיליון ש"ח ויקבל בתמורה את מלוא הזכויות בדירת המגורים של בני הזוג. האם העברת הדירה בנסיבות אלה מחייבת את בני הזוג במס רכישה ובמס שבח?', '["העברת הדירה פטורה ממס שבח אך חייבת במס רכישה.", "העברת הדירה פטורה ממס שבח וממס רכישה.", "העברת הדירה חייבת בשליש מס רכישה כיוון שמדובר בהעברה בין קרובים.", "העברת הדירה פטורה ממס כל עוד טרם חלה חלוקת הרכוש ורק אם התשלום שמשלם הבעל לא מגיע ממקורות חיצוניים לנכסי בני הזוג."]'::jsonb, 1, null, 'סעיף 4א לחוק מיסוי מקרקעין: העברת זכויות במקרקעין בין בני זוג אגב גירושין, על פי פסק דין שניתן בעקבות גירושין, לא תיחשב "מכירה" לעניין החוק. אם אין מכירה, אין מס שבח ואין מס רכישה, גם כשמשולמת תמורה. חלופה ג מתייחסת להעברה ללא תמורה בין קרובים, שהוא מסלול אחר.', 'סעיף 4א לחוק מיסוי מקרקעין', 15, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
