insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q16', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 16', 'חברת בניה (להלן: "החברה") הקימה פרויקט למגורים. החברה לא צירפה להסכמי המכר של הדירות מפרט והוראות שימוש ותחזוקה. בין הקונים לבין החברה התעוררה מחלוקת לגבי טיב המטבח שסופק: החברה טוענת שהיתה צריכה לספק מטבח ברמה ממוצעת, ואילו הקונים טענו שהחברה היתה צריכה לספק מטבח ברמה גבוהה. בנסיבות העניין, מהי רמת המטבח שהחברה הייתה צריכה לספק לרוכשים?', '["החברה היתה צריכה לספק לרוכשים מטבח ברמה גבוהה.", "בנסיבות העניין, החברה צריכה לקיים את החוזה ברמה ממוצעת.", "על החברה להציע לרוכשים 3 סוגי מטבחים והרוכשים יבחרו מטבח מתוך חלופות אלו.", "החברה מחויבת להציע לכל רוכש זיכוי לרכישת מטבח, מחברת מטבחים לבחירתו."]'::jsonb, 0, null, 'חוק המכר (דירות) מחייב את המוכר לצרף לחוזה מפרט, וקובע שפרט שהמוכר היה חייב לפרט במפרט ולא פירט, רואים אותו כאילו התחייב לספקו ברמה הגבוהה (ולא הממוצעת). הכלל נועד לתמרץ מוכרים למלא מפרט מלא. כאן לא צורף מפרט כלל, ולכן הקונים צודקים.', 'חוק המכר (דירות), מפרט ופרט שלא פורט', 16, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q17', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 17', 'מירי רוכשת דירה מקבלן ומבקשת לשלם 25% מערך הדירה בתשלום הראשון. מירי פנתה לקבלן בבקשה כי במקום ערבות בנקאית להבטחת התשלום, יעניק לה הקבלן הנחה בשווי 10% ממחיר המחירון של הדירה. האם הקבלן רשאי להסכים להצעתה של מירי?', '["כן. כל עוד העסקה מדווחת לרשות המיסים במחיר שנקבע בפועל (לפני ההנחה).", "לא. כי הקבלן לא יכול לדווח על העסקה לרשות המיסים במחיר הנמוך ממחיר המחירון של הדירה.", "כן. מירי רשאית לוותר על ערבות, שכן, הערבות נועדה להגן עליה, ולכן רשאית לבקש ולקבל הנחה במקומה.", "לא. הקבלן לא יכול לקבל תשלום בסך 25% ממחיר הדירה ללא מתן ערבות."]'::jsonb, 3, null, 'חוק המכר (דירות) (הבטחת השקעות של רוכשי דירות): מוכר לא יקבל מהקונה יותר משבעה אחוזים ממחיר הדירה בלי להבטיח את כספו באחת הבטוחות שבחוק (ערבות בנקאית, פוליסת ביטוח, משכנתה ועוד). החובה היא קוגנטית, על המוכר, והקונה אינו יכול לוותר עליה תמורת הנחה.', 'סעיף 2 לחוק המכר (דירות) (הבטחת השקעות)', 17, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q18', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 18', 'בעקבות קשיים כלכליים מציע מלון חדרים להשכרה לטווח ארוך. לקוח פונה אליכם בשאלה האם יוכל לשכור חדר במלון ולהיחשב לדייר מוגן, שכן, מדובר בנכס בו בכוונתו להתגורר שנים רבות. האם חוק הגנת הדייר יחול על השכירות בבית המלון, בהנחה שבחוזה בין הלקוח למלון אינו מתייחס במפורש לתחולת חוק הגנת הדייר?', '["כן. חוק הגנת הדייר חל בכל נכס שבו אדם גר, והוא מגן עליו מפינוי מדירת המגורים שלו.", "כן. בגלל שלא נקבע בחוזה שחוק הגנת הדייר לא חל על השכירות בין הצדדים, אדם שגר במלון לתקופה ארוכה יכול להיות דייר מוגן.", "לא. הלקוח יוכל להיות מוגדר כדייר מוגן רק אם יקנה את הדירה כדירת נופש.", "לא. חוק הגנת הדייר לא חל על שכירות בבתי מלון."]'::jsonb, 3, null, 'חוק הגנת הדייר מונה במפורש נכסים שהוא אינו חל עליהם, ובהם שכירות בבתי מלון ובתי הארחה. ההחרגה היא מכוח החוק, ולכן אינה תלויה בניסוח החוזה (חלופה ב). חלופה א רחבה מדי: החוק חל רק על שכירויות מסוימות (בעיקר ישנות, או שבהן שולמו דמי מפתח), לא על כל מגורים.', 'חוק הגנת הדייר, נכסים שהחוק אינו חל עליהם', 18, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q19', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 19', 'ציונה ובתה דנה ניהלו יחד חנות נעליים. החנות הושכרה לציונה בדמי מפתח במשך שנים רבות. לאחר פטירתה של ציונה, המשיכה דנה להחזיק בחנות כדיירת ממשיכה. לאחר זמן מה ביקשה דנה לשנות את ייעוד העסק ולהפעיל במקום מסעדה, אולם בעל הנכס סירב לכך. מה הדין במקרה זה?', '["דייר ממשיך רשאי לשנות את מטרת העסק, ואין צורך באישור בעל הנכס או בית הדין, כל עוד דייר לא מבצע שינוי פיזי במושכר.", "דייר ממשיך רשאי לשנות את מטרת העסק, ואין צורך באישור בעל הנכס ו/או בית הדין, כל עוד השינוי לא מהווה מטרד לשכנים או לסביבה.", "בעל הנכס רשאי לסרב, שכן, דייר מוגן לא רשאי לשנות את מטרת השימוש במושכר ללא הסכמת בעל הנכס, ולבית הדין אין סמכות להורות אחרת.", "בעל הנכס רשאי לסרב, אך לבית הדין סמכות להתיר שינוי במטרת השימוש במושכר, אם מצא שהשינוי דרוש לקיומו של הדייר."]'::jsonb, 3, null, 'חוק הגנת הדייר: שינוי מטרת השכירות בבית עסק טעון הסכמת בעל הבית, אבל אם סירב, רשאי בית הדין לשכירות להתיר את השינוי כשהוא דרוש לקיומו של הדייר (ובתנאים שיקבע). לכן בעל הנכס רשאי לסרב, אבל זו אינה המילה האחרונה.', 'חוק הגנת הדייר, שינוי מטרת השכירות בבית עסק', 19, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q20', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 20', 'ביום 1 ביוני 2026, בעת שאורי שהה בטיול בחו"ל, פרץ ניר לדירתו של אורי והחל להתגורר בה. אורי חזר לישראל ביום 20 ביוני 2026 וגילה את דבר הפלישה. ביום 5 ביולי 2026, פנה אורי לניר ודרש ממנו להתפנות. משסירב ניר, שכר אורי מאבטחים פרטיים אשר נכנסו לדירה, השתמשו בכוח סביר ופינו את ניר ואת חפציו מן הנכס. האם פעולתו של אורי חוקית?', '["פעולתו של אורי חוקית לחלוטין, שכן הוא פעל בתוך 30 ימים מיום שגילה בפועל את הפלישה לדירתו, וזהו המועד הקובע לצורך הפעלת סעד עצמי.", "פעולתו של אורי לא חוקית. היה עליו לפנות לבית משפט. זאת משום שזכות הסעד העצמי מוגבלת לשימוש בכוח סביר תוך 30 ימים מיום התפיסה (הפלישה עצמה), ולא מיום הגילוי.", "אורי היה רשאי להשתמש בכוח סביר ללא הגבלת זמן, שכן מדובר במקרקעין פרטיים רשומים, והגבלת 30 הימים חלה אך ורק על מקרקעי ציבור שאינם רשומים.", "שימוש בכוח סביר מותר אך ורק למניעת פלישה, ואילו מרגע שהפולש תפס את ההחזקה הפיזית בנכס, חל איסור מוחלט על עשיית דין עצמי ויש לפנות לבית המשפט בלבד."]'::jsonb, 1, null, 'סעיף 18(ב) לחוק המקרקעין: מי שתפסו ממנו מקרקעין שלא כדין רשאי, תוך שלושים ימים מיום התפיסה, להשתמש בכוח במידה סבירה כדי להוציא את התופס. המניין הוא מיום התפיסה (1 ביוני), לא מיום הגילוי, ולכן ב-5 ביולי חלפו יותר מ-30 יום והדרך היחידה היא בית המשפט.', 'סעיף 18 לחוק המקרקעין', 20, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q21', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 21', 'צילה - בעלת קרקע, התקשרה בהסכם קומבינציה עם יזם. העסקה בוצעה באמצעות מתווך. התמורה לה זכאית צילה מכח ההסכם, כללה תשלום כספי במזומן וכן 4 דירות שיבנו בפרויקט שיקים היזם על הקרקע. בהתאם לפס"ד עא 107/86 אהרון חסין נ'' דוד בלס ואח'', מהו הבסיס לחישוב דמי תיווך בעסקה?', '["המזומן בלבד.", "שווי כלל התמורה בעסקה, לרבות שווי הדירות בנוסף לרכיב המזומן.", "שווי הדירות בלבד, ללא רכיב המזומן.", "שווי הקרקע המקורי, ללא התמורה העתידית."]'::jsonb, 1, null, 'בפסק הדין חסין נ'' בלס נקבע שדמי התיווך בעסקת קומבינציה מחושבים משווי התמורה הכוללת שמקבל בעל הקרקע, כולל שווי הדירות שייבנו, ולא רק מהרכיב הכספי. דמי התיווך הם אחוז מערך העסקה, והעסקה כוללת את כל מה שהמוכר מקבל.', 'ע"א 107/86 חסין נ'' בלס', 21, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q22', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 22', 'יעל ותמר הן בעלים במשותף בדירת מגורים בחלקים שווים. בין השתיים נערך הסכם, לפיו יעל תהיה זכאית לשימוש ייחודי בחדר העבודה בדירה למשך עשר שנים, ותמר לא תעשה בו כל שימוש. ההסכם לא נרשם בפנקסי המקרקעין. בנסיבות העניין, האם ההסכם מחייב רוכש עתידי (צד ג'') שיקנה את חלקה של תמר בדירה מבלי להכיר את ההסכם בין יעל ותמר בכל דרך שהיא, בהסתמך על נוסח הרישום שהופק מפנקסי המקרקעין?', '["ההסכם מחייב גם צד ג'' כאמור, שכן אין חובת רישום של הסכם השיתוף.", "כאשר הסכם שיתוף לא נרשם בפנקסי המקרקעין, הוא לא מחייב אדם שנעשה שותף לאחר חתימת ההסכם.", "ההסכם חסר תוקף, שכן, שותפים במקרקעין הם שותפים בחלק בלתי מסוים מהנכס.", "ההסכם מחייב, שכן הסכם שיתוף מחייב רוכש עתידי בתנאי שדווח לרשות המקומית ולמיסוי מקרקעין."]'::jsonb, 1, null, 'סעיף 29 לחוק המקרקעין: הסכם שיתוף ניתן לרישום, ומשנרשם כוחו יפה גם כלפי אדם שנעשה שותף לאחר מכן וכלפי כל אדם אחר. הסכם שלא נרשם מחייב רק את הצדדים לו, ולא את מי שרכש חלק בתום לב בהסתמך על המרשם. ההסכם עצמו תקף בין יעל לתמר (ולכן חלופה ג שגויה).', 'סעיף 29 לחוק המקרקעין', 22, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
