  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q23', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 23', 'שרה מבקשת למכור את דירתה. יוסי, מתווך במקרקעין, הגיע לביתה של שרה על מנת לשכנע אותה לחתום על הסכם בלעדיות במכירת דירתה. שרה סירבה לחתום, ואף הבהירה כי היא לא מעוניינת בשירותי תיווך כלל. לאחר סירובה, יוסי התקשר לשרה פעמים רבות עם הצעות מרוכשים שייצג והגיע לביתה שלוש פעמים נוספות. בלחץ השתכנעה שרה, חתמה על הזמנת שירותי תיווך, ומכרה את הדירה באמצעות תיווכו של יוסי. בנסיבות העניין, האם יוסי פעל כדין?', '["יוסי פעל כדין. מותר למתווך לפנות ללקוח מספר פעמים עד שהוא משתכנע לבצע עסקה.", "יוסי פעל כדין. שכן הוא מייצג את לקוחותיו שמעוניינים לרכוש את דירתה של שרה.", "יוסי פעל בניגוד לדין. מותר למתווך לפנות ללקוח מספר פעמים, אך אסור לו להגיע לביתו.", "יוסי פעל בניגוד לדין. שכן, חל איסור על פניות חוזרות לשם קשירת עסקה."]'::jsonb, 3, null, 'תקנה 3 לתקנות האתיקה אוסרת להפעיל על יחיד השפעה בלתי הוגנת כמשמעותה בסעיף 3 לחוק הגנת הצרכן כדי שיתקשר בעסקת תיווך, וסעיף 3 לחוק הגנת הצרכן מונה פניות חוזרות ונשנות למרות סירוב. ההגעה לבית היא רק עוד ביטוי של אותה התנהגות; האיסור הוא על הפניות החוזרות עצמן, גם בטלפון.', 'תקנה 3, סעיף 3 לחוק הגנת הצרכן', 23, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q24', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 24', 'יונתן והראל חתמו על הסכם מכר אשר לפיו יונתן רוכש דירה מהראל. התשלום הראשון היה אמור להתבצע כשבועיים לאחר החתימה. יום לפני מועד התשלום הודיע יונתן על ביטול ההסכם. מהן התרופות העומדות להראל בגין הפרת החוזה?', '["הראל רשאי לדרוש את אכיפת החוזה או לבטלו. בנוסף, הוא רשאי לתבוע פיצויים בנוסף לביטול החוזה או אכיפתו, או במקומם.", "אי אפשר לדרוש אכיפת חוזה מכר דירה, שכן, מדובר בעניין בשירות אישי. לכן הראל זכאי לפיצוי כספי בלבד.", "הראל רשאי לבחור בין אכיפת החוזה לבין פיצויים, אך לא יכול לקבל את שניהם.", "מאחר שהתשלום הראשון טרם בוצע, ההסכם טרם נכנס לתוקף. לכן אין להראל זכות לדרוש אכיפה או פיצויים."]'::jsonb, 0, null, 'סעיף 2 לחוק החוזים (תרופות בשל הפרת חוזה): הנפגע זכאי לתבוע אכיפה או לבטל את החוזה, וזכאי לפיצויים בנוסף על אחת התרופות או במקומן. הודעה על ביטול לפני מועד הקיום היא הפרה צפויה (סעיף 17), שמקימה את התרופות מיד. חוזה מכר דירה אינו "שירות אישי" (החריג לאכיפה בסעיף 3), והחוזה נכרת בחתימה, לא בתשלום.', 'סעיפים 2, 3 ו-17 לחוק החוזים (תרופות)', 24, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

insert into public.course_questions (slug, chapter_id, lesson_id, kind, source, question, options, correct, accepted, explanation, law_ref, position, published)
select 'exam-2026-07-q25', l.chapter_id, l.id, 'exam', 'מבחן רשם המתווכים, יולי 2026, שאלה 25', 'בחוזה המכר נקבע תנאי מפורש לפיו הקונה לא יהיה רשאי לבצע כל עסקה במקרקעין הנרכשים, ללא קבלה מראש של הסכמה של המוכר בכתב. המוכר מעוניין להבטיח תנאי זה ברישום בפנקסי המקרקעין. איזו הערה רשאי הרשם לרשום בפנקס המקרקעין ומה משמעותה?', '["הרשם רשאי לרשום הערה בדבר הצורך בהסכמה של המוכר. כל עוד ההערה רשומה, לא ניתן לרשום כל עסקה הסותרת את תוכן ההערה.", "הרשם רשאי לרשום הערת אזהרה רגילה בלבד, אך היא לא מונעת רישום עסקאות סותרות, אלא רק מעניקה למוכר זכות קדימה לקבלת פיצויים כספיים.", "אין אפשרות לרשום הערה על צורך בהסכמה של צד שלישי. שכן, תניה כזו נחשבת לפגיעה בלתי חוקית בחופש העיסוק ובחופש הקניין של הקונה.", "ניתן לרשום הערה על הגבלת כשרות משפטית, אשר תוקפה פג באופן אוטומטי בחלוף שנה מיום הרישום, אלא אם כן חודשה בצו של בית משפט."]'::jsonb, 0, null, 'סעיף 128 לחוק המקרקעין: רשאי הרשם, על פי הסכמת בעל המקרקעין, לרשום הערה שעסקה במקרקעין טעונה הסכמתו של צד שלישי, ומשנרשמה לא תירשם עסקה הסותרת את תוכן ההערה אלא בהסכמת אותו צד או בצו בית משפט. זו הערה שונה מהערת אזהרה (סעיף 126) ומהערה על הגבלת כשרות (סעיף 129).', 'סעיף 128 לחוק המקרקעין', 25, true
  from public.course_lessons l join public.course_chapters c on c.id = l.chapter_id
  where c.slug = 'past-exams' and l.slug = 'exam-2026-07'
on conflict (slug) do update set chapter_id = excluded.chapter_id, lesson_id = excluded.lesson_id,
  kind = excluded.kind, source = excluded.source, question = excluded.question, options = excluded.options,
  correct = excluded.correct, accepted = excluded.accepted, explanation = excluded.explanation, law_ref = excluded.law_ref,
  position = excluded.position, published = excluded.published;

