update public.course_lessons l set published = false
  from public.course_chapters c where c.id = l.chapter_id and (c.slug, l.slug) not in (('intro', 'exam-format'), ('brokers-law', 'law-scope'), ('brokers-law', 'license'), ('brokers-law', 'duty-of-care'), ('brokers-law', 'written-order'), ('brokers-law', 'exclusivity'), ('brokers-law', 'brokerage-fee'), ('brokers-law', 'personal-interest'), ('brokers-law', 'discipline'), ('ethics-regulations', 'definitions'), ('ethics-regulations', 'professional-conduct'), ('ethics-regulations', 'disclosure-and-explanation'), ('ethics-regulations', 'material-information'), ('ethics-regulations', 'documents-and-information'), ('ethics-regulations', 'service-rules'), ('ethics-regulations', 'representation-marketing-ads'), ('ethics-regulations', 'prohibitions'), ('land-law', 'land-basics'), ('land-law', 'land-writing'), ('land-law', 'land-conflicting'), ('land-law', 'land-coownership'), ('land-law', 'land-condo-property'), ('land-law', 'land-condo-management'), ('land-law', 'land-others-rights'), ('past-exams', 'exam-2023-01'), ('past-exams', 'exam-2023-05'), ('past-exams', 'exam-2023-07'), ('past-exams', 'exam-2024-05'), ('past-exams', 'exam-2024-08'), ('past-exams', 'exam-2024-11'), ('past-exams', 'exam-2025-02'), ('past-exams', 'exam-2025-05'), ('past-exams', 'exam-2025-07'), ('past-exams', 'exam-2026-07'));
